class ContainerContractError(RuntimeError):
    """The observed container boundary did not satisfy the launch contract."""


class _SubstratePreflightFailure(ContainerContractError):
    """Private handoff: preflight failed and controller roles are absent."""

    def __init__(
        self,
        *,
        substrate_identity_sha256: str,
        stage: str,
        error_type: str,
        failure_class: str,
        failure_code: str,
        preflight_root: str,
        state_tree_sha256: str,
        partial_scan_receipt_path: str,
        partial_scan_receipt_sha256: str,
        purge_receipt_path: str,
        purge_receipt_sha256: str,
    ) -> None:
        super().__init__("controller substrate preflight failed")
        self.substrate_identity_sha256 = substrate_identity_sha256
        self.stage = stage
        self.error_type = error_type
        self.failure_class = failure_class
        self.failure_code = failure_code
        self.preflight_root = preflight_root
        self.state_tree_sha256 = state_tree_sha256
        self.partial_scan_receipt_path = partial_scan_receipt_path
        self.partial_scan_receipt_sha256 = (
            partial_scan_receipt_sha256
        )
        self.purge_receipt_path = purge_receipt_path
        self.purge_receipt_sha256 = purge_receipt_sha256


def _classify_substrate_preflight_failure(
    stage: str, error: BaseException
) -> tuple[str, str]:
    """Classify configuration defects separately from transient outages."""

    current: BaseException | None = error
    seen: set[int] = set()
    while current is not None and id(current) not in seen:
        seen.add(id(current))
        typed_class = getattr(
            current, "substrate_failure_class", None
        )
        typed_code = getattr(
            current, "substrate_failure_code", None
        )
        if (
            typed_class
            in {
                "DETERMINISTIC_CONFIGURATION",
                "TRANSIENT_INFRASTRUCTURE",
            }
            and _safe_probe_identifier(typed_code) == typed_code
        ):
            return typed_class, typed_code
        current = (
            current.__cause__
            if current.__cause__ is not None
            else current.__context__
        )
    text = " ".join(
        (
            type(error).__name__,
            str(error),
            str(getattr(error, "__cause__", "") or ""),
            str(getattr(error, "__context__", "") or ""),
        )
    ).lower()
    if (
        "path-alias/startup preflight wrote stderr" in text
        or "path alias" in text
        or "path-alias" in text
    ):
        return (
            "DETERMINISTIC_CONFIGURATION",
            "controller_path_alias_or_startup_stderr",
        )
    if (
        isinstance(error, PermissionError)
        or "permission denied" in text
        or "operation not permitted" in text
        or "not writable by its runtime identity" in text
        or "state root is not writable" in text
    ):
        return (
            "DETERMINISTIC_CONFIGURATION",
            "controller_state_root_permission",
        )
    if (
        stage == "preflight-evidence-validation"
        and "stderr" in text
    ):
        return (
            "DETERMINISTIC_CONFIGURATION",
            "controller_nonzero_startup_stderr",
        )
    return ("TRANSIENT_INFRASTRUCTURE", "controller_substrate_transient")


class _PreflightDeniedBridge:
    """No solver bridge exists during the disposable controller preflight."""

    def call(self, *_args: Any, **_kwargs: Any) -> Any:
        raise ContainerContractError(
            "substrate preflight cannot call a proposer bridge"
        )

    def close(self) -> None:
        return None


def _apply_terminal_result_precedence(
    runner_contract: Any,
    *,
    terminal_status: object,
    result: Any,
) -> Any:
    """Delegate terminal authority to the runner's single policy function."""

    return runner_contract.apply_terminal_result_precedence(
        terminal_status,
        result,
    )


