@dataclass(frozen=True)
class CommandResult:
    """One argv-only command observation."""

    argv: tuple[str, ...]
    returncode: int
    stdout: str = ""
    stderr: str = ""


@dataclass(frozen=True)
class AttachedStreamResult:
    """Bounded host-owned bytes from one attached container start."""

    argv: tuple[str, ...]
    returncode: int | None
    stdout_path: str
    stdout_sha256: str
    stdout_bytes: int
    stdout_truncated: bool
    stderr_path: str
    stderr_sha256: str
    stderr_bytes: int
    stderr_truncated: bool
    timed_out: bool
    output_overflow: bool
    started_monotonic: float
    finished_monotonic: float


class CommandRunner(Protocol):
    """Narrow command runner used by the backend and mocked by unit tests."""

    def run(
        self,
        argv: Sequence[str],
        *,
        timeout_seconds: float | None = None,
    ) -> CommandResult:
        """Run exactly ``argv`` without a shell."""


class AttachedStreamCommandRunner(CommandRunner, Protocol):
    """Command runner able to stream an attached container without buffering."""

    def run_attached_stream(
        self,
        argv: Sequence[str],
        *,
        timeout_seconds: int,
        stdout_path: Path,
        stderr_path: Path,
        stdout_limit_bytes: int,
        stderr_limit_bytes: int,
    ) -> AttachedStreamResult:
        """Run exactly ``argv`` and retain bounded streams in new host files."""


class InteractiveAttachCommandRunner(CommandRunner, Protocol):
    def spawn_interactive(
        self, argv: Sequence[str]
    ) -> subprocess.Popen[bytes]:
        """Spawn one exact stdin/stdout/stderr Docker attach command."""


@dataclass(frozen=True)
class _ManagedChildInvocation:
    invocation_id: str
    root: Path
    intent_sha256: str
    active_sha256: str | None


class _ManagedInteractivePopen(subprocess.Popen[bytes]):
    """Popen whose successful wait seals the managed-child terminal receipt."""

    def __init__(self, *args: Any, **kwargs: Any) -> None:
        self._managed_terminal_recorder: (
            Callable[[subprocess.Popen[bytes]], None] | None
        ) = None
        self._managed_terminal_recorded = False
        super().__init__(*args, **kwargs)

    def bind_terminal_recorder(
        self,
        recorder: Callable[[subprocess.Popen[bytes]], None],
    ) -> None:
        if (
            self._managed_terminal_recorder is not None
            or self._managed_terminal_recorded
            or not callable(recorder)
        ):
            raise ContainerContractError(
                "managed interactive terminal recorder is malformed"
            )
        self._managed_terminal_recorder = recorder

    def _record_managed_terminal(self) -> None:
        if self._managed_terminal_recorded:
            return
        recorder = self._managed_terminal_recorder
        if recorder is None:
            raise ContainerContractError(
                "managed interactive process lacks its terminal recorder"
            )
        recorder(self)
        self._managed_terminal_recorded = True

    def wait(self, timeout: float | None = None) -> int:
        returncode = super().wait(timeout=timeout)
        self._record_managed_terminal()
        return returncode

    def communicate(
        self,
        input: bytes | None = None,
        timeout: float | None = None,
    ) -> tuple[bytes, bytes]:
        stdout, stderr = super().communicate(
            input=input, timeout=timeout
        )
        self._record_managed_terminal()
        return stdout, stderr


