def parse_digest_reference(reference: str) -> tuple[str, str]:
    """Return ``(repository, digest)`` for an immutable repository reference."""
    if (
        not isinstance(reference, str)
        or reference.count("@") != 1
        or any(char.isspace() for char in reference)
    ):
        raise ContainerContractError(
            "image reference must be repository@sha256:<64 lowercase hex>"
        )
    repository, digest = reference.split("@", 1)
    if (
        not repository
        or repository.startswith("-")
        or repository.endswith("/")
        or ":" not in digest
        or not SHA256_RE.fullmatch(digest)
    ):
        raise ContainerContractError(
            "image reference must be repository@sha256:<64 lowercase hex>"
        )
    return repository, digest


def expected_worker_command() -> tuple[str, ...]:
    """Exact command for the pinned independent replay worker."""
    return (
        "-I",
        "-m",
        WORKER_MODULE,
        f"--socket={RPC_SOCKET_DESTINATION}",
        f"--token-file={RPC_TOKEN_DESTINATION}",
        f"--solve={SOLVER_DESTINATION}",
        f"--outcome={OUTCOME_DESTINATION}",
    )


def expected_proposer_worker_command() -> tuple[str, ...]:
    """Exact command for the isolated, networkless proposer lane worker."""
    return (
        "-I",
        "-m",
        PROPOSER_WORKER_MODULE,
        f"--bridge-socket={BRIDGE_SOCKET_DESTINATION}",
        f"--bridge-token-file={BRIDGE_TOKEN_DESTINATION}",
        f"--bridge-policy={BRIDGE_POLICY_DESTINATION}",
        f"--arena-socket={PROPOSER_RPC_SOCKET_DESTINATION}",
        f"--arena-token-file={RPC_TOKEN_DESTINATION}",
        f"--workspace={WORKSPACE_DESTINATION}",
        f"--export={EXPORT_DESTINATION}",
    )


