def _validate_private_host_directory(path: Path) -> None:
    if not isinstance(path, Path) or not path.is_absolute():
        raise ContainerContractError(
            "runner generation directories must be absolute Paths"
        )
    if Path(os.path.abspath(os.fspath(path))) != path:
        raise ContainerContractError(
            "runner generation directory has a noncanonical path alias"
        )
    _reject_symlink_components(path, label="runner generation directory")
    try:
        metadata = path.lstat()
    except OSError as exc:
        raise ContainerContractError(
            "runner generation directory is unavailable"
        ) from exc
    if (
        not stat.S_ISDIR(metadata.st_mode)
        or metadata.st_uid != os.getuid()
        or stat.S_IMODE(metadata.st_mode) & 0o077
    ):
        raise ContainerContractError(
            "runner generation directories must be supervisor-owned and private"
        )


def _read_unaliased_json(path: Path, *, label: str) -> dict[str, Any]:
    _reject_symlink_components(path, label=label)
    try:
        before = path.lstat()
    except OSError as exc:
        raise ContainerContractError(f"{label} is unavailable") from exc
    if (
        not stat.S_ISREG(before.st_mode)
        or before.st_nlink != 1
        or before.st_size > MAX_INSPECT_BYTES
    ):
        raise ContainerContractError(
            f"{label} must be a bounded unaliased regular file"
        )
    descriptor = -1
    try:
        descriptor = os.open(
            path,
            os.O_RDONLY | getattr(os, "O_NOFOLLOW", 0),
        )
        current = os.fstat(descriptor)
        if (
            not stat.S_ISREG(current.st_mode)
            or current.st_nlink != 1
            or (
                current.st_dev,
                current.st_ino,
                current.st_size,
                stat.S_IMODE(current.st_mode),
                current.st_uid,
                current.st_gid,
            )
            != (
                before.st_dev,
                before.st_ino,
                before.st_size,
                stat.S_IMODE(before.st_mode),
                before.st_uid,
                before.st_gid,
            )
        ):
            raise ContainerContractError(f"{label} changed during admission")
        raw = bytearray()
        while len(raw) <= MAX_INSPECT_BYTES:
            block = os.read(descriptor, min(1024 * 1024, MAX_INSPECT_BYTES + 1))
            if not block:
                break
            raw.extend(block)
        if len(raw) > MAX_INSPECT_BYTES:
            raise ContainerContractError(f"{label} exceeds the evidence limit")
    except OSError as exc:
        raise ContainerContractError(f"{label} cannot be read") from exc
    finally:
        if descriptor >= 0:
            os.close(descriptor)
    try:
        value = json.loads(raw)
    except (UnicodeDecodeError, json.JSONDecodeError) as exc:
        raise ContainerContractError(f"{label} is not valid JSON") from exc
    if not isinstance(value, dict):
        raise ContainerContractError(f"{label} must be a JSON object")
    return value


def _validate_runner_wip_evidence_graph(
    runner_spec: Any,
    wip: Any,
) -> None:
    """Reopen every retained WIP receipt without trusting runner validation."""

    publication_path = Path(wip.wip_publication_receipt_path)
    origin = publication_path.parent
    host_root = origin / "host"
    expected_paths = {
        "wip_root_path": origin / "output" / WIP_DIRECTORY,
        "solver_source_path": origin
        / "output"
        / WIP_DIRECTORY
        / WIP_SOLVER_SOURCE_DIRECTORY,
        "final_thread_binding_path":
            origin / "final_thread_binding.json",
        "wip_export_receipt_path":
            host_root / "wip_export_receipt.json",
        "final_transcript_chain_receipt_path":
            host_root / "final_transcript_chain_receipt.json",
        "controller_state_scan_receipt_path":
            host_root / "controller_state_scan_receipt.json",
        "retained_canary_scan_receipt_path":
            origin / "retained_canary_scan_receipt.json",
        "taint_scan_receipt_path":
            host_root / "taint_scan_receipt.json",
        "token_usage_receipt_path":
            host_root / "token_usage_receipt.json",
        "provider_usage_receipt_path":
            host_root / "provider_usage_receipt.json",
        "app_server_state_dir":
            origin / "state" / "codex_home",
        "wip_publication_receipt_path":
            origin / "wip_publication_receipt.json",
    }
    if (
        not origin.is_absolute()
        or Path(os.path.abspath(os.fspath(origin))) != origin
        or any(
            Path(getattr(wip, field, "")) != expected
            for field, expected in expected_paths.items()
        )
    ):
        raise ContainerContractError(
            "runner WIP receipts do not form one canonical generation"
        )
    publication_digest = _hash_unaliased_regular_file(
        publication_path, label="runner WIP publication receipt"
    )
    if publication_digest != wip.wip_publication_receipt_sha256:
        raise ContainerContractError(
            "runner WIP publication receipt hash changed"
        )
    publication = _read_unaliased_json(
        publication_path, label="runner WIP publication receipt"
    )
    try:
        _canonical_uuid4(
            publication.get("generation_id"),
            label="retained WIP generation",
        )
        _canonical_uuid4(
            publication.get("attempt_id"),
            label="retained WIP attempt",
        )
    except ContainerContractError:
        raise
    base = {
        "schema": 1,
        "kind": "contiguous_wip_publication",
        "campaign_id": _runner_field(runner_spec, "campaign_id"),
        "generation_id": origin.name,
        "attempt_id": publication.get("attempt_id"),
        "attempt_spec_sha256":
            publication.get("attempt_spec_sha256"),
    }
    publication_fields = asdict(wip)
    publication_fields.pop("wip_publication_receipt_path")
    publication_fields.pop("wip_publication_receipt_sha256")
    if (
        not _is_hex_sha256(base["attempt_spec_sha256"])
        or set(publication) != {*base, *publication_fields}
        or any(
            publication.get(key) != value
            for key, value in {**base, **publication_fields}.items()
        )
    ):
        raise ContainerContractError(
            "runner WIP publication receipt is incomplete or substituted"
        )
    identity = {
        key: base[key]
        for key in (
            "campaign_id",
            "generation_id",
            "attempt_id",
            "attempt_spec_sha256",
        )
    }
    supervisory_handoff = _runner_field(
        runner_spec, "supervisory_handoff"
    )
    supervisory_path_fields = (
        _runner_field(runner_spec, "supervisory_handoff_path"),
        _runner_field(
            runner_spec,
            "supervisory_handoff_binding_receipt_path",
        ),
    )
    supervisory_digest_fields = (
        _runner_field(runner_spec, "supervisory_handoff_sha256"),
        _runner_field(
            runner_spec,
            "supervisory_handoff_binding_receipt_sha256",
        ),
    )
    if supervisory_handoff is None:
        if any(
            value is not None
            for value in (
                *supervisory_path_fields,
                *supervisory_digest_fields,
            )
        ):
            raise ContainerContractError(
                "runner no-handoff attempt carries supervisory fields"
            )
    else:
        if (
            any(
                not isinstance(value, str)
                for value in supervisory_path_fields
            )
            or any(
                not _is_hex_sha256(value)
                for value in supervisory_digest_fields
            )
        ):
            raise ContainerContractError(
                "runner supervisory input fields are malformed"
            )
        supervisory_paths = tuple(
            Path(str(value)) for value in supervisory_path_fields
        )
        if supervisory_paths != (
            Path(_runner_field(runner_spec, "input_dir"))
            / "supervisory_handoff.json",
            Path(_runner_field(runner_spec, "input_dir"))
            / "supervisory_handoff_binding_receipt.json",
        ):
            raise ContainerContractError(
                "runner supervisory input paths escape the input bundle"
            )

    def reopen(
        path_field: str,
        digest_field: str,
        kind: str,
    ) -> dict[str, Any]:
        path = Path(getattr(wip, path_field))
        digest = getattr(wip, digest_field)
        if (
            _hash_unaliased_regular_file(
                path, label=f"runner WIP {kind}"
            )
            != digest
        ):
            raise ContainerContractError(
                f"runner WIP {kind} hash changed"
            )
        receipt = _read_unaliased_json(
            path, label=f"runner WIP {kind}"
        )
        if (
            receipt.get("schema") != 1
            or receipt.get("kind") != kind
            or any(
                receipt.get(key) != value
                for key, value in identity.items()
            )
        ):
            raise ContainerContractError(
                f"runner WIP {kind} identity differs"
            )
        return receipt

    wip_export = reopen(
        "wip_export_receipt_path",
        "wip_export_receipt_sha256",
        "contiguous_wip_export",
    )
    final_chain = reopen(
        "final_transcript_chain_receipt_path",
        "final_transcript_chain_receipt_sha256",
        "contiguous_final_transcript_chain",
    )
    controller_scan = reopen(
        "controller_state_scan_receipt_path",
        "controller_state_scan_receipt_sha256",
        "contiguous_controller_state_scan",
    )
    retained_scan = reopen(
        "retained_canary_scan_receipt_path",
        "retained_canary_scan_receipt_sha256",
        "contiguous_retained_canary_scan",
    )
    taint_scan = reopen(
        "taint_scan_receipt_path",
        "taint_scan_receipt_sha256",
        "contiguous_taint_scan",
    )
    token_usage = reopen(
        "token_usage_receipt_path",
        "token_usage_receipt_sha256",
        "contiguous_token_usage",
    )
    provider_usage = reopen(
        "provider_usage_receipt_path",
        "provider_usage_receipt_sha256",
        "contiguous_provider_usage",
    )
    final_binding = reopen(
        "final_thread_binding_path",
        "final_thread_binding_sha256",
        "contiguous_final_thread_binding",
    )
    provider_fields = {
        "schema",
        "kind",
        "campaign_id",
        "generation_id",
        "attempt_id",
        "attempt_spec_sha256",
        "thread_id",
        "turn_id",
        "token_usage_observations",
        "pre_provider_usage_window",
        "post_provider_usage_window",
        "provider_usage_settlement",
    }
    try:
        pre_window = probe_transport.provider_usage_window_from_dict(
            provider_usage["pre_provider_usage_window"]
        )
        post_window = probe_transport.provider_usage_window_from_dict(
            provider_usage["post_provider_usage_window"]
        )
        probe_transport.provider_usage_settlement_from_dict(
            provider_usage["provider_usage_settlement"],
            pre=pre_window,
            post=post_window,
            token_usage_observations=(
                provider_usage["token_usage_observations"]
            ),
        )
    except Exception as exc:
        raise ContainerContractError(
            "runner WIP provider usage is not independently settleable"
        ) from exc
    expected_final_hashes = {
        "final_transcript_chain_receipt_sha256":
            wip.final_transcript_chain_receipt_sha256,
        "token_usage_receipt_sha256":
            wip.token_usage_receipt_sha256,
        "provider_usage_receipt_sha256":
            wip.provider_usage_receipt_sha256,
        "app_server_state_tree_sha256":
            wip.app_server_state_tree_sha256,
        "controller_state_scan_receipt_sha256":
            wip.controller_state_scan_receipt_sha256,
        "retained_canary_scan_receipt_sha256":
            wip.retained_canary_scan_receipt_sha256,
        "taint_scan_receipt_sha256":
            wip.taint_scan_receipt_sha256,
        "wip_export_receipt_sha256":
            wip.wip_export_receipt_sha256,
    }
    if (
        set(provider_usage) != provider_fields
        or provider_usage.get("thread_id") != wip.codex_thread_id
        or provider_usage.get("token_usage_observations")
        != token_usage.get("observations")
        or final_chain.get("thread_id") != wip.codex_thread_id
        or final_chain.get("chain_head_sha256")
        != wip.transcript_chain_sha256
        or taint_scan.get("status") != "CLEAN"
        or taint_scan.get("hits") != []
        or controller_scan.get("scanner_source_sha256") is None
        or retained_scan.get("retained_canary_scan") is None
        or wip_export.get("wip_root_path") != wip.wip_root_path
        or wip_export.get("wip_tree_sha256")
        != wip.wip_tree_sha256
        or wip_export.get("solver_source_path")
        != wip.solver_source_path
        or wip_export.get("solver_source_tree_sha256")
        != wip.solver_source_tree_sha256
        or final_binding.get("thread_id") != wip.codex_thread_id
        or final_binding.get("transcript_chain_sha256")
        != wip.transcript_chain_sha256
        or any(
            final_binding.get(key) != value
            for key, value in expected_final_hashes.items()
        )
    ):
        raise ContainerContractError(
            "runner WIP receipt graph is stale, tainted, or unbound"
        )


def validate_runner_attempt_contract(
    runner_spec: Any,
    *,
    recovery: bool = False,
    containment_canary_anchor: CanaryEscrowAnchor | None = None,
) -> AttemptSpec:
    """Validate the runner/backend boundary and return the low-level spec.

    This is intentionally independent of the runner's own parser.  The two
    modules therefore fail if either side drops a security-critical field.
    Arena endpoint files are backend-owned and may be absent at this stage.
    """
    if not isinstance(recovery, bool):
        raise ContainerContractError("runner recovery mode must be boolean")
    if (
        containment_canary_anchor is not None
        and not isinstance(
            containment_canary_anchor, CanaryEscrowAnchor
        )
    ):
        raise ContainerContractError(
            "runner proposer canary anchor has the wrong type"
        )
    try:
        fields = vars(runner_spec)
    except TypeError as exc:
        raise ContainerContractError(
            "runner attempt spec must expose frozen dataclass fields"
        ) from exc
    missing = sorted(RUNNER_ATTEMPT_SECURITY_FIELDS - set(fields))
    if missing:
        raise ContainerContractError(
            f"runner attempt spec drops backend security fields: {missing}"
        )
    extra = sorted(set(fields) - RUNNER_ATTEMPT_SECURITY_FIELDS)
    if extra:
        raise ContainerContractError(
            f"runner attempt spec adds unreviewed fields: {extra}"
        )
    supervisory_handoff = _runner_field(
        runner_spec, "supervisory_handoff"
    )
    supervisory_path_fields = (
        _runner_field(runner_spec, "supervisory_handoff_path"),
        _runner_field(
            runner_spec,
            "supervisory_handoff_binding_receipt_path",
        ),
    )
    supervisory_digest_fields = (
        _runner_field(runner_spec, "supervisory_handoff_sha256"),
        _runner_field(
            runner_spec,
            "supervisory_handoff_binding_receipt_sha256",
        ),
    )
    if supervisory_handoff is None:
        if any(
            value is not None
            for value in (
                *supervisory_path_fields,
                *supervisory_digest_fields,
            )
        ):
            raise ContainerContractError(
                "runner no-handoff attempt carries supervisory fields"
            )
    else:
        if (
            any(
                not isinstance(value, str)
                for value in supervisory_path_fields
            )
            or any(
                not _is_hex_sha256(value)
                for value in supervisory_digest_fields
            )
        ):
            raise ContainerContractError(
                "runner supervisory input fields are malformed"
            )
        supervisory_paths = tuple(
            Path(str(value)) for value in supervisory_path_fields
        )
        if supervisory_paths != (
            Path(_runner_field(runner_spec, "input_dir"))
            / "supervisory_handoff.json",
            Path(_runner_field(runner_spec, "input_dir"))
            / "supervisory_handoff_binding_receipt.json",
        ):
            raise ContainerContractError(
                "runner supervisory input paths escape the input bundle"
            )
    try:
        import arc_agi3_contiguous_runner as runner_contract
    except ImportError as exc:
        raise ContainerContractError(
            "runner contract module is unavailable"
        ) from exc
    if _runner_field(runner_spec, "schema") != runner_contract.RUNNER_SCHEMA:
        raise ContainerContractError("runner attempt schema is not supported")
    for label in ("campaign_id", "generation_id", "attempt_id"):
        _canonical_uuid4(_runner_field(runner_spec, label), label=label)
    if len(
        {
            _runner_field(runner_spec, label)
            for label in ("campaign_id", "generation_id", "attempt_id")
        }
    ) != 3:
        raise ContainerContractError(
            "campaign, generation, and attempt UUIDs must be distinct"
        )
    identity = AttemptIdentity(
        campaign_id=_runner_field(runner_spec, "campaign_id"),
        generation_id=_runner_field(runner_spec, "generation_id"),
        attempt_id=_runner_field(runner_spec, "attempt_id"),
        game=_runner_field(runner_spec, "game"),
        target_level=_runner_field(runner_spec, "target_level"),
    )
    identity.validate()
    authoritative_target = _runner_field(
        runner_spec, "authoritative_target"
    )
    if (
        isinstance(authoritative_target, bool)
        or not isinstance(authoritative_target, int)
        or authoritative_target < identity.target_level
    ):
        raise ContainerContractError(
            "authoritative target must cover the exact requested level"
        )
    declared_parent_sha256 = _runner_field(
        runner_spec, "parent_checkpoint_sha256"
    )
    if not _is_hex_sha256(declared_parent_sha256):
        raise ContainerContractError(
            "runner parent checkpoint hash is malformed"
        )
    try:
        expected_frontier = runner_contract.frontier_sha256(
            identity.game,
            identity.target_level - 1,
            declared_parent_sha256,
        )
    except Exception as exc:
        raise ContainerContractError(
            "runner frontier binding could not be derived"
        ) from exc
    if _runner_field(runner_spec, "frontier_sha256") != expected_frontier:
        raise ContainerContractError(
            "runner frontier hash does not bind the exact admitted edge"
        )
    effort = _runner_field(runner_spec, "effort")
    if effort not in {"medium", "high", "xhigh", "max"}:
        raise ContainerContractError("runner effort is outside the escalation schema")
    remaining = _runner_field(runner_spec, "cost_limit_remaining")
    if remaining is not None and (
        isinstance(remaining, bool)
        or not isinstance(remaining, (int, float))
        or not math.isfinite(remaining)
        or remaining < 0
    ):
        raise ContainerContractError(
            "runner cost limit must be null or a nonnegative finite value"
        )
    hard_safety_seconds, max_auth_refreshes = (
        _app_server_hard_limits()
    )
    if (
        _runner_field(runner_spec, "hard_safety_seconds")
        != hard_safety_seconds
        or _runner_field(runner_spec, "max_auth_refreshes")
        != max_auth_refreshes
        or _runner_field(runner_spec, "soft_allocation_seconds")
        >= hard_safety_seconds
    ):
        raise ContainerContractError(
            "runner app-server hard lifetime/refresh contract is inconsistent"
        )
    image_reference = _runner_field(runner_spec, "image_reference")
    _, image_digest = parse_digest_reference(image_reference)
    if image_digest != _runner_field(runner_spec, "image_digest"):
        raise ContainerContractError(
            "runner image reference and image digest disagree"
        )
    worker_command = _runner_field(runner_spec, "worker_command")
    if not isinstance(worker_command, tuple) or worker_command != (
        expected_proposer_worker_command()
    ):
        raise ContainerContractError(
            "runner worker command is not the exact pinned proposer command"
        )
    _validate_proposer_transport(
        _runner_field(runner_spec, "proposer_transport")
    )
    runner_limits = _runner_field(runner_spec, "resource_limits")
    try:
        limits = ResourceLimits(
            cpus=runner_limits.cpus,
            memory_bytes=runner_limits.memory_bytes,
            pids=runner_limits.pids,
            tmpfs_bytes=runner_limits.tmpfs_bytes,
        )
    except AttributeError as exc:
        raise ContainerContractError(
            "runner resource-limit projection is incomplete"
        ) from exc
    limits.validate()
    paths = {
        name: Path(_runner_field(runner_spec, name))
        for name in (
            "generation_dir",
            "input_dir",
            "scratch_dir",
            "workspace_dir",
            "output_dir",
            "arena_socket_path",
            "arena_token_file_path",
            "bridge_dir",
            "bridge_socket_path",
            "bridge_token_file_path",
            "bridge_policy_receipt_path",
            "host_transcript_path",
            "app_server_transcript_path",
            "neutral_host_cwd_path",
            "app_server_state_dir",
            "app_server_control_dir",
            "parent_checkpoint_path",
            "parent_source_path",
            "input_bundle_receipt_path",
            "frontier_brief_path",
            "bridge_policy_path",
        )
    }
    if any(
        not path.is_absolute()
        or Path(os.path.abspath(os.fspath(path))) != path
        for path in paths.values()
    ):
        raise ContainerContractError(
            "runner attempt paths must be absolute and canonical"
        )
    generation = paths["generation_dir"]
    host_root = generation / "host"
    expected_layout = {
        "input_dir": generation / "input",
        "scratch_dir": generation / "scratch",
        "workspace_dir": generation / "scratch",
        "output_dir": generation / "output",
        "arena_socket_path": generation / "rpc" / "arena.sock",
        "arena_token_file_path": generation / "rpc" / "token",
        "bridge_dir": generation / "bridge",
        "bridge_socket_path": generation / "bridge" / "proposer.sock",
        "bridge_token_file_path":
            generation / "bridge" / "proposer-token",
        "bridge_policy_receipt_path":
            host_root / "bridge_policy_receipt.json",
        "host_transcript_path": host_root / "backend.jsonl",
        "app_server_transcript_path": host_root / "app_server.jsonl",
        "neutral_host_cwd_path": host_root / "neutral",
        "app_server_control_dir": host_root / "app_server_control",
        "input_bundle_receipt_path":
            generation / "input_bundle_receipt.json",
        "frontier_brief_path": generation / "input" / "frontier_brief.json",
        "bridge_policy_path": generation / "input" / "bridge_policy.json",
    }
    if any(paths[name] != expected for name, expected in expected_layout.items()):
        raise ContainerContractError(
            "runner attempt paths do not match the unique generation layout"
        )
    if generation.name != identity.generation_id:
        raise ContainerContractError(
            "runner generation path does not bind generation UUID"
        )
    parent_source_root = paths["parent_source_path"]
    try:
        parent_source_root.relative_to(generation)
        source_overlaps_generation = True
    except ValueError:
        try:
            generation.relative_to(parent_source_root)
            source_overlaps_generation = True
        except ValueError:
            source_overlaps_generation = False
    if source_overlaps_generation:
        raise ContainerContractError(
            "lane-bound parent source overlaps the mutable attempt generation"
        )
    state_root = paths["app_server_state_dir"]
    if (
        state_root.name != "codex_home"
        or state_root.parent.name != "state"
        or state_root.parent.parent != generation
    ):
        raise ContainerContractError(
            "app-server state root does not match the per-attempt layout"
        )
    for directory in (
        generation,
        paths["input_dir"],
        paths["scratch_dir"],
        paths["output_dir"],
        paths["arena_socket_path"].parent,
        paths["bridge_dir"],
        paths["host_transcript_path"].parent,
        paths["neutral_host_cwd_path"],
        paths["app_server_state_dir"],
        paths["app_server_control_dir"],
    ):
        _validate_private_host_directory(directory)
    for label, socket_path in (
        ("Arena RPC", paths["arena_socket_path"]),
        ("proposer bridge", paths["bridge_socket_path"]),
    ):
        if len(os.fsencode(socket_path)) > (
            MAX_PORTABLE_UNIX_SOCKET_PATH_BYTES
        ):
            raise ContainerContractError(
                f"{label} socket path exceeds the portable Unix-domain limit"
            )
    if len(
        {
            (path.lstat().st_dev, path.lstat().st_ino)
            for path in (
                paths["input_dir"],
                paths["scratch_dir"],
                paths["output_dir"],
                paths["arena_socket_path"].parent,
                paths["bridge_dir"],
                paths["host_transcript_path"].parent,
                paths["neutral_host_cwd_path"],
                paths["app_server_state_dir"],
                paths["app_server_control_dir"],
            )
        }
    ) != 9:
        raise ContainerContractError(
            "runner generation directories are filesystem aliases"
        )
    neutral_metadata = paths["neutral_host_cwd_path"].lstat()
    if stat.S_IMODE(neutral_metadata.st_mode) & 0o222:
        raise ContainerContractError(
            "neutral host cwd must be supervisor-owned and read-only"
        )
    parent_digest = _hash_unaliased_regular_file(
        paths["parent_checkpoint_path"],
        label="runner parent checkpoint",
    )
    if parent_digest != _runner_field(
        runner_spec, "parent_checkpoint_sha256"
    ):
        raise ContainerContractError(
            "runner parent checkpoint hash changed before backend admission"
        )
    input_root = paths["input_dir"]
    try:
        import arc_agi3_contiguous_supervisor as supervisor_contract

        supervisor_contract._validate_regular_tree(
            input_root, label="runner input bundle"
        )
        input_tree_sha256 = supervisor_contract._tree_hash(input_root)
        parent_source = input_root / "parent_source"
        supervisor_contract._validate_regular_tree(
            parent_source, label="runner parent source"
        )
        parent_source_tree_sha256 = supervisor_contract._tree_hash(
            parent_source
        )
        supervisor_contract._validate_regular_tree(
            parent_source_root, label="lane-bound parent source"
        )
        lane_parent_source_tree_sha256 = supervisor_contract._tree_hash(
            parent_source_root
        )
        workspace_root = paths["workspace_dir"]
        supervisor_contract._validate_regular_tree(
            workspace_root, label="runner initial workspace"
        )
        initial_workspace_tree_sha256 = supervisor_contract._tree_hash(
            workspace_root
        )
        initial_app_server_state_tree_sha256 = (
            supervisor_contract._tree_hash(state_root)
        )
    except Exception as exc:
        raise ContainerContractError(
            "runner input/workspace failed the supervisor regular-tree contract"
        ) from exc
    if input_tree_sha256 != _runner_field(
        runner_spec, "input_tree_sha256"
    ):
        raise ContainerContractError("runner input bundle hash changed")
    if (
        parent_source_tree_sha256
        != _runner_field(runner_spec, "parent_source_tree_sha256")
        or lane_parent_source_tree_sha256
        != parent_source_tree_sha256
        or initial_workspace_tree_sha256
        != _runner_field(runner_spec, "initial_workspace_tree_sha256")
        or initial_app_server_state_tree_sha256
        != _runner_field(
            runner_spec, "initial_app_server_state_tree_sha256"
        )
    ):
        raise ContainerContractError(
            "runner parent source, workspace, or staged state hash changed"
        )
    source_names = {
        entry.name for entry in parent_source.iterdir()
        if entry.is_file()
    }
    if (
        not {"legs.py", "players.py", "solve.py"} <= source_names
        or source_names - {
            "legs.py", "players.py", "solve.py", "perception.py"
        }
    ):
        raise ContainerContractError(
            "runner parent source inventory is incomplete or unreviewed"
        )
    for name in source_names:
        _hash_unaliased_regular_file(
            parent_source / name, label="runner parent solver source"
        )
    if _hash_unaliased_regular_file(
        input_root / "checkpoint.json",
        label="bundled parent checkpoint",
    ) != parent_digest:
        raise ContainerContractError(
            "input bundle substituted the trusted parent checkpoint"
        )
    parent_action_count = _runner_field(
        runner_spec, "parent_action_count"
    )
    remaining_action_budget = _runner_field(
        runner_spec, "remaining_action_budget"
    )
    fresh_prefix_required = _runner_field(
        runner_spec, "fresh_prefix_required"
    )
    if (
        isinstance(parent_action_count, bool)
        or not isinstance(parent_action_count, int)
        or not 0 <= parent_action_count <= 600
        or isinstance(remaining_action_budget, bool)
        or not isinstance(remaining_action_budget, int)
        or remaining_action_budget != 600 - parent_action_count
        or not isinstance(fresh_prefix_required, bool)
        or fresh_prefix_required is not (remaining_action_budget == 0)
    ):
        raise ContainerContractError(
            "runner frontier action budget projection is inconsistent"
        )
    frontier_sha256 = _runner_field(runner_spec, "frontier_sha256")
    if not _is_hex_sha256(frontier_sha256):
        raise ContainerContractError("runner frontier hash is malformed")
    frontier_brief_path = paths["frontier_brief_path"]
    frontier_brief_sha256 = _hash_unaliased_regular_file(
        frontier_brief_path, label="runner frontier brief"
    )
    if frontier_brief_sha256 != _runner_field(
        runner_spec, "frontier_brief_sha256"
    ) or _read_unaliased_json(
        frontier_brief_path, label="runner frontier brief"
    ) != _expected_frontier_brief_document(runner_spec):
        raise ContainerContractError(
            "runner frontier brief is stale or nonminimal"
        )
    supervisory_handoff_sha256 = _runner_field(
        runner_spec, "supervisory_handoff_sha256"
    )
    supervisory_binding_receipt_sha256 = _runner_field(
        runner_spec,
        "supervisory_handoff_binding_receipt_sha256",
    )
    if supervisory_handoff is not None:
        handoff_path = Path(str(supervisory_path_fields[0]))
        handoff_receipt_path = Path(
            str(supervisory_path_fields[1])
        )
        if (
            _hash_unaliased_regular_file(
                handoff_path,
                label="runner supervisory handoff",
            )
            != supervisory_handoff_sha256
            or _hash_unaliased_regular_file(
                handoff_receipt_path,
                label="runner supervisory handoff binding receipt",
            )
            != supervisory_binding_receipt_sha256
        ):
            raise ContainerContractError(
                "runner supervisory prompt bytes changed"
            )
        prompt_projection = (
            _runner_contract().Scheduler
            .supervisory_prompt_projection(supervisory_handoff)
        )
        binding_receipt = _read_unaliased_json(
            handoff_receipt_path,
            label="runner supervisory handoff binding receipt",
        )
        expected_binding_receipt = {
            "schema": 1,
            "kind": "contiguous_supervisory_handoff_prompt_binding",
            "campaign_id": identity.campaign_id,
            "generation_id": identity.generation_id,
            "attempt_id": identity.attempt_id,
            "game": identity.game,
            "frontier_sha256": _runner_field(
                runner_spec, "frontier_sha256"
            ),
            "parent_checkpoint_sha256": _runner_field(
                runner_spec, "parent_checkpoint_sha256"
            ),
            "assignment_id": supervisory_handoff.assignment_id,
            "output_manifest_sha256":
                supervisory_handoff.output_manifest_sha256,
            "supervisory_handoff_sha256":
                supervisory_handoff.supervisory_handoff_sha256,
            "handoff_file_sha256": supervisory_handoff_sha256,
            "admission_receipt_sha256":
                supervisory_handoff.admission_receipt_sha256,
            "prompt_authority": "unverified_hypothesis_only",
            "native_reproduction_required_before_wip_candidate_or_promotion":
                True,
            "scheduler_authority": False,
            "mutation_authority": False,
            "promotion_authority": False,
        }
        if (
            _read_unaliased_json(
                handoff_path,
                label="runner supervisory handoff",
            )
            != prompt_projection
            or binding_receipt != expected_binding_receipt
        ):
            raise ContainerContractError(
                "runner supervisory prompt projection is substituted"
            )
    bridge_policy_path = paths["bridge_policy_path"]
    bridge_policy_sha256 = _hash_unaliased_regular_file(
        bridge_policy_path, label="runner bridge policy"
    )
    if bridge_policy_sha256 != _runner_field(
        runner_spec, "bridge_policy_sha256"
    ):
        raise ContainerContractError("runner bridge policy hash changed")
    bridge_policy = _read_unaliased_json(
        bridge_policy_path, label="runner bridge policy"
    )
    expected_bridge_policy = _expected_bridge_policy_document(runner_spec)
    if bridge_policy != expected_bridge_policy:
        raise ContainerContractError(
            "runner bridge policy does not bind the exact proposer capability"
        )
    receipt_path = paths["input_bundle_receipt_path"]
    receipt_sha256 = _hash_unaliased_regular_file(
        receipt_path, label="runner input-bundle receipt"
    )
    if receipt_sha256 != _runner_field(
        runner_spec, "input_bundle_receipt_sha256"
    ):
        raise ContainerContractError("runner input-bundle receipt hash changed")
    receipt = _read_unaliased_json(
        receipt_path, label="runner input-bundle receipt"
    )
    required_receipt = {
        "schema",
        "campaign_id",
        "generation_id",
        "attempt_id",
        "game",
        "target_level",
        "frontier_sha256",
            "input_tree_sha256",
            "parent_source_tree_sha256",
            "initial_workspace_tree_sha256",
        "parent_checkpoint_sha256",
        "wip_tree_sha256",
        "wip_solver_source_tree_sha256",
        "frontier_brief_sha256",
        "bridge_policy_sha256",
        "parent_action_count",
        "remaining_action_budget",
        "fresh_prefix_required",
        "supervisory_handoff_sha256",
        "supervisory_handoff_binding_receipt_sha256",
    }
    wip = getattr(runner_spec, "wip", None)
    expected_wip_hash = getattr(wip, "wip_tree_sha256", None)
    expected_wip_source_hash = getattr(
        wip, "solver_source_tree_sha256", None
    )
    expected_input_entries = {
        "bridge_policy.json",
        "checkpoint.json",
        "frontier_brief.json",
        "parent_source",
    }
    if wip is not None:
        expected_input_entries.add("wip")
    if supervisory_handoff is not None:
        expected_input_entries.update({
            "supervisory_handoff.json",
            "supervisory_handoff_binding_receipt.json",
        })
    if (
        {entry.name for entry in input_root.iterdir()}
        != expected_input_entries
        or _hash_unaliased_regular_file(
            paths["workspace_dir"] / "checkpoint.json",
            label="workspace parent checkpoint",
        )
        != parent_digest
        or _hash_unaliased_regular_file(
            paths["workspace_dir"] / "frontier_brief.json",
            label="workspace frontier brief",
        )
        != frontier_brief_sha256
    ):
        raise ContainerContractError(
            "runner input/workspace top-level projection is substituted"
        )
    if (
        set(receipt) != required_receipt
        or receipt["schema"] != _runner_field(runner_spec, "schema")
        or receipt["campaign_id"] != identity.campaign_id
        or receipt["generation_id"] != identity.generation_id
        or receipt["attempt_id"] != identity.attempt_id
        or receipt["game"] != identity.game
        or receipt["target_level"] != identity.target_level
        or receipt["frontier_sha256"] != frontier_sha256
        or receipt["input_tree_sha256"] != input_tree_sha256
        or receipt["parent_source_tree_sha256"]
        != parent_source_tree_sha256
        or receipt["initial_workspace_tree_sha256"]
        != initial_workspace_tree_sha256
        or receipt["parent_checkpoint_sha256"] != parent_digest
        or receipt["wip_tree_sha256"] != expected_wip_hash
        or receipt["wip_solver_source_tree_sha256"]
        != expected_wip_source_hash
        or receipt["frontier_brief_sha256"] != frontier_brief_sha256
        or receipt["bridge_policy_sha256"] != bridge_policy_sha256
        or receipt["parent_action_count"] != parent_action_count
        or receipt["remaining_action_budget"]
        != remaining_action_budget
        or receipt["fresh_prefix_required"] is not fresh_prefix_required
        or receipt["supervisory_handoff_sha256"]
        != supervisory_handoff_sha256
        or receipt[
            "supervisory_handoff_binding_receipt_sha256"
        ]
        != supervisory_binding_receipt_sha256
    ):
        raise ContainerContractError(
            "runner input-bundle receipt does not bind the admitted lineage"
        )
    wip = getattr(runner_spec, "wip", None)
    wip_mode = _runner_field(runner_spec, "wip_mode")
    if wip_mode == "exclude":
        if wip is not None:
            raise ContainerContractError(
                "runner exclude mode cannot carry a WIP snapshot"
            )
    elif wip_mode == "restore_clean_same_frontier":
        if wip is None:
            raise ContainerContractError(
                "runner restore mode requires a WIP snapshot"
            )
        try:
            wip_path = Path(wip.wip_root_path)
            wip_source_path = Path(wip.solver_source_path)
            wip_game = wip.game
            wip_target = wip.target_level
            wip_parent = wip.parent_checkpoint_sha256
            wip_frontier = wip.frontier_sha256
            wip_tree = wip.wip_tree_sha256
            wip_source_tree = wip.solver_source_tree_sha256
            wip_taint = wip.taint_verdict
        except AttributeError as exc:
            raise ContainerContractError(
                "runner WIP projection is incomplete"
            ) from exc
        if (
            not wip_path.is_absolute()
            or Path(os.path.abspath(os.fspath(wip_path))) != wip_path
            or wip_game != identity.game
            or wip_target != identity.target_level
            or wip_parent != parent_digest
            or wip_frontier != frontier_sha256
            or not _is_hex_sha256(wip_tree)
            or not _is_hex_sha256(wip_source_tree)
            or wip_source_path.parent != wip_path
            or wip_source_path.name != WIP_SOLVER_SOURCE_DIRECTORY
            or wip_taint != "clean"
        ):
            raise ContainerContractError(
                "runner WIP does not bind the exact clean frontier"
            )
        try:
            supervisor_contract._validate_regular_tree(
                wip_path, label="runner WIP snapshot"
            )
            if (
                {
                    entry.name for entry in wip_path.iterdir()
                }
                - {WIP_SOLVER_SOURCE_DIRECTORY, "context"}
                or any(
                    not entry.is_file()
                    for entry in wip_source_path.iterdir()
                )
            ):
                raise ContainerContractError(
                    "runner WIP/source has an undeclared shape"
                )
            observed_wip_hash = supervisor_contract._tree_hash(wip_path)
            source_contract = __import__(
                "arc_agi3_source_schema"
            )
            source_payloads = {
                entry.name: _read_unaliased_bytes(
                    entry,
                    label=f"runner WIP source {entry.name}",
                    maximum_bytes=MAX_INPUT_FILE_BYTES,
                )
                for entry in wip_source_path.iterdir()
                if entry.is_file()
            }
            source_contract.validate_source_payloads(source_payloads)
            observed_wip_source_hash = (
                supervisor_contract._tree_hash(wip_source_path)
            )
        except Exception as exc:
            raise ContainerContractError(
                "runner WIP failed the supervisor regular-tree contract"
            ) from exc
        if observed_wip_hash != wip_tree:
            raise ContainerContractError(
                "runner WIP changed before backend admission"
            )
        if observed_wip_source_hash != wip_source_tree:
            raise ContainerContractError(
                "runner WIP solver source changed before backend admission"
            )
        _validate_runner_wip_evidence_graph(runner_spec, wip)
    else:
        raise ContainerContractError("runner WIP mode is unsupported")
    thread_mode = _runner_field(runner_spec, "thread_mode")
    resume_thread_id = _runner_field(runner_spec, "resume_thread_id")
    resume_binding_sha256 = _runner_field(
        runner_spec, "resume_thread_binding_sha256"
    )
    if thread_mode == "new":
        if (
            wip_mode != "exclude"
            or resume_thread_id is not None
            or resume_binding_sha256 is not None
        ):
            raise ContainerContractError(
                "new proposer thread cannot import prior thread state"
            )
    elif thread_mode == "resume":
        try:
            wip_thread_id = wip.codex_thread_id
            wip_binding_path = Path(
                wip.final_thread_binding_path
            )
            wip_binding_sha256 = (
                wip.final_thread_binding_sha256
            )
            wip_transcript_sha256 = wip.transcript_chain_sha256
            wip_state_dir = Path(wip.app_server_state_dir)
            wip_state_tree_sha256 = wip.app_server_state_tree_sha256
        except (AttributeError, TypeError) as exc:
            raise ContainerContractError(
                "resumed WIP lacks complete thread lineage"
            ) from exc
        if (
            wip_mode != "restore_clean_same_frontier"
            or not _is_canonical_uuid(resume_thread_id)
            or resume_thread_id != wip_thread_id
            or not _is_hex_sha256(resume_binding_sha256)
            or resume_binding_sha256 != wip_binding_sha256
            or not wip_binding_path.is_absolute()
            or Path(os.path.abspath(os.fspath(wip_binding_path)))
            != wip_binding_path
            or _hash_unaliased_regular_file(
                wip_binding_path, label="resumed thread binding"
            )
            != wip_binding_sha256
            or not _is_hex_sha256(wip_transcript_sha256)
            or not wip_state_dir.is_absolute()
            or Path(os.path.abspath(os.fspath(wip_state_dir)))
            != wip_state_dir
            or wip_state_dir == paths["app_server_state_dir"]
            or not _is_hex_sha256(wip_state_tree_sha256)
            or _validated_tree_hash(
                wip_state_dir, label="prior immutable Codex state"
            )
            != wip_state_tree_sha256
            or _validated_tree_hash(
                paths["app_server_state_dir"],
                label="staged per-attempt Codex state",
            )
            != wip_state_tree_sha256
        ):
            raise ContainerContractError(
                "resumed proposer thread does not bind the exact clean WIP"
            )
    else:
        raise ContainerContractError(
            "runner thread mode is unsupported"
        )
    # The backend owns these paths.  Existing endpoints would allow a stale or
    # cross-attempt channel to be mounted into a fresh preparation.
    if not recovery:
        for label, path in (
            ("Arena RPC socket", paths["arena_socket_path"]),
            ("Arena RPC token", paths["arena_token_file_path"]),
            ("proposer bridge socket", paths["bridge_socket_path"]),
            ("proposer bridge token", paths["bridge_token_file_path"]),
            (
                "bridge policy receipt",
                paths["bridge_policy_receipt_path"],
            ),
            ("host transcript", paths["host_transcript_path"]),
            (
                "app-server transcript",
                paths["app_server_transcript_path"],
            ),
        ):
            if path.exists() or path.is_symlink():
                raise ContainerContractError(
                    f"fresh runner preparation has a preexisting {label}"
                )
        for label, path, require_empty in (
            (
                "runner workspace",
                paths["workspace_dir"],
                False,
            ),
            ("runner bridge root", paths["bridge_dir"], True),
            (
                "neutral host cwd",
                paths["neutral_host_cwd_path"],
                True,
            ),
            (
                "app-server state root",
                paths["app_server_state_dir"],
                thread_mode == "new",
            ),
            (
                "app-server control root",
                paths["app_server_control_dir"],
                True,
            ),
        ):
            _snapshot_mount_root(
                path,
                label=label,
                require_empty=require_empty,
                require_private=True,
            )
    # Snapshotting the export root enforces empty/private/no-alias admission.
    _snapshot_mount_root(
        paths["output_dir"],
        label="runner output root",
        require_empty=not recovery,
        require_private=True,
    )
    low_spec = AttemptSpec(
        identity=identity,
        image_reference=image_reference,
        parent_input=input_root,
        export_root=paths["output_dir"],
        arena_socket=paths["arena_socket_path"],
        arena_token_file=paths["arena_token_file_path"],
        command=worker_command,
        resource_limits=limits,
        soft_allocation_seconds=_runner_field(
            runner_spec, "soft_allocation_seconds"
        ),
        role="proposer",
        workspace_root=paths["workspace_dir"],
        bridge_root=paths["bridge_dir"],
        bridge_socket=paths["bridge_socket_path"],
        bridge_token_file=paths["bridge_token_file_path"],
        containment_canary_anchor=containment_canary_anchor,
    )
    low_spec.validate()
    return low_spec


def decide_soft_allocation(
    *,
    elapsed_seconds: float,
    soft_allocation_seconds: float,
    proposer_active: bool,
) -> SoftAllocationDecision:
    """Move a live turn to DRAINING without emitting a container signal."""
    for label, value, allow_zero in (
        ("elapsed_seconds", elapsed_seconds, True),
        ("soft_allocation_seconds", soft_allocation_seconds, False),
    ):
        if (
            isinstance(value, bool)
            or not isinstance(value, (int, float))
            or not math.isfinite(value)
            or value < 0
            or (not allow_zero and value == 0)
        ):
            qualifier = "nonnegative" if allow_zero else "positive"
            raise ContainerContractError(f"{label} must be a {qualifier} number")
    if not isinstance(proposer_active, bool):
        raise ContainerContractError("proposer_active must be boolean")
    expired = elapsed_seconds >= soft_allocation_seconds
    if proposer_active:
        return SoftAllocationDecision(
            phase="DRAINING" if expired else "PROPOSING",
            launch_new_turn=False,
        )
    return SoftAllocationDecision(
        phase="ALLOCATION_COMPLETE" if expired else "READY",
        launch_new_turn=not expired,
    )


class DockerContainerBackend:
    """Docker CLI backend whose decisions are based on inspected evidence."""

    def __init__(
        self,
        runner: CommandRunner,
        *,
        docker_binary: str = "docker",
    ) -> None:
        if (
            not isinstance(docker_binary, str)
            or not docker_binary
            or "\x00" in docker_binary
        ):
            raise ContainerContractError("docker_binary must be a nonempty string")
        if (
            isinstance(runner, SubprocessCommandRunner)
            and not Path(docker_binary).is_absolute()
        ):
            raise ContainerContractError(
                "production Docker executable must be an absolute path"
            )
        self._runner = runner
        self._docker = docker_binary

    def inspect_image(self, reference: str) -> ImageObservation:
        _, requested_digest = parse_digest_reference(reference)
        result = self._required(
            (self._docker, "image", "inspect", reference),
            timeout_seconds=30,
            label="image inspection",
        )
        observed = _parse_single_inspect_object(
            result.stdout, label="image inspection"
        )
        image_id = _required_digest(observed, "Id", label="image Id")
        repo_digests_value = _required_list(
            observed, "RepoDigests", label="image RepoDigests"
        )
        if not repo_digests_value or not all(
            isinstance(value, str) for value in repo_digests_value
        ):
            raise ContainerContractError(
                "image inspection lacks repository-digest evidence"
            )
        repo_digests = tuple(sorted(repo_digests_value))
        observed_manifest_digests: set[str] = set()
        for repo_digest in repo_digests:
            try:
                _, digest = parse_digest_reference(repo_digest)
            except ContainerContractError as exc:
                raise ContainerContractError(
                    "image inspection returned a mutable or malformed RepoDigest"
                ) from exc
            observed_manifest_digests.add(digest)
        if requested_digest not in observed_manifest_digests:
            raise ContainerContractError(
                "requested image digest is not present in observed RepoDigests"
            )
        config = _required_dict(observed, "Config", label="image Config")
        env = _required_list(config, "Env", label="image Config.Env")
        environment_names = _parse_environment_names(env)
        unexpected_environment = sorted(
            set(environment_names) - ALLOWED_IMAGE_ENV_NAMES
        )
        if unexpected_environment:
            raise ContainerContractError(
                "image embeds unapproved environment names: "
                f"{unexpected_environment}"
            )
        entrypoint_value = _required_list(
            config, "Entrypoint", label="image Config.Entrypoint"
        )
        if not all(isinstance(part, str) and part for part in entrypoint_value):
            raise ContainerContractError("image entrypoint evidence is malformed")
        entrypoint = tuple(entrypoint_value)
        labels = _required_dict(config, "Labels", label="image Config.Labels")
        expected_worker_hashes = trusted_worker_hashes()
        for label, expected_hash in expected_worker_hashes.items():
            if labels.get(label) != expected_hash:
                raise ContainerContractError(
                    "image does not bind the current pinned worker controls: "
                    f"{label}"
                )
        observation_sha256 = _json_sha256(observed)
        return ImageObservation(
            requested_reference=reference,
            manifest_digest=requested_digest,
            image_id=image_id,
            repo_digests=repo_digests,
            config_environment_names=environment_names,
            entrypoint=entrypoint,
            worker_control_sha256=tuple(sorted(expected_worker_hashes.items())),
            observation_sha256=observation_sha256,
        )

    def build_create_command(
        self,
        spec: AttemptSpec,
        *,
        image: ImageObservation,
        parent: MountObservation,
        export: MountObservation,
        arena_socket: EndpointObservation,
        arena_token_file: EndpointObservation,
        workspace: MountObservation | None = None,
        bridge: MountObservation | None = None,
        bridge_token_file: EndpointObservation | None = None,
    ) -> tuple[str, ...]:
        """Construct the exact argv used by ``docker container create``."""
        spec.validate()
        _require_same_image_reference(spec.image_reference, image)
        _require_current_mount_identity(spec.parent_input, parent, label="parent")
        _require_current_mount_identity(spec.export_root, export, label="export")
        _require_current_endpoint_identity(
            spec.arena_socket, arena_socket, label="Arena RPC socket"
        )
        _require_current_endpoint_identity(
            spec.arena_token_file,
            arena_token_file,
            label="Arena RPC token",
        )
        if spec.role == "proposer":
            if (
                workspace is None
                or bridge is None
                or bridge_token_file is None
            ):
                raise ContainerContractError(
                    "proposer create requires observed workspace and bridge roots"
                )
            _require_current_mount_identity(
                spec.workspace_root, workspace, label="workspace"
            )
            _require_current_mount_identity(
                spec.bridge_root, bridge, label="bridge"
            )
            _require_current_endpoint_identity(
                spec.bridge_token_file,
                bridge_token_file,
                label="proposer bridge token",
            )
            _reject_proposer_mount_aliases(
                parent,
                workspace,
                export,
                bridge,
                arena_socket,
                arena_token_file,
                bridge_token_file,
            )
        else:
            if any(
                value is not None
                for value in (workspace, bridge, bridge_token_file)
            ):
                raise ContainerContractError(
                    "replay create cannot receive proposer mounts"
                )
            _reject_mount_alias(parent, export)
            _reject_endpoint_aliases(
                parent,
                export,
                arena_socket,
                arena_token_file,
            )
        limits = spec.resource_limits
        identity = spec.identity
        name = _container_name(identity)
        runtime_user = _runtime_user(export)
        tmpfs = (
            f"{TMPFS_DESTINATION}:rw,nosuid,nodev,noexec,"
            f"size={limits.tmpfs_bytes},mode=1777,"
            f"uid={export.owner_uid},gid={export.owner_gid}"
        )
        parent_mount = (
            f"type=bind,src={parent.path},dst={INPUT_DESTINATION},"
            "readonly,bind-propagation=rprivate"
        )
        export_mount = (
            f"type=bind,src={export.path},dst={EXPORT_DESTINATION},"
            "bind-propagation=rprivate"
        )
        socket_mount = (
            f"type=bind,src={arena_socket.path},dst={RPC_SOCKET_DESTINATION},"
            "readonly,bind-propagation=rprivate"
        )
        arena_volume_mount = (
            f"type=volume,src={arena_volume_name(spec.identity)},"
            f"dst={PROPOSER_RPC_ROOT_DESTINATION},readonly,volume-nocopy"
        )
        token_mount = (
            f"type=bind,src={arena_token_file.path},dst={RPC_TOKEN_DESTINATION},"
            "readonly,bind-propagation=rprivate"
        )
        proposer_mounts: tuple[str, ...] = ()
        workdir = INPUT_DESTINATION
        if spec.role == "proposer":
            assert workspace is not None
            assert bridge is not None
            assert bridge_token_file is not None
            proposer_mounts = (
                (
                    f"type=bind,src={workspace.path},"
                    f"dst={WORKSPACE_DESTINATION},"
                    "bind-propagation=rprivate"
                ),
                (
                    f"type=bind,src={bridge.path},"
                    f"dst={BRIDGE_ROOT_DESTINATION},"
                    "bind-propagation=rprivate"
                ),
                (
                    f"type=bind,src={bridge_token_file.path},"
                    f"dst={BRIDGE_TOKEN_DESTINATION},"
                    "readonly,bind-propagation=rprivate"
                ),
            )
            workdir = WORKSPACE_DESTINATION
        values = (
            ("ARC_AGI3_CAMPAIGN_ID", identity.campaign_id),
            ("ARC_AGI3_GENERATION_ID", identity.generation_id),
            ("ARC_AGI3_ATTEMPT_ID", identity.attempt_id),
            ("ARC_AGI3_GAME", identity.game),
            ("ARC_AGI3_TARGET_LEVEL", str(identity.target_level)),
        )
        argv: list[str] = [
            self._docker,
            "container",
            "create",
            "--name",
            name,
            "--label",
            f"{LABEL_CAMPAIGN}={identity.campaign_id}",
            "--label",
            f"{LABEL_GENERATION}={identity.generation_id}",
            "--label",
            f"{LABEL_ATTEMPT}={identity.attempt_id}",
            "--label",
            f"{LABEL_GAME}={identity.game}",
            "--label",
            f"{LABEL_LEVEL}={identity.target_level}",
            "--label",
            f"{LABEL_ROLE}={ATTEMPT_WORKER_ROLE}",
            "--read-only",
            "--network",
            "none",
            "--cgroupns",
            "private",
            "--ipc",
            "private",
            "--cap-drop",
            "ALL",
            "--security-opt",
            "no-new-privileges=true",
            "--user",
            runtime_user,
            "--cpus",
            _format_cpus(limits.cpus),
            "--memory",
            str(limits.memory_bytes),
            "--memory-swap",
            str(limits.memory_bytes),
            "--pids-limit",
            str(limits.pids),
            "--restart",
            "no",
            "--no-healthcheck",
            "--log-driver",
            "local",
            "--log-opt",
            "max-size=4m",
            "--log-opt",
            "max-file=1",
            "--pull",
            "never",
            "--init",
            "--tmpfs",
            tmpfs,
            "--mount",
            parent_mount,
        ]
        if spec.role == "proposer":
            # The writable workspace and bridge directory are separate
            # generation-owned roots.  The token is over-mounted read-only
            # inside the bridge root so the worker cannot replace it.
            argv.extend(("--mount", proposer_mounts[0]))
        argv.extend(
            [
            "--mount",
            export_mount,
            ]
        )
        if spec.role == "proposer":
            argv.extend(("--mount", proposer_mounts[1]))
        argv.extend(
            [
            "--mount",
            (
                arena_volume_mount
                if spec.role == "proposer"
                else socket_mount
            ),
            "--mount",
            token_mount,
            ]
        )
        if spec.role == "proposer":
            argv.extend(("--mount", proposer_mounts[2]))
        argv.extend(
            [
            "--workdir",
            workdir,
            "--entrypoint",
            PYTHON_ENTRYPOINT,
            ]
        )
        for key, value in values:
            argv.extend(("--env", f"{key}={value}"))
        argv.append(image.requested_reference)
        argv.extend(spec.command)
        return _validated_argv(argv)

    def build_launch_attestation(
        self, spec: AttemptSpec
    ) -> LaunchAttestation:
        """Create, inspect, and attest one *unstarted* attempt container."""
        spec.validate()
        parent = _snapshot_mount_root(
            spec.parent_input,
            label="parent input",
            require_empty=False,
            require_private=False,
        )
        export = _snapshot_mount_root(
            spec.export_root,
            label="export root",
            require_empty=True,
            require_private=True,
        )
        arena_socket = _snapshot_endpoint(
            spec.arena_socket,
            label="Arena RPC socket",
            expected_kind="socket",
        )
        arena_token_file = _snapshot_endpoint(
            spec.arena_token_file,
            label="Arena RPC token",
            expected_kind="token",
        )
        workspace: MountObservation | None = None
        bridge: MountObservation | None = None
        bridge_token_file: EndpointObservation | None = None
        if spec.role == "proposer":
            workspace = _snapshot_mount_root(
                spec.workspace_root,
                label="proposer workspace",
                require_empty=False,
                require_private=True,
            )
            bridge = _snapshot_mount_root(
                spec.bridge_root,
                label="proposer bridge root",
                require_empty=False,
                require_private=True,
            )
            bridge_token_file = _snapshot_endpoint(
                spec.bridge_token_file,
                label="proposer bridge token",
                expected_kind="token",
            )
            _reject_proposer_mount_aliases(
                parent,
                workspace,
                export,
                bridge,
                arena_socket,
                arena_token_file,
                bridge_token_file,
            )
        else:
            _reject_mount_alias(parent, export)
            _reject_endpoint_aliases(
                parent,
                export,
                arena_socket,
                arena_token_file,
            )
        first_image = self.inspect_image(spec.image_reference)
        create_argv = self.build_create_command(
            spec,
            image=first_image,
            parent=parent,
            export=export,
            arena_socket=arena_socket,
            arena_token_file=arena_token_file,
            workspace=workspace,
            bridge=bridge,
            bridge_token_file=bridge_token_file,
        )
        # A second observation immediately before create catches daemon/cache
        # drift and ensures the command is still bound to the inspected image.
        second_image = self.inspect_image(spec.image_reference)
        _require_same_image(first_image, second_image)
        result = self._required(
            create_argv,
            timeout_seconds=60,
            label="container create",
        )
        container_id = result.stdout.strip()
        if not CONTAINER_ID_RE.fullmatch(container_id):
            cleanup_error = self._emergency_remove_identity(spec.identity)
            if cleanup_error is not None:
                raise ContainerContractError(
                    "docker create returned no full container id and the "
                    f"created identity could not be removed: {cleanup_error}"
                )
            raise ContainerContractError(
                "docker create did not return one full container id; the "
                "identity-labelled container was removed"
            )
        try:
            observed = self._inspect_container(container_id)
            projection, facts = _validate_container_observation(
                observed,
                spec=spec,
                image=second_image,
                parent=parent,
                export=export,
                arena_socket=arena_socket,
                arena_token_file=arena_token_file,
                workspace=workspace,
                bridge=bridge,
                bridge_token_file=bridge_token_file,
                container_id=container_id,
            )
            document = _attestation_document(
                spec=spec,
                image=second_image,
                parent=parent,
                export=export,
                arena_socket=arena_socket,
                arena_token_file=arena_token_file,
                workspace=workspace,
                bridge=bridge,
                bridge_token_file=bridge_token_file,
                container_id=container_id,
                container_observation_sha256=_json_sha256(observed),
                security_projection_sha256=_json_sha256(projection),
                create_argv_sha256=_argv_sha256(create_argv),
                evidence=facts,
            )
            document_bytes = _canonical_json_bytes(document)
            return LaunchAttestation(
                schema=1,
                identity=spec.identity,
                container_id=container_id,
                container_name=_container_name(spec.identity),
                image=second_image,
                role=spec.role,
                parent_input=parent,
                export_root=export,
                workspace_root=workspace,
                bridge_root=bridge,
                arena_socket=arena_socket,
                arena_volume_name=(
                    arena_volume_name(spec.identity)
                    if spec.role == "proposer"
                    else None
                ),
                arena_token_file=arena_token_file,
                bridge_token_file=bridge_token_file,
                create_argv_sha256=_argv_sha256(create_argv),
                container_observation_sha256=_json_sha256(observed),
                security_projection_sha256=_json_sha256(projection),
                evidence=facts,
                soft_allocation_seconds=float(spec.soft_allocation_seconds),
                document_bytes=document_bytes,
                document_sha256=hashlib.sha256(document_bytes).hexdigest(),
            )
        except BaseException as original:
            cleanup_error = self._emergency_remove(
                container_id, identity=spec.identity
            )
            if cleanup_error is not None:
                raise ContainerContractError(
                    "container attestation failed and emergency cleanup "
                    f"also failed: {cleanup_error}"
                ) from original
            raise

    def start_attested(
        self,
        attestation: LaunchAttestation,
        spec: AttemptSpec,
    ) -> RunningAttempt:
        """Re-observe and start only the exact container that was attested."""
        self._validate_attestation_object(attestation, spec)
        parent = _snapshot_mount_root(
            spec.parent_input,
            label="parent input",
            require_empty=False,
            require_private=False,
        )
        export = _snapshot_mount_root(
            spec.export_root,
            label="export root",
            require_empty=True,
            require_private=True,
        )
        arena_socket = _snapshot_endpoint(
            spec.arena_socket,
            label="Arena RPC socket",
            expected_kind="socket",
        )
        arena_token_file = _snapshot_endpoint(
            spec.arena_token_file,
            label="Arena RPC token",
            expected_kind="token",
        )
        _require_same_mount(attestation.parent_input, parent, label="parent input")
        _require_same_mount(attestation.export_root, export, label="export root")
        _require_same_endpoint(
            attestation.arena_socket,
            arena_socket,
            label="Arena RPC socket",
        )
        _require_same_endpoint(
            attestation.arena_token_file,
            arena_token_file,
            label="Arena RPC token",
        )
        workspace: MountObservation | None = None
        bridge: MountObservation | None = None
        bridge_token_file: EndpointObservation | None = None
        if spec.role == "proposer":
            workspace = _snapshot_mount_root(
                spec.workspace_root,
                label="proposer workspace",
                require_empty=False,
                require_private=True,
            )
            bridge = _snapshot_mount_root(
                spec.bridge_root,
                label="proposer bridge root",
                require_empty=False,
                require_private=True,
            )
            bridge_token_file = _snapshot_endpoint(
                spec.bridge_token_file,
                label="proposer bridge token",
                expected_kind="token",
            )
            if (
                attestation.workspace_root is None
                or attestation.bridge_root is None
                or attestation.bridge_token_file is None
            ):
                raise ContainerContractError(
                    "proposer attestation dropped bridge mount evidence"
                )
            _require_same_mount(
                attestation.workspace_root,
                workspace,
                label="proposer workspace",
            )
            _require_same_mount(
                attestation.bridge_root,
                bridge,
                label="proposer bridge root",
            )
            _require_same_endpoint(
                attestation.bridge_token_file,
                bridge_token_file,
                label="proposer bridge token",
            )
            _reject_proposer_mount_aliases(
                parent,
                workspace,
                export,
                bridge,
                arena_socket,
                arena_token_file,
                bridge_token_file,
            )
        else:
            if any(
                value is not None
                for value in (
                    attestation.workspace_root,
                    attestation.bridge_root,
                    attestation.bridge_token_file,
                )
            ):
                raise ContainerContractError(
                    "replay attestation contains proposer mount evidence"
                )
            _reject_mount_alias(parent, export)
            _reject_endpoint_aliases(
                parent,
                export,
                arena_socket,
                arena_token_file,
            )
        image = self.inspect_image(spec.image_reference)
        _require_same_image(attestation.image, image)
        observed = self._inspect_container(attestation.container_id)
        projection, _ = _validate_container_observation(
            observed,
            spec=spec,
            image=image,
            parent=parent,
            export=export,
            arena_socket=arena_socket,
            arena_token_file=arena_token_file,
            workspace=workspace,
            bridge=bridge,
            bridge_token_file=bridge_token_file,
            container_id=attestation.container_id,
        )
        if _json_sha256(projection) != attestation.security_projection_sha256:
            raise ContainerContractError(
                "created container isolation configuration drifted before launch"
            )
        state = _required_dict(observed, "State", label="container State")
        if (
            _required_bool(state, "Running", label="container State.Running")
            or _required_bool(state, "Paused", label="container State.Paused")
            or _required_bool(
                state, "Restarting", label="container State.Restarting"
            )
        ):
            raise ContainerContractError(
                "attested container is not in the unstarted created state"
            )
        self._required(
            (
                self._docker,
                "container",
                "start",
                attestation.container_id,
            ),
            timeout_seconds=60,
            label="container start",
        )
        running = self._inspect_container(attestation.container_id)
        running_projection, _ = _validate_container_observation(
            running,
            spec=spec,
            image=image,
            parent=parent,
            export=export,
            arena_socket=arena_socket,
            arena_token_file=arena_token_file,
            workspace=workspace,
            bridge=bridge,
            bridge_token_file=bridge_token_file,
            container_id=attestation.container_id,
        )
        if _json_sha256(running_projection) != attestation.security_projection_sha256:
            raise ContainerContractError(
                "container isolation configuration changed during launch"
            )
        running_state = _required_dict(running, "State", label="container State")
        observed_running = _required_bool(
            running_state, "Running", label="container State.Running"
        )
        observed_status = _required_string(
            running_state, "Status", label="container State.Status"
        )
        if not observed_running and observed_status != "exited":
            raise ContainerContractError(
                "container neither remained running nor completed after start"
            )
        return RunningAttempt(
            attestation=attestation,
            running_observation_sha256=_json_sha256(running),
        )

    def observe_container_state(
        self,
        attestation: LaunchAttestation,
        spec: AttemptSpec,
        *,
        timeout_seconds: float = 30,
    ) -> ContainerStateObservation:
        """Inspect the exact container and project only bounded lifecycle state."""
        if (
            isinstance(timeout_seconds, bool)
            or not isinstance(timeout_seconds, (int, float))
            or not math.isfinite(timeout_seconds)
            or timeout_seconds <= 0
            or timeout_seconds > 60
        ):
            raise ContainerContractError(
                "container-state timeout must be in the interval (0, 60]"
            )
        self._validate_attestation_object(attestation, spec)
        observed = self._inspect_container(
            attestation.container_id,
            timeout_seconds=float(timeout_seconds),
        )
        projection, _ = _validate_container_observation(
            observed,
            spec=spec,
            image=attestation.image,
            parent=attestation.parent_input,
            export=attestation.export_root,
            arena_socket=attestation.arena_socket,
            arena_token_file=attestation.arena_token_file,
            workspace=attestation.workspace_root,
            bridge=attestation.bridge_root,
            bridge_token_file=attestation.bridge_token_file,
            container_id=attestation.container_id,
        )
        if _json_sha256(projection) != attestation.security_projection_sha256:
            raise ContainerContractError(
                "container isolation configuration drifted while polling"
            )
        state = _required_dict(observed, "State", label="container State")
        status = _required_string(
            state, "Status", label="container State.Status"
        )
        running = _required_bool(
            state, "Running", label="container State.Running"
        )
        paused = _required_bool(
            state, "Paused", label="container State.Paused"
        )
        restarting = _required_bool(
            state, "Restarting", label="container State.Restarting"
        )
        oom_killed = _required_bool(
            state, "OOMKilled", label="container State.OOMKilled"
        )
        exit_code_value = _required_int(
            state, "ExitCode", label="container State.ExitCode"
        )
        error = _required_string(
            state, "Error", label="container State.Error"
        )
        if len(error) > 4096:
            raise ContainerContractError(
                "container State.Error exceeds the evidence limit"
            )
        if status not in {
            "created",
            "running",
            "paused",
            "restarting",
            "removing",
            "exited",
            "dead",
        }:
            raise ContainerContractError(
                "container State.Status is outside the observed allowlist"
            )
        if running != (status in {"running", "paused", "restarting"}):
            raise ContainerContractError(
                "container running flag and status disagree"
            )
        if paused != (status == "paused"):
            raise ContainerContractError(
                "container paused flag and status disagree"
            )
        if restarting != (status == "restarting"):
            raise ContainerContractError(
                "container restarting flag and status disagree"
            )
        state_projection = {
            "container_id": attestation.container_id,
            "status": status,
            "running": running,
            "paused": paused,
            "restarting": restarting,
            "oom_killed": oom_killed,
            "exit_code": exit_code_value,
            "error": error,
            "container_inspect_sha256": _json_sha256(observed),
            "security_projection_sha256": _json_sha256(projection),
        }
        return ContainerStateObservation(
            status=status,
            running=running,
            exit_code=None if running else exit_code_value,
            oom_killed=oom_killed,
            error=error,
            observation_sha256=_json_sha256(state_projection),
        )

    def collect_terminal_logs(
        self,
        attestation: LaunchAttestation,
        spec: AttemptSpec,
    ) -> ContainerLogObservation:
        """Capture bounded logs only after the exact container is quiescent."""
        self._validate_attestation_object(attestation, spec)
        observed = self._inspect_container(attestation.container_id)
        projection, _ = _validate_container_observation(
            observed,
            spec=spec,
            image=attestation.image,
            parent=attestation.parent_input,
            export=attestation.export_root,
            arena_socket=attestation.arena_socket,
            arena_token_file=attestation.arena_token_file,
            workspace=attestation.workspace_root,
            bridge=attestation.bridge_root,
            bridge_token_file=attestation.bridge_token_file,
            container_id=attestation.container_id,
        )
        if _json_sha256(projection) != attestation.security_projection_sha256:
            raise ContainerContractError(
                "container isolation configuration drifted before log collection"
            )
        state = _required_dict(observed, "State", label="container State")
        if _required_bool(
            state, "Running", label="container State.Running"
        ):
            raise ContainerContractError(
                "refusing to collect logs from a live container"
            )
        result = self._required(
            (
                self._docker,
                "container",
                "logs",
                attestation.container_id,
            ),
            timeout_seconds=30,
            label="terminal container logs",
            max_output_bytes=2 * MAX_CONTAINER_STREAM_BYTES,
        )
        stdout_raw = result.stdout.encode("utf-8")
        stderr_raw = result.stderr.encode("utf-8")
        if (
            len(stdout_raw) > MAX_CONTAINER_STREAM_BYTES
            or len(stderr_raw) > MAX_CONTAINER_STREAM_BYTES
        ):
            raise ContainerContractError(
                "terminal container stream exceeds its immutable evidence bound"
            )
        body = {
            "container_id": attestation.container_id,
            "stdout_sha256": hashlib.sha256(stdout_raw).hexdigest(),
            "stderr_sha256": hashlib.sha256(stderr_raw).hexdigest(),
            "stdout_bytes": len(stdout_raw),
            "stderr_bytes": len(stderr_raw),
        }
        return ContainerLogObservation(
            stdout=result.stdout,
            stderr=result.stderr,
            stdout_sha256=body["stdout_sha256"],
            stderr_sha256=body["stderr_sha256"],
            stdout_bytes=body["stdout_bytes"],
            stderr_bytes=body["stderr_bytes"],
            observation_sha256=_json_sha256(body),
        )

    def quiesce_orphan_for_containment(
        self,
        attestation: LaunchAttestation,
        spec: AttemptSpec,
        *,
        graceful_seconds: int = 5,
    ) -> str:
        """Stop, but do not remove, an attempt whose host owner was lost.

        This is a hard containment action, never a soft-allocation action.  The
        later runner teardown still has to remove the cgroup and prove absence.
        """
        if (
            isinstance(graceful_seconds, bool)
            or not isinstance(graceful_seconds, int)
            or graceful_seconds < 0
            or graceful_seconds > 30
        ):
            raise ContainerContractError(
                "orphan quiescence grace must be an integer in [0, 30]"
            )
        self._validate_attestation_object(attestation, spec)
        observed = self._inspect_container(attestation.container_id)
        projection, _ = _validate_container_observation(
            observed,
            spec=spec,
            image=attestation.image,
            parent=attestation.parent_input,
            export=attestation.export_root,
            arena_socket=attestation.arena_socket,
            arena_token_file=attestation.arena_token_file,
            workspace=attestation.workspace_root,
            bridge=attestation.bridge_root,
            bridge_token_file=attestation.bridge_token_file,
            container_id=attestation.container_id,
        )
        if _json_sha256(projection) != attestation.security_projection_sha256:
            raise ContainerContractError(
                "orphan container isolation projection drifted"
            )
        state = _required_dict(observed, "State", label="container State")
        if _required_bool(
            state, "Running", label="container State.Running"
        ):
            top = self._required(
                (
                    self._docker,
                    "container",
                    "top",
                    attestation.container_id,
                    "-eo",
                    "pid,ppid",
                ),
                timeout_seconds=30,
                label="orphan container process inventory",
            )
            if not _parse_top_pids(top.stdout):
                raise ContainerContractError(
                    "live orphan has no observed container process inventory"
                )
            self._required(
                (
                    self._docker,
                    "container",
                    "stop",
                    "--time",
                    str(graceful_seconds),
                    attestation.container_id,
                ),
                timeout_seconds=graceful_seconds + 30,
                label="orphan containment stop",
            )
            after_stop = self._inspect_container(attestation.container_id)
            after_stop_state = _required_dict(
                after_stop, "State", label="orphan State after stop"
            )
            if _required_bool(
                after_stop_state,
                "Running",
                label="orphan State.Running after stop",
            ):
                self._required(
                    (
                        self._docker,
                        "container",
                        "kill",
                        attestation.container_id,
                    ),
                    timeout_seconds=30,
                    label="orphan containment kill",
                )
        quiescent = self._inspect_container(attestation.container_id)
        quiescent_projection, _ = _validate_container_observation(
            quiescent,
            spec=spec,
            image=attestation.image,
            parent=attestation.parent_input,
            export=attestation.export_root,
            arena_socket=attestation.arena_socket,
            arena_token_file=attestation.arena_token_file,
            workspace=attestation.workspace_root,
            bridge=attestation.bridge_root,
            bridge_token_file=attestation.bridge_token_file,
            container_id=attestation.container_id,
        )
        if (
            _json_sha256(quiescent_projection)
            != attestation.security_projection_sha256
            or _required_bool(
                _required_dict(
                    quiescent, "State", label="quiescent container State"
                ),
                "Running",
                label="quiescent container State.Running",
            )
        ):
            raise ContainerContractError(
                "orphan container did not become observably quiescent"
            )
        return _json_sha256(
            {
                "kind": "supervisor-restart-orphan-quiescence",
                "container_id": attestation.container_id,
                "container_inspect_sha256": _json_sha256(quiescent),
                "security_projection_sha256": _json_sha256(
                    quiescent_projection
                ),
            }
        )

    def observe_soft_allocation(
        self,
        attestation: LaunchAttestation,
        *,
        elapsed_seconds: float,
        proposer_active: bool,
    ) -> SoftAllocationDecision:
        """Return state only; this method intentionally cannot call Docker."""
        return decide_soft_allocation(
            elapsed_seconds=elapsed_seconds,
            soft_allocation_seconds=attestation.soft_allocation_seconds,
            proposer_active=proposer_active,
        )

    def teardown(
        self,
        attempt: RunningAttempt | LaunchAttestation,
        *,
        cause: TeardownCause,
        graceful_seconds: int = 20,
    ) -> TeardownProof:
        """Destroy the exact attempt and prove its Docker cgroup is absent."""
        if not isinstance(cause, TeardownCause):
            raise ContainerContractError(
                "teardown cause must be an explicit TeardownCause; "
                "soft allocation is not one"
            )
        if (
            isinstance(graceful_seconds, bool)
            or not isinstance(graceful_seconds, int)
            or graceful_seconds < 0
            or graceful_seconds > 300
        ):
            raise ContainerContractError(
                "graceful_seconds must be an integer in [0, 300]"
            )
        attestation = (
            attempt.attestation
            if isinstance(attempt, RunningAttempt)
            else attempt
        )
        if not isinstance(attestation, LaunchAttestation):
            raise ContainerContractError("attempt is not a launch attestation")
        observed = self._inspect_container(attestation.container_id)
        labels = _required_dict(
            _required_dict(observed, "Config", label="container Config"),
            "Labels",
            label="container Config.Labels",
        )
        _require_identity_labels(labels, attestation.identity)
        if _required_digest(observed, "Image", label="container Image") != (
            attestation.image.image_id
        ):
            raise ContainerContractError(
                "refusing to tear down a container with a drifted image identity"
            )
        state = _required_dict(observed, "State", label="container State")
        running = _required_bool(state, "Running", label="container State.Running")
        processes_before: tuple[int, ...] = ()
        if running:
            top = self._required(
                (
                    self._docker,
                    "container",
                    "top",
                    attestation.container_id,
                    "-eo",
                    "pid,ppid",
                ),
                timeout_seconds=30,
                label="container-scoped process inventory",
            )
            processes_before = _parse_top_pids(top.stdout)
            if not processes_before:
                raise ContainerContractError(
                    "running container has no observed process inventory"
                )
            self._required(
                (
                    self._docker,
                    "container",
                    "stop",
                    "--time",
                    str(graceful_seconds),
                    attestation.container_id,
                ),
                timeout_seconds=graceful_seconds + 30,
                label="container-local graceful stop",
            )
            after_stop = self._inspect_container(attestation.container_id)
            after_state = _required_dict(
                after_stop, "State", label="container State after stop"
            )
            if _required_bool(
                after_state, "Running", label="container State.Running after stop"
            ):
                self._required(
                    (
                        self._docker,
                        "container",
                        "kill",
                        attestation.container_id,
                    ),
                    timeout_seconds=30,
                    label="container cgroup kill",
                )
        self._required(
            (
                self._docker,
                "container",
                "rm",
                "--force",
                "--volumes",
                attestation.container_id,
            ),
            timeout_seconds=60,
            label="container/cgroup removal",
        )
        inspect_absent = self._expect_absent(
            (
                self._docker,
                "container",
                "inspect",
                attestation.container_id,
            ),
            label="post-teardown container inspection",
        )
        top_absent = self._expect_absent(
            (
                self._docker,
                "container",
                "top",
                attestation.container_id,
                "-eo",
                "pid,ppid",
            ),
            label="post-teardown process inventory",
        )
        query = self._required(
            (
                self._docker,
                "container",
                "ls",
                "--all",
                "--quiet",
                "--filter",
                f"label={LABEL_CAMPAIGN}={attestation.identity.campaign_id}",
                "--filter",
                f"label={LABEL_GENERATION}={attestation.identity.generation_id}",
                "--filter",
                f"label={LABEL_ATTEMPT}={attestation.identity.attempt_id}",
            ),
            timeout_seconds=30,
            label="post-teardown identity query",
        )
        label_query_empty = not query.stdout.strip()
        if not (inspect_absent and top_absent and label_query_empty):
            raise ContainerContractError(
                "container teardown could not prove the attempt cgroup absent"
            )
        proof_body = {
            "schema": 1,
            "campaign_id": attestation.identity.campaign_id,
            "generation_id": attestation.identity.generation_id,
            "attempt_id": attestation.identity.attempt_id,
            "container_id": attestation.container_id,
            "cause": cause.value,
            "observed_container_processes_before": list(processes_before),
            "container_inspect_absent": inspect_absent,
            "container_top_absent": top_absent,
            "identity_label_query_empty": label_query_empty,
            "no_descendants": True,
        }
        proof_sha256 = _json_sha256(proof_body)
        return TeardownProof(
            schema=1,
            campaign_id=attestation.identity.campaign_id,
            generation_id=attestation.identity.generation_id,
            attempt_id=attestation.identity.attempt_id,
            container_id=attestation.container_id,
            cause=cause.value,
            observed_container_processes_before=processes_before,
            container_inspect_absent=inspect_absent,
            container_top_absent=top_absent,
            identity_label_query_empty=label_query_empty,
            no_descendants=True,
            proof_sha256=proof_sha256,
        )

    def write_attestation(
        self, path: Path, attestation: LaunchAttestation
    ) -> None:
        """Persist new host-owned evidence without following or overwriting."""
        if not isinstance(path, Path) or not path.is_absolute():
            raise ContainerContractError(
                "attestation path must be an absolute Path"
            )
        _reject_symlink_components(path.parent, label="attestation parent")
        if not path.parent.is_dir():
            raise ContainerContractError("attestation parent is not a directory")
        parent_metadata = path.parent.lstat()
        if (
            parent_metadata.st_uid != os.getuid()
            or stat.S_IMODE(parent_metadata.st_mode) & 0o022
        ):
            raise ContainerContractError(
                "attestation parent must be supervisor-owned and not writable "
                "by group/other"
            )
        flags = os.O_WRONLY | os.O_CREAT | os.O_EXCL
        if hasattr(os, "O_NOFOLLOW"):
            flags |= os.O_NOFOLLOW
        try:
            descriptor = os.open(path, flags, 0o600)
        except OSError as exc:
            raise ContainerContractError(
                "attestation target must be a new regular file"
            ) from exc
        try:
            with os.fdopen(descriptor, "wb", closefd=False) as handle:
                handle.write(attestation.document_bytes)
                handle.flush()
                os.fsync(handle.fileno())
            written = path.lstat()
            if (
                not stat.S_ISREG(written.st_mode)
                or written.st_nlink != 1
                or _hash_unaliased_regular_file(
                    path, label="persisted launch attestation"
                )
                != attestation.document_sha256
            ):
                raise ContainerContractError(
                    "persisted launch attestation failed inode/hash validation"
                )
            directory_fd = os.open(path.parent, os.O_RDONLY)
            try:
                os.fsync(directory_fd)
            finally:
                os.close(directory_fd)
        finally:
            os.close(descriptor)

    def _validate_attestation_object(
        self, attestation: LaunchAttestation, spec: AttemptSpec
    ) -> None:
        if not isinstance(attestation, LaunchAttestation):
            raise ContainerContractError(
                "launch requires an observed LaunchAttestation object"
            )
        spec.validate()
        if hashlib.sha256(attestation.document_bytes).hexdigest() != (
            attestation.document_sha256
        ):
            raise ContainerContractError("launch attestation bytes were modified")
        document = attestation.as_dict()
        if _canonical_json_bytes(document) != attestation.document_bytes:
            raise ContainerContractError(
                "launch attestation is not canonically encoded"
            )
        if (
            attestation.identity != spec.identity
            or attestation.role != spec.role
            or attestation.image.requested_reference != spec.image_reference
            or attestation.arena_volume_name
            != (
                arena_volume_name(spec.identity)
                if spec.role == "proposer"
                else None
            )
            or set(fact.name for fact in attestation.evidence)
            != set(expected_isolation_evidence_names(spec.role))
            or len(attestation.evidence)
            != len(expected_isolation_evidence_names(spec.role))
        ):
            raise ContainerContractError(
                "launch attestation does not bind the requested attempt"
            )
        rebuilt = _attestation_document(
            spec=spec,
            image=attestation.image,
            parent=attestation.parent_input,
            export=attestation.export_root,
            arena_socket=attestation.arena_socket,
            arena_token_file=attestation.arena_token_file,
            workspace=attestation.workspace_root,
            bridge=attestation.bridge_root,
            bridge_token_file=attestation.bridge_token_file,
            container_id=attestation.container_id,
            create_argv_sha256=attestation.create_argv_sha256,
            container_observation_sha256=(
                attestation.container_observation_sha256
            ),
            security_projection_sha256=(
                attestation.security_projection_sha256
            ),
            evidence=attestation.evidence,
        )
        if document != rebuilt:
            raise ContainerContractError(
                "launch attestation fields and document disagree"
            )
    def _inspect_container(
        self,
        container_id: str,
        *,
        timeout_seconds: float = 30,
    ) -> dict[str, Any]:
        if not CONTAINER_ID_RE.fullmatch(container_id):
            raise ContainerContractError("container id is not a full digest id")
        result = self._required(
            (self._docker, "container", "inspect", container_id),
            timeout_seconds=timeout_seconds,
            label="container inspection",
        )
        return _parse_single_inspect_object(
            result.stdout, label="container inspection"
        )

    def _required(
        self,
        argv: Sequence[str],
        *,
        timeout_seconds: float,
        label: str,
        max_output_bytes: int = MAX_INSPECT_BYTES,
    ) -> CommandResult:
        command = _validated_argv(argv)
        result = self._runner.run(
            command,
            timeout_seconds=timeout_seconds,
        )
        if not isinstance(result, CommandResult) or result.argv != command:
            raise ContainerContractError(
                f"{label} runner did not bind its result to the requested argv"
            )
        if (
            isinstance(result.returncode, bool)
            or not isinstance(result.returncode, int)
            or result.returncode != 0
        ):
            detail = (result.stderr or result.stdout)[-1000:]
            raise ContainerContractError(
                f"{label} failed"
                + (f": {detail}" if detail else "")
            )
        if (
            isinstance(max_output_bytes, bool)
            or not isinstance(max_output_bytes, int)
            or max_output_bytes <= 0
            or max_output_bytes > 64 * 1024 * 1024
        ):
            raise ContainerContractError(
                f"{label} output bound is invalid"
            )
        if (
            len(result.stdout.encode("utf-8"))
            + len(result.stderr.encode("utf-8"))
            > max_output_bytes
        ):
            raise ContainerContractError(f"{label} output exceeds evidence limit")
        return result

    def _expect_absent(self, argv: Sequence[str], *, label: str) -> bool:
        command = _validated_argv(argv)
        result = self._runner.run(command, timeout_seconds=30)
        if not isinstance(result, CommandResult) or result.argv != command:
            raise ContainerContractError(
                f"{label} runner did not bind its result to the requested argv"
            )
        if result.returncode == 0:
            return False
        # Docker uses nonzero for an absent container.  Do not parse prose as a
        # control signal; the following identity-label query is the independent
        # machine-readable absence check.
        return True

    def _identity_query(
        self, identity: AttemptIdentity
    ) -> CommandResult:
        identity.validate()
        return self._required(
            (
                self._docker,
                "container",
                "ls",
                "--all",
                "--quiet",
                "--no-trunc",
                "--filter",
                f"label={LABEL_CAMPAIGN}={identity.campaign_id}",
                "--filter",
                f"label={LABEL_GENERATION}={identity.generation_id}",
                "--filter",
                f"label={LABEL_ATTEMPT}={identity.attempt_id}",
                "--filter",
                f"label={LABEL_ROLE}={ATTEMPT_WORKER_ROLE}",
            ),
            timeout_seconds=30,
            label="attempt identity query",
        )

    def _emergency_remove_identity(
        self, identity: AttemptIdentity
    ) -> str | None:
        try:
            query = self._identity_query(identity)
        except BaseException as exc:
            return f"identity query failed: {type(exc).__name__}"
        ids = tuple(
            line.strip()
            for line in query.stdout.splitlines()
            if line.strip()
        )
        if not ids:
            return "identity query found no created container"
        if (
            len(ids) != len(set(ids))
            or not all(CONTAINER_ID_RE.fullmatch(value) for value in ids)
        ):
            return "identity query returned malformed container ids"
        errors: list[str] = []
        for container_id in ids:
            try:
                observed = self._inspect_container(container_id)
                labels = _required_dict(
                    _required_dict(
                        observed, "Config", label="container Config"
                    ),
                    "Labels",
                    label="container Config.Labels",
                )
                _require_identity_labels(labels, identity)
            except BaseException as exc:
                errors.append(
                    f"{container_id[:12]} identity check failed: "
                    f"{type(exc).__name__}"
                )
                continue
            error = self._emergency_remove(
                container_id, identity=identity
            )
            if error is not None:
                errors.append(f"{container_id[:12]}: {error}")
        return "; ".join(errors) if errors else None

    def _emergency_remove(
        self,
        container_id: str,
        *,
        identity: AttemptIdentity,
    ) -> str | None:
        command = (
            self._docker,
            "container",
            "rm",
            "--force",
            "--volumes",
            container_id,
        )
        try:
            result = self._runner.run(command, timeout_seconds=60)
        except BaseException as exc:  # cleanup must report, not mask
            return repr(exc)
        if (
            not isinstance(result, CommandResult)
            or result.argv != command
            or result.returncode != 0
        ):
            return "docker rm did not confirm removal"
        try:
            inspect_absent = self._expect_absent(
                (
                    self._docker,
                    "container",
                    "inspect",
                    container_id,
                ),
                label="emergency post-removal inspection",
            )
            identity_empty = not self._identity_query(identity).stdout.strip()
        except BaseException as exc:
            return f"post-removal proof failed: {type(exc).__name__}"
        if not (inspect_absent and identity_empty):
            return "post-removal identity or container remained present"
        return None


@dataclass(frozen=True)
class ArenaVolumePreparationEvidence:
    """Observed identity of the per-attempt Arena relay boundary."""

    transport: str
    volume_name: str
    volume_observation_sha256: str
    relay_container_id: str
    relay_image_reference: str
    relay_image_digest: str
    relay_image_observation_sha256: str
    relay_container_observation_sha256: str
    readiness_nonce: str
    readiness_receipt_path: str
    readiness_receipt_sha256: str
    attach_argv_sha256: str
    arena_socket_identity_sha256: str
    preparation_receipt_path: str
    preparation_receipt_sha256: str


@dataclass
class ArenaVolumeRuntime:
    """Live relay state retained only by the owning host supervisor."""

    evidence: ArenaVolumePreparationEvidence
    attachment: arena_volume_transport.AttachedArenaRelay | None


@dataclass(frozen=True)
class ArenaVolumeTeardownEvidence:
    """Machine-observed proof that the relay and volume are absent."""

    relay_container_id: str
    volume_name: str
    attachment_status: str
    attachment_receipt_sha256: str | None
    relay_inspect_absent: bool
    relay_top_absent: bool
    relay_identity_query_empty: bool
    volume_inspect_absent: bool
    volume_identity_query_empty: bool
    receipt_path: str
    receipt_sha256: str


class DockerArenaVolumeLifecycle:
    """Fail-closed named-volume relay lifecycle for one proposer attempt."""

    def __init__(self, backend: DockerContainerBackend) -> None:
        if not isinstance(backend, DockerContainerBackend):
            raise ContainerContractError(
                "Arena volume lifecycle requires the observed Docker backend"
            )
        self._backend = backend
        self._docker = backend._docker
        self._runner = backend._runner

    @staticmethod
    def _identity_labels(
        identity: AttemptIdentity,
    ) -> dict[str, str]:
        identity.validate()
        return {
            LABEL_CAMPAIGN: identity.campaign_id,
            LABEL_GENERATION: identity.generation_id,
            LABEL_ATTEMPT: identity.attempt_id,
            LABEL_GAME: identity.game,
            LABEL_LEVEL: str(identity.target_level),
            LABEL_ROLE: ARENA_VOLUME_RELAY_ROLE,
        }

    def _query_relay_ids(
        self, identity: AttemptIdentity
    ) -> tuple[str, ...]:
        argv: list[str] = [
            self._docker,
            "container",
            "ls",
            "--all",
            "--quiet",
            "--no-trunc",
        ]
        for name, value in sorted(
            self._identity_labels(identity).items()
        ):
            argv.extend(("--filter", f"label={name}={value}"))
        result = self._backend._required(
            tuple(argv),
            timeout_seconds=30,
            label="Arena relay identity query",
        )
        return _parse_container_id_lines(
            result.stdout, label="Arena relay identity query"
        )

    def _query_volume_names(
        self, identity: AttemptIdentity
    ) -> tuple[str, ...]:
        argv: list[str] = [
            self._docker,
            "volume",
            "ls",
            "--quiet",
        ]
        for name, value in sorted(
            self._identity_labels(identity).items()
        ):
            argv.extend(("--filter", f"label={name}={value}"))
        result = self._backend._required(
            tuple(argv),
            timeout_seconds=30,
            label="Arena volume identity query",
        )
        names = tuple(
            line.strip()
            for line in result.stdout.splitlines()
            if line.strip()
        )
        expected = arena_volume_name(identity)
        if (
            len(names) != len(set(names))
            or any(name != expected for name in names)
        ):
            raise ContainerContractError(
                "Arena volume identity query is ambiguous"
            )
        return names

    def _inspect_relay_image(
        self,
        *,
        reference: str,
        digest: str,
        source_sha256: str,
    ) -> tuple[dict[str, Any], str, str]:
        repository, parsed_digest = parse_digest_reference(reference)
        del repository
        if parsed_digest != digest:
            raise ContainerContractError(
                "Arena relay image reference and digest disagree"
            )
        result = self._backend._required(
            (self._docker, "image", "inspect", reference),
            timeout_seconds=30,
            label="Arena relay image inspection",
        )
        observed = _parse_single_inspect_object(
            result.stdout, label="Arena relay image inspection"
        )
        image_id = _required_digest(
            observed, "Id", label="Arena relay image Id"
        )
        repo_digests = _required_list(
            observed,
            "RepoDigests",
            label="Arena relay image RepoDigests",
        )
        observed_digests: set[str] = set()
        for item in repo_digests:
            if not isinstance(item, str):
                raise ContainerContractError(
                    "Arena relay image RepoDigests are malformed"
                )
            _, item_digest = parse_digest_reference(item)
            observed_digests.add(item_digest)
        config = _required_dict(
            observed, "Config", label="Arena relay image Config"
        )
        environment = _required_list(
            config, "Env", label="Arena relay image Config.Env"
        )
        labels = _required_dict(
            config,
            "Labels",
            label="Arena relay image Config.Labels",
        )
        if (
            digest not in observed_digests
            or _required_list(
                config,
                "Entrypoint",
                label="Arena relay image Entrypoint",
            )
            != [ARENA_RELAY_ENTRYPOINT]
            or _required_string(
                config, "User", label="Arena relay image User"
            )
            != "0:0"
            or _required_string(
                config,
                "WorkingDir",
                label="Arena relay image WorkingDir",
            )
            != "/"
            or set(_parse_environment_names(environment))
            - ALLOWED_IMAGE_ENV_NAMES
            or labels.get(LABEL_ROLE) != ARENA_VOLUME_RELAY_ROLE
            or labels.get(ARENA_RELAY_LABEL_TRANSPORT)
            != ARENA_VOLUME_TRANSPORT
            or labels.get(ARENA_RELAY_LABEL_SOURCE_SHA256)
            != source_sha256
        ):
            raise ContainerContractError(
                "Arena relay image does not match its pinned contract"
            )
        return observed, image_id, _json_sha256(observed)

    def _inspect_volume(
        self,
        identity: AttemptIdentity,
    ) -> tuple[dict[str, Any], str]:
        name = arena_volume_name(identity)
        result = self._backend._required(
            (self._docker, "volume", "inspect", name),
            timeout_seconds=30,
            label="Arena volume inspection",
        )
        observed = _parse_single_inspect_object(
            result.stdout, label="Arena volume inspection"
        )
        labels = _required_dict(
            observed, "Labels", label="Arena volume Labels"
        )
        options = _required_field(
            observed, "Options", label="Arena volume Options"
        )
        if (
            _required_string(
                observed, "Name", label="Arena volume Name"
            )
            != name
            or _required_string(
                observed, "Driver", label="Arena volume Driver"
            )
            != "local"
            or _required_string(
                observed, "Scope", label="Arena volume Scope"
            )
            != "local"
            or labels != self._identity_labels(identity)
            or options not in (None, {})
        ):
            raise ContainerContractError(
                "Arena volume observation differs from its exact identity"
            )
        return observed, _json_sha256(observed)

    def _relay_command(
        self,
        identity: AttemptIdentity,
        *,
        readiness_nonce: str,
    ) -> tuple[str, ...]:
        return (
            f"--socket-path={PROPOSER_RPC_SOCKET_DESTINATION}",
            f"--campaign-id={identity.campaign_id}",
            f"--generation-id={identity.generation_id}",
            f"--attempt-id={identity.attempt_id}",
            f"--readiness-nonce={readiness_nonce}",
        )

    def _relay_create_argv(
        self,
        identity: AttemptIdentity,
        *,
        image_reference: str,
        source_sha256: str,
        readiness_nonce: str,
    ) -> tuple[str, ...]:
        labels = {
            **self._identity_labels(identity),
            ARENA_RELAY_LABEL_TRANSPORT: ARENA_VOLUME_TRANSPORT,
            ARENA_RELAY_LABEL_SOURCE_SHA256: source_sha256,
        }
        argv: list[str] = [
            self._docker,
            "container",
            "create",
            "--name",
            arena_relay_container_name(identity),
        ]
        for name, value in sorted(labels.items()):
            argv.extend(("--label", f"{name}={value}"))
        argv.extend(
            (
                "--read-only",
                "--network",
                "none",
                "--cgroupns",
                "private",
                "--ipc",
                "private",
                "--cap-drop",
                "ALL",
                "--security-opt",
                "no-new-privileges=true",
                "--user",
                "0:0",
                "--cpus",
                _format_cpus(ARENA_RELAY_CPUS),
                "--memory",
                str(ARENA_RELAY_MEMORY_BYTES),
                "--memory-swap",
                str(ARENA_RELAY_MEMORY_BYTES),
                "--pids-limit",
                str(ARENA_RELAY_PIDS),
                "--restart",
                "no",
                "--no-healthcheck",
                "--log-driver",
                "local",
                "--log-opt",
                "max-size=1m",
                "--log-opt",
                "max-file=1",
                "--pull",
                "never",
                "--init",
                "--tmpfs",
                (
                    f"{ARENA_RELAY_TMPFS_DESTINATION}:"
                    "rw,nosuid,nodev,noexec,"
                    f"size={ARENA_RELAY_TMPFS_BYTES},"
                    "mode=0700,uid=0,gid=0"
                ),
                "--mount",
                (
                    f"type=volume,src={arena_volume_name(identity)},"
                    f"dst={PROPOSER_RPC_ROOT_DESTINATION},volume-nocopy"
                ),
                "--workdir",
                "/",
                "--entrypoint",
                ARENA_RELAY_ENTRYPOINT,
                image_reference,
                *self._relay_command(
                    identity, readiness_nonce=readiness_nonce
                ),
            )
        )
        return _validated_argv(argv)

    def _validate_relay_container(
        self,
        observed: Mapping[str, Any],
        *,
        identity: AttemptIdentity,
        container_id: str,
        image_reference: str,
        image_id: str,
        source_sha256: str,
        readiness_nonce: str,
        running: bool,
    ) -> str:
        config = _required_dict(
            observed, "Config", label="Arena relay Config"
        )
        host = _required_dict(
            observed, "HostConfig", label="Arena relay HostConfig"
        )
        state = _required_dict(
            observed, "State", label="Arena relay State"
        )
        network = _required_dict(
            observed,
            "NetworkSettings",
            label="Arena relay NetworkSettings",
        )
        mounts = _required_list(
            observed, "Mounts", label="Arena relay Mounts"
        )
        labels = _required_dict(
            config, "Labels", label="Arena relay Labels"
        )
        expected_labels = {
            **self._identity_labels(identity),
            ARENA_RELAY_LABEL_TRANSPORT: ARENA_VOLUME_TRANSPORT,
            ARENA_RELAY_LABEL_SOURCE_SHA256: source_sha256,
        }
        expected_tmpfs = (
            "rw,nosuid,nodev,noexec,"
            f"size={ARENA_RELAY_TMPFS_BYTES},"
            "mode=0700,uid=0,gid=0"
        )
        if (
            _required_string(observed, "Id", label="Arena relay Id")
            != container_id
            or _required_digest(
                observed, "Image", label="Arena relay Image"
            )
            != image_id
            or _required_string(
                observed, "Name", label="Arena relay Name"
            ).removeprefix("/")
            != arena_relay_container_name(identity)
            or _required_string(
                config, "Image", label="Arena relay Config.Image"
            )
            != image_reference
            or _required_string(
                config, "User", label="Arena relay Config.User"
            )
            != "0:0"
            or _required_list(
                config,
                "Entrypoint",
                label="Arena relay Config.Entrypoint",
            )
            != [ARENA_RELAY_ENTRYPOINT]
            or tuple(
                _required_list(
                    config, "Cmd", label="Arena relay Config.Cmd"
                )
            )
            != self._relay_command(
                identity, readiness_nonce=readiness_nonce
            )
            or _required_string(
                config,
                "WorkingDir",
                label="Arena relay Config.WorkingDir",
            )
            != "/"
            or _required_dict(
                config,
                "Healthcheck",
                label="Arena relay Config.Healthcheck",
            )
            != {"Test": ["NONE"]}
            or labels != expected_labels
            or set(
                _parse_environment_names(
                    _required_list(
                        config, "Env", label="Arena relay Config.Env"
                    )
                )
            )
            - ALLOWED_IMAGE_ENV_NAMES
            or not _required_bool(
                host,
                "ReadonlyRootfs",
                label="Arena relay ReadonlyRootfs",
            )
            or _required_string(
                host, "NetworkMode", label="Arena relay NetworkMode"
            )
            != "none"
            or _required_string(
                host, "PidMode", label="Arena relay PidMode"
            )
            != ""
            or _required_string(
                host, "CgroupnsMode", label="Arena relay CgroupnsMode"
            )
            != "private"
            or _required_string(
                host, "IpcMode", label="Arena relay IpcMode"
            )
            != "private"
            or _required_string(
                host, "UTSMode", label="Arena relay UTSMode"
            )
            != ""
            or _required_bool(
                host, "Privileged", label="Arena relay Privileged"
            )
            or _required_optional_empty_list(
                host, "CapAdd", label="Arena relay CapAdd"
            )
            or {
                str(value).upper()
                for value in _required_list(
                    host, "CapDrop", label="Arena relay CapDrop"
                )
            }
            != {"ALL"}
            or "no-new-privileges=true"
            not in _required_list(
                host, "SecurityOpt", label="Arena relay SecurityOpt"
            )
            or _required_int(
                host, "NanoCpus", label="Arena relay NanoCpus"
            )
            != int(ARENA_RELAY_CPUS * 1_000_000_000)
            or _required_int(
                host, "Memory", label="Arena relay Memory"
            )
            != ARENA_RELAY_MEMORY_BYTES
            or _required_int(
                host, "MemorySwap", label="Arena relay MemorySwap"
            )
            != ARENA_RELAY_MEMORY_BYTES
            or _required_int(
                host, "PidsLimit", label="Arena relay PidsLimit"
            )
            != ARENA_RELAY_PIDS
            or _required_dict(
                host, "Tmpfs", label="Arena relay Tmpfs"
            )
            != {ARENA_RELAY_TMPFS_DESTINATION: expected_tmpfs}
            or _required_dict(
                host, "RestartPolicy", label="Arena relay RestartPolicy"
            )
            != {"Name": "no", "MaximumRetryCount": 0}
            or _required_dict(
                host, "LogConfig", label="Arena relay LogConfig"
            )
            != {
                "Type": "local",
                "Config": {"max-size": "1m", "max-file": "1"},
            }
            or _required_list(
                host, "Devices", label="Arena relay Devices"
            )
            or _required_list(
                host,
                "DeviceRequests",
                label="Arena relay DeviceRequests",
            )
            or _required_dict(
                network, "Networks", label="Arena relay Networks"
            )
            != {}
            or _required_bool(
                state, "Running", label="Arena relay Running"
            )
            is not running
            or len(mounts) != 1
        ):
            raise ContainerContractError(
                "Arena relay container differs from the exact isolation contract"
            )
        mount = mounts[0]
        if (
            not isinstance(mount, dict)
            or _required_string(
                mount, "Type", label="Arena relay mount Type"
            )
            != "volume"
            or _required_string(
                mount, "Name", label="Arena relay mount Name"
            )
            != arena_volume_name(identity)
            or _required_string(
                mount, "Driver", label="Arena relay mount Driver"
            )
            != "local"
            or _required_string(
                mount, "Destination", label="Arena relay mount Destination"
            )
            != PROPOSER_RPC_ROOT_DESTINATION
            or _required_bool(
                mount, "RW", label="Arena relay mount RW"
            )
            is not True
            or _required_string(
                mount,
                "Propagation",
                label="Arena relay mount Propagation",
            )
            != ""
        ):
            raise ContainerContractError(
                "Arena relay writable named-volume mount differs"
            )
        return _json_sha256(observed)

    def _read_readiness(
        self,
        *,
        identity: AttemptIdentity,
        container_id: str,
        readiness_nonce: str,
        receipt_path: Path,
    ) -> tuple[str, dict[str, Any]]:
        result = self._backend._required(
            (
                self._docker,
                "container",
                "exec",
                "--user",
                "0:0",
                container_id,
                "/bin/cat",
                ARENA_RELAY_READINESS_PATH,
            ),
            timeout_seconds=30,
            label="Arena relay readiness read",
            max_output_bytes=64 * 1024,
        )
        try:
            value = json.loads(result.stdout)
        except json.JSONDecodeError as exc:
            raise ContainerContractError(
                "Arena relay readiness is not JSON"
            ) from exc
        expected_fields = {
            "schema",
            "kind",
            "status",
            "campaign_id",
            "generation_id",
            "attempt_id",
            "readiness_nonce",
            "relay_pid",
            "socket_path",
            "socket_mode",
            "network_mode_required",
            "transport",
        }
        if (
            not isinstance(value, dict)
            or set(value) != expected_fields
            or value.get("schema") != 1
            or value.get("kind")
            != "arc_agi3_arena_volume_relay_readiness"
            or value.get("status") != "READY"
            or value.get("campaign_id") != identity.campaign_id
            or value.get("generation_id") != identity.generation_id
            or value.get("attempt_id") != identity.attempt_id
            or value.get("readiness_nonce") != readiness_nonce
            or isinstance(value.get("relay_pid"), bool)
            or not isinstance(value.get("relay_pid"), int)
            or value["relay_pid"] <= 0
            or value.get("socket_path")
            != PROPOSER_RPC_SOCKET_DESTINATION
            or value.get("socket_mode") != 0o666
            or value.get("network_mode_required") != "none"
            or value.get("transport") != ARENA_VOLUME_TRANSPORT
        ):
            raise ContainerContractError(
                "Arena relay readiness does not bind the attempt"
            )
        _write_private_json_new(receipt_path, value)
        return (
            _hash_unaliased_regular_file(
                receipt_path, label="Arena relay readiness receipt"
            ),
            value,
        )

    def _start_attachment(
        self,
        *,
        container_id: str,
        arena_socket: Path,
    ) -> arena_volume_transport.AttachedArenaRelay:
        spawn = getattr(self._runner, "spawn_interactive", None)
        if not callable(spawn):
            raise ContainerContractError(
                "Docker runner lacks an interactive attach authority"
            )
        argv = (
            self._docker,
            "container",
            "attach",
            container_id,
        )
        process = spawn(argv)
        connection = socket.socket(socket.AF_UNIX, socket.SOCK_STREAM)
        try:
            connection.settimeout(30)
            connection.connect(str(arena_socket))
            connection.settimeout(None)
            return arena_volume_transport.AttachedArenaRelay.start(
                process=process,
                arena_socket=connection,
                relay_argv=argv,
                relay_container_id=container_id,
                arena_socket_identity_sha256=(
                    arena_volume_transport
                    ._endpoint_identity_sha256(arena_socket)
                ),
            )
        except BaseException:
            connection.close()
            if process.poll() is None:
                process.kill()
                process.wait(timeout=5)
            raise

    def prepare(
        self,
        *,
        identity: AttemptIdentity,
        transport: Any,
        arena_socket: Path,
        receipt_root: Path,
    ) -> ArenaVolumeRuntime:
        """Create, observe, start, and attach one exact relay boundary."""

        identity.validate()
        _snapshot_endpoint(
            arena_socket,
            label="Arena relay host socket",
            expected_kind="socket",
        )
        _validate_private_host_directory(receipt_root)
        image_reference = getattr(
            transport, "arena_relay_image_reference", None
        )
        image_digest = getattr(
            transport, "arena_relay_image_digest", None
        )
        source_sha256 = getattr(
            transport, "arena_relay_source_sha256", None
        )
        if (
            getattr(transport, "arena_transport", None)
            != ARENA_VOLUME_TRANSPORT
            or not isinstance(image_reference, str)
            or not isinstance(image_digest, str)
            or not _is_hex_sha256(source_sha256)
            or source_sha256
            != hashlib.sha256(
                Path(__file__).with_name(
                    "arc_agi3_arena_volume_relay.py"
                ).read_bytes()
            ).hexdigest()
        ):
            raise ContainerContractError(
                "Arena relay transport projection differs"
            )
        if self._query_relay_ids(identity) or self._query_volume_names(
            identity
        ):
            raise ContainerContractError(
                "fresh Arena relay preparation found a prior identity"
            )
        readiness_nonce = secrets.token_hex(32)
        volume = arena_volume_name(identity)
        relay_id: str | None = None
        attachment: arena_volume_transport.AttachedArenaRelay | None = None
        try:
            image, image_id, image_observation = (
                self._inspect_relay_image(
                    reference=image_reference,
                    digest=image_digest,
                    source_sha256=source_sha256,
                )
            )
            del image
            volume_argv: list[str] = [
                self._docker,
                "volume",
                "create",
                "--driver",
                "local",
            ]
            for name, value in sorted(
                self._identity_labels(identity).items()
            ):
                volume_argv.extend(("--label", f"{name}={value}"))
            volume_argv.append(volume)
            created_volume = self._backend._required(
                tuple(volume_argv),
                timeout_seconds=30,
                label="Arena volume create",
            ).stdout.strip()
            if created_volume != volume:
                raise ContainerContractError(
                    "Arena volume create acknowledgement differs"
                )
            _, volume_observation = self._inspect_volume(identity)
            create_argv = self._relay_create_argv(
                identity,
                image_reference=image_reference,
                source_sha256=source_sha256,
                readiness_nonce=readiness_nonce,
            )
            relay_id = self._backend._required(
                create_argv,
                timeout_seconds=60,
                label="Arena relay create",
            ).stdout.strip()
            if not CONTAINER_ID_RE.fullmatch(relay_id):
                raise ContainerContractError(
                    "Arena relay create acknowledgement is malformed"
                )
            created = self._backend._inspect_container(relay_id)
            self._validate_relay_container(
                created,
                identity=identity,
                container_id=relay_id,
                image_reference=image_reference,
                image_id=image_id,
                source_sha256=source_sha256,
                readiness_nonce=readiness_nonce,
                running=False,
            )
            start_result = self._backend._required(
                (self._docker, "container", "start", relay_id),
                timeout_seconds=30,
                label="Arena relay start",
            )
            if start_result.stdout.strip() not in ("", relay_id):
                raise ContainerContractError(
                    "Arena relay start acknowledgement differs"
                )
            running = self._backend._inspect_container(relay_id)
            running_observation = self._validate_relay_container(
                running,
                identity=identity,
                container_id=relay_id,
                image_reference=image_reference,
                image_id=image_id,
                source_sha256=source_sha256,
                readiness_nonce=readiness_nonce,
                running=True,
            )
            readiness_path = (
                receipt_root / "arena_volume_readiness.json"
            )
            readiness_sha256, _ = self._read_readiness(
                identity=identity,
                container_id=relay_id,
                readiness_nonce=readiness_nonce,
                receipt_path=readiness_path,
            )
            attachment = self._start_attachment(
                container_id=relay_id,
                arena_socket=arena_socket,
            )
            attach_argv_sha256 = hashlib.sha256(
                arena_volume_transport.canonical_json(
                    list(attachment.relay_argv)
                )
            ).hexdigest()
            receipt_path = (
                receipt_root / "arena_volume_preparation.json"
            )
            document = {
                "schema": 1,
                "kind": "arc_agi3_arena_volume_preparation",
                "campaign_id": identity.campaign_id,
                "generation_id": identity.generation_id,
                "attempt_id": identity.attempt_id,
                "game": identity.game,
                "target_level": identity.target_level,
                "transport": ARENA_VOLUME_TRANSPORT,
                "volume_name": volume,
                "volume_observation_sha256": volume_observation,
                "relay_container_id": relay_id,
                "relay_image_reference": image_reference,
                "relay_image_digest": image_digest,
                "relay_image_observation_sha256": image_observation,
                "relay_container_observation_sha256":
                    running_observation,
                "readiness_nonce": readiness_nonce,
                "readiness_receipt_path": str(readiness_path),
                "readiness_receipt_sha256": readiness_sha256,
                "attach_argv_sha256": attach_argv_sha256,
                "arena_socket_identity_sha256":
                    attachment.arena_socket_identity_sha256,
            }
            _write_private_json_new(receipt_path, document)
            receipt_sha256 = _hash_unaliased_regular_file(
                receipt_path,
                label="Arena volume preparation receipt",
            )
            evidence = ArenaVolumePreparationEvidence(
                transport=ARENA_VOLUME_TRANSPORT,
                volume_name=volume,
                volume_observation_sha256=volume_observation,
                relay_container_id=relay_id,
                relay_image_reference=image_reference,
                relay_image_digest=image_digest,
                relay_image_observation_sha256=image_observation,
                relay_container_observation_sha256=running_observation,
                readiness_nonce=readiness_nonce,
                readiness_receipt_path=str(readiness_path),
                readiness_receipt_sha256=readiness_sha256,
                attach_argv_sha256=attach_argv_sha256,
                arena_socket_identity_sha256=(
                    attachment.arena_socket_identity_sha256
                ),
                preparation_receipt_path=str(receipt_path),
                preparation_receipt_sha256=receipt_sha256,
            )
            return ArenaVolumeRuntime(
                evidence=evidence, attachment=attachment
            )
        except BaseException as original:
            if attachment is not None:
                attachment.abort()
            cleanup_errors = self._remove_exact_resources(
                identity=identity,
                relay_container_id=relay_id,
                volume_name=volume,
            )
            if cleanup_errors:
                raise ContainerContractError(
                    "Arena relay preparation failed and cleanup was "
                    "incomplete: "
                    + "; ".join(cleanup_errors)
                ) from original
            raise

    def rehydrate(
        self,
        *,
        identity: AttemptIdentity,
        transport: Any,
        receipt_root: Path,
    ) -> ArenaVolumeRuntime:
        """Rebind durable relay evidence solely for containment recovery."""

        identity.validate()
        _validate_private_host_directory(receipt_root)
        preparation_path = (
            receipt_root / "arena_volume_preparation.json"
        )
        readiness_path = receipt_root / "arena_volume_readiness.json"
        preparation = _read_unaliased_json(
            preparation_path,
            label="rehydrated Arena volume preparation",
        )
        readiness = _read_unaliased_json(
            readiness_path,
            label="rehydrated Arena volume readiness",
        )
        expected_preparation_fields = {
            "schema",
            "kind",
            "campaign_id",
            "generation_id",
            "attempt_id",
            "game",
            "target_level",
            "transport",
            "volume_name",
            "volume_observation_sha256",
            "relay_container_id",
            "relay_image_reference",
            "relay_image_digest",
            "relay_image_observation_sha256",
            "relay_container_observation_sha256",
            "readiness_nonce",
            "readiness_receipt_path",
            "readiness_receipt_sha256",
            "attach_argv_sha256",
            "arena_socket_identity_sha256",
        }
        expected_readiness_fields = {
            "schema",
            "kind",
            "status",
            "campaign_id",
            "generation_id",
            "attempt_id",
            "readiness_nonce",
            "relay_pid",
            "socket_path",
            "socket_mode",
            "network_mode_required",
            "transport",
        }
        volume_name = arena_volume_name(identity)
        relay_ids = self._query_relay_ids(identity)
        volume_names = self._query_volume_names(identity)
        relay_id = preparation.get("relay_container_id")
        image_reference = getattr(
            transport, "arena_relay_image_reference", None
        )
        image_digest = getattr(
            transport, "arena_relay_image_digest", None
        )
        source_sha256 = getattr(
            transport, "arena_relay_source_sha256", None
        )
        readiness_sha256 = _hash_unaliased_regular_file(
            readiness_path, label="rehydrated Arena readiness receipt"
        )
        if (
            set(preparation) != expected_preparation_fields
            or set(readiness) != expected_readiness_fields
            or preparation.get("schema") != 1
            or preparation.get("kind")
            != "arc_agi3_arena_volume_preparation"
            or readiness.get("schema") != 1
            or readiness.get("kind")
            != "arc_agi3_arena_volume_relay_readiness"
            or readiness.get("status") != "READY"
            or any(
                preparation.get(name) != value
                or readiness.get(name) != value
                for name, value in (
                    ("campaign_id", identity.campaign_id),
                    ("generation_id", identity.generation_id),
                    ("attempt_id", identity.attempt_id),
                )
            )
            or preparation.get("game") != identity.game
            or preparation.get("target_level")
            != identity.target_level
            or preparation.get("transport") != ARENA_VOLUME_TRANSPORT
            or readiness.get("transport") != ARENA_VOLUME_TRANSPORT
            or preparation.get("volume_name") != volume_name
            or preparation.get("relay_image_reference")
            != image_reference
            or preparation.get("relay_image_digest") != image_digest
            or getattr(transport, "arena_transport", None)
            != ARENA_VOLUME_TRANSPORT
            or not _is_hex_sha256(source_sha256)
            or not isinstance(relay_id, str)
            or not CONTAINER_ID_RE.fullmatch(relay_id)
            or relay_ids != (relay_id,)
            or volume_names != (volume_name,)
            or preparation.get("readiness_nonce")
            != readiness.get("readiness_nonce")
            or not re.fullmatch(
                r"[0-9a-f]{64}",
                str(preparation.get("readiness_nonce", "")),
            )
            or preparation.get("readiness_receipt_path")
            != str(readiness_path)
            or preparation.get("readiness_receipt_sha256")
            != readiness_sha256
            or readiness.get("socket_path")
            != PROPOSER_RPC_SOCKET_DESTINATION
            or readiness.get("socket_mode") != 0o666
            or readiness.get("network_mode_required") != "none"
            or not isinstance(readiness.get("relay_pid"), int)
            or isinstance(readiness.get("relay_pid"), bool)
            or readiness["relay_pid"] <= 0
            or any(
                not _is_hex_sha256(preparation.get(name))
                for name in (
                    "volume_observation_sha256",
                    "relay_image_observation_sha256",
                    "relay_container_observation_sha256",
                    "attach_argv_sha256",
                    "arena_socket_identity_sha256",
                )
            )
        ):
            raise ContainerContractError(
                "durable Arena relay preparation is stale or malformed"
            )
        _, volume_observation = self._inspect_volume(identity)
        if (
            volume_observation
            != preparation["volume_observation_sha256"]
        ):
            raise ContainerContractError(
                "durable Arena volume observation changed"
            )
        _, image_id, image_observation = self._inspect_relay_image(
            reference=image_reference,
            digest=image_digest,
            source_sha256=source_sha256,
        )
        if (
            image_observation
            != preparation["relay_image_observation_sha256"]
        ):
            raise ContainerContractError(
                "durable Arena relay image observation changed"
            )
        observed = self._backend._inspect_container(relay_id)
        state = _required_dict(
            observed, "State", label="rehydrated Arena relay State"
        )
        running = _required_bool(
            state,
            "Running",
            label="rehydrated Arena relay State.Running",
        )
        observed_sha256 = self._validate_relay_container(
            observed,
            identity=identity,
            container_id=relay_id,
            image_reference=image_reference,
            image_id=image_id,
            source_sha256=source_sha256,
            readiness_nonce=preparation["readiness_nonce"],
            running=running,
        )
        if (
            running
            and observed_sha256
            != preparation["relay_container_observation_sha256"]
        ):
            raise ContainerContractError(
                "running durable Arena relay observation changed"
            )
        evidence = ArenaVolumePreparationEvidence(
            transport=ARENA_VOLUME_TRANSPORT,
            volume_name=volume_name,
            volume_observation_sha256=(
                preparation["volume_observation_sha256"]
            ),
            relay_container_id=relay_id,
            relay_image_reference=image_reference,
            relay_image_digest=image_digest,
            relay_image_observation_sha256=(
                preparation["relay_image_observation_sha256"]
            ),
            relay_container_observation_sha256=(
                preparation["relay_container_observation_sha256"]
            ),
            readiness_nonce=preparation["readiness_nonce"],
            readiness_receipt_path=str(readiness_path),
            readiness_receipt_sha256=readiness_sha256,
            attach_argv_sha256=preparation["attach_argv_sha256"],
            arena_socket_identity_sha256=(
                preparation["arena_socket_identity_sha256"]
            ),
            preparation_receipt_path=str(preparation_path),
            preparation_receipt_sha256=(
                _hash_unaliased_regular_file(
                    preparation_path,
                    label="rehydrated Arena preparation receipt",
                )
            ),
        )
        return ArenaVolumeRuntime(evidence=evidence, attachment=None)

    def reopen_preparation_after_teardown(
        self,
        *,
        identity: AttemptIdentity,
        transport: Any,
        receipt_root: Path,
        prepared: Any,
    ) -> ArenaVolumePreparationEvidence:
        """Authenticate durable relay preparation after resources are absent.

        ``rehydrate`` deliberately requires the relay container and named
        volume to remain live, so it cannot be used after teardown has
        completed but before the aggregate backend proof was journaled.  This
        narrower path reopens both immutable preparation receipts and binds
        every projected field without treating vanished runtime resources as
        evidence.  ``recover_teardown`` subsequently performs the live absence
        queries and authenticates the terminal teardown receipt.
        """

        identity.validate()
        _validate_private_host_directory(receipt_root)
        preparation_path = (
            receipt_root / "arena_volume_preparation.json"
        )
        readiness_path = receipt_root / "arena_volume_readiness.json"
        preparation = _read_unaliased_json(
            preparation_path,
            label="terminal Arena volume preparation",
        )
        readiness = _read_unaliased_json(
            readiness_path,
            label="terminal Arena volume readiness",
        )
        preparation_sha256 = _hash_unaliased_regular_file(
            preparation_path,
            label="terminal Arena preparation receipt",
        )
        readiness_sha256 = _hash_unaliased_regular_file(
            readiness_path,
            label="terminal Arena readiness receipt",
        )
        for evidence_path, label in (
            (preparation_path, "Arena preparation receipt"),
            (readiness_path, "Arena readiness receipt"),
        ):
            metadata = evidence_path.lstat()
            if (
                metadata.st_uid != os.getuid()
                or metadata.st_nlink != 1
                or not stat.S_ISREG(metadata.st_mode)
                or stat.S_IMODE(metadata.st_mode) != 0o600
            ):
                raise ContainerContractError(
                    f"{label} must remain supervisor-owned and private"
                )
        expected_preparation_fields = {
            "schema",
            "kind",
            "campaign_id",
            "generation_id",
            "attempt_id",
            "game",
            "target_level",
            "transport",
            "volume_name",
            "volume_observation_sha256",
            "relay_container_id",
            "relay_image_reference",
            "relay_image_digest",
            "relay_image_observation_sha256",
            "relay_container_observation_sha256",
            "readiness_nonce",
            "readiness_receipt_path",
            "readiness_receipt_sha256",
            "attach_argv_sha256",
            "arena_socket_identity_sha256",
        }
        expected_readiness_fields = {
            "schema",
            "kind",
            "status",
            "campaign_id",
            "generation_id",
            "attempt_id",
            "readiness_nonce",
            "relay_pid",
            "socket_path",
            "socket_mode",
            "network_mode_required",
            "transport",
        }
        image_reference = getattr(
            transport, "arena_relay_image_reference", None
        )
        image_digest = getattr(
            transport, "arena_relay_image_digest", None
        )
        projected = {
            "transport": getattr(prepared, "arena_transport", None),
            "volume_name": getattr(
                prepared, "arena_volume_name", None
            ),
            "volume_observation_sha256": getattr(
                prepared, "arena_volume_observation_sha256", None
            ),
            "relay_container_id": getattr(
                prepared, "arena_relay_container_id", None
            ),
            "relay_image_digest": getattr(
                prepared, "arena_relay_image_digest", None
            ),
            "relay_image_observation_sha256": getattr(
                prepared,
                "arena_relay_image_observation_sha256",
                None,
            ),
            "relay_container_observation_sha256": getattr(
                prepared,
                "arena_relay_container_observation_sha256",
                None,
            ),
            "readiness_receipt_path": getattr(
                prepared,
                "arena_relay_readiness_receipt_path",
                None,
            ),
            "readiness_receipt_sha256": getattr(
                prepared,
                "arena_relay_readiness_receipt_sha256",
                None,
            ),
            "attach_argv_sha256": getattr(
                prepared, "arena_relay_attach_argv_sha256", None
            ),
            "arena_socket_identity_sha256": getattr(
                prepared,
                "arena_relay_socket_identity_sha256",
                None,
            ),
            "preparation_receipt_path": getattr(
                prepared,
                "arena_relay_preparation_receipt_path",
                None,
            ),
            "preparation_receipt_sha256": getattr(
                prepared,
                "arena_relay_preparation_receipt_sha256",
                None,
            ),
        }
        common = {
            "campaign_id": identity.campaign_id,
            "generation_id": identity.generation_id,
            "attempt_id": identity.attempt_id,
            "transport": ARENA_VOLUME_TRANSPORT,
        }
        if (
            set(preparation) != expected_preparation_fields
            or set(readiness) != expected_readiness_fields
            or preparation.get("schema") != 1
            or preparation.get("kind")
            != "arc_agi3_arena_volume_preparation"
            or readiness.get("schema") != 1
            or readiness.get("kind")
            != "arc_agi3_arena_volume_relay_readiness"
            or readiness.get("status") != "READY"
            or any(
                preparation.get(name) != value
                or readiness.get(name) != value
                for name, value in common.items()
            )
            or preparation.get("game") != identity.game
            or preparation.get("target_level")
            != identity.target_level
            or projected["transport"] != ARENA_VOLUME_TRANSPORT
            or getattr(transport, "arena_transport", None)
            != ARENA_VOLUME_TRANSPORT
            or preparation.get("volume_name")
            != arena_volume_name(identity)
            or preparation.get("volume_name")
            != projected["volume_name"]
            or preparation.get("relay_image_reference")
            != image_reference
            or preparation.get("relay_image_digest")
            != image_digest
            or preparation.get("relay_image_digest")
            != projected["relay_image_digest"]
            or preparation.get("readiness_nonce")
            != readiness.get("readiness_nonce")
            or not re.fullmatch(
                r"[0-9a-f]{64}",
                str(preparation.get("readiness_nonce", "")),
            )
            or preparation.get("readiness_receipt_path")
            != str(readiness_path)
            or preparation.get("readiness_receipt_path")
            != projected["readiness_receipt_path"]
            or preparation.get("readiness_receipt_sha256")
            != readiness_sha256
            or readiness_sha256
            != projected["readiness_receipt_sha256"]
            or preparation_sha256
            != projected["preparation_receipt_sha256"]
            or str(preparation_path)
            != projected["preparation_receipt_path"]
            or readiness.get("socket_path")
            != PROPOSER_RPC_SOCKET_DESTINATION
            or readiness.get("socket_mode") != 0o666
            or readiness.get("network_mode_required") != "none"
            or not isinstance(readiness.get("relay_pid"), int)
            or isinstance(readiness.get("relay_pid"), bool)
            or readiness["relay_pid"] <= 0
            or any(
                preparation.get(name) != projected[name]
                for name in (
                    "volume_observation_sha256",
                    "relay_container_id",
                    "relay_image_observation_sha256",
                    "relay_container_observation_sha256",
                    "attach_argv_sha256",
                    "arena_socket_identity_sha256",
                )
            )
            or not isinstance(
                preparation.get("relay_container_id"), str
            )
            or not CONTAINER_ID_RE.fullmatch(
                preparation["relay_container_id"]
            )
            or any(
                not _is_hex_sha256(preparation.get(name))
                for name in (
                    "volume_observation_sha256",
                    "relay_image_observation_sha256",
                    "relay_container_observation_sha256",
                    "attach_argv_sha256",
                    "arena_socket_identity_sha256",
                )
            )
        ):
            raise ContainerContractError(
                "terminal Arena relay preparation is stale or malformed"
            )
        return ArenaVolumePreparationEvidence(
            transport=ARENA_VOLUME_TRANSPORT,
            volume_name=preparation["volume_name"],
            volume_observation_sha256=(
                preparation["volume_observation_sha256"]
            ),
            relay_container_id=preparation["relay_container_id"],
            relay_image_reference=preparation[
                "relay_image_reference"
            ],
            relay_image_digest=preparation["relay_image_digest"],
            relay_image_observation_sha256=preparation[
                "relay_image_observation_sha256"
            ],
            relay_container_observation_sha256=preparation[
                "relay_container_observation_sha256"
            ],
            readiness_nonce=preparation["readiness_nonce"],
            readiness_receipt_path=str(readiness_path),
            readiness_receipt_sha256=readiness_sha256,
            attach_argv_sha256=preparation["attach_argv_sha256"],
            arena_socket_identity_sha256=preparation[
                "arena_socket_identity_sha256"
            ],
            preparation_receipt_path=str(preparation_path),
            preparation_receipt_sha256=preparation_sha256,
        )

    def _remove_exact_resources(
        self,
        *,
        identity: AttemptIdentity,
        relay_container_id: str | None,
        volume_name: str,
    ) -> list[str]:
        errors: list[str] = []
        ids = self._query_relay_ids(identity)
        if relay_container_id is None:
            if len(ids) > 1:
                return ["Arena relay identity is ambiguous"]
            relay_container_id = ids[0] if ids else None
        elif ids not in ((), (relay_container_id,)):
            return ["Arena relay identity changed before cleanup"]
        if relay_container_id is not None:
            result = self._runner.run(
                (
                    self._docker,
                    "container",
                    "rm",
                    "--force",
                    "--volumes",
                    relay_container_id,
                ),
                timeout_seconds=60,
            )
            if (
                not isinstance(result, CommandResult)
                or result.argv
                != (
                    self._docker,
                    "container",
                    "rm",
                    "--force",
                    "--volumes",
                    relay_container_id,
                )
                or result.returncode != 0
            ):
                errors.append("Arena relay container removal failed")
        if self._query_volume_names(identity):
            result = self._runner.run(
                (
                    self._docker,
                    "volume",
                    "rm",
                    volume_name,
                ),
                timeout_seconds=60,
            )
            if (
                not isinstance(result, CommandResult)
                or result.argv
                != (
                    self._docker,
                    "volume",
                    "rm",
                    volume_name,
                )
                or result.returncode != 0
            ):
                errors.append("Arena volume removal failed")
        return errors

    def reconcile_incomplete(
        self, identity: AttemptIdentity
    ) -> None:
        """Remove exact pre-attestation remnants before a fresh preparation."""

        errors = self._remove_exact_resources(
            identity=identity,
            relay_container_id=None,
            volume_name=arena_volume_name(identity),
        )
        if errors:
            raise ContainerContractError(
                "incomplete Arena relay reconciliation failed: "
                + "; ".join(errors)
            )
        if self._query_relay_ids(identity) or self._query_volume_names(
            identity
        ):
            raise ContainerContractError(
                "incomplete Arena relay reconciliation left descendants"
            )

    def teardown(
        self,
        *,
        identity: AttemptIdentity,
        runtime: ArenaVolumeRuntime,
        receipt_root: Path,
        containment_fault: bool,
    ) -> ArenaVolumeTeardownEvidence:
        evidence = runtime.evidence
        if (
            evidence.transport != ARENA_VOLUME_TRANSPORT
            or evidence.volume_name != arena_volume_name(identity)
            or not CONTAINER_ID_RE.fullmatch(
                evidence.relay_container_id
            )
        ):
            raise ContainerContractError(
                "Arena relay teardown binding differs"
            )
        attachment_receipt: dict[str, Any] | None = None
        attachment_status = "ABORTED_CONTAINMENT"
        attachment_error: BaseException | None = None
        if runtime.attachment is not None:
            if containment_fault:
                runtime.attachment.abort()
            else:
                try:
                    attachment_receipt = runtime.attachment.finish(
                        timeout_seconds=30
                    )
                    attachment_status = "CLEAN_EOF"
                except BaseException as exc:
                    attachment_error = exc
                    runtime.attachment.abort()
        elif not containment_fault:
            attachment_error = ContainerContractError(
                "normal Arena relay teardown lost attachment ownership"
            )
        removal_errors = self._remove_exact_resources(
            identity=identity,
            relay_container_id=evidence.relay_container_id,
            volume_name=evidence.volume_name,
        )
        relay_inspect_absent = self._backend._expect_absent(
            (
                self._docker,
                "container",
                "inspect",
                evidence.relay_container_id,
            ),
            label="terminal Arena relay inspection",
        )
        relay_top_absent = self._backend._expect_absent(
            (
                self._docker,
                "container",
                "top",
                evidence.relay_container_id,
                "-eo",
                "pid,ppid",
            ),
            label="terminal Arena relay process inventory",
        )
        relay_identity_empty = not self._query_relay_ids(identity)
        volume_inspect_absent = self._backend._expect_absent(
            (
                self._docker,
                "volume",
                "inspect",
                evidence.volume_name,
            ),
            label="terminal Arena volume inspection",
        )
        volume_identity_empty = not self._query_volume_names(identity)
        if (
            removal_errors
            or not relay_inspect_absent
            or not relay_top_absent
            or not relay_identity_empty
            or not volume_inspect_absent
            or not volume_identity_empty
        ):
            raise ContainerContractError(
                "Arena relay/volume teardown did not prove exact absence"
                + (
                    ": " + "; ".join(removal_errors)
                    if removal_errors
                    else ""
                )
            )
        if attachment_error is not None:
            raise ContainerContractError(
                "Arena relay transport did not close cleanly"
            ) from attachment_error
        attachment_receipt_sha256 = (
            _json_sha256(attachment_receipt)
            if attachment_receipt is not None
            else None
        )
        receipt_path = receipt_root / "arena_volume_teardown.json"
        document = {
            "schema": 1,
            "kind": "arc_agi3_arena_volume_teardown",
            "campaign_id": identity.campaign_id,
            "generation_id": identity.generation_id,
            "attempt_id": identity.attempt_id,
            "transport": ARENA_VOLUME_TRANSPORT,
            "preparation_receipt_sha256":
                evidence.preparation_receipt_sha256,
            "relay_container_id": evidence.relay_container_id,
            "volume_name": evidence.volume_name,
            "attachment_status": attachment_status,
            "attachment_receipt": attachment_receipt,
            "attachment_receipt_sha256":
                attachment_receipt_sha256,
            "relay_inspect_absent": True,
            "relay_top_absent": True,
            "relay_identity_query_empty": True,
            "volume_inspect_absent": True,
            "volume_identity_query_empty": True,
        }
        _write_private_json_new(receipt_path, document)
        receipt_sha256 = _hash_unaliased_regular_file(
            receipt_path, label="Arena volume teardown receipt"
        )
        return ArenaVolumeTeardownEvidence(
            relay_container_id=evidence.relay_container_id,
            volume_name=evidence.volume_name,
            attachment_status=attachment_status,
            attachment_receipt_sha256=attachment_receipt_sha256,
            relay_inspect_absent=True,
            relay_top_absent=True,
            relay_identity_query_empty=True,
            volume_inspect_absent=True,
            volume_identity_query_empty=True,
            receipt_path=str(receipt_path),
            receipt_sha256=receipt_sha256,
        )

    def recover_teardown(
        self,
        *,
        identity: AttemptIdentity,
        preparation: ArenaVolumePreparationEvidence,
        transport: Any,
        receipt_root: Path,
        containment_fault: bool,
    ) -> ArenaVolumeTeardownEvidence:
        """Reopen a completed receipt or fail closed while containing orphans."""

        identity.validate()
        expected_status = (
            "ABORTED_CONTAINMENT"
            if containment_fault
            else "CLEAN_EOF"
        )
        receipt_path = receipt_root / "arena_volume_teardown.json"
        if receipt_path.exists() or receipt_path.is_symlink():
            value = _read_unaliased_json(
                receipt_path,
                label="recovered Arena relay teardown receipt",
            )
            attachment = value.get("attachment_receipt")
            attachment_sha256 = (
                _json_sha256(attachment)
                if isinstance(attachment, dict)
                else None
            )
            expected_fields = {
                "schema",
                "kind",
                "campaign_id",
                "generation_id",
                "attempt_id",
                "transport",
                "preparation_receipt_sha256",
                "relay_container_id",
                "volume_name",
                "attachment_status",
                "attachment_receipt",
                "attachment_receipt_sha256",
                "relay_inspect_absent",
                "relay_top_absent",
                "relay_identity_query_empty",
                "volume_inspect_absent",
                "volume_identity_query_empty",
            }
            if (
                set(value) != expected_fields
                or value.get("schema") != 1
                or value.get("kind")
                != "arc_agi3_arena_volume_teardown"
                or value.get("campaign_id") != identity.campaign_id
                or value.get("generation_id")
                != identity.generation_id
                or value.get("attempt_id") != identity.attempt_id
                or value.get("transport") != ARENA_VOLUME_TRANSPORT
                or value.get("preparation_receipt_sha256")
                != preparation.preparation_receipt_sha256
                or value.get("relay_container_id")
                != preparation.relay_container_id
                or value.get("volume_name")
                != preparation.volume_name
                or value.get("attachment_status") != expected_status
                or value.get("attachment_receipt_sha256")
                != attachment_sha256
                or (
                    expected_status == "CLEAN_EOF"
                    and not isinstance(attachment, dict)
                )
                or (
                    expected_status == "ABORTED_CONTAINMENT"
                    and attachment is not None
                )
                or any(
                    value.get(name) is not True
                    for name in (
                        "relay_inspect_absent",
                        "relay_top_absent",
                        "relay_identity_query_empty",
                        "volume_inspect_absent",
                        "volume_identity_query_empty",
                    )
                )
                or self._query_relay_ids(identity)
                or self._query_volume_names(identity)
                or not self._backend._expect_absent(
                    (
                        self._docker,
                        "container",
                        "inspect",
                        preparation.relay_container_id,
                    ),
                    label="recovered terminal Arena relay inspection",
                )
                or not self._backend._expect_absent(
                    (
                        self._docker,
                        "container",
                        "top",
                        preparation.relay_container_id,
                        "-eo",
                        "pid,ppid",
                    ),
                    label="recovered terminal Arena relay process inventory",
                )
                or not self._backend._expect_absent(
                    (
                        self._docker,
                        "volume",
                        "inspect",
                        preparation.volume_name,
                    ),
                    label="recovered terminal Arena volume inspection",
                )
            ):
                raise ContainerContractError(
                    "durable Arena relay teardown proof changed"
                )
            return ArenaVolumeTeardownEvidence(
                relay_container_id=preparation.relay_container_id,
                volume_name=preparation.volume_name,
                attachment_status=expected_status,
                attachment_receipt_sha256=attachment_sha256,
                relay_inspect_absent=True,
                relay_top_absent=True,
                relay_identity_query_empty=True,
                volume_inspect_absent=True,
                volume_identity_query_empty=True,
                receipt_path=str(receipt_path),
                receipt_sha256=_hash_unaliased_regular_file(
                    receipt_path,
                    label="recovered Arena relay teardown receipt",
                ),
            )
        relay_ids = self._query_relay_ids(identity)
        volume_names = self._query_volume_names(identity)
        if not relay_ids and not volume_names:
            raise ContainerContractError(
                "Arena relay resources vanished without a durable teardown "
                "receipt"
            )
        runtime = self.rehydrate(
            identity=identity,
            transport=transport,
            receipt_root=receipt_root,
        )
        recovered = self.teardown(
            identity=identity,
            runtime=runtime,
            receipt_root=receipt_root,
            containment_fault=True,
        )
        if not containment_fault:
            raise ContainerContractError(
                "normal Arena relay ownership was lost; resources were "
                "contained but CLEAN_EOF cannot be reconstructed"
            )
        return recovered


@dataclass(frozen=True)
class ControllerRoleImage:
    reference: str
    manifest_digest: str
    image_id: str
    role: str
    entrypoint: tuple[str, ...]
    user: str
    labels: tuple[tuple[str, str], ...]
    observation_sha256: str


class DockerControllerContainerLauncher:
    """Create/attach/contain the model controller and enforcing proxy.

    Intent is fsynced before the first Docker create.  The immutable launch
    receipt is fsynced after both full container IDs have been inspected and
    before either role starts.  Recovery therefore queries exact
    campaign/generation/attempt/role labels and never signals a host PID.
    """

    _PROXY_CPUS = 1.0
    _PROXY_MEMORY_BYTES = 256 * 1024 * 1024
    _PROXY_PIDS = 128
    _PROXY_TMPFS_BYTES = 64 * 1024 * 1024

    def __init__(self, backend: DockerContainerBackend) -> None:
        if not isinstance(backend, DockerContainerBackend):
            raise ContainerContractError(
                "controller launcher requires the observed Docker backend"
            )
        if not callable(
            getattr(backend._runner, "spawn_interactive", None)
        ):
            raise ContainerContractError(
                "controller launcher requires interactive Docker attach"
            )
        self._backend = backend
        self._runner = backend._runner
        self._docker = backend._docker
        self._lock = threading.RLock()

    @staticmethod
    def _identity(binding: Any) -> AttemptIdentity:
        identity = AttemptIdentity(
            campaign_id=binding.campaign_id,
            generation_id=binding.generation_id,
            attempt_id=binding.attempt_id,
            game="ctrl",
            target_level=1,
        )
        # AttemptIdentity's game contract is the ARC four-character syntax;
        # this synthetic value is never used as a game label.
        identity.validate()
        return identity

    @staticmethod
    def _role_name(binding: Any, role: str) -> str:
        suffix = "controller" if role == CONTROLLER_ROLE else "egress"
        return f"arc3-{binding.attempt_id}-{suffix}"

    @staticmethod
    def _labels(
        binding: Any,
        *,
        role: str,
        transport: Any,
        proxy_id: str | None = None,
    ) -> dict[str, str]:
        labels = {
            LABEL_CAMPAIGN: binding.campaign_id,
            LABEL_GENERATION: binding.generation_id,
            LABEL_ATTEMPT: binding.attempt_id,
            LABEL_ROLE: role,
            LABEL_CONTROLLER_IMAGE_DIGEST:
                transport.controller_image_digest,
            LABEL_EGRESS_PROXY_IMAGE_DIGEST:
                transport.controller_egress_proxy_image_digest,
            LABEL_EGRESS_POLICY_SHA256:
                transport.controller_egress_policy_sha256,
        }
        if proxy_id is not None:
            labels[LABEL_CONTROLLER_PROXY] = proxy_id
        return labels

    def _inspect_role_image(
        self,
        *,
        reference: str,
        role: str,
        expected_entrypoint: tuple[str, ...],
        expected_user: str,
        required_labels: Mapping[str, str],
    ) -> ControllerRoleImage:
        _, requested_digest = parse_digest_reference(reference)
        result = self._backend._required(
            (self._docker, "image", "inspect", reference),
            timeout_seconds=30,
            label=f"{role} image inspection",
        )
        observed = _parse_single_inspect_object(
            result.stdout, label=f"{role} image inspection"
        )
        image_id = _required_digest(
            observed, "Id", label=f"{role} image Id"
        )
        repo_digests = _required_list(
            observed, "RepoDigests", label=f"{role} RepoDigests"
        )
        observed_digests: set[str] = set()
        for item in repo_digests:
            if not isinstance(item, str):
                raise ContainerContractError(
                    f"{role} RepoDigest is malformed"
                )
            _, digest = parse_digest_reference(item)
            observed_digests.add(digest)
        if requested_digest not in observed_digests:
            raise ContainerContractError(
                f"{role} image is not observed at the requested digest"
            )
        config = _required_dict(
            observed, "Config", label=f"{role} image Config"
        )
        entrypoint_value = _required_list(
            config, "Entrypoint", label=f"{role} image entrypoint"
        )
        user = _required_string(
            config, "User", label=f"{role} image user"
        )
        labels = _required_dict(
            config, "Labels", label=f"{role} image labels"
        )
        environment = _required_list(
            config, "Env", label=f"{role} image environment"
        )
        if (
            tuple(entrypoint_value) != expected_entrypoint
            or user != expected_user
            or set(_parse_environment_names(environment))
            - ALLOWED_IMAGE_ENV_NAMES
            or any(labels.get(key) != value
                   for key, value in required_labels.items())
        ):
            raise ContainerContractError(
                f"{role} image configuration differs from the frozen pins"
            )
        return ControllerRoleImage(
            reference=reference,
            manifest_digest=requested_digest,
            image_id=image_id,
            role=role,
            entrypoint=expected_entrypoint,
            user=user,
            labels=tuple(
                sorted(
                    (key, str(labels[key]))
                    for key in required_labels
                )
            ),
            observation_sha256=_json_sha256(observed),
        )

    def _query_role_ids(
        self, binding: Any, *, role: str
    ) -> tuple[str, ...]:
        result = self._backend._required(
            (
                self._docker,
                "container",
                "ls",
                "--all",
                "--quiet",
                "--no-trunc",
                "--filter",
                f"label={LABEL_CAMPAIGN}={binding.campaign_id}",
                "--filter",
                f"label={LABEL_GENERATION}={binding.generation_id}",
                "--filter",
                f"label={LABEL_ATTEMPT}={binding.attempt_id}",
                "--filter",
                f"label={LABEL_ROLE}={role}",
            ),
            timeout_seconds=30,
            label=f"{role} identity query",
        )
        return _parse_container_id_lines(
            result.stdout, label=f"{role} identity query"
        )

    @staticmethod
    def _receipt_root(binding: Any) -> Path:
        control = Path(binding.app_server_control_dir)
        _validate_private_host_directory(control)
        root = control.parent
        _validate_private_host_directory(root)
        return root

    @staticmethod
    def _canary_anchor_document(
        binding: Any,
    ) -> dict[str, str]:
        return {
            "escrow_path": binding.controller_canary_escrow_path,
            "escrow_sha256": binding.controller_canary_escrow_sha256,
            "escrow_identity_sha256":
                binding.controller_canary_escrow_identity_sha256,
            "commitments_json":
                binding.controller_canary_commitments_json,
            "commitments_sha256":
                binding.controller_canary_commitments_sha256,
            "placement_descriptors_json":
                binding
                .controller_canary_placement_descriptors_json,
            "placement_descriptors_sha256":
                binding
                .controller_canary_placement_descriptors_sha256,
        }

    @staticmethod
    def _intent_document(
        binding: Any, transport: Any
    ) -> dict[str, Any]:
        return {
            "schema": 1,
            "kind": "arc_agi3_controller_launch_intent",
            "campaign_id": binding.campaign_id,
            "generation_id": binding.generation_id,
            "attempt_id": binding.attempt_id,
            "attempt_spec_sha256": binding.attempt_spec_sha256,
            "containment_canary_anchor":
                DockerControllerContainerLauncher
                ._canary_anchor_document(binding),
            "controller_image_reference":
                transport.controller_image_reference,
            "controller_image_digest":
                transport.controller_image_digest,
            "egress_proxy_image_reference":
                transport.controller_egress_proxy_image_reference,
            "egress_proxy_image_digest":
                transport.controller_egress_proxy_image_digest,
            "egress_policy": transport.controller_egress_policy,
            "egress_policy_sha256":
                transport.controller_egress_policy_sha256,
            "controller_entrypoint":
                list(transport.controller_entrypoint),
            "controller_user": transport.controller_user,
            "controller_resources": {
                "cpus": float(transport.controller_cpus),
                "memory_bytes": transport.controller_memory_bytes,
                "pids": transport.controller_pids,
                "tmpfs_bytes": transport.controller_tmpfs_bytes,
            },
        }

    @staticmethod
    def _read_exact_receipt(
        path: Path, expected: Mapping[str, Any], *, label: str
    ) -> str:
        observed = _read_unaliased_json(path, label=label)
        if observed != dict(expected):
            raise ContainerContractError(f"{label} differs")
        return _hash_unaliased_regular_file(path, label=label)

    def _ensure_intent(
        self, binding: Any, transport: Any
    ) -> tuple[Path, str]:
        path = self._receipt_root(binding) / "controller_launch_intent.json"
        document = self._intent_document(binding, transport)
        if path.exists() or path.is_symlink():
            return path, self._read_exact_receipt(
                path, document, label="controller launch intent"
            )
        _write_private_json_new(path, document)
        return path, self._read_exact_receipt(
            path, document, label="controller launch intent"
        )

    @staticmethod
    def _archive_superseded_receipt(
        path: Path,
        *,
        label: str,
    ) -> Path | None:
        if not path.exists() and not path.is_symlink():
            return None
        digest = _hash_unaliased_regular_file(path, label=label)
        archived = path.with_name(
            f"{path.stem}.superseded-{digest}{path.suffix}"
        )
        if archived.exists() or archived.is_symlink():
            if (
                _hash_unaliased_regular_file(
                    archived, label=f"archived {label}"
                )
                != digest
            ):
                raise ContainerContractError(
                    f"archived {label} conflicts with active receipt"
                )
            path.unlink()
        else:
            os.replace(path, archived)
        _fsync_private_parent(path)
        return archived

    def _supersede_stopped_launch(
        self,
        *,
        binding: Any,
        controller_id: str,
        proxy_id: str,
        launch_path: Path,
    ) -> None:
        """Remove an incomplete launch epoch; never restart stopped roles."""

        observed_roles = {
            CONTROLLER_ROLE: self._query_role_ids(
                binding, role=CONTROLLER_ROLE
            ),
            EGRESS_PROXY_ROLE: self._query_role_ids(
                binding, role=EGRESS_PROXY_ROLE
            ),
        }
        expected_ids = {
            CONTROLLER_ROLE: controller_id,
            EGRESS_PROXY_ROLE: proxy_id,
        }
        for role, ids in observed_roles.items():
            expected_id = expected_ids[role]
            if ids not in ((), (expected_id,)):
                raise ContainerContractError(
                    f"stopped {role} launch recovery is ambiguous"
                )
            if ids:
                self._remove_role(
                    binding,
                    role=role,
                    container_id=expected_id,
                    force=True,
                )
        if any(
            self._query_role_ids(binding, role=role)
            for role in (CONTROLLER_ROLE, EGRESS_PROXY_ROLE)
        ):
            raise ContainerContractError(
                "stopped controller launch roles survived exact recovery"
            )
        control_root = self._receipt_root(binding)
        self._archive_superseded_receipt(
            launch_path, label="stopped controller launch receipt"
        )
        self._archive_superseded_receipt(
            control_root / "controller_guardian_start.json",
            label="stopped controller guardian start receipt",
        )
        self._archive_superseded_receipt(
            control_root / "controller_egress_readiness.json",
            label="stopped controller egress readiness receipt",
        )
        self._archive_superseded_receipt(
            control_root / "controller_egress_live_probe.json",
            label="stopped controller egress live-probe receipt",
        )

    def _validate_role_container(
        self,
        *,
        observed: Mapping[str, Any],
        binding: Any,
        role: str,
        image: ControllerRoleImage,
        labels: Mapping[str, str],
        expected_network: str,
        expected_user: str,
        expected_entrypoint: tuple[str, ...],
        expected_command: tuple[str, ...],
        state_root: Path | None,
        transport: Any,
    ) -> str:
        container_id = _required_string(
            observed, "Id", label=f"{role} container Id"
        )
        if not CONTAINER_ID_RE.fullmatch(container_id):
            raise ContainerContractError(
                f"{role} container lacks a full Id"
            )
        if _required_digest(
            observed, "Image", label=f"{role} container Image"
        ) != image.image_id:
            raise ContainerContractError(
                f"{role} container image ID differs"
            )
        config = _required_dict(
            observed, "Config", label=f"{role} Config"
        )
        host = _required_dict(
            observed, "HostConfig", label=f"{role} HostConfig"
        )
        actual_labels = _required_dict(
            config, "Labels", label=f"{role} labels"
        )
        if any(actual_labels.get(key) != value
               for key, value in labels.items()):
            raise ContainerContractError(
                f"{role} identity/security labels differ"
            )
        if (
            _required_string(
                config, "Image", label=f"{role} Config.Image"
            )
            != image.reference
            or _required_string(
                config, "User", label=f"{role} Config.User"
            )
            != expected_user
            or tuple(
                _required_list(
                    config,
                    "Entrypoint",
                    label=f"{role} Config.Entrypoint",
                )
            )
            != expected_entrypoint
            or tuple(
                _required_list(
                    config, "Cmd", label=f"{role} Config.Cmd"
                )
            )
            != expected_command
            or set(
                _parse_environment_names(
                    _required_list(
                        config,
                        "Env",
                        label=f"{role} Config.Env",
                    )
                )
            )
            - ALLOWED_IMAGE_ENV_NAMES
            or not _required_bool(
                host, "ReadonlyRootfs",
                label=f"{role} ReadonlyRootfs",
            )
            or _required_string(
                host, "NetworkMode", label=f"{role} NetworkMode"
            )
            != expected_network
            or _required_string(
                host, "PidMode", label=f"{role} PidMode"
            )
            != ""
            or _required_string(
                host, "CgroupnsMode", label=f"{role} CgroupnsMode"
            )
            != "private"
            or _required_string(
                host, "IpcMode", label=f"{role} IpcMode"
            )
            != "private"
            or _required_string(
                host, "UTSMode", label=f"{role} UTSMode"
            )
            != ""
            or _required_bool(
                host, "Privileged", label=f"{role} Privileged"
            )
            or "no-new-privileges=true"
            not in _required_list(
                host, "SecurityOpt", label=f"{role} SecurityOpt"
            )
            or _required_dict(
                host, "RestartPolicy",
                label=f"{role} RestartPolicy",
            ).get("Name")
            != "no"
        ):
            raise ContainerContractError(
                f"{role} isolation projection differs"
            )
        cap_add = (
            _required_optional_empty_list(
                host, "CapAdd", label=f"{role} CapAdd"
            )
            if role == CONTROLLER_ROLE
            else _required_list(
                host, "CapAdd", label=f"{role} CapAdd"
            )
        )
        cap_drop = {
            str(value).upper()
            for value in _required_list(
                host, "CapDrop", label=f"{role} CapDrop"
            )
        }
        if role == CONTROLLER_ROLE:
            if cap_add or cap_drop != {"ALL"}:
                raise ContainerContractError(
                    "controller capabilities are not fully dropped"
                )
            expected_cpus = int(
                float(transport.controller_cpus) * 1_000_000_000
            )
            expected_memory = transport.controller_memory_bytes
            expected_pids = transport.controller_pids
        else:
            if {str(value).upper() for value in cap_add} != {
                "NET_ADMIN"
            } or cap_drop != {"ALL"}:
                raise ContainerContractError(
                    "egress proxy capabilities are not exact"
                )
            expected_cpus = int(self._PROXY_CPUS * 1_000_000_000)
            expected_memory = self._PROXY_MEMORY_BYTES
            expected_pids = self._PROXY_PIDS
        if (
            _required_int(host, "NanoCpus", label=f"{role} NanoCpus")
            != expected_cpus
            or _required_int(host, "Memory", label=f"{role} Memory")
            != expected_memory
            or _required_int(
                host, "MemorySwap", label=f"{role} MemorySwap"
            )
            != expected_memory
            or _required_int(
                host, "PidsLimit", label=f"{role} PidsLimit"
            )
            != expected_pids
        ):
            raise ContainerContractError(
                f"{role} resource bounds differ"
            )
        mounts = _required_list(
            observed, "Mounts", label=f"{role} Mounts"
        )
        if role == CONTROLLER_ROLE:
            if state_root is None or len(mounts) != 1:
                raise ContainerContractError(
                    "controller mount allowlist is not exactly state-only"
                )
            mount = mounts[0]
            if (
                not isinstance(mount, dict)
                or mount.get("Type") != "bind"
                or Path(str(mount.get("Source"))) != state_root
                or mount.get("Destination")
                != CONTROLLER_STATE_DESTINATION
                or mount.get("RW") is not True
                or mount.get("Propagation") != "rprivate"
            ):
                raise ContainerContractError(
                    "controller state mount differs"
                )
        elif mounts:
            raise ContainerContractError(
                "egress proxy unexpectedly received a host mount"
            )
        return _json_sha256(observed)

    def _remove_role(
        self,
        binding: Any,
        *,
        role: str,
        container_id: str,
        force: bool,
    ) -> None:
        if not CONTAINER_ID_RE.fullmatch(container_id):
            raise ContainerContractError(
                "controller recovery target is not a full Id"
            )
        observed = self._backend._inspect_container(container_id)
        config = _required_dict(
            observed, "Config", label=f"{role} recovery Config"
        )
        labels = _required_dict(
            config, "Labels", label=f"{role} recovery labels"
        )
        expected = {
            LABEL_CAMPAIGN: binding.campaign_id,
            LABEL_GENERATION: binding.generation_id,
            LABEL_ATTEMPT: binding.attempt_id,
            LABEL_ROLE: role,
        }
        if any(labels.get(key) != value
               for key, value in expected.items()):
            raise ContainerContractError(
                "controller recovery refused a label mismatch"
            )
        argv = [self._docker, "container", "rm"]
        if force:
            argv.append("--force")
        argv.append(container_id)
        self._backend._required(
            tuple(argv),
            timeout_seconds=60,
            label=f"{role} exact removal",
        )
        if not self._backend._expect_absent(
            (self._docker, "container", "inspect", container_id),
            label=f"{role} post-removal inspect",
        ):
            raise ContainerContractError(
                f"{role} survived exact removal"
            )

    def _recover_pre_receipt_orphans(
        self, binding: Any, *, launch_receipt_exists: bool
    ) -> None:
        if launch_receipt_exists:
            return
        for role in (CONTROLLER_ROLE, EGRESS_PROXY_ROLE):
            ids = self._query_role_ids(binding, role=role)
            if len(ids) > 1:
                raise ContainerContractError(
                    f"multiple orphaned {role} containers exist"
                )
            if ids:
                self._remove_role(
                    binding,
                    role=role,
                    container_id=ids[0],
                    force=True,
                )
        if any(
            self._query_role_ids(binding, role=role)
            for role in (CONTROLLER_ROLE, EGRESS_PROXY_ROLE)
        ):
            raise ContainerContractError(
                "pre-receipt controller recovery left a role present"
            )
        control_root = self._receipt_root(binding)
        self._archive_superseded_receipt(
            control_root / "controller_egress_readiness.json",
            label="orphan controller egress readiness receipt",
        )
        self._archive_superseded_receipt(
            control_root / "controller_egress_live_probe.json",
            label="orphan controller egress live-probe receipt",
        )

    @staticmethod
    def _proxy_readiness_nonce(binding: Any, transport: Any) -> str:
        return _json_sha256(
            {
                "schema": 1,
                "kind": "arc_agi3_controller_egress_readiness_nonce",
                "campaign_id": binding.campaign_id,
                "generation_id": binding.generation_id,
                "attempt_id": binding.attempt_id,
                "attempt_spec_sha256": binding.attempt_spec_sha256,
                "egress_proxy_image_digest":
                    transport.controller_egress_proxy_image_digest,
                "egress_policy": transport.controller_egress_policy,
                "egress_policy_sha256":
                    transport.controller_egress_policy_sha256,
            }
        )

    @classmethod
    def _proxy_command(
        cls, binding: Any, transport: Any
    ) -> tuple[str, ...]:
        return (
            "--policy",
            transport.controller_egress_policy,
            "--policy-sha256",
            transport.controller_egress_policy_sha256,
            "--campaign-id",
            binding.campaign_id,
            "--generation-id",
            binding.generation_id,
            "--attempt-id",
            binding.attempt_id,
            "--readiness-nonce",
            cls._proxy_readiness_nonce(binding, transport),
        )

    def _proxy_create_argv(
        self,
        *,
        binding: Any,
        transport: Any,
        image: ControllerRoleImage,
    ) -> tuple[str, ...]:
        labels = self._labels(
            binding, role=EGRESS_PROXY_ROLE, transport=transport
        )
        argv: list[str] = [
            self._docker,
            "container",
            "create",
            "--name",
            self._role_name(binding, EGRESS_PROXY_ROLE),
        ]
        for key, value in sorted(labels.items()):
            argv.extend(("--label", f"{key}={value}"))
        argv.extend(
            (
                "--read-only",
                "--network",
                "bridge",
                "--cgroupns",
                "private",
                "--ipc",
                "private",
                "--cap-drop",
                "ALL",
                "--cap-add",
                "NET_ADMIN",
                "--security-opt",
                "no-new-privileges=true",
                "--user",
                "0:0",
                "--cpus",
                _format_cpus(self._PROXY_CPUS),
                "--memory",
                str(self._PROXY_MEMORY_BYTES),
                "--memory-swap",
                str(self._PROXY_MEMORY_BYTES),
                "--pids-limit",
                str(self._PROXY_PIDS),
                "--restart",
                "no",
                "--no-healthcheck",
                "--log-driver",
                "none",
                "--pull",
                "never",
                "--tmpfs",
                (
                    "/run:rw,nosuid,nodev,noexec,"
                    f"size={self._PROXY_TMPFS_BYTES},mode=0755"
                ),
                "--entrypoint",
                CONTROLLER_PROXY_ENTRYPOINT[0],
                image.reference,
                *self._proxy_command(binding, transport),
            )
        )
        return _validated_argv(argv)

    def _controller_create_argv(
        self,
        *,
        binding: Any,
        transport: Any,
        image: ControllerRoleImage,
        proxy_id: str,
        state_root: Path,
    ) -> tuple[str, ...]:
        if not CONTAINER_ID_RE.fullmatch(proxy_id):
            raise ContainerContractError(
                "controller network authority lacks a full proxy Id"
            )
        labels = self._labels(
            binding,
            role=CONTROLLER_ROLE,
            transport=transport,
            proxy_id=proxy_id,
        )
        state_mount = (
            f"type=bind,src={state_root},"
            f"dst={CONTROLLER_STATE_DESTINATION},"
            "bind-propagation=rprivate"
        )
        try:
            runtime_uid_text, runtime_gid_text = (
                transport.controller_user.split(":", 1)
            )
            runtime_uid = int(runtime_uid_text)
            runtime_gid = int(runtime_gid_text)
        except (AttributeError, TypeError, ValueError) as exc:
            raise ContainerContractError(
                "controller runtime user is malformed"
            ) from exc
        if (
            runtime_uid <= 0
            or runtime_gid <= 0
            or str(runtime_uid) != runtime_uid_text
            or str(runtime_gid) != runtime_gid_text
        ):
            raise ContainerContractError(
                "controller runtime user must be canonical and nonroot"
            )
        tmp_options = (
            "rw,nosuid,nodev,noexec,"
            f"size={transport.controller_tmpfs_bytes},"
            f"mode=0700,uid={runtime_uid},gid={runtime_gid}"
        )
        control_tmp_options = (
            "rw,nosuid,nodev,noexec,size=1048576,"
            f"mode=0700,uid={runtime_uid},gid={runtime_gid}"
        )
        argv: list[str] = [
            self._docker,
            "container",
            "create",
            "--name",
            self._role_name(binding, CONTROLLER_ROLE),
        ]
        for key, value in sorted(labels.items()):
            argv.extend(("--label", f"{key}={value}"))
        argv.extend(
            (
                "--interactive",
                "--read-only",
                "--network",
                f"container:{proxy_id}",
                "--cgroupns",
                "private",
                "--ipc",
                "private",
                "--cap-drop",
                "ALL",
                "--security-opt",
                "no-new-privileges=true",
                "--user",
                transport.controller_user,
                "--cpus",
                _format_cpus(transport.controller_cpus),
                "--memory",
                str(transport.controller_memory_bytes),
                "--memory-swap",
                str(transport.controller_memory_bytes),
                "--pids-limit",
                str(transport.controller_pids),
                "--restart",
                "no",
                "--no-healthcheck",
                "--log-driver",
                "none",
                "--pull",
                "never",
                "--mount",
                state_mount,
                "--tmpfs",
                f"{CONTROLLER_NEUTRAL_DESTINATION}:{tmp_options}",
                "--tmpfs",
                f"{CONTROLLER_TMP_DESTINATION}:{tmp_options}",
                "--tmpfs",
                f"/run/arc-agi3-controller:{control_tmp_options}",
                "--workdir",
                CONTROLLER_NEUTRAL_DESTINATION,
                "--entrypoint",
                transport.controller_entrypoint[0],
                image.reference,
                *CONTROLLER_CHILD_COMMAND,
            )
        )
        return _validated_argv(argv)

    @staticmethod
    def _parse_create_id(
        result: CommandResult, *, label: str
    ) -> str:
        container_id = result.stdout.strip()
        if not CONTAINER_ID_RE.fullmatch(container_id):
            raise ContainerContractError(
                f"{label} did not return one full container Id"
            )
        return container_id

    def _create_roles(
        self,
        *,
        binding: Any,
        transport: Any,
        controller_image: ControllerRoleImage,
        proxy_image: ControllerRoleImage,
        state_root: Path,
    ) -> tuple[
        str,
        str,
        str,
        str,
        Path,
        str,
        Path,
        str,
    ]:
        proxy_argv = self._proxy_create_argv(
            binding=binding,
            transport=transport,
            image=proxy_image,
        )
        proxy_result = self._backend._required(
            proxy_argv,
            timeout_seconds=60,
            label="controller egress proxy create",
        )
        proxy_id = self._parse_create_id(
            proxy_result, label="controller egress proxy create"
        )
        controller_id: str | None = None
        try:
            proxy_observed = self._backend._inspect_container(proxy_id)
            proxy_observation_sha256 = (
                self._validate_role_container(
                    observed=proxy_observed,
                    binding=binding,
                    role=EGRESS_PROXY_ROLE,
                    image=proxy_image,
                    labels=self._labels(
                        binding,
                        role=EGRESS_PROXY_ROLE,
                        transport=transport,
                    ),
                    expected_network="bridge",
                    expected_user="0:0",
                    expected_entrypoint=CONTROLLER_PROXY_ENTRYPOINT,
                    expected_command=self._proxy_command(
                        binding, transport
                    ),
                    state_root=None,
                    transport=transport,
                )
            )
            self._backend._required(
                (
                    self._docker,
                    "container",
                    "start",
                    proxy_id,
                ),
                timeout_seconds=30,
                label="egress proxy pre-controller start",
            )
            (
                egress_readiness_path,
                egress_readiness_sha256,
                egress_probe_path,
                egress_probe_sha256,
            ) = self._ensure_proxy_ready(
                binding=binding,
                transport=transport,
                proxy_id=proxy_id,
            )
            controller_argv = self._controller_create_argv(
                binding=binding,
                transport=transport,
                image=controller_image,
                proxy_id=proxy_id,
                state_root=state_root,
            )
            controller_result = self._backend._required(
                controller_argv,
                timeout_seconds=60,
                label="controller container create",
            )
            controller_id = self._parse_create_id(
                controller_result, label="controller container create"
            )
            controller_observed = self._backend._inspect_container(
                controller_id
            )
            expected_child = tuple(
                _required_list(
                    _required_dict(
                        controller_observed,
                        "Config",
                        label="controller Config",
                    ),
                    "Cmd",
                    label="controller Config.Cmd",
                )
            )
            controller_observation_sha256 = (
                self._validate_role_container(
                    observed=controller_observed,
                    binding=binding,
                    role=CONTROLLER_ROLE,
                    image=controller_image,
                    labels=self._labels(
                        binding,
                        role=CONTROLLER_ROLE,
                        transport=transport,
                        proxy_id=proxy_id,
                    ),
                    expected_network=f"container:{proxy_id}",
                    expected_user=transport.controller_user,
                    expected_entrypoint=
                        transport.controller_entrypoint,
                    expected_command=expected_child,
                    state_root=state_root,
                    transport=transport,
                )
            )
            if expected_child != CONTROLLER_CHILD_COMMAND:
                raise ContainerContractError(
                    "controller child command is not exact"
                )
            return (
                controller_id,
                proxy_id,
                controller_observation_sha256,
                proxy_observation_sha256,
                egress_readiness_path,
                egress_readiness_sha256,
                egress_probe_path,
                egress_probe_sha256,
            )
        except BaseException:
            if controller_id is not None:
                try:
                    self._remove_role(
                        binding,
                        role=CONTROLLER_ROLE,
                        container_id=controller_id,
                        force=True,
                    )
                except BaseException:
                    pass
            try:
                self._remove_role(
                    binding,
                    role=EGRESS_PROXY_ROLE,
                    container_id=proxy_id,
                    force=True,
                )
            except BaseException:
                pass
            raise

    def _copy_ephemeral_receipt(
        self,
        *,
        container_id: str,
        container_path: str,
        host_path: Path,
        timeout_seconds: float,
    ) -> str:
        deadline = time.monotonic() + timeout_seconds
        command = _validated_argv(
            (
                self._docker,
                "container",
                "exec",
                "--user",
                "0:0",
                container_id,
                "/bin/cat",
                container_path,
            )
        )
        while True:
            result = self._runner.run(
                command, timeout_seconds=10
            )
            if (
                isinstance(result, CommandResult)
                and result.argv == command
                and result.returncode == 0
            ):
                if result.stderr:
                    raise ContainerContractError(
                        "container receipt read emitted stderr"
                    )
                payload = result.stdout.encode("utf-8")
                if not payload or len(payload) > 256 * 1024:
                    raise ContainerContractError(
                        "container receipt read exceeded its evidence bound"
                    )
                return _ensure_private_immutable_bytes(
                    host_path,
                    payload,
                    label="controller container receipt",
                    maximum_bytes=256 * 1024,
                )
            if time.monotonic() >= deadline:
                raise ContainerContractError(
                    "controller container receipt did not become "
                    "observable"
                )
            time.sleep(0.05)

    def _proxy_readiness_projection(
        self,
        *,
        binding: Any,
        transport: Any,
        receipt_path: Path,
    ) -> str:
        value = _read_unaliased_json(
            receipt_path,
            label="controller egress readiness receipt",
        )
        if (
            set(value)
            != {
                "schema",
                "kind",
                "status",
                "campaign_id",
                "generation_id",
                "attempt_id",
                "policy",
                "policy_sha256",
                "readiness_nonce",
                "guardian_pid",
                "controller_uid",
                "listen",
                "iptables_rules_sha256",
                "ip6tables_rules_sha256",
                "allowed_sni",
                "resolver_ipv4",
                "default_deny_installed",
            }
            or value.get("schema") != 1
            or value.get("kind")
            != "arc_agi3_controller_egress_readiness"
            or value.get("status") != "READY"
            or value.get("campaign_id") != binding.campaign_id
            or value.get("generation_id") != binding.generation_id
            or value.get("attempt_id") != binding.attempt_id
            or value.get("policy")
            != transport.controller_egress_policy
            or value.get("policy_sha256")
            != transport.controller_egress_policy_sha256
            or value.get("readiness_nonce")
            != self._proxy_readiness_nonce(binding, transport)
            or isinstance(value.get("guardian_pid"), bool)
            or not isinstance(value.get("guardian_pid"), int)
            or value["guardian_pid"] <= 0
            or value.get("controller_uid") != CONTROLLER_PROXY_UID
            or value.get("listen") != "127.0.0.1:19443"
            or not _is_hex_sha256(
                value.get("iptables_rules_sha256")
            )
            or not _is_hex_sha256(
                value.get("ip6tables_rules_sha256")
            )
            or value.get("allowed_sni")
            != list(CONTROLLER_PROXY_ALLOWED_SNI)
            or not isinstance(value.get("resolver_ipv4"), list)
            or not 1 <= len(value["resolver_ipv4"]) <= 4
            or len(set(value["resolver_ipv4"]))
            != len(value["resolver_ipv4"])
            or any(
                not _is_canonical_ipv4(address)
                for address in value["resolver_ipv4"]
            )
            or value.get("default_deny_installed") is not True
            or transport.controller_user
            != f"{CONTROLLER_PROXY_UID}:{CONTROLLER_PROXY_UID}"
        ):
            raise ContainerContractError(
                "controller egress readiness receipt differs"
            )
        return _hash_unaliased_regular_file(
            receipt_path,
            label="controller egress readiness receipt",
        )

    def _proxy_live_probe_projection(
        self,
        *,
        binding: Any,
        transport: Any,
        value: Mapping[str, Any],
    ) -> dict[str, Any]:
        expected_checks = {
            "allowed_openai_tls": True,
            "denied_unallowlisted_sni": True,
            "denied_loopback": True,
            "denied_metadata": True,
        }
        if (
            set(value)
            != {
                "schema",
                "kind",
                "policy",
                "policy_sha256",
                "nonce",
                "uid",
                "checks",
                "status",
            }
            or value.get("schema") != 1
            or value.get("kind")
            != "arc_agi3_controller_egress_live_probe"
            or value.get("policy")
            != transport.controller_egress_policy
            or value.get("policy_sha256")
            != transport.controller_egress_policy_sha256
            or value.get("nonce")
            != self._proxy_readiness_nonce(binding, transport)
            or value.get("uid") != CONTROLLER_PROXY_UID
            or value.get("checks") != expected_checks
            or value.get("status") != "PASS"
        ):
            raise ContainerContractError(
                "controller egress live probe did not prove allow and deny"
            )
        return dict(value)

    def _ensure_proxy_ready(
        self,
        *,
        binding: Any,
        transport: Any,
        proxy_id: str,
    ) -> tuple[Path, str, Path, str]:
        self._validate_runtime_role(
            container_id=proxy_id,
            binding=binding,
            role=EGRESS_PROXY_ROLE,
            require_running=True,
        )
        control_root = self._receipt_root(binding)
        readiness_path = (
            control_root / "controller_egress_readiness.json"
        )
        self._copy_ephemeral_receipt(
            container_id=proxy_id,
            container_path=CONTROLLER_PROXY_READINESS_PATH,
            host_path=readiness_path,
            timeout_seconds=120,
        )
        readiness_sha256 = self._proxy_readiness_projection(
            binding=binding,
            transport=transport,
            receipt_path=readiness_path,
        )
        probe_command = _validated_argv(
            (
                self._docker,
                "container",
                "exec",
                "--user",
                f"{CONTROLLER_PROXY_UID}:{CONTROLLER_PROXY_UID}",
                proxy_id,
                CONTROLLER_PROXY_ENTRYPOINT[0],
                "--probe",
                "--readiness-nonce",
                self._proxy_readiness_nonce(binding, transport),
            )
        )
        probe_result = self._backend._required(
            probe_command,
            timeout_seconds=45,
            label="controller egress live allow-and-deny probe",
            max_output_bytes=64 * 1024,
        )
        try:
            parsed_probe = json.loads(probe_result.stdout)
        except (UnicodeDecodeError, json.JSONDecodeError) as exc:
            raise ContainerContractError(
                "controller egress live probe returned malformed JSON"
            ) from exc
        if not isinstance(parsed_probe, dict):
            raise ContainerContractError(
                "controller egress live probe is not a JSON object"
            )
        probe_document = self._proxy_live_probe_projection(
            binding=binding,
            transport=transport,
            value=parsed_probe,
        )
        if probe_result.stdout.encode("utf-8") != (
            _canonical_json_bytes(probe_document)
        ):
            raise ContainerContractError(
                "controller egress live probe is not canonical"
            )
        probe_path = (
            control_root / "controller_egress_live_probe.json"
        )
        if probe_path.exists() or probe_path.is_symlink():
            probe_sha256 = self._read_exact_receipt(
                probe_path,
                probe_document,
                label="controller egress live-probe receipt",
            )
        else:
            _write_private_json_new(probe_path, probe_document)
            probe_sha256 = self._read_exact_receipt(
                probe_path,
                probe_document,
                label="controller egress live-probe receipt",
            )
        return (
            readiness_path,
            readiness_sha256,
            probe_path,
            probe_sha256,
        )

    @staticmethod
    def _image_equal(
        first: ControllerRoleImage, second: ControllerRoleImage
    ) -> bool:
        return (
            first.reference == second.reference
            and first.manifest_digest == second.manifest_digest
            and first.image_id == second.image_id
            and first.role == second.role
            and first.entrypoint == second.entrypoint
            and first.user == second.user
            and first.labels == second.labels
        )

    def _inspect_controller_image(
        self, transport: Any
    ) -> ControllerRoleImage:
        return self._inspect_role_image(
            reference=transport.controller_image_reference,
            role=CONTROLLER_ROLE,
            expected_entrypoint=transport.controller_entrypoint,
            expected_user=(
                _runner_contract().EXPECTED_CONTROLLER_IMAGE_USER
            ),
            required_labels={
                LABEL_ROLE: CONTROLLER_ROLE,
                "org.gkm.arc-agi3.controller-guardian-sha256":
                    transport.controller_guardian_sha256,
                "org.gkm.arc-agi3.codex-cli-version":
                    transport.codex_cli_version,
            },
        )

    def _inspect_proxy_image(
        self, transport: Any
    ) -> ControllerRoleImage:
        return self._inspect_role_image(
            reference=(
                transport.controller_egress_proxy_image_reference
            ),
            role=EGRESS_PROXY_ROLE,
            expected_entrypoint=CONTROLLER_PROXY_ENTRYPOINT,
            expected_user="0:0",
            required_labels={
                LABEL_ROLE: EGRESS_PROXY_ROLE,
                LABEL_EGRESS_POLICY_SHA256:
                    transport.controller_egress_policy_sha256,
                "org.gkm.arc-agi3.egress-policy":
                    transport.controller_egress_policy,
                "org.gkm.arc-agi3.egress-guardian-sha256":
                    CONTROLLER_PROXY_GUARDIAN_SHA256,
                "org.gkm.arc-agi3.egress-enforcement":
                    CONTROLLER_PROXY_ENFORCEMENT,
            },
        )

    def _launch_document(
        self,
        *,
        binding: Any,
        transport: Any,
        intent_sha256: str,
        controller_id: str,
        proxy_id: str,
        controller_image: ControllerRoleImage,
        proxy_image: ControllerRoleImage,
        controller_observation_sha256: str,
        proxy_observation_sha256: str,
        egress_readiness_path: Path,
        egress_readiness_sha256: str,
        egress_probe_path: Path,
        egress_probe_sha256: str,
        state_root: Path,
    ) -> dict[str, Any]:
        controller_argv = self._controller_create_argv(
            binding=binding,
            transport=transport,
            image=controller_image,
            proxy_id=proxy_id,
            state_root=state_root,
        )
        proxy_argv = self._proxy_create_argv(
            binding=binding,
            transport=transport,
            image=proxy_image,
        )
        return {
            "schema": 1,
            "kind": "arc_agi3_controller_launch",
            "campaign_id": binding.campaign_id,
            "generation_id": binding.generation_id,
            "attempt_id": binding.attempt_id,
            "attempt_spec_sha256": binding.attempt_spec_sha256,
            "containment_canary_anchor":
                self._canary_anchor_document(binding),
            "launch_intent_sha256": intent_sha256,
            "controller_container_id": controller_id,
            "controller_image_reference": controller_image.reference,
            "controller_image_digest":
                controller_image.manifest_digest,
            "controller_image_id": controller_image.image_id,
            "controller_image_observation_sha256":
                controller_image.observation_sha256,
            "controller_create_argv_sha256":
                _argv_sha256(controller_argv),
            "controller_observation_sha256":
                controller_observation_sha256,
            "egress_proxy_container_id": proxy_id,
            "egress_proxy_image_reference": proxy_image.reference,
            "egress_proxy_image_digest":
                proxy_image.manifest_digest,
            "egress_proxy_image_id": proxy_image.image_id,
            "egress_proxy_image_observation_sha256":
                proxy_image.observation_sha256,
            "egress_proxy_create_argv_sha256":
                _argv_sha256(proxy_argv),
            "egress_proxy_observation_sha256":
                proxy_observation_sha256,
            "egress_policy": transport.controller_egress_policy,
            "egress_policy_sha256":
                transport.controller_egress_policy_sha256,
            "egress_readiness_nonce":
                self._proxy_readiness_nonce(binding, transport),
            "egress_readiness_receipt_path":
                str(egress_readiness_path),
            "egress_readiness_receipt_sha256":
                egress_readiness_sha256,
            "egress_live_probe_receipt_path":
                str(egress_probe_path),
            "egress_live_probe_receipt_sha256":
                egress_probe_sha256,
            "egress_live_probe_before_controller_create": True,
            "state_root": str(state_root),
            "credentials_in_argv_or_env": False,
            "bridge_or_arena_mounts": 0,
            "authoritative_identity": "controller_container_cgroup",
        }

    @staticmethod
    def _validate_guardian_native_workspace(
        value: Any,
    ) -> None:
        required = {
            "policy",
            "workspace_root",
            "git_dir",
            "git_root_equals_workspace",
            "head_ref",
            "head_commit",
            "file_count",
            "inventory_sha256",
            "symlink_count",
            "hardlink_count",
            "path_escape_count",
            "forbidden_classes_absent",
            "git_ceiling_directories",
            "git_discovery_across_filesystem",
            "git_global_config_disabled",
            "git_system_config_disabled",
        }
        if (
            not isinstance(value, dict)
            or set(value) != required
            or value.get("policy")
            != "isolated-local-git-root-no-parent-discovery-v1"
            or value.get("workspace_root")
            != CONTROLLER_NEUTRAL_DESTINATION
            or value.get("git_dir")
            != f"{CONTROLLER_NEUTRAL_DESTINATION}/.git"
            or value.get("git_root_equals_workspace") is not True
            or value.get("head_ref") != "refs/heads/contiguous"
            or not isinstance(value.get("head_commit"), str)
            or re.fullmatch(r"[0-9a-f]{40}", value["head_commit"])
            is None
            or value.get("file_count") != 6
            or not _is_hex_sha256(value.get("inventory_sha256"))
            or value.get("symlink_count") != 0
            or value.get("hardlink_count") != 0
            or value.get("path_escape_count") != 0
            or value.get("forbidden_classes_absent")
            != [
                "campaign-plan",
                "sidecar-or-quarantine-output",
                "manuscript",
                "comparator",
                "benchmark",
                "parent-repository-git-metadata",
            ]
            or value.get("git_ceiling_directories")
            != CONTROLLER_NEUTRAL_DESTINATION
            or value.get("git_discovery_across_filesystem") is not False
            or value.get("git_global_config_disabled") is not True
            or value.get("git_system_config_disabled") is not True
        ):
            raise ContainerContractError(
                "controller native proposer workspace proof is malformed"
            )

    def _guardian_start_projection(
        self,
        *,
        binding: Any,
        transport: Any,
        receipt_path: Path,
    ) -> tuple[str, str]:
        value = _read_unaliased_json(
            receipt_path, label="controller guardian start receipt"
        )
        if (
            set(value)
            != {
                "schema",
                "kind",
                "guardian_pid",
                "child_pid",
                "child_process_group_id",
                "hard_safety_seconds",
                "supply_chain_manifest_sha256",
                "supply_chain_files",
                "state_root_write_probe",
                "native_workspace",
                "started_monotonic_ns",
            }
            or value.get("schema") != 1
            or value.get("kind")
            != "arc_agi3_controller_guardian_start"
            or value.get("hard_safety_seconds")
            != binding.hard_safety_seconds
            or not _is_hex_sha256(
                value.get("supply_chain_manifest_sha256")
            )
            or any(
                isinstance(value.get(name), bool)
                or not isinstance(value.get(name), int)
                or value[name] <= 0
                for name in (
                    "guardian_pid",
                    "child_pid",
                    "child_process_group_id",
                    "started_monotonic_ns",
                )
            )
            or value.get("child_pid")
            != value.get("child_process_group_id")
            or not isinstance(value.get("supply_chain_files"), list)
        ):
            raise ContainerContractError(
                "controller guardian start receipt is malformed"
            )
        try:
            runtime_uid_text, runtime_gid_text = (
                transport.controller_user.split(":", 1)
            )
            runtime_uid = int(runtime_uid_text)
            runtime_gid = int(runtime_gid_text)
        except (AttributeError, TypeError, ValueError) as exc:
            raise ContainerContractError(
                "controller runtime identity is malformed"
            ) from exc
        if value.get("state_root_write_probe") != {
            "schema": 1,
            "kind": "controller_state_root_write_probe",
            "runtime_uid": runtime_uid,
            "runtime_gid": runtime_gid,
            "relative_path": CONTROLLER_STATE_WRITE_PROBE_NAME,
            "payload_sha256": hashlib.sha256(
                CONTROLLER_STATE_WRITE_PROBE_PAYLOAD
            ).hexdigest(),
            "payload_bytes": len(
                CONTROLLER_STATE_WRITE_PROBE_PAYLOAD
            ),
            "file_fsync": True,
            "directory_fsync_after_unlink": True,
            "probe_absent_after_fsync": True,
            "status": "PASS",
        }:
            raise ContainerContractError(
                "controller guardian state-root write probe is malformed"
            )
        self._validate_guardian_native_workspace(
            value.get("native_workspace")
        )
        observed_files: dict[str, dict[str, Any]] = {}
        for item in value["supply_chain_files"]:
            if (
                not isinstance(item, dict)
                or set(item)
                != {"path", "sha256", "bytes", "executable"}
                or not isinstance(item["path"], str)
                or item["path"] in observed_files
                or not _is_hex_sha256(item["sha256"])
                or isinstance(item["bytes"], bool)
                or not isinstance(item["bytes"], int)
                or item["bytes"] <= 0
                or not isinstance(item["executable"], bool)
            ):
                raise ContainerContractError(
                    "controller supply-chain observation is malformed"
                )
            observed_files[item["path"]] = item
        expected = (
            (
                transport.controller_guardian_path,
                transport.controller_guardian_sha256,
                None,
                True,
            ),
            (
                transport.codex_launcher_path,
                transport.codex_launcher_sha256,
                None,
                True,
            ),
            (
                transport.codex_package_manifest_path,
                transport.codex_package_manifest_sha256,
                None,
                False,
            ),
            (
                transport.codex_binary_path,
                transport.codex_binary_sha256,
                transport.codex_binary_bytes,
                True,
            ),
            (
                transport.app_server_protocol_schema_path,
                transport.app_server_protocol_schema_sha256,
                None,
                False,
            ),
            (
                transport.app_server_protocol_schema_bundle_path,
                transport.app_server_protocol_schema_bundle_sha256,
                None,
                False,
            ),
        )
        for path, digest, byte_count, executable in expected:
            item = observed_files.get(path)
            if (
                item is None
                or item["sha256"] != digest
                or item["executable"] is not executable
                or (
                    byte_count is not None
                    and item["bytes"] != byte_count
                )
            ):
                raise ContainerContractError(
                    "in-image controller supply chain differs from pins"
                )
        return (
            _hash_unaliased_regular_file(
                receipt_path,
                label="controller guardian start receipt",
            ),
            value["supply_chain_manifest_sha256"],
        )

    def _validate_runtime_role(
        self,
        *,
        container_id: str,
        binding: Any,
        role: str,
        require_running: bool,
    ) -> dict[str, Any]:
        observed = self._backend._inspect_container(container_id)
        config = _required_dict(
            observed, "Config", label=f"{role} runtime Config"
        )
        labels = _required_dict(
            config, "Labels", label=f"{role} runtime labels"
        )
        if (
            _required_string(
                observed, "Id", label=f"{role} runtime Id"
            )
            != container_id
            or labels.get(LABEL_CAMPAIGN) != binding.campaign_id
            or labels.get(LABEL_GENERATION) != binding.generation_id
            or labels.get(LABEL_ATTEMPT) != binding.attempt_id
            or labels.get(LABEL_ROLE) != role
        ):
            raise ContainerContractError(
                f"{role} runtime identity differs"
            )
        state = _required_dict(
            observed, "State", label=f"{role} runtime State"
        )
        if require_running and state.get("Running") is not True:
            raise ContainerContractError(f"{role} is not running")
        return observed

    def start(
        self,
        *,
        binding: probe_transport.ControllerBinding,
        probe_spec: Any,
    ) -> probe_transport.ControllerContainerStart:
        with self._lock:
            if not isinstance(
                binding, probe_transport.ControllerBinding
            ):
                raise ContainerContractError(
                    "controller launch binding type differs"
                )
            transport = _runner_field(
                probe_spec, "proposer_transport"
            )
            _validate_proposer_transport(transport)
            if (
                binding.attempt_spec_sha256
                != _runner_contract()
                .proposer_attempt_binding_sha256(probe_spec)
            ):
                raise ContainerContractError(
                    "controller binding differs from attempt spec"
                )
            try:
                canary_anchor = CanaryEscrowAnchor(
                    **self._canary_anchor_document(binding)
                )
                canary_anchor.validate()
            except (TypeError, ContainerContractError) as exc:
                raise ContainerContractError(
                    "controller launch lacks the exact prelaunch "
                    "containment-canary anchor"
                ) from exc
            expected_escrow_path = (
                Path(_runner_field(probe_spec, "generation_dir"))
                .parent.parent
                / "containment_canary_escrow"
                / f"{binding.generation_id}.json"
            )
            if Path(canary_anchor.escrow_path) != expected_escrow_path:
                raise ContainerContractError(
                    "controller canary escrow left its host-only root"
                )
            state_root = Path(binding.state_root)
            _validate_private_host_directory(state_root)
            state_metadata = state_root.stat(follow_symlinks=False)
            expected_runtime_user = (
                f"{state_metadata.st_uid}:{state_metadata.st_gid}"
            )
            if (
                expected_runtime_user != transport.controller_user
                or state_metadata.st_uid == 0
                or state_metadata.st_gid == 0
            ):
                raise ContainerContractError(
                    "controller runtime identity does not own its private "
                    "state volume as a nonroot principal"
                )
            control_root = self._receipt_root(binding)
            absence_path = control_root / "controller_absence_receipt.json"
            if absence_path.exists() or absence_path.is_symlink():
                raise ContainerContractError(
                    "contained controller attempt cannot be relaunched"
                )
            _intent_path, intent_sha256 = self._ensure_intent(
                binding, transport
            )
            controller_image = self._inspect_controller_image(
                transport
            )
            proxy_image = self._inspect_proxy_image(transport)
            launch_path = control_root / "controller_launch_receipt.json"
            self._recover_pre_receipt_orphans(
                binding, launch_receipt_exists=launch_path.exists()
            )
            create_roles = True
            if launch_path.exists() or launch_path.is_symlink():
                launch = _read_unaliased_json(
                    launch_path, label="controller launch receipt"
                )
                controller_id = _required_string(
                    launch,
                    "controller_container_id",
                    label="controller launch Id",
                )
                proxy_id = _required_string(
                    launch,
                    "egress_proxy_container_id",
                    label="egress launch Id",
                )
                if (
                    not CONTAINER_ID_RE.fullmatch(controller_id)
                    or not CONTAINER_ID_RE.fullmatch(proxy_id)
                    or launch.get("launch_intent_sha256")
                    != intent_sha256
                    or launch.get("attempt_spec_sha256")
                    != binding.attempt_spec_sha256
                    or launch.get("containment_canary_anchor")
                    != self._canary_anchor_document(binding)
                    or launch.get("controller_image_digest")
                    != transport.controller_image_digest
                    or launch.get("egress_proxy_image_digest")
                    != transport.controller_egress_proxy_image_digest
                    or launch.get("egress_policy_sha256")
                    != transport.controller_egress_policy_sha256
                    or launch.get("egress_readiness_nonce")
                    != self._proxy_readiness_nonce(binding, transport)
                    or launch.get("egress_readiness_receipt_path")
                    != str(
                        control_root
                        / "controller_egress_readiness.json"
                    )
                    or not _is_hex_sha256(
                        launch.get(
                            "egress_readiness_receipt_sha256"
                        )
                    )
                    or launch.get("egress_live_probe_receipt_path")
                    != str(
                        control_root
                        / "controller_egress_live_probe.json"
                    )
                    or not _is_hex_sha256(
                        launch.get(
                            "egress_live_probe_receipt_sha256"
                        )
                    )
                    or launch.get(
                        "egress_live_probe_before_controller_create"
                    )
                    is not True
                ):
                    raise ContainerContractError(
                        "retained controller launch receipt differs"
                    )
                launch_sha256 = _hash_unaliased_regular_file(
                    launch_path, label="controller launch receipt"
                )
                controller_ids = self._query_role_ids(
                    binding, role=CONTROLLER_ROLE
                )
                proxy_ids = self._query_role_ids(
                    binding, role=EGRESS_PROXY_ROLE
                )
                if (
                    controller_ids == (controller_id,)
                    and proxy_ids == (proxy_id,)
                ):
                    controller_runtime = self._validate_runtime_role(
                        container_id=controller_id,
                        binding=binding,
                        role=CONTROLLER_ROLE,
                        require_running=False,
                    )
                    proxy_runtime = self._validate_runtime_role(
                        container_id=proxy_id,
                        binding=binding,
                        role=EGRESS_PROXY_ROLE,
                        require_running=False,
                    )
                    create_roles = not (
                        _required_dict(
                            controller_runtime,
                            "State",
                            label="controller recovery State",
                        ).get("Running")
                        is True
                        and _required_dict(
                            proxy_runtime,
                            "State",
                            label="proxy recovery State",
                        ).get("Running")
                        is True
                    )
                if create_roles:
                    self._supersede_stopped_launch(
                        binding=binding,
                        controller_id=controller_id,
                        proxy_id=proxy_id,
                        launch_path=launch_path,
                    )
            if create_roles:
                second_controller_image = (
                    self._inspect_controller_image(transport)
                )
                second_proxy_image = self._inspect_proxy_image(
                    transport
                )
                if (
                    not self._image_equal(
                        controller_image, second_controller_image
                    )
                    or not self._image_equal(
                        proxy_image, second_proxy_image
                    )
                ):
                    raise ContainerContractError(
                        "controller/proxy image changed before create"
                    )
                controller_image = second_controller_image
                proxy_image = second_proxy_image
                (
                    controller_id,
                    proxy_id,
                    controller_observation_sha256,
                    proxy_observation_sha256,
                    egress_readiness_path,
                    egress_readiness_sha256,
                    egress_probe_path,
                    egress_probe_sha256,
                ) = self._create_roles(
                    binding=binding,
                    transport=transport,
                    controller_image=controller_image,
                    proxy_image=proxy_image,
                    state_root=state_root,
                )
                launch_document = self._launch_document(
                    binding=binding,
                    transport=transport,
                    intent_sha256=intent_sha256,
                    controller_id=controller_id,
                    proxy_id=proxy_id,
                    controller_image=controller_image,
                    proxy_image=proxy_image,
                    controller_observation_sha256=
                        controller_observation_sha256,
                    proxy_observation_sha256=
                        proxy_observation_sha256,
                    egress_readiness_path=egress_readiness_path,
                    egress_readiness_sha256=
                        egress_readiness_sha256,
                    egress_probe_path=egress_probe_path,
                    egress_probe_sha256=egress_probe_sha256,
                    state_root=state_root,
                )
                _write_private_json_new(launch_path, launch_document)
                launch_sha256 = self._read_exact_receipt(
                    launch_path,
                    launch_document,
                    label="controller launch receipt",
                )
            proxy_runtime = self._validate_runtime_role(
                container_id=proxy_id,
                binding=binding,
                role=EGRESS_PROXY_ROLE,
                require_running=False,
            )
            if not _required_dict(
                proxy_runtime, "State", label="proxy State"
            ).get("Running"):
                if not create_roles:
                    raise ContainerContractError(
                        "recovered egress proxy stopped after admission"
                    )
                self._backend._required(
                    (
                        self._docker,
                        "container",
                        "start",
                        proxy_id,
                    ),
                    timeout_seconds=30,
                    label="egress proxy start",
                )
            self._validate_runtime_role(
                container_id=proxy_id,
                binding=binding,
                role=EGRESS_PROXY_ROLE,
                require_running=True,
            )
            (
                egress_readiness_path,
                egress_readiness_sha256,
                egress_probe_path,
                egress_probe_sha256,
            ) = self._ensure_proxy_ready(
                binding=binding,
                transport=transport,
                proxy_id=proxy_id,
            )
            launch = _read_unaliased_json(
                launch_path, label="controller launch receipt"
            )
            if (
                launch.get("egress_readiness_receipt_path")
                != str(egress_readiness_path)
                or launch.get("egress_readiness_receipt_sha256")
                != egress_readiness_sha256
                or launch.get("egress_live_probe_receipt_path")
                != str(egress_probe_path)
                or launch.get("egress_live_probe_receipt_sha256")
                != egress_probe_sha256
            ):
                raise ContainerContractError(
                    "controller launch does not bind live egress evidence"
                )
            controller_runtime = self._validate_runtime_role(
                container_id=controller_id,
                binding=binding,
                role=CONTROLLER_ROLE,
                require_running=False,
            )
            if _required_dict(
                controller_runtime, "State", label="controller State"
            ).get("Running"):
                attach_argv = (
                    self._docker,
                    "container",
                    "attach",
                    controller_id,
                )
            elif create_roles:
                attach_argv = (
                    self._docker,
                    "container",
                    "start",
                    "--attach",
                    "--interactive",
                    controller_id,
                )
            else:
                raise ContainerContractError(
                    "recovered controller stopped after admission"
                )
            process = self._runner.spawn_interactive(attach_argv)
            deadline = time.monotonic() + 20
            while True:
                if process.poll() is not None:
                    raise ContainerContractError(
                        "controller attach exited before guardian readiness"
                    )
                try:
                    self._validate_runtime_role(
                        container_id=controller_id,
                        binding=binding,
                        role=CONTROLLER_ROLE,
                        require_running=True,
                    )
                    break
                except ContainerContractError:
                    if time.monotonic() >= deadline:
                        raise
                    time.sleep(0.05)
            guardian_path = (
                control_root / "controller_guardian_start.json"
            )
            self._copy_ephemeral_receipt(
                container_id=controller_id,
                container_path=(
                    "/run/arc-agi3-controller/process_start.json"
                ),
                host_path=guardian_path,
                timeout_seconds=20,
            )
            (
                guardian_sha256,
                supply_chain_manifest_sha256,
            ) = self._guardian_start_projection(
                binding=binding,
                transport=transport,
                receipt_path=guardian_path,
            )
            return probe_transport.ControllerContainerStart(
                process=process,
                controller_container_id=controller_id,
                controller_image_digest=
                    transport.controller_image_digest,
                egress_proxy_container_id=proxy_id,
                egress_proxy_image_digest=
                    transport.controller_egress_proxy_image_digest,
                egress_policy_sha256=
                    transport.controller_egress_policy_sha256,
                launch_intent_sha256=intent_sha256,
                launch_receipt_path=str(launch_path),
                launch_receipt_sha256=launch_sha256,
                guardian_start_receipt_path=str(guardian_path),
                guardian_start_receipt_sha256=guardian_sha256,
                codex_binary_sha256=transport.codex_binary_sha256,
                codex_binary_bytes=transport.codex_binary_bytes,
                supply_chain_manifest_sha256=
                    supply_chain_manifest_sha256,
            )

    def _stop_if_running(
        self,
        *,
        binding: Any,
        container_id: str,
        role: str,
        grace_seconds: int,
    ) -> None:
        observed = self._validate_runtime_role(
            container_id=container_id,
            binding=binding,
            role=role,
            require_running=False,
        )
        if _required_dict(
            observed, "State", label=f"{role} State"
        ).get("Running"):
            self._backend._required(
                (
                    self._docker,
                    "container",
                    "stop",
                    "--time",
                    str(grace_seconds),
                    container_id,
                ),
                timeout_seconds=grace_seconds + 30,
                label=f"{role} stop",
            )
        terminal = self._validate_runtime_role(
            container_id=container_id,
            binding=binding,
            role=role,
            require_running=False,
        )
        if _required_dict(
            terminal, "State", label=f"{role} terminal State"
        ).get("Running"):
            raise ContainerContractError(f"{role} survived stop")

    def _prove_removed_role(
        self,
        *,
        binding: Any,
        role: str,
        container_id: str,
    ) -> None:
        self._backend._required(
            (
                self._docker,
                "container",
                "rm",
                container_id,
            ),
            timeout_seconds=60,
            label=f"{role} remove",
        )
        inspect_absent = self._backend._expect_absent(
            (
                self._docker,
                "container",
                "inspect",
                container_id,
            ),
            label=f"{role} absent inspect",
        )
        top_absent = self._backend._expect_absent(
            (
                self._docker,
                "container",
                "top",
                container_id,
                "-eo",
                "pid",
            ),
            label=f"{role} absent top",
        )
        query_empty = not self._query_role_ids(
            binding, role=role
        )
        if not (inspect_absent and top_absent and query_empty):
            raise ContainerContractError(
                f"{role} absence proof is incomplete"
            )

    def contain(
        self,
        *,
        binding: probe_transport.ControllerBinding,
        started: probe_transport.ControllerContainerStart,
    ) -> probe_transport.ControllerContainerStop:
        with self._lock:
            if (
                not isinstance(
                    started, probe_transport.ControllerContainerStart
                )
                or not CONTAINER_ID_RE.fullmatch(
                    started.controller_container_id
                )
                or not CONTAINER_ID_RE.fullmatch(
                    started.egress_proxy_container_id
                )
            ):
                raise ContainerContractError(
                    "controller containment authority is malformed"
                )
            controller_id = started.controller_container_id
            proxy_id = started.egress_proxy_container_id
            control_root = self._receipt_root(binding)
            self._stop_if_running(
                binding=binding,
                container_id=controller_id,
                role=CONTROLLER_ROLE,
                grace_seconds=40,
            )
            exit_path = (
                control_root / "controller_guardian_exit.json"
            )
            self._copy_ephemeral_receipt(
                container_id=controller_id,
                container_path=(
                    "/run/arc-agi3-controller/process_exit.json"
                ),
                host_path=exit_path,
                timeout_seconds=5,
            )
            exit_sha256 = _hash_unaliased_regular_file(
                exit_path, label="controller guardian exit receipt"
            )
            self._prove_removed_role(
                binding=binding,
                role=CONTROLLER_ROLE,
                container_id=controller_id,
            )
            self._stop_if_running(
                binding=binding,
                container_id=proxy_id,
                role=EGRESS_PROXY_ROLE,
                grace_seconds=10,
            )
            self._prove_removed_role(
                binding=binding,
                role=EGRESS_PROXY_ROLE,
                container_id=proxy_id,
            )
            absence = {
                "schema": 1,
                "kind": "arc_agi3_controller_absence",
                "campaign_id": binding.campaign_id,
                "generation_id": binding.generation_id,
                "attempt_id": binding.attempt_id,
                "attempt_spec_sha256":
                    binding.attempt_spec_sha256,
                "controller_container_id": controller_id,
                "egress_proxy_container_id": proxy_id,
                "controller_launch_receipt_sha256":
                    started.launch_receipt_sha256,
                "guardian_start_receipt_sha256":
                    started.guardian_start_receipt_sha256,
                "guardian_exit_receipt_sha256": exit_sha256,
                "controller_inspect_absent": True,
                "controller_identity_query_empty": True,
                "controller_top_absent": True,
                "controller_no_descendants": True,
                "egress_proxy_inspect_absent": True,
                "egress_proxy_identity_query_empty": True,
                "egress_proxy_top_absent": True,
                "egress_proxy_no_descendants": True,
                "authoritative_identity":
                    "controller_container_cgroup",
            }
            absence_path = (
                control_root / "controller_absence_receipt.json"
            )
            if absence_path.exists() or absence_path.is_symlink():
                absence_sha256 = self._read_exact_receipt(
                    absence_path,
                    absence,
                    label="controller absence receipt",
                )
            else:
                _write_private_json_new(absence_path, absence)
                absence_sha256 = self._read_exact_receipt(
                    absence_path,
                    absence,
                    label="controller absence receipt",
                )
            return probe_transport.ControllerContainerStop(
                controller_container_id=controller_id,
                egress_proxy_container_id=proxy_id,
                controller_inspect_absent=True,
                controller_identity_query_empty=True,
                controller_top_absent=True,
                controller_no_descendants=True,
                egress_proxy_inspect_absent=True,
                egress_proxy_identity_query_empty=True,
                egress_proxy_top_absent=True,
                egress_proxy_no_descendants=True,
                absence_receipt_path=str(absence_path),
                absence_receipt_sha256=absence_sha256,
            )

    def recover_preflight_absence(
        self,
        *,
        binding: probe_transport.ControllerBinding,
    ) -> tuple[str, str]:
        """Contain a controller probe lost before a start handle was retained.

        A host crash can occur after one or both labelled controller roles are
        created but before :class:`ControllerContainerStart` reaches the
        mediator.  The ordinary ``contain`` API intentionally requires that
        handle.  This recovery path instead derives the exact role identities
        from the immutable attempt labels, durably records them *before*
        removal, and then proves both full-ID/cgroup roles absent.  It is only
        used for disposable pre-turn substrate probes; it cannot recover or
        authorize a proposer turn.
        """

        with self._lock:
            if not isinstance(
                binding, probe_transport.ControllerBinding
            ):
                raise ContainerContractError(
                    "preflight recovery binding type differs"
                )
            control_root = self._receipt_root(binding)
            intent_path = (
                control_root
                / "controller_preflight_recovery_intent.json"
            )
            receipt_path = (
                control_root
                / "controller_preflight_recovery_absence.json"
            )
            if receipt_path.exists() or receipt_path.is_symlink():
                value = _read_unaliased_json(
                    receipt_path,
                    label="controller preflight recovery absence",
                )
                required = {
                    "schema",
                    "kind",
                    "campaign_id",
                    "generation_id",
                    "attempt_id",
                    "attempt_spec_sha256",
                    "recovery_intent_sha256",
                    "controller_container_id",
                    "egress_proxy_container_id",
                    "controller_inspect_absent",
                    "controller_identity_query_empty",
                    "controller_top_absent",
                    "controller_no_descendants",
                    "egress_proxy_inspect_absent",
                    "egress_proxy_identity_query_empty",
                    "egress_proxy_top_absent",
                    "egress_proxy_no_descendants",
                    "proposer_container_started",
                    "authoritative_identity",
                    "status",
                }
                if (
                    set(value) != required
                    or value.get("schema") != 1
                    or value.get("kind")
                    != "arc_agi3_controller_preflight_recovery_absence"
                    or value.get("campaign_id") != binding.campaign_id
                    or value.get("generation_id")
                    != binding.generation_id
                    or value.get("attempt_id") != binding.attempt_id
                    or value.get("attempt_spec_sha256")
                    != binding.attempt_spec_sha256
                    or not _is_hex_sha256(
                        value.get("recovery_intent_sha256")
                    )
                    or any(
                        item is not None
                        and (
                            not isinstance(item, str)
                            or not CONTAINER_ID_RE.fullmatch(item)
                        )
                        for item in (
                            value.get("controller_container_id"),
                            value.get("egress_proxy_container_id"),
                        )
                    )
                    or any(
                        value.get(name) is not True
                        for name in (
                            "controller_inspect_absent",
                            "controller_identity_query_empty",
                            "controller_top_absent",
                            "controller_no_descendants",
                            "egress_proxy_inspect_absent",
                            "egress_proxy_identity_query_empty",
                            "egress_proxy_top_absent",
                            "egress_proxy_no_descendants",
                        )
                    )
                    or value.get("proposer_container_started") is not False
                    or value.get("authoritative_identity")
                    != "controller_container_cgroup"
                    or value.get("status") != "PASS"
                    or self._query_role_ids(
                        binding, role=CONTROLLER_ROLE
                    )
                    or self._query_role_ids(
                        binding, role=EGRESS_PROXY_ROLE
                    )
                ):
                    raise ContainerContractError(
                        "retained preflight recovery absence changed"
                    )
                return (
                    str(receipt_path),
                    _hash_unaliased_regular_file(
                        receipt_path,
                        label=(
                            "controller preflight recovery absence"
                        ),
                    ),
                )

            controller_ids = self._query_role_ids(
                binding, role=CONTROLLER_ROLE
            )
            proxy_ids = self._query_role_ids(
                binding, role=EGRESS_PROXY_ROLE
            )
            if len(controller_ids) > 1 or len(proxy_ids) > 1:
                raise ContainerContractError(
                    "preflight recovery found ambiguous controller roles"
                )
            intent = {
                "schema": 1,
                "kind":
                    "arc_agi3_controller_preflight_recovery_intent",
                "campaign_id": binding.campaign_id,
                "generation_id": binding.generation_id,
                "attempt_id": binding.attempt_id,
                "attempt_spec_sha256":
                    binding.attempt_spec_sha256,
                "controller_container_id": (
                    controller_ids[0] if controller_ids else None
                ),
                "egress_proxy_container_id": (
                    proxy_ids[0] if proxy_ids else None
                ),
                "proposer_container_started": False,
            }
            if intent_path.exists() or intent_path.is_symlink():
                retained_intent = _read_unaliased_json(
                    intent_path,
                    label="controller preflight recovery intent",
                )
                if (
                    set(retained_intent) != set(intent)
                    or any(
                        retained_intent.get(name) != value
                        for name, value in intent.items()
                        if name
                        not in {
                            "controller_container_id",
                            "egress_proxy_container_id",
                        }
                    )
                    or any(
                        retained_intent.get(name) is not None
                        and retained_intent.get(name)
                        != intent.get(name)
                        for name in (
                            "controller_container_id",
                            "egress_proxy_container_id",
                        )
                    )
                ):
                    raise ContainerContractError(
                        "controller preflight recovery identity changed"
                    )
                intent = retained_intent
            else:
                _write_private_json_new(intent_path, intent)
            intent_sha256 = _hash_unaliased_regular_file(
                intent_path,
                label="controller preflight recovery intent",
            )

            for role, key in (
                (CONTROLLER_ROLE, "controller_container_id"),
                (EGRESS_PROXY_ROLE, "egress_proxy_container_id"),
            ):
                container_id = intent[key]
                current = self._query_role_ids(binding, role=role)
                if container_id is None:
                    if current:
                        raise ContainerContractError(
                            "controller role appeared after recovery intent"
                        )
                    continue
                if current not in ((), (container_id,)):
                    raise ContainerContractError(
                        "controller role changed after recovery intent"
                    )
                if current:
                    self._stop_if_running(
                        binding=binding,
                        container_id=container_id,
                        role=role,
                        grace_seconds=(
                            40 if role == CONTROLLER_ROLE else 10
                        ),
                    )
                    self._prove_removed_role(
                        binding=binding,
                        role=role,
                        container_id=container_id,
                    )
            if (
                self._query_role_ids(binding, role=CONTROLLER_ROLE)
                or self._query_role_ids(
                    binding, role=EGRESS_PROXY_ROLE
                )
            ):
                raise ContainerContractError(
                    "preflight controller roles survived recovery"
                )
            receipt = {
                "schema": 1,
                "kind":
                    "arc_agi3_controller_preflight_recovery_absence",
                "campaign_id": binding.campaign_id,
                "generation_id": binding.generation_id,
                "attempt_id": binding.attempt_id,
                "attempt_spec_sha256":
                    binding.attempt_spec_sha256,
                "recovery_intent_sha256": intent_sha256,
                "controller_container_id":
                    intent["controller_container_id"],
                "egress_proxy_container_id":
                    intent["egress_proxy_container_id"],
                "controller_inspect_absent": True,
                "controller_identity_query_empty": True,
                "controller_top_absent": True,
                "controller_no_descendants": True,
                "egress_proxy_inspect_absent": True,
                "egress_proxy_identity_query_empty": True,
                "egress_proxy_top_absent": True,
                "egress_proxy_no_descendants": True,
                "proposer_container_started": False,
                "authoritative_identity":
                    "controller_container_cgroup",
                "status": "PASS",
            }
            _write_private_json_new(receipt_path, receipt)
            return (
                str(receipt_path),
                _hash_unaliased_regular_file(
                    receipt_path,
                    label="controller preflight recovery absence",
                ),
            )

    def recover_absence(
        self,
        *,
        binding: probe_transport.ControllerBinding,
        controller_container_id: str,
        egress_proxy_container_id: str,
        controller_launch_receipt_sha256: str,
        guardian_start_receipt_sha256: str,
    ) -> probe_transport.ControllerContainerStop:
        """Recover exact labelled containers after mediator/supervisor loss."""

        with self._lock:
            for value, label in (
                (controller_container_id, "controller"),
                (egress_proxy_container_id, "egress proxy"),
            ):
                if not CONTAINER_ID_RE.fullmatch(value):
                    raise ContainerContractError(
                        f"recovered {label} Id is malformed"
                    )
            control_root = self._receipt_root(binding)
            launch_path = control_root / "controller_launch_receipt.json"
            if (
                _hash_unaliased_regular_file(
                    launch_path, label="recovered controller launch receipt"
                )
                != controller_launch_receipt_sha256
            ):
                raise ContainerContractError(
                    "recovered controller launch receipt changed"
                )
            exit_path = (
                control_root / "controller_guardian_exit.json"
            )
            controller_ids = self._query_role_ids(
                binding, role=CONTROLLER_ROLE
            )
            if controller_ids not in (
                (),
                (controller_container_id,),
            ):
                raise ContainerContractError(
                    "recovered controller identity query is ambiguous"
                )
            if controller_ids:
                self._stop_if_running(
                    binding=binding,
                    container_id=controller_container_id,
                    role=CONTROLLER_ROLE,
                    grace_seconds=40,
                )
                try:
                    self._copy_ephemeral_receipt(
                        container_id=controller_container_id,
                        container_path=(
                            "/run/arc-agi3-controller/process_exit.json"
                        ),
                        host_path=exit_path,
                        timeout_seconds=2,
                    )
                except ContainerContractError:
                    # A daemon/container SIGKILL legitimately has no guardian
                    # exit receipt.  The full-ID/cgroup absence below remains
                    # authoritative and the attempt is a containment fault.
                    pass
                self._prove_removed_role(
                    binding=binding,
                    role=CONTROLLER_ROLE,
                    container_id=controller_container_id,
                )
            elif self._query_role_ids(
                binding, role=CONTROLLER_ROLE
            ):
                raise ContainerContractError(
                    "controller role query is not empty after loss"
                )
            proxy_ids = self._query_role_ids(
                binding, role=EGRESS_PROXY_ROLE
            )
            if proxy_ids not in ((), (egress_proxy_container_id,)):
                raise ContainerContractError(
                    "recovered egress identity query is ambiguous"
                )
            if proxy_ids:
                self._stop_if_running(
                    binding=binding,
                    container_id=egress_proxy_container_id,
                    role=EGRESS_PROXY_ROLE,
                    grace_seconds=10,
                )
                self._prove_removed_role(
                    binding=binding,
                    role=EGRESS_PROXY_ROLE,
                    container_id=egress_proxy_container_id,
                )
            elif self._query_role_ids(
                binding, role=EGRESS_PROXY_ROLE
            ):
                raise ContainerContractError(
                    "egress role query is not empty after loss"
                )
            exit_sha256 = (
                _hash_unaliased_regular_file(
                    exit_path,
                    label="recovered controller guardian exit receipt",
                )
                if exit_path.exists()
                else None
            )
            absence = {
                "schema": 1,
                "kind": "arc_agi3_controller_absence",
                "campaign_id": binding.campaign_id,
                "generation_id": binding.generation_id,
                "attempt_id": binding.attempt_id,
                "attempt_spec_sha256":
                    binding.attempt_spec_sha256,
                "controller_container_id":
                    controller_container_id,
                "egress_proxy_container_id":
                    egress_proxy_container_id,
                "controller_launch_receipt_sha256":
                    controller_launch_receipt_sha256,
                "guardian_start_receipt_sha256":
                    guardian_start_receipt_sha256,
                "guardian_exit_receipt_sha256": exit_sha256,
                "controller_inspect_absent": True,
                "controller_identity_query_empty": True,
                "controller_top_absent": True,
                "controller_no_descendants": True,
                "egress_proxy_inspect_absent": True,
                "egress_proxy_identity_query_empty": True,
                "egress_proxy_top_absent": True,
                "egress_proxy_no_descendants": True,
                "authoritative_identity":
                    "controller_container_cgroup",
                "recovered_after_supervisor_loss": True,
            }
            absence_path = (
                control_root / "controller_absence_receipt.json"
            )
            if absence_path.exists() or absence_path.is_symlink():
                observed = _read_unaliased_json(
                    absence_path,
                    label="recovered controller absence receipt",
                )
                # A normally completed absence receipt is stronger; accept it
                # only when its exact lineage/absence projection agrees.
                for key, expected in absence.items():
                    if (
                        key == "recovered_after_supervisor_loss"
                        and key not in observed
                    ):
                        continue
                    if observed.get(key) != expected:
                        raise ContainerContractError(
                            "retained controller absence lineage differs"
                        )
                absence_sha256 = _hash_unaliased_regular_file(
                    absence_path,
                    label="recovered controller absence receipt",
                )
            else:
                _write_private_json_new(absence_path, absence)
                absence_sha256 = _hash_unaliased_regular_file(
                    absence_path,
                    label="recovered controller absence receipt",
                )
            return probe_transport.ControllerContainerStop(
                controller_container_id=controller_container_id,
                egress_proxy_container_id=egress_proxy_container_id,
                controller_inspect_absent=True,
                controller_identity_query_empty=True,
                controller_top_absent=True,
                controller_no_descendants=True,
                egress_proxy_inspect_absent=True,
                egress_proxy_identity_query_empty=True,
                egress_proxy_top_absent=True,
                egress_proxy_no_descendants=True,
                absence_receipt_path=str(absence_path),
                absence_receipt_sha256=absence_sha256,
            )


class DockerWorkspaceProbeExecutor:
    """Run one offline model-authored probe in a fresh, token-free container.

    The proposer container is never used as an execution sandbox.  This role
    receives only a controller-created immutable workspace snapshot, has no
    Arena/bridge/input/export mount, and streams both pipes directly into
    bounded host-owned evidence.  Timeout or overflow is a hard probe boundary
    and always precedes exact cgroup teardown.
    """

    def __init__(
        self,
        backend: DockerContainerBackend,
        *,
        image_reference: str,
        result_factory: Callable[..., Any] | None = None,
    ) -> None:
        if not isinstance(backend, DockerContainerBackend):
            raise ContainerContractError(
                "workspace probes require the observed Docker backend"
            )
        if not callable(
            getattr(backend._runner, "run_attached_stream", None)
        ):
            raise ContainerContractError(
                "workspace probes require bounded attached-stream capture"
            )
        _, digest = parse_digest_reference(image_reference)
        self._backend = backend
        self._image_reference = image_reference
        self._image_digest = digest
        recipe_path = (
            Path(__file__).resolve().parent
            / "container"
            / "Containerfile.arc-agi3-workspace-probe"
        )
        self._recipe_path, self._recipe_sha256 = (
            _validate_reviewed_probe_recipe(recipe_path)
        )
        self._result_factory = result_factory
        self._lock = threading.RLock()

    def run_probe(
        self, *, spec: Any, launched: Any, request: Any
    ) -> Any:
        """Execute and tear down a single exact offline probe synchronously."""
        with self._lock:
            factory = self._result_factory
            if factory is None:
                factory = _probe_result_factory()
            projection = self._validate_request(spec, launched, request)
            snapshot = self._observe_probe_snapshot(
                request=request, projection=projection
            )
            request_document = _probe_request_document(request)
            request_sha256 = hashlib.sha256(
                probe_transport.canonical_json(request_document)
            ).hexdigest()
            declared_request_sha256 = request.sha256()
            if (
                not _is_hex_sha256(declared_request_sha256)
                or request_sha256 != declared_request_sha256
            ):
                raise ContainerContractError(
                    "probe request hash differs from the shared transport"
                )
            evidence_root = snapshot.call_root / "evidence"
            _create_private_directory_new(
                evidence_root, label="probe evidence root"
            )
            request_receipt_path = evidence_root / "request.json"
            _write_private_json_new(
                request_receipt_path,
                {
                    "schema": 1,
                    "kind": "arc_agi3_contiguous_probe_request",
                    "request_sha256": request_sha256,
                    "request": request_document,
                },
            )

            image = self._inspect_probe_image()
            probe_id = str(uuid.uuid4())
            labels = self._probe_labels(
                projection, launched=launched, probe_id=probe_id
            )
            if self._probe_identity_query(labels).stdout.strip():
                raise ContainerContractError(
                    "probe identity already has a live container"
                )
            command = self._build_probe_create_command(
                projection,
                snapshot=snapshot,
                image=image,
                labels=labels,
                probe_id=probe_id,
            )
            dispatch_path = evidence_root / "dispatch_receipt.json"
            _write_private_json_new(
                dispatch_path,
                {
                    "schema": 1,
                    "kind": "arc_agi3_contiguous_probe_dispatch",
                    "campaign_id": projection["campaign_id"],
                    "generation_id": projection["generation_id"],
                    "attempt_id": projection["attempt_id"],
                    "dynamic_request_id":
                        projection["dynamic_request_id"],
                    "dynamic_call_id": projection["dynamic_call_id"],
                    "thread_id": projection["thread_id"],
                    "turn_id": projection["turn_id"],
                    "request_sha256": request_sha256,
                    "probe_id": probe_id,
                    "probe_labels": dict(sorted(labels.items())),
                    "image_reference": image.requested_reference,
                    "image_digest": image.manifest_digest,
                    "reviewed_probe_recipe_sha256":
                        image.recipe_sha256,
                    "snapshot_manifest_sha256":
                        snapshot.manifest_sha256,
                    "snapshot_tree_sha256": snapshot.tree_sha256,
                    "create_argv_sha256": _argv_sha256(command),
                    "terminal_receipt":
                        str(evidence_root / "teardown_receipt.json"),
                },
            )
            container_id: str | None = None
            stream: AttachedStreamResult | None = None
            exit_code: int | None = None
            containment_path = evidence_root / "containment_attestation.json"
            teardown_path = evidence_root / "teardown_receipt.json"
            stdout_path = evidence_root / "stdout.bin"
            stderr_path = evidence_root / "stderr.bin"
            create_may_have_committed = False
            try:
                self._reinspect_parent_proposer(
                    spec,
                    launched,
                    projection=projection,
                    stage="before workspace probe create",
                )
                repeated_snapshot = self._observe_probe_snapshot(
                    request=request, projection=projection
                )
                if repeated_snapshot != snapshot:
                    raise ContainerContractError(
                        "workspace probe snapshot drifted before create"
                    )
                created = self._backend._required(
                    command,
                    timeout_seconds=60,
                    label="workspace probe container creation",
                )
                create_may_have_committed = True
                container_id = _parse_created_container_id(
                    created.stdout,
                    labels=labels,
                    identity_query=self._probe_identity_query,
                )
                observed = self._backend._inspect_container(container_id)
                containment = self._validate_probe_container(
                    observed,
                    projection=projection,
                    snapshot=snapshot,
                    image=image,
                    labels=labels,
                    probe_id=probe_id,
                    container_id=container_id,
                    create_argv_sha256=_argv_sha256(command),
                )
                _write_private_json_new(containment_path, containment)
                containment_sha256 = _hash_unaliased_regular_file(
                    containment_path,
                    label="workspace probe containment attestation",
                )

                # A mutable local tag or changed rootfs must not enter between
                # create and start.  Re-observe both identities immediately.
                current_image = self._inspect_probe_image()
                if current_image != image:
                    raise ContainerContractError(
                        "workspace probe image drifted before start"
                    )
                repeated = self._backend._inspect_container(container_id)
                if _json_sha256(repeated) != _json_sha256(observed):
                    raise ContainerContractError(
                        "workspace probe container drifted before start"
                    )
                self._reinspect_parent_proposer(
                    spec,
                    launched,
                    projection=projection,
                    stage="before workspace probe start",
                )
                repeated_snapshot = self._observe_probe_snapshot(
                    request=request, projection=projection
                )
                if repeated_snapshot != snapshot:
                    raise ContainerContractError(
                        "workspace probe snapshot drifted before start"
                    )
                attached_runner = self._backend._runner
                stream = attached_runner.run_attached_stream(
                    (
                        self._backend._docker,
                        "container",
                        "start",
                        "--attach",
                        container_id,
                    ),
                    timeout_seconds=projection["timeout_seconds"],
                    stdout_path=stdout_path,
                    stderr_path=stderr_path,
                    stdout_limit_bytes=projection[
                        "stdout_limit_bytes"
                    ],
                    stderr_limit_bytes=projection[
                        "stderr_limit_bytes"
                    ],
                )
                terminal = self._backend._inspect_container(container_id)
                terminal_state = _required_dict(
                    terminal, "State", label="probe terminal State"
                )
                if _required_bool(
                    terminal_state,
                    "Running",
                    label="probe terminal State.Running",
                ):
                    if not (stream.timed_out or stream.output_overflow):
                        raise ContainerContractError(
                            "workspace probe remained live after attached start"
                        )
                else:
                    observed_exit = _required_int(
                        terminal_state,
                        "ExitCode",
                        label="probe terminal State.ExitCode",
                    )
                    exit_code = observed_exit
                    if (
                        not stream.timed_out
                        and not stream.output_overflow
                        and stream.returncode != observed_exit
                    ):
                        raise ContainerContractError(
                            "attached probe exit and Docker state disagree"
                        )
            except BaseException as original:
                try:
                    if container_id is not None:
                        self._remove_probe_container(
                            container_id, labels=labels
                        )
                    elif create_may_have_committed:
                        self._reconcile_uncertain_probe_create(labels)
                except BaseException as cleanup_error:
                    raise ContainerContractError(
                        "workspace probe failed and exact cleanup was "
                        "not provable"
                    ) from original
                raise

            assert container_id is not None
            assert stream is not None
            teardown = self._remove_probe_container(
                container_id, labels=labels
            )
            final_snapshot = self._observe_probe_snapshot(
                request=request, projection=projection
            )
            if final_snapshot != snapshot:
                raise ContainerContractError(
                    "workspace probe mutated its read-only snapshot"
                )
            teardown.update(
                {
                    "schema": 1,
                    "kind":
                        "arc_agi3_contiguous_probe_teardown",
                    "request_sha256": request_sha256,
                    "containment_attestation_sha256":
                        containment_sha256,
                    "snapshot_tree_sha256": snapshot.tree_sha256,
                    "no_writeback": True,
                }
            )
            _write_private_json_new(teardown_path, teardown)
            teardown_sha256 = _hash_unaliased_regular_file(
                teardown_path,
                label="workspace probe teardown receipt",
            )
            return factory(
                schema=1,
                request_sha256=request_sha256,
                probe_container_id=container_id,
                image_reference=self._image_reference,
                image_digest=self._image_digest,
                containment_attestation_path=str(containment_path),
                containment_attestation_sha256=containment_sha256,
                snapshot_tree_sha256=snapshot.tree_sha256,
                stdout_path=stream.stdout_path,
                stdout_sha256=stream.stdout_sha256,
                stdout_bytes=stream.stdout_bytes,
                stdout_truncated=stream.stdout_truncated,
                stderr_path=stream.stderr_path,
                stderr_sha256=stream.stderr_sha256,
                stderr_bytes=stream.stderr_bytes,
                stderr_truncated=stream.stderr_truncated,
                exit_code=exit_code,
                timed_out=stream.timed_out,
                output_overflow=stream.output_overflow,
                arena_session_id=None,
                arena_transcript_path=None,
                arena_transcript_sha256=None,
                started_monotonic_ns=int(
                    stream.started_monotonic * 1_000_000_000
                ),
                finished_monotonic_ns=int(
                    stream.finished_monotonic * 1_000_000_000
                ),
                teardown_receipt_path=str(teardown_path),
                teardown_receipt_sha256=teardown_sha256,
                container_absent=teardown["container_absent"],
                process_group_absent=teardown[
                    "process_group_absent"
                ],
                descendants_absent=teardown["descendants_absent"],
                no_writeback=True,
            )

    def _observe_probe_snapshot(
        self,
        *,
        request: Any,
        projection: Mapping[str, Any],
    ) -> ProbeSnapshotObservation:
        return _validate_probe_snapshot(
            request,
            expected_campaign=projection["campaign_id"],
            expected_generation=projection["generation_id"],
            expected_attempt=projection["attempt_id"],
            expected_request=projection["dynamic_request_id"],
            expected_call=projection["dynamic_call_id"],
            expected_thread=projection["thread_id"],
            expected_turn=projection["turn_id"],
            expected_tree_sha256=projection[
                "workspace_snapshot_tree_sha256"
            ],
            expected_generation_root=projection["_generation_root"],
            expected_call_root=projection["_call_root"],
            expected_snapshot_root=projection["_snapshot_root"],
            expected_manifest_path=projection["_manifest_path"],
            entrypoint=projection["entrypoint"],
        )

    def _validate_request(
        self, spec: Any, launched: Any, request: Any
    ) -> dict[str, Any]:
        if not isinstance(request, probe_transport.ProbeExecutionRequest):
            raise ContainerContractError(
                "probe request must use the shared frozen transport type"
            )
        try:
            fields = vars(request)
        except TypeError as exc:
            raise ContainerContractError(
                "probe request must expose dataclass fields"
            ) from exc
        if set(fields) != PROBE_EXECUTION_REQUEST_FIELDS:
            raise ContainerContractError(
                "probe request security projection differs"
            )
        campaign = _canonical_uuid4(
            fields["campaign_id"], label="probe campaign_id"
        )
        generation = _canonical_uuid4(
            fields["generation_id"], label="probe generation_id"
        )
        attempt = _canonical_uuid4(
            fields["attempt_id"], label="probe attempt_id"
        )
        if (
            campaign != _runner_field(spec, "campaign_id")
            or generation != _runner_field(spec, "generation_id")
            or attempt != _runner_field(spec, "attempt_id")
            or getattr(launched, "container_id", None) is None
            or not CONTAINER_ID_RE.fullmatch(launched.container_id)
            or fields["thread_id"]
            != getattr(launched, "codex_thread_id", None)
            or fields["turn_id"]
            != getattr(launched, "codex_turn_id", None)
        ):
            raise ContainerContractError(
                "probe request does not bind the launched proposer turn"
            )
        identifiers: dict[str, str] = {}
        for name in ("dynamic_request_id", "dynamic_call_id"):
            identifier = _safe_probe_identifier(fields[name])
            if identifier is None:
                raise ContainerContractError(
                    f"probe {name} is not a safe exact identifier"
                )
            identifiers[name] = identifier
        for name in ("thread_id", "turn_id"):
            value = fields[name]
            if (
                not isinstance(value, str)
                or not _is_canonical_uuid(value)
            ):
                raise ContainerContractError(
                    f"probe {name} is not a canonical UUID"
                )
            identifiers[name] = value
        if fields["schema"] != 1 or isinstance(fields["schema"], bool):
            raise ContainerContractError("probe request schema differs")
        generation_root = Path(_runner_field(spec, "generation_dir"))
        _validate_private_host_directory(generation_root)
        _reject_docker_mount_path(
            generation_root, label="probe generation directory"
        )
        request_root = (
            generation_root
            / "probe_calls"
            / identifiers["dynamic_request_id"]
        )
        call_root = request_root / identifiers["dynamic_call_id"]
        snapshot_root = call_root / "snapshot"
        expected_manifest_path = call_root / "snapshot_manifest.json"
        for path, label in (
            (generation_root / "probe_calls", "probe call namespace"),
            (request_root, "probe dynamic-request directory"),
            (call_root, "probe dynamic-call directory"),
        ):
            _private_directory_identity(path, label=label)
        try:
            call_entries = {
                entry.name for entry in os.scandir(call_root)
            }
        except OSError as exc:
            raise ContainerContractError(
                "probe dynamic-call directory cannot be enumerated"
            ) from exc
        if call_entries != {"snapshot", "snapshot_manifest.json"}:
            raise ContainerContractError(
                "probe dynamic-call directory is not a fresh exact snapshot"
            )
        manifest_path = Path(
            fields["workspace_snapshot_manifest_path"]
        )
        if (
            not manifest_path.is_absolute()
            or Path(os.path.abspath(os.fspath(manifest_path)))
            != manifest_path
            or manifest_path != expected_manifest_path
            or not _is_hex_sha256(
                fields["workspace_snapshot_manifest_sha256"]
            )
            or not _is_hex_sha256(
                fields["workspace_snapshot_tree_sha256"]
            )
            or _hash_unaliased_regular_file(
                manifest_path, label="workspace snapshot manifest"
            )
            != fields["workspace_snapshot_manifest_sha256"]
        ):
            raise ContainerContractError(
                "probe workspace snapshot manifest is stale or malformed"
            )
        _reject_docker_mount_path(
            snapshot_root, label="probe snapshot mount source"
        )
        entrypoint = fields["entrypoint"]
        if not _valid_probe_relative_path(entrypoint) \
                or not entrypoint.endswith(".py"):
            raise ContainerContractError(
                "probe entrypoint is not a confined Python file"
            )
        arguments = fields["arguments"]
        if (
            not isinstance(arguments, tuple)
            or len(arguments) > 64
            or not all(
                isinstance(item, str)
                and "\x00" not in item
                and len(item.encode("utf-8")) <= 16 * 1024
                and not Path(item).is_absolute()
                for item in arguments
            )
        ):
            raise ContainerContractError(
                "probe arguments are not the exact bounded tuple"
            )
        for name in (
            "timeout_seconds",
            "stdout_limit_bytes",
            "stderr_limit_bytes",
        ):
            value = fields[name]
            maximum = (
                MAX_PROBE_TIMEOUT_SECONDS
                if name == "timeout_seconds"
                else MAX_CONTAINER_STREAM_BYTES
            )
            if (
                isinstance(value, bool)
                or not isinstance(value, int)
                or not 1 <= value <= maximum
            ):
                raise ContainerContractError(
                    f"probe {name} is outside its hard bound"
                )
        limits_value = fields["resource_limits"]
        try:
            limits = ResourceLimits(
                cpus=limits_value.cpus,
                memory_bytes=limits_value.memory_bytes,
                pids=limits_value.pids,
                tmpfs_bytes=limits_value.tmpfs_bytes,
            )
        except AttributeError as exc:
            raise ContainerContractError(
                "probe resource limits are incomplete"
            ) from exc
        limits.validate()
        if fields["arena_mode"] != "disabled" \
                or fields["arena_session_id"] is not None:
            raise ContainerContractError(
                "probe Arena mediation is not yet an admitted backend mode"
            )
        return {
            **fields,
            "resource_limits": limits,
            "_game": _runner_field(spec, "game"),
            "_target_level": _runner_field(spec, "target_level"),
            "dynamic_request_label": identifiers[
                "dynamic_request_id"
            ],
            "_generation_root": generation_root,
            "_call_root": call_root,
            "_snapshot_root": snapshot_root,
            "_manifest_path": expected_manifest_path,
        }

    def _reinspect_parent_proposer(
        self,
        spec: Any,
        launched: Any,
        *,
        projection: Mapping[str, Any],
        stage: str,
    ) -> str:
        """Prove the live parent identity immediately before probe mutation."""
        container_id = getattr(launched, "container_id", None)
        if (
            not isinstance(container_id, str)
            or not CONTAINER_ID_RE.fullmatch(container_id)
        ):
            raise ContainerContractError(
                f"{stage}: proposer container id is malformed"
            )
        observed = self._backend._inspect_container(container_id)
        if _required_string(
            observed, "Id", label=f"{stage} proposer Id"
        ) != container_id:
            raise ContainerContractError(
                f"{stage}: proposer container identity drifted"
            )
        config = _required_dict(
            observed, "Config", label=f"{stage} proposer Config"
        )
        labels = _required_dict(
            config,
            "Labels",
            label=f"{stage} proposer Config.Labels",
        )
        expected_labels = {
            LABEL_CAMPAIGN: projection["campaign_id"],
            LABEL_GENERATION: projection["generation_id"],
            LABEL_ATTEMPT: projection["attempt_id"],
            LABEL_GAME: _runner_field(spec, "game"),
            LABEL_LEVEL: str(_runner_field(spec, "target_level")),
            **trusted_worker_hashes(),
        }
        if any(
            labels.get(name) != expected
            for name, expected in expected_labels.items()
        ):
            raise ContainerContractError(
                f"{stage}: proposer labels do not bind the exact turn"
            )
        configured_image = _required_string(
            config, "Image", label=f"{stage} proposer Config.Image"
        )
        if configured_image != _runner_field(spec, "image_reference"):
            raise ContainerContractError(
                f"{stage}: proposer image reference drifted"
            )
        _, configured_digest = parse_digest_reference(configured_image)
        if configured_digest != _runner_field(spec, "image_digest"):
            raise ContainerContractError(
                f"{stage}: proposer image digest drifted"
            )
        state = _required_dict(
            observed, "State", label=f"{stage} proposer State"
        )
        if (
            _required_string(
                state, "Status", label=f"{stage} proposer State.Status"
            )
            != "running"
            or not _required_bool(
                state, "Running", label=f"{stage} proposer State.Running"
            )
            or _required_bool(
                state, "Paused", label=f"{stage} proposer State.Paused"
            )
            or _required_bool(
                state,
                "Restarting",
                label=f"{stage} proposer State.Restarting",
            )
        ):
            raise ContainerContractError(
                f"{stage}: proposer is not exact and continuously running"
            )
        observed_sha256 = _json_sha256(observed)
        launch_sha256 = getattr(
            launched, "running_observation_sha256", None
        )
        if (
            not _is_hex_sha256(launch_sha256)
            or launch_sha256 != observed_sha256
        ):
            raise ContainerContractError(
                f"{stage}: proposer differs from its launch observation"
            )
        _validate_parent_turn_binding(
            spec,
            launched,
            expected_thread=projection["thread_id"],
            expected_turn=projection["turn_id"],
            stage=stage,
        )
        return observed_sha256

    def _inspect_probe_image(self) -> ProbeImageObservation:
        result = self._backend._required(
            (
                self._backend._docker,
                "image",
                "inspect",
                self._image_reference,
            ),
            timeout_seconds=30,
            label="workspace probe image inspection",
        )
        observed = _parse_single_inspect_object(
            result.stdout, label="workspace probe image inspection"
        )
        image_id = _required_digest(
            observed, "Id", label="workspace probe image Id"
        )
        repo_values = _required_list(
            observed,
            "RepoDigests",
            label="workspace probe RepoDigests",
        )
        if not repo_values or not all(
            isinstance(value, str) for value in repo_values
        ):
            raise ContainerContractError(
                "workspace probe image lacks repository digests"
            )
        repo_digests = tuple(sorted(repo_values))
        observed_digests = {
            parse_digest_reference(value)[1] for value in repo_digests
        }
        config = _required_dict(
            observed, "Config", label="workspace probe image Config"
        )
        environment = _required_list(
            config, "Env", label="workspace probe image environment"
        )
        environment_names = _parse_environment_names(environment)
        labels = _required_dict(
            config,
            "Labels",
            label="workspace probe image labels",
        )
        if (
            self._image_digest not in observed_digests
            or tuple(
                _required_list(
                    config,
                    "Entrypoint",
                    label="workspace probe image entrypoint",
                )
            )
            != (PYTHON_ENTRYPOINT, "-I")
            or config.get("User") != PROBE_USER
            or config.get("WorkingDir") != PROBE_DESTINATION
            or labels.get(PROBE_ROLE_LABEL) != PROBE_ROLE_VALUE
            or labels.get(PROBE_RECIPE_LABEL) != self._recipe_sha256
            or labels.get(PROBE_BASE_IMAGE_LABEL)
            != PROBE_BASE_IMAGE_DIGEST
            or labels.get(PROBE_CONTENT_POLICY_LABEL)
            != PROBE_CONTENT_POLICY_VALUE
            or config.get("Cmd") not in (None, [])
            or config.get("Volumes") not in (None, {})
            or config.get("ExposedPorts") not in (None, {})
            or set(environment_names) - ALLOWED_IMAGE_ENV_NAMES
        ):
            raise ContainerContractError(
                "workspace probe image is not the exact token-free role"
            )
        return ProbeImageObservation(
            requested_reference=self._image_reference,
            manifest_digest=self._image_digest,
            image_id=image_id,
            repo_digests=repo_digests,
            environment=tuple(environment),
            environment_names=environment_names,
            recipe_path=str(self._recipe_path),
            recipe_sha256=self._recipe_sha256,
            base_image_digest=PROBE_BASE_IMAGE_DIGEST,
            content_policy=PROBE_CONTENT_POLICY_VALUE,
            observation_sha256=_json_sha256(observed),
        )

    def _probe_labels(
        self,
        projection: Mapping[str, Any],
        *,
        launched: Any,
        probe_id: str,
    ) -> dict[str, str]:
        return {
            LABEL_CAMPAIGN: projection["campaign_id"],
            LABEL_GENERATION: projection["generation_id"],
            LABEL_ATTEMPT: projection["attempt_id"],
            LABEL_GAME: projection["_game"],
            LABEL_LEVEL: str(projection["_target_level"]),
            LABEL_PROBE: probe_id,
            LABEL_DYNAMIC_REQUEST: projection["dynamic_request_label"],
            LABEL_DYNAMIC_CALL: projection["dynamic_call_id"],
            LABEL_CODEX_THREAD: projection["thread_id"],
            LABEL_CODEX_TURN: projection["turn_id"],
            LABEL_PARENT_CONTAINER: launched.container_id,
            PROBE_ROLE_LABEL: PROBE_ROLE_VALUE,
        }

    def _probe_identity_query(
        self, labels: Mapping[str, str]
    ) -> CommandResult:
        argv: list[str] = [
            self._backend._docker,
            "container",
            "ls",
            "--all",
            "--no-trunc",
            "--quiet",
        ]
        for key, value in sorted(labels.items()):
            argv.extend(("--filter", f"label={key}={value}"))
        return self._backend._required(
            tuple(argv),
            timeout_seconds=30,
            label="workspace probe identity query",
        )

    def _build_probe_create_command(
        self,
        projection: Mapping[str, Any],
        *,
        snapshot: ProbeSnapshotObservation,
        image: ProbeImageObservation,
        labels: Mapping[str, str],
        probe_id: str,
    ) -> tuple[str, ...]:
        limits: ResourceLimits = projection["resource_limits"]
        name = "arc-agi3-probe-" + probe_id
        mount_source = _docker_mount_source(snapshot.root)
        argv: list[str] = [
            self._backend._docker,
            "container",
            "create",
            "--name",
            name,
            "--pull",
            "never",
            "--read-only",
            "--network",
            "none",
            "--cgroupns",
            "private",
            "--ipc",
            "private",
            "--cap-drop",
            "ALL",
            "--security-opt",
            "no-new-privileges=true",
            "--user",
            PROBE_USER,
            "--cpus",
            str(float(limits.cpus)),
            "--memory",
            str(limits.memory_bytes),
            "--memory-swap",
            str(limits.memory_bytes),
            "--pids-limit",
            str(limits.pids),
            "--restart",
            "no",
            "--no-healthcheck",
            "--log-driver",
            "none",
            "--tmpfs",
            (
                f"{TMPFS_DESTINATION}:rw,nosuid,nodev,noexec,"
                f"size={limits.tmpfs_bytes},mode=1777,"
                "uid=65534,gid=65534"
            ),
            "--mount",
            (
                f"type=bind,src={mount_source},"
                f"dst={PROBE_DESTINATION},readonly,"
                "bind-propagation=rprivate"
            ),
            "--workdir",
            PROBE_DESTINATION,
            "--entrypoint",
            PYTHON_ENTRYPOINT,
        ]
        for key, value in sorted(labels.items()):
            argv.extend(("--label", f"{key}={value}"))
        argv.extend(
            (
                image.requested_reference,
                "-I",
                f"{PROBE_DESTINATION}/{projection['entrypoint']}",
                *projection["arguments"],
            )
        )
        return tuple(argv)

    def _validate_probe_container(
        self,
        observed: Mapping[str, Any],
        *,
        projection: Mapping[str, Any],
        snapshot: ProbeSnapshotObservation,
        image: ProbeImageObservation,
        labels: Mapping[str, str],
        probe_id: str,
        container_id: str,
        create_argv_sha256: str,
    ) -> dict[str, Any]:
        _validate_probe_container_observation(
            observed,
            projection=projection,
            snapshot=snapshot,
            image=image,
            labels=labels,
            probe_id=probe_id,
            container_id=container_id,
        )
        return {
            "schema": 1,
            "kind": "arc_agi3_contiguous_probe_containment",
            "scenario_owner": "S03",
            "campaign_id": projection["campaign_id"],
            "generation_id": projection["generation_id"],
            "attempt_id": projection["attempt_id"],
            "dynamic_request_id": projection["dynamic_request_id"],
            "dynamic_call_id": projection["dynamic_call_id"],
            "thread_id": projection["thread_id"],
            "turn_id": projection["turn_id"],
            "probe_id": probe_id,
            "container_id": container_id,
            "parent_container_id": labels[LABEL_PARENT_CONTAINER],
            "image_reference": image.requested_reference,
            "image_digest": image.manifest_digest,
            "image_id": image.image_id,
            "image_observation_sha256": image.observation_sha256,
            "reviewed_probe_recipe_path": image.recipe_path,
            "reviewed_probe_recipe_sha256": image.recipe_sha256,
            "probe_base_image_digest": image.base_image_digest,
            "probe_content_policy": image.content_policy,
            "snapshot_manifest_sha256": snapshot.manifest_sha256,
            "snapshot_tree_sha256": snapshot.tree_sha256,
            "generation_root": str(snapshot.generation_root),
            "generation_root_device": snapshot.generation_device,
            "generation_root_inode": snapshot.generation_inode,
            "call_root": str(snapshot.call_root),
            "call_root_device": snapshot.call_device,
            "call_root_inode": snapshot.call_inode,
            "snapshot_root": str(snapshot.root),
            "snapshot_root_device": snapshot.root_device,
            "snapshot_root_inode": snapshot.root_inode,
            "snapshot_file_count": snapshot.file_count,
            "snapshot_total_bytes": snapshot.total_bytes,
            "snapshot_entries_sha256": snapshot.entries_sha256,
            "entrypoint_sha256": snapshot.entrypoint_sha256,
            "create_argv_sha256": create_argv_sha256,
            "container_observation_sha256": _json_sha256(observed),
            "isolation": {
                "read_only_root": True,
                "network_none": True,
                "private_pid": True,
                "private_cgroup": True,
                "private_ipc": True,
                "private_uts": True,
                "capabilities_dropped": True,
                "no_new_privileges": True,
                "nonroot_identity": PROBE_USER,
                "single_read_only_snapshot_mount": True,
                "private_scratch_tmpfs": True,
                "container_log_driver": "none",
                "arena_mode": "disabled",
                "no_input_export_bridge_or_token_mounts": True,
                "no_writeback": True,
            },
        }

    def _remove_probe_container(
        self, container_id: str, *, labels: Mapping[str, str]
    ) -> dict[str, Any]:
        command = (
            self._backend._docker,
            "container",
            "rm",
            "--force",
            "--volumes",
            container_id,
        )
        removed = self._backend._runner.run(
            command, timeout_seconds=60
        )
        if (
            not isinstance(removed, CommandResult)
            or removed.argv != command
            or removed.returncode != 0
        ):
            raise ContainerContractError(
                "workspace probe cgroup removal was not acknowledged"
            )
        inspect_absent = self._backend._expect_absent(
            (
                self._backend._docker,
                "container",
                "inspect",
                container_id,
            ),
            label="workspace probe absence inspection",
        )
        top_absent = self._backend._expect_absent(
            (
                self._backend._docker,
                "container",
                "top",
                container_id,
                "-eo",
                "pid,ppid,pgid",
            ),
            label="workspace probe process-group absence",
        )
        identity_empty = not self._probe_identity_query(
            labels
        ).stdout.strip()
        if not (inspect_absent and top_absent and identity_empty):
            raise ContainerContractError(
                "workspace probe teardown left a container or descendant"
            )
        return {
            "container_id": container_id,
            "container_absent": True,
            "process_group_absent": True,
            "descendants_absent": True,
            "identity_query_empty": True,
        }

    def _reconcile_uncertain_probe_create(
        self, labels: Mapping[str, str]
    ) -> None:
        """Remove a label-bound create whose stdout acknowledgement was bad."""
        query = self._probe_identity_query(labels)
        ids = tuple(
            line for line in query.stdout.splitlines() if line
        )
        if (
            len(ids) > 1
            or len(ids) != len(set(ids))
            or not all(CONTAINER_ID_RE.fullmatch(value) for value in ids)
        ):
            raise ContainerContractError(
                "uncertain workspace probe create has ambiguous identities"
            )
        if ids:
            self._remove_probe_container(ids[0], labels=labels)
        elif self._probe_identity_query(labels).stdout.strip():
            raise ContainerContractError(
                "uncertain workspace probe identity changed while proving absence"
            )

    def reconcile_attempt_probes(
        self, *, spec: Any, stage: str
    ) -> dict[str, Any]:
        """Crash-reconcile every sibling probe carrying this attempt identity."""
        if stage not in {"startup", "teardown"}:
            raise ContainerContractError(
                "probe reconciliation stage is unsupported"
            )
        labels = _attempt_probe_labels(spec)
        receipt_path = (
            Path(_runner_field(spec, "host_transcript_path")).parent
            / f"probe_reconciliation_{stage}.json"
        )
        ids = self._query_attempt_probe_ids(labels)
        if receipt_path.exists() or receipt_path.is_symlink():
            prior = _read_unaliased_json(
                receipt_path, label="probe reconciliation receipt"
            )
            _validate_probe_reconciliation_receipt(
                prior,
                labels=labels,
                stage=stage,
            )
            if ids:
                raise ContainerContractError(
                    "workspace probe identity reappeared after reconciliation"
                )
            return {
                **prior,
                "receipt_path": str(receipt_path),
                "receipt_sha256": _hash_unaliased_regular_file(
                    receipt_path, label="probe reconciliation receipt"
                ),
            }
        removed: list[str] = []
        for container_id in ids:
            observed = self._backend._inspect_container(container_id)
            config = _required_dict(
                observed,
                "Config",
                label="orphan probe Config",
            )
            observed_labels = _required_dict(
                config,
                "Labels",
                label="orphan probe Config.Labels",
            )
            if any(
                observed_labels.get(name) != value
                for name, value in labels.items()
            ):
                raise ContainerContractError(
                    "orphan probe identity query returned a substituted object"
                )
            remove = (
                self._backend._docker,
                "container",
                "rm",
                "--force",
                "--volumes",
                container_id,
            )
            result = self._backend._runner.run(
                remove, timeout_seconds=60
            )
            if (
                not isinstance(result, CommandResult)
                or result.argv != remove
                or result.returncode != 0
            ):
                raise ContainerContractError(
                    "orphan probe cgroup removal was not acknowledged"
                )
            if not self._backend._expect_absent(
                (
                    self._backend._docker,
                    "container",
                    "inspect",
                    container_id,
                ),
                label="orphan probe post-removal inspection",
            ) or not self._backend._expect_absent(
                (
                    self._backend._docker,
                    "container",
                    "top",
                    container_id,
                    "-eo",
                    "pid,ppid,pgid",
                ),
                label="orphan probe post-removal process inventory",
            ):
                raise ContainerContractError(
                    "orphan probe container or process group remained present"
                )
            removed.append(container_id)
        if self._query_attempt_probe_ids(labels):
            raise ContainerContractError(
                "attempt probe identities remained after reconciliation"
            )
        body = {
            "schema": 1,
            "kind": "arc_agi3_contiguous_probe_reconciliation",
            "stage": stage,
            "campaign_id": labels[LABEL_CAMPAIGN],
            "generation_id": labels[LABEL_GENERATION],
            "attempt_id": labels[LABEL_ATTEMPT],
            "game": labels[LABEL_GAME],
            "target_level": int(labels[LABEL_LEVEL]),
            "removed_container_ids": removed,
            "identity_query_empty": True,
            "container_inspect_absent": True,
            "process_groups_absent": True,
        }
        _write_private_json_new(receipt_path, body)
        return {
            **body,
            "receipt_path": str(receipt_path),
            "receipt_sha256": _hash_unaliased_regular_file(
                receipt_path, label="probe reconciliation receipt"
            ),
        }

    def prove_attempt_probe_absence(
        self, *, spec: Any, stage: str
    ) -> dict[str, Any]:
        """Fail if any sibling probe survives a quiescent attempt boundary."""
        if stage not in {"pre_collection", "pre_promotion"}:
            raise ContainerContractError(
                "probe-absence proof stage is unsupported"
            )
        labels = _attempt_probe_labels(spec)
        if self._query_attempt_probe_ids(labels):
            raise ContainerContractError(
                "live workspace probe survived the quiescent attempt boundary"
            )
        body = {
            "schema": 1,
            "kind": "arc_agi3_contiguous_probe_absence",
            "stage": stage,
            "campaign_id": labels[LABEL_CAMPAIGN],
            "generation_id": labels[LABEL_GENERATION],
            "attempt_id": labels[LABEL_ATTEMPT],
            "identity_query_empty": True,
        }
        receipt_path = (
            Path(_runner_field(spec, "host_transcript_path")).parent
            / f"probe_absence_{stage}.json"
        )
        if receipt_path.exists() or receipt_path.is_symlink():
            if _read_unaliased_json(
                receipt_path, label="probe absence receipt"
            ) != body:
                raise ContainerContractError(
                    "probe absence receipt changed"
                )
        else:
            _write_private_json_new(receipt_path, body)
        return {
            **body,
            "receipt_path": str(receipt_path),
            "receipt_sha256": _hash_unaliased_regular_file(
                receipt_path, label="probe absence receipt"
            ),
        }

    def _query_attempt_probe_ids(
        self, labels: Mapping[str, str]
    ) -> tuple[str, ...]:
        argv: list[str] = [
            self._backend._docker,
            "container",
            "ls",
            "--all",
            "--no-trunc",
            "--quiet",
        ]
        for name, value in sorted(labels.items()):
            argv.extend(("--filter", f"label={name}={value}"))
        result = self._backend._required(
            tuple(argv),
            timeout_seconds=30,
            label="attempt-wide workspace probe identity query",
        )
        ids = tuple(
            line for line in result.stdout.splitlines() if line
        )
        if (
            len(ids) != len(set(ids))
            or len(ids) > MAX_PROBE_FILES
            or not all(CONTAINER_ID_RE.fullmatch(value) for value in ids)
        ):
            raise ContainerContractError(
                "attempt-wide workspace probe identity query is malformed"
            )
        return ids


class ContiguousDockerAttemptBackend:
    """Typed runner adapter over the observed Docker boundary.

    This adapter owns the host Arena session, its one-client Unix RPC server,
    and the private token file.  It deliberately requires a trusted result
    collector: a container-authored outcome is diagnostic and can never, by
    itself, become a promotion candidate.

    Idempotence is currently process-local.  The release gate remains false
    until durable adapter rehydration and real-daemon adversarial probes exist.
    """

    requires_controller_state_canaries = True

    def __init__(
        self,
        backend: DockerContainerBackend,
        *,
        result_collector: AttemptResultCollector,
        credentials: probe_transport.ExternalChatGptCredentials,
        probe_executor: DockerWorkspaceProbeExecutor,
        controller_factory: Callable[..., Any] | None = None,
        controller_container_launcher: (
            probe_transport.ControllerContainerLauncher | None
        ) = None,
        controller_state_canaries: tuple[Any, ...] = (),
        canary_operator: (
            canary_operator_contract.HostContainmentCanaryOperator | None
        ) = None,
        bridge_client_factory: Callable[..., Any] | None = None,
        arena_session_factory: Callable[..., Any] | None = None,
        arena_server_factory: (
            Callable[[Any, Path, Path], Any] | None
        ) = None,
        arena_client_factory: Callable[[Path, str], Any] | None = None,
        arena_volume_lifecycle: Any | None = None,
    ) -> None:
        if not isinstance(backend, DockerContainerBackend):
            raise ContainerContractError(
                "contiguous adapter requires the observed Docker backend"
            )
        if not callable(result_collector):
            raise ContainerContractError(
                "contiguous adapter requires a trusted result collector"
            )
        if not isinstance(
            credentials, probe_transport.ExternalChatGptCredentials
        ):
            raise ContainerContractError(
                "contiguous adapter requires pinned external ChatGPT credentials"
            )
        if not isinstance(probe_executor, DockerWorkspaceProbeExecutor):
            raise ContainerContractError(
                "contiguous adapter requires the observed workspace-probe executor"
            )
        using_production_controller = controller_factory is None
        try:
            import arc_agi3_contiguous_taint as taint_contract

            normalized_controller_state_canaries = (
                taint_contract.validate_live_canaries(
                    controller_state_canaries,
                    require_complete=using_production_controller,
                )
                if controller_state_canaries
                else ()
            )
        except Exception as exc:
            raise ContainerContractError(
                "controller-state canaries are malformed"
            ) from exc
        if using_production_controller and canary_operator is None:
            raise ContainerContractError(
                "production controller requires the formal per-attempt "
                "host containment-canary operator"
            )
        if (
            using_production_controller
            and normalized_controller_state_canaries
        ):
            raise ContainerContractError(
                "production controller rejects static containment canaries"
            )
        self._backend = backend
        self.requires_controller_state_canaries = False
        self.generates_controller_state_canaries = (
            using_production_controller and canary_operator is not None
        )
        self._result_collector = result_collector
        self._credentials = credentials
        self._probe_executor = probe_executor
        # Live-only containment inputs.  Values are scanned but never retained;
        # only their cardinality and zero/nonzero occurrence verdict are
        # receipt-bound.
        self._controller_state_canaries = (
            normalized_controller_state_canaries
        )
        if (
            canary_operator is not None
            and not isinstance(
                canary_operator,
                canary_operator_contract.HostContainmentCanaryOperator,
            )
        ):
            raise ContainerContractError(
                "containment canary operator has the wrong type"
            )
        self._canary_operator = canary_operator
        self._controller_factory = (
            controller_factory
            or probe_transport.CodexAppServerController
        )
        if using_production_controller:
            self._controller_container_launcher = (
                controller_container_launcher
                or DockerControllerContainerLauncher(backend)
            )
        else:
            self._controller_container_launcher = (
                controller_container_launcher
            )
        self._bridge_client_factory = (
            bridge_client_factory or probe_transport.BridgeClient
        )
        self._arena_session_factory = (
            arena_session_factory or _default_arena_session
        )
        self._arena_server_factory = (
            arena_server_factory or _default_arena_server
        )
        self._arena_client_factory = (
            arena_client_factory or _default_arena_client
        )
        if arena_volume_lifecycle is None:
            self._arena_volume_lifecycle = DockerArenaVolumeLifecycle(
                backend
            )
        else:
            if (
                using_production_controller
                and not isinstance(
                    arena_volume_lifecycle,
                    DockerArenaVolumeLifecycle,
                )
            ):
                raise ContainerContractError(
                    "production controller rejects a substituted Arena "
                    "volume lifecycle"
                )
            for method in (
                "prepare",
                "rehydrate",
                "reconcile_incomplete",
                "reopen_preparation_after_teardown",
                "recover_teardown",
                "teardown",
            ):
                if not callable(
                    getattr(arena_volume_lifecycle, method, None)
                ):
                    raise ContainerContractError(
                        "Arena volume lifecycle is incomplete"
                    )
            self._arena_volume_lifecycle = arena_volume_lifecycle
        for label, factory in (
            ("Arena session factory", self._arena_session_factory),
            ("Arena server factory", self._arena_server_factory),
            ("Arena client factory", self._arena_client_factory),
            ("app-server controller factory", self._controller_factory),
            ("proposer bridge client factory", self._bridge_client_factory),
        ):
            if not callable(factory):
                raise ContainerContractError(f"{label} must be callable")
        self._attempts: dict[str, _AdapterRuntime] = {}
        self._attempt_controller_canaries: dict[str, tuple[Any, ...]] = {}
        self._attempt_canary_plantings: dict[
            str, canary_operator_contract.CanaryPlanting
        ] = {}
        self._lock = threading.RLock()

    @staticmethod
    def _canary_storage_root(spec: Any, *, reveal: bool) -> Path:
        generation = Path(_runner_field(spec, "generation_dir"))
        if (
            generation.name != _runner_field(spec, "generation_id")
            or generation.parent.name != "generations"
        ):
            raise ContainerContractError(
                "canary storage cannot derive the canonical campaign root"
            )
        campaign_root = generation.parent.parent
        selected = campaign_root / (
            "containment_canary_reveals"
            if reveal
            else "containment_canary_escrow"
        )
        if selected.exists() or selected.is_symlink():
            _validate_private_host_directory(selected)
        else:
            selected.mkdir(mode=0o700)
            _fsync_directory_path(campaign_root)
            _validate_private_host_directory(selected)
        return selected

    @staticmethod
    def _canary_commitment_documents(
        canaries: tuple[Any, ...],
    ) -> list[dict[str, str]]:
        return [
            item.commitment()
            for item in sorted(
                canaries, key=lambda item: item.category
            )
        ]

    @staticmethod
    def _canary_placement_documents(
        canaries: tuple[Any, ...],
    ) -> list[dict[str, str]]:
        return [
            {
                "category": item.category,
                "location_name": item.location_name,
                "provenance": item.provenance,
            }
            for item in sorted(
                canaries, key=lambda item: item.category
            )
        ]

    def _ensure_canary_escrow(self, spec: Any) -> tuple[Any, ...]:
        """Persist host-only values for crash recovery, not cryptographic secrecy.

        The trusted host owns the 0700 parent and 0400 regular file.  The
        directory is outside every generation, input, evidence, and mounted
        controller/proposer root; this is an access-boundary escrow, not
        encryption at rest.
        """
        import arc_agi3_contiguous_taint as taint_contract

        attempt_id = _runner_field(spec, "attempt_id")
        cached = self._attempt_controller_canaries.get(attempt_id)
        if cached is not None:
            return cached
        path = (
            self._canary_storage_root(spec, reveal=False)
            / f"{_runner_field(spec, 'generation_id')}.json"
        )
        attempt_spec_sha256 = (
            _runner_contract().proposer_attempt_binding_sha256(spec)
        )
        if path.exists() or path.is_symlink():
            metadata = path.stat(follow_symlinks=False)
            value = _read_unaliased_json(
                path, label="controller canary escrow"
            )
            if (
                metadata.st_uid != os.getuid()
                or stat.S_IMODE(metadata.st_mode) != 0o400
                or set(value)
                != {
                    "schema",
                    "kind",
                    "campaign_id",
                    "generation_id",
                    "attempt_id",
                    "attempt_spec_sha256",
                    "storage_policy",
                    "canary_commitments",
                    "planting_receipt_path",
                    "planting_receipt_sha256",
                    "placement_descriptors_json",
                    "placement_descriptors_sha256",
                    "host_only_canary_escrow",
                }
                or value.get("schema") != 1
                or value.get("kind")
                != "contiguous_controller_canary_escrow"
                or value.get("campaign_id")
                != _runner_field(spec, "campaign_id")
                or value.get("generation_id")
                != _runner_field(spec, "generation_id")
                or value.get("attempt_id") != attempt_id
                or value.get("attempt_spec_sha256")
                != attempt_spec_sha256
                or value.get("storage_policy")
                != "host_only_never_mounted"
                or not isinstance(
                    value.get("canary_commitments"), list
                )
                or not isinstance(
                    value.get("placement_descriptors_json"), str
                )
                or not _is_hex_sha256(
                    value.get("placement_descriptors_sha256")
                )
                or hashlib.sha256(
                    value["placement_descriptors_json"].encode(
                        "ascii"
                    )
                ).hexdigest()
                != value["placement_descriptors_sha256"]
            ):
                raise ContainerContractError(
                    "controller canary escrow is malformed or substituted"
                )
            expected_rows = tuple(
                (
                    row.get("category"),
                    row.get("location_name"),
                    row.get("provenance"),
                    row.get("commitment_sha256"),
                )
                for row in value["canary_commitments"]
                if isinstance(row, dict)
            )
            try:
                recovered = taint_contract.validate_live_canary_reveal(
                    value.get("host_only_canary_escrow"),
                    expected_commitments=expected_rows,
                )
            except Exception as exc:
                raise ContainerContractError(
                    "controller canary escrow reveal is invalid"
                ) from exc
            if (
                self._canary_commitment_documents(recovered)
                != value["canary_commitments"]
            ):
                raise ContainerContractError(
                    "controller canary escrow commitments differ"
                )
            operator = getattr(self, "_canary_operator", None)
            if operator is not None:
                try:
                    planting = (
                        canary_operator_contract.CanaryPlanting(
                            canaries=recovered,
                            receipt_path=value["planting_receipt_path"],
                            receipt_sha256=value[
                                "planting_receipt_sha256"
                            ],
                            placement_descriptors_json=value[
                                "placement_descriptors_json"
                            ],
                            placement_descriptors_sha256=value[
                                "placement_descriptors_sha256"
                            ],
                        )
                    )
                    try:
                        operator.verify(spec, planting)
                    except Exception:
                        reveal_path = (
                            self._canary_storage_root(
                                spec, reveal=True
                            )
                            / (
                                f"{_runner_field(spec, 'generation_id')}"
                                ".json"
                            )
                        )
                        if not (
                            reveal_path.exists()
                            and not reveal_path.is_symlink()
                        ):
                            raise
                        reveal_sha256 = (
                            _hash_unaliased_regular_file(
                                reveal_path,
                                label=(
                                    "terminal canary reveal for "
                                    "planting recovery"
                                ),
                            )
                        )
                        operator.cleanup(
                            spec,
                            planting,
                            reveal_path=str(reveal_path),
                            reveal_sha256=reveal_sha256,
                        )
                        operator.verify_cleanup(
                            spec,
                            planting,
                            reveal_path=str(reveal_path),
                            reveal_sha256=reveal_sha256,
                        )
                except Exception as exc:
                    raise ContainerContractError(
                        "controller canary planting changed after restart"
                    ) from exc
                self._attempt_canary_plantings[attempt_id] = planting
            elif (
                value["planting_receipt_path"] is not None
                or value["planting_receipt_sha256"] is not None
            ):
                raise ContainerContractError(
                    "controller canary planting has no formal operator"
                )
            self._attempt_controller_canaries[attempt_id] = recovered
            return recovered

        operator = getattr(self, "_canary_operator", None)
        if operator is not None:
            try:
                planting = operator.provision(spec)
                normalized = operator.verify(spec, planting)
            except Exception as exc:
                raise ContainerContractError(
                    "formal containment-canary planting failed"
                ) from exc
            planting_receipt_path: str | None = planting.receipt_path
            planting_receipt_sha256: str | None = (
                planting.receipt_sha256
            )
            placement_descriptors_json = (
                planting.placement_descriptors_json
            )
            placement_descriptors_sha256 = (
                planting.placement_descriptors_sha256
            )
            self._attempt_canary_plantings[attempt_id] = planting
        else:
            normalized = taint_contract.validate_live_canaries(
                self._controller_state_canaries
            )
            planting_receipt_path = None
            planting_receipt_sha256 = None
            placement_descriptors_json = (
                _canonical_json_bytes(
                    self._canary_placement_documents(normalized)
                ).decode("ascii")
            )
            placement_descriptors_sha256 = hashlib.sha256(
                placement_descriptors_json.encode("ascii")
            ).hexdigest()
        value = {
            "schema": 1,
            "kind": "contiguous_controller_canary_escrow",
            "campaign_id": _runner_field(spec, "campaign_id"),
            "generation_id": _runner_field(spec, "generation_id"),
            "attempt_id": attempt_id,
            "attempt_spec_sha256": attempt_spec_sha256,
            "storage_policy": "host_only_never_mounted",
            "canary_commitments":
                self._canary_commitment_documents(normalized),
            "planting_receipt_path": planting_receipt_path,
            "planting_receipt_sha256": planting_receipt_sha256,
            "placement_descriptors_json":
                placement_descriptors_json,
            "placement_descriptors_sha256":
                placement_descriptors_sha256,
            "host_only_canary_escrow":
                taint_contract.build_live_canary_reveal(normalized),
        }
        _write_private_json_new(path, value)
        os.chmod(path, 0o400, follow_symlinks=False)
        _fsync_private_parent(path)
        self._attempt_controller_canaries[attempt_id] = normalized
        return normalized

    def _ensure_canary_anchor(
        self, spec: Any
    ) -> CanaryEscrowAnchor:
        """Reopen one escrow descriptor-safely and derive its prelaunch anchor."""

        canaries = self._ensure_canary_escrow(spec)
        path = (
            self._canary_storage_root(spec, reveal=False)
            / f"{_runner_field(spec, 'generation_id')}.json"
        )
        raw, metadata = _read_unaliased_bytes_with_identity(
            path,
            label="controller canary escrow",
            maximum_bytes=MAX_INSPECT_BYTES,
        )
        if (
            metadata.st_uid != os.getuid()
            or metadata.st_nlink != 1
            or stat.S_IMODE(metadata.st_mode) != 0o400
        ):
            raise ContainerContractError(
                "controller canary escrow identity is unsafe"
            )
        escrow_sha256 = hashlib.sha256(raw).hexdigest()
        identity_sha256 = _canary_escrow_identity_sha256(
            path, metadata, escrow_sha256
        )
        commitments_json = _canonical_json_bytes(
            self._canary_commitment_documents(canaries)
        ).decode("ascii")
        try:
            escrow_document = json.loads(raw)
            placements_json = escrow_document[
                "placement_descriptors_json"
            ]
            placement_descriptors_sha256 = escrow_document[
                "placement_descriptors_sha256"
            ]
        except (UnicodeError, json.JSONDecodeError, KeyError) as exc:
            raise ContainerContractError(
                "controller canary escrow placement binding is malformed"
            ) from exc
        anchor = CanaryEscrowAnchor(
            escrow_path=str(path),
            escrow_sha256=escrow_sha256,
            escrow_identity_sha256=identity_sha256,
            commitments_json=commitments_json,
            commitments_sha256=hashlib.sha256(
                commitments_json.encode("ascii")
            ).hexdigest(),
            placement_descriptors_json=placements_json,
            placement_descriptors_sha256=
                placement_descriptors_sha256,
        )
        anchor.validate()
        return anchor

    def _ensure_terminal_canary_reveal(
        self,
        *,
        spec: Any,
        prepared: Any,
        controller_state_scan_receipt_path: str,
        controller_state_scan_receipt_sha256: str,
        retained_canary_scan_receipt_path: str,
        retained_canary_scan_receipt_sha256: str,
        container_id: str,
        controller_container_id: str,
        egress_proxy_container_id: str,
        container_proof_sha256: str,
    ) -> tuple[str, str]:
        """Publish the escrowed values only after every runtime is absent."""

        import arc_agi3_contiguous_taint as taint_contract

        canaries = self._ensure_canary_escrow(spec)
        runner_contract = _runner_contract()
        if not isinstance(
            prepared, runner_contract.BackendPreparation
        ):
            raise ContainerContractError(
                "terminal canary reveal lacks its journaled preparation"
            )
        anchored = CanaryEscrowAnchor(
            escrow_path=prepared.controller_canary_escrow_path,
            escrow_sha256=prepared.controller_canary_escrow_sha256,
            escrow_identity_sha256=(
                prepared.controller_canary_escrow_identity_sha256
            ),
            commitments_json=(
                prepared.controller_canary_commitments_json
            ),
            commitments_sha256=(
                prepared.controller_canary_commitments_sha256
            ),
            placement_descriptors_json=(
                prepared
                .controller_canary_placement_descriptors_json
            ),
            placement_descriptors_sha256=(
                prepared
                .controller_canary_placement_descriptors_sha256
            ),
        )
        anchored.validate()
        if self._ensure_canary_anchor(spec) != anchored:
            raise ContainerContractError(
                "terminal canary reveal differs from the prelaunch anchor"
            )
        state_scan_path = Path(controller_state_scan_receipt_path)
        retained_scan_path = Path(retained_canary_scan_receipt_path)
        if (
            _hash_unaliased_regular_file(
                state_scan_path, label="controller state scan receipt"
            )
            != controller_state_scan_receipt_sha256
            or _hash_unaliased_regular_file(
                retained_scan_path, label="retained canary scan receipt"
            )
            != retained_canary_scan_receipt_sha256
        ):
            raise ContainerContractError(
                "canary reveal scan receipts changed before publication"
            )
        state_scan_receipt = _read_unaliased_json(
            state_scan_path, label="controller state scan receipt"
        )
        retained_scan_receipt = _read_unaliased_json(
            retained_scan_path, label="retained canary scan receipt"
        )
        state_scan = state_scan_receipt.get("controller_state_scan")
        retained_scan = retained_scan_receipt.get(
            "retained_canary_scan"
        )
        commitments = json.loads(anchored.commitments_json)
        if (
            not isinstance(state_scan, dict)
            or not isinstance(retained_scan, dict)
            or state_scan.get("canary_commitments") != commitments
            or retained_scan.get("canary_commitments") != commitments
            or state_scan.get("canary_occurrences") != 0
            or retained_scan.get("canary_occurrences") != 0
            or state_scan.get("status") != "CLEAN"
            or retained_scan.get("status") != "CLEAN"
        ):
            raise ContainerContractError(
                "canary reveal commitments do not match both clean scans"
            )
        host_root = Path(
            _runner_field(spec, "host_transcript_path")
        ).parent
        controller_absence_path = (
            host_root / "controller_absence_receipt.json"
        )
        controller_absence_receipt_sha256 = (
            _hash_unaliased_regular_file(
                controller_absence_path,
                label="terminal controller absence receipt",
            )
        )
        controller_absence = _read_unaliased_json(
            controller_absence_path,
            label="terminal controller absence receipt",
        )
        if (
            controller_absence.get("schema") != 1
            or controller_absence.get("kind")
            != "arc_agi3_controller_absence"
            or controller_absence.get("campaign_id")
            != _runner_field(spec, "campaign_id")
            or controller_absence.get("generation_id")
            != _runner_field(spec, "generation_id")
            or controller_absence.get("attempt_id")
            != _runner_field(spec, "attempt_id")
            or controller_absence.get("attempt_spec_sha256")
            != _runner_contract().proposer_attempt_binding_sha256(spec)
            or controller_absence.get("controller_container_id")
            != controller_container_id
            or controller_absence.get("egress_proxy_container_id")
            != egress_proxy_container_id
            or controller_absence.get("authoritative_identity")
            != "controller_container_cgroup"
            or any(
                controller_absence.get(name) is not True
                for name in (
                    "controller_inspect_absent",
                    "controller_identity_query_empty",
                    "controller_top_absent",
                    "controller_no_descendants",
                    "egress_proxy_inspect_absent",
                    "egress_proxy_identity_query_empty",
                    "egress_proxy_top_absent",
                    "egress_proxy_no_descendants",
                )
            )
        ):
            raise ContainerContractError(
                "terminal controller absence receipt is not authoritative"
            )
        identity = AttemptIdentity(
            campaign_id=_runner_field(spec, "campaign_id"),
            generation_id=_runner_field(spec, "generation_id"),
            attempt_id=_runner_field(spec, "attempt_id"),
            game=_runner_field(spec, "game"),
            target_level=_runner_field(spec, "target_level"),
        )
        identity.validate()
        if (
            not CONTAINER_ID_RE.fullmatch(container_id)
            or not CONTAINER_ID_RE.fullmatch(controller_container_id)
            or not CONTAINER_ID_RE.fullmatch(egress_proxy_container_id)
            or not self._backend._expect_absent(
                (
                    self._backend._docker,
                    "container",
                    "inspect",
                    container_id,
                ),
                label="terminal proposer inspection",
            )
            or not self._backend._expect_absent(
                (
                    self._backend._docker,
                    "container",
                    "top",
                    container_id,
                    "-eo",
                    "pid,ppid",
                ),
                label="terminal proposer process inventory",
            )
            or self._backend._identity_query(identity).stdout.strip()
        ):
            raise ContainerContractError(
                "terminal proposer identity is not absent"
            )
        for role, exact_id in (
            (CONTROLLER_ROLE, controller_container_id),
            (EGRESS_PROXY_ROLE, egress_proxy_container_id),
        ):
            if (
                not self._backend._expect_absent(
                    (
                        self._backend._docker,
                        "container",
                        "inspect",
                        exact_id,
                    ),
                    label=f"terminal {role} inspection",
                )
                or not self._backend._expect_absent(
                    (
                        self._backend._docker,
                        "container",
                        "top",
                        exact_id,
                        "-eo",
                        "pid,ppid",
                    ),
                    label=f"terminal {role} process inventory",
                )
            ):
                raise ContainerContractError(
                    f"terminal {role} identity is not absent"
                )
            query = self._backend._required(
                (
                    self._backend._docker,
                    "container",
                    "ls",
                    "--all",
                    "--quiet",
                    "--no-trunc",
                    "--filter",
                    f"label={LABEL_CAMPAIGN}={identity.campaign_id}",
                    "--filter",
                    f"label={LABEL_GENERATION}={identity.generation_id}",
                    "--filter",
                    f"label={LABEL_ATTEMPT}={identity.attempt_id}",
                    "--filter",
                    f"label={LABEL_ROLE}={role}",
                ),
                timeout_seconds=30,
                label=f"terminal {role} identity query",
            )
            if _parse_container_id_lines(
                query.stdout, label=f"terminal {role} identity query"
            ):
                raise ContainerContractError(
                    f"terminal {role} label identity is not absent"
                )
        probe_path = host_root / "probe_reconciliation_teardown.json"
        probe_reconciliation_receipt_sha256 = (
            _hash_unaliased_regular_file(
                probe_path,
                label="terminal probe reconciliation receipt",
            )
        )
        probe_reconciliation = _read_unaliased_json(
            probe_path,
            label="terminal probe reconciliation receipt",
        )
        _validate_probe_reconciliation_receipt(
            probe_reconciliation,
            labels=_attempt_probe_labels(spec),
            stage="teardown",
        )
        if self._probe_executor._query_attempt_probe_ids(
            _attempt_probe_labels(spec)
        ):
            raise ContainerContractError(
                "terminal workspace-probe identity is not absent"
            )
        expected_rows = tuple(
            (
                row["category"],
                row["location_name"],
                row["provenance"],
                row["commitment_sha256"],
            )
            for row in commitments
        )
        reveal = taint_contract.build_live_canary_reveal(canaries)
        taint_contract.validate_live_canary_reveal(
            reveal, expected_commitments=expected_rows
        )
        teardown_observation_sha256 = _json_sha256(
            {
                "container_proof_sha256": container_proof_sha256,
                "controller_absence_receipt_sha256":
                    controller_absence_receipt_sha256,
                "probe_reconciliation_receipt_sha256":
                    probe_reconciliation_receipt_sha256,
                "controller_container_id": controller_container_id,
                "egress_proxy_container_id":
                    egress_proxy_container_id,
                "all_exact_roles_absent": True,
            }
        )
        value = {
            "schema": 1,
            "kind": "contiguous_controller_canary_reveal",
            "campaign_id": _runner_field(spec, "campaign_id"),
            "generation_id": _runner_field(spec, "generation_id"),
            "attempt_id": _runner_field(spec, "attempt_id"),
            "attempt_spec_sha256":
                _runner_contract().proposer_attempt_binding_sha256(spec),
            "canary_escrow_sha256": anchored.escrow_sha256,
            "canary_escrow_identity_sha256":
                anchored.escrow_identity_sha256,
            "canary_commitments_sha256":
                anchored.commitments_sha256,
            "canary_placement_descriptors_sha256":
                anchored.placement_descriptors_sha256,
            "controller_container_id": controller_container_id,
            "egress_proxy_container_id": egress_proxy_container_id,
            "controller_absence_receipt_sha256":
                controller_absence_receipt_sha256,
            "controller_state_scan_receipt_sha256":
                controller_state_scan_receipt_sha256,
            "retained_canary_scan_receipt_sha256":
                retained_canary_scan_receipt_sha256,
            "canary_commitments": commitments,
            "reveal": reveal,
            "teardown_observation_sha256":
                teardown_observation_sha256,
        }
        path = (
            self._canary_storage_root(spec, reveal=True)
            / f"{_runner_field(spec, 'generation_id')}.json"
        )
        if path.exists() or path.is_symlink():
            metadata = path.stat(follow_symlinks=False)
            if (
                metadata.st_uid != os.getuid()
                or stat.S_IMODE(metadata.st_mode) != 0o400
                or _read_unaliased_json(
                    path, label="controller canary reveal"
                )
                != value
            ):
                raise ContainerContractError(
                    "controller canary reveal is stale or substituted"
                )
        else:
            _write_private_json_new(path, value)
            os.chmod(path, 0o400, follow_symlinks=False)
            _fsync_private_parent(path)
        return (
            str(path),
            _hash_unaliased_regular_file(
                path, label="controller canary reveal"
            ),
        )

    def _ensure_terminal_canary_cleanup(
        self,
        *,
        spec: Any,
        canary_reveal_path: str,
        canary_reveal_sha256: str,
    ) -> tuple[str | None, str | None]:
        """Remove formal host placements after the exact reveal is durable."""

        operator = getattr(self, "_canary_operator", None)
        if operator is None:
            return None, None
        attempt_id = _runner_field(spec, "attempt_id")
        planting = self._attempt_canary_plantings.get(attempt_id)
        if planting is None:
            raise ContainerContractError(
                "terminal canary cleanup lacks its formal planting"
            )
        try:
            cleanup = operator.cleanup(
                spec,
                planting,
                reveal_path=canary_reveal_path,
                reveal_sha256=canary_reveal_sha256,
            )
        except Exception as exc:
            raise ContainerContractError(
                "terminal containment-canary cleanup failed"
            ) from exc
        return cleanup.receipt_path, cleanup.receipt_sha256

    def _contain_arena_protocol_violation(
        self,
        *,
        spec: Any,
        runtime: _AdapterRuntime,
        event: Mapping[str, Any],
    ) -> None:
        """Immediately revoke every proposer-side mutation capability.

        The Arena server invokes this after durably logging the first rejected
        request and before returning an error to untrusted solver code.  The
        exact proposer cgroup is stopped (but retained for immutable log
        collection), and the only host bridge connection is revoked.  The
        app-server controller owns no solver workspace/export mount; it is
        allowed only to reach its structured terminal barrier so provider
        accounting remains exact, after which its normal containment path
        removes the controller and egress-proxy cgroups.
        """

        required = {
            "schema",
            "kind",
            "phase",
            "seq",
            "op",
            "ok",
            "error",
        }
        if (
            not isinstance(event, Mapping)
            or not required.issubset(event)
            or event.get("schema") != "arc-agi3-arena-rpc/v1"
            or event.get("kind") != "rpc"
            or event.get("phase") != "rejected"
            or event.get("ok") is not False
            or not isinstance(event.get("error"), str)
        ):
            raise ContainerContractError(
                "public-action protocol-invalid event is malformed"
            )
        frozen = json.loads(
            _canonical_json_bytes(dict(event)).decode("ascii")
        )
        digest = _json_sha256(frozen)
        with self._lock:
            if runtime.arena_protocol_violation is not None:
                if (
                    runtime.arena_protocol_violation != frozen
                    or runtime.arena_protocol_violation_sha256
                    != digest
                ):
                    raise ContainerContractError(
                        "public-action protocol-invalid identity changed"
                    )
                return
            if runtime.launched is None:
                raise ContainerContractError(
                    "public-action protocol-invalid event preceded exact "
                    "proposer launch"
                )
            runtime.arena_protocol_violation = frozen
            runtime.arena_protocol_violation_sha256 = digest
            bridge = runtime.bridge_client
        # Revoke the host half of the sole bridge first, then stop the exact
        # proposer cgroup.  Either operation failing is a containment fault;
        # no WIP/candidate publication path is subsequently admitted.
        try:
            if bridge is not None:
                bridge.close()
        finally:
            observation = self._backend.quiesce_orphan_for_containment(
                runtime.attestation,
                runtime.low_spec,
                graceful_seconds=0,
            )
        if not _is_hex_sha256(observation):
            raise ContainerContractError(
                "Arena protocol containment observation is malformed"
            )
        with self._lock:
            runtime.arena_protocol_containment_sha256 = observation

    def prepare(self, spec: Any) -> Any:
        """Create RPC endpoints and attest one unstarted exact container."""
        attempt_id = _canonical_uuid4(
            _runner_field(spec, "attempt_id"), label="attempt_id"
        )
        fingerprint = _runner_spec_fingerprint(spec)
        with self._lock:
            canary_anchor = self._ensure_canary_anchor(spec)
            cached = self._attempts.get(attempt_id)
            if cached is not None:
                self._require_same_adapter_spec(cached, fingerprint)
                if (
                    cached.low_spec.containment_canary_anchor
                    != canary_anchor
                ):
                    raise ContainerContractError(
                        "cached attempt canary anchor changed"
                    )
                _require_file_hash(
                    Path(cached.preparation.launch_attestation_path),
                    cached.preparation.launch_attestation_sha256,
                    label="cached launch attestation",
                )
                return cached.preparation
            durable_attestation = _expected_attestation_path(spec)
            if durable_attestation.exists() or durable_attestation.is_symlink():
                runtime = self._rehydrate_orphan(
                    spec,
                    prepared=None,
                    launched=None,
                )
                self._attempts[attempt_id] = runtime
                return runtime.preparation
            low_spec = validate_runner_attempt_contract(
                spec,
                containment_canary_anchor=canary_anchor,
            )
            # A host crash may happen after Docker created the relay volume
            # but before any host evidence path exists.  Exact labelled
            # Docker reconciliation therefore runs on every fresh prepare,
            # independently of host-path recovery.
            self._arena_volume_lifecycle.reconcile_incomplete(
                low_spec.identity
            )
            backend_owned_paths = (
                Path(_runner_field(spec, "arena_socket_path")),
                Path(_runner_field(spec, "arena_token_file_path")),
                Path(_runner_field(spec, "bridge_socket_path")),
                Path(_runner_field(spec, "bridge_token_file_path")),
                Path(_runner_field(spec, "host_transcript_path")),
                Path(_runner_field(spec, "app_server_transcript_path")),
                Path(_runner_field(spec, "bridge_policy_receipt_path")),
                Path(_runner_field(spec, "host_transcript_path")).parent
                / "arena_session_binding_receipt.json",
                Path(_runner_field(spec, "host_transcript_path")).parent
                / "neutral_cwd_attestation.json",
                Path(_runner_field(spec, "host_transcript_path")).parent
                / "app_server_config_receipt.json",
                Path(_runner_field(spec, "host_transcript_path")).parent
                / "codex_binary_receipt.json",
                Path(_runner_field(spec, "host_transcript_path")).parent
                / "app_server_protocol_schema_receipt.json",
                Path(_runner_field(spec, "host_transcript_path")).parent
                / "arena_volume_readiness.json",
                Path(_runner_field(spec, "host_transcript_path")).parent
                / "arena_volume_preparation.json",
                Path(_runner_field(spec, "host_transcript_path")).parent
                / "arena_volume_teardown.json",
            )
            if any(path.exists() or path.is_symlink()
                   for path in backend_owned_paths):
                self._recover_incomplete_preparation(spec)

            token = secrets.token_hex(32)
            token_path = Path(_runner_field(spec, "arena_token_file_path"))
            socket_path = Path(_runner_field(spec, "arena_socket_path"))
            bridge_token_path = Path(
                _runner_field(spec, "bridge_token_file_path")
            )
            bridge_socket_path = Path(
                _runner_field(spec, "bridge_socket_path")
            )
            transcript_path = Path(_runner_field(spec, "host_transcript_path"))
            attestation_path = transcript_path.parent / (
                "launch_attestation.json"
            )
            session: Any | None = None
            server: Any | None = None
            thread: Any | None = None
            arena_volume_runtime: ArenaVolumeRuntime | None = None
            attestation: LaunchAttestation | None = None
            static_receipts: dict[str, tuple[str, str]] = {}
            runtime_holder: dict[str, _AdapterRuntime] = {}
            try:
                parent_checkpoint, parent_path = (
                    _load_exact_parent_checkpoint(spec)
                )
                arena_binding = _arena_session_binding(
                    spec, parent_level=parent_checkpoint.reached
                )
                session = self._arena_session_factory(
                    low_spec.identity.game,
                    binding=arena_binding,
                    parent_path=parent_path,
                    token=token,
                )
                arena_binding_event = _validate_arena_binding_event(
                    session, spec=spec, parent_path=parent_path
                )
                static_receipts = _prepare_static_receipts(
                    spec,
                    arena_binding_event=arena_binding_event,
                )
                _write_private_token(token_path, token)
                _write_private_token(
                    bridge_token_path, secrets.token_hex(32)
                )
                if getattr(session, "token", None) != token:
                    raise ContainerContractError(
                        "Arena session did not retain the backend-owned token"
                    )
                server = self._arena_server_factory(
                    session, socket_path, transcript_path
                )
                callback_setter = getattr(
                    server,
                    "set_protocol_violation_callback",
                    None,
                )
                if callable(callback_setter):
                    callback_setter(
                        lambda event: (
                            self._contain_arena_protocol_violation(
                                spec=spec,
                                runtime=runtime_holder["runtime"],
                                event=event,
                            )
                        )
                    )
                elif self._arena_server_factory is _default_arena_server:
                    raise ContainerContractError(
                        "production Arena server lacks protocol-invalid "
                        "containment"
                    )
                thread = server.start_thread()
                if not _thread_is_alive(thread):
                    raise ContainerContractError(
                        "Arena RPC thread did not remain live for launch"
                    )
                arena_volume_runtime = (
                    self._arena_volume_lifecycle.prepare(
                        identity=low_spec.identity,
                        transport=_runner_field(
                            spec, "proposer_transport"
                        ),
                        arena_socket=socket_path,
                        receipt_root=transcript_path.parent,
                    )
                )
                attestation = self._backend.build_launch_attestation(low_spec)
                self._backend.write_attestation(
                    attestation_path, attestation
                )
                runner_contract = _runner_contract()
                prepared_transport = _runner_field(
                    spec, "proposer_transport"
                )
                arena_volume_evidence = (
                    arena_volume_runtime.evidence
                )
                preparation = runner_contract.BackendPreparation(
                    preparation_id=_preparation_id(
                        attestation,
                        canary_anchor,
                        arena_volume_evidence,
                    ),
                    launch_attestation_path=str(attestation_path),
                    launch_attestation_sha256=attestation.document_sha256,
                    observed_image_digest=attestation.image.manifest_digest,
                    image_observation_sha256=(
                        attestation.image.observation_sha256
                    ),
                    container_observation_sha256=(
                        attestation.container_observation_sha256
                    ),
                    bridge_policy_receipt_path=(
                        static_receipts["bridge_policy"][0]
                    ),
                    bridge_policy_receipt_sha256=(
                        static_receipts["bridge_policy"][1]
                    ),
                    arena_session_binding_receipt_path=(
                        static_receipts["arena_binding"][0]
                    ),
                    arena_session_binding_receipt_sha256=(
                        static_receipts["arena_binding"][1]
                    ),
                    arena_transport=(
                        arena_volume_evidence.transport
                    ),
                    arena_volume_name=(
                        arena_volume_evidence.volume_name
                    ),
                    arena_volume_observation_sha256=(
                        arena_volume_evidence
                        .volume_observation_sha256
                    ),
                    arena_relay_container_id=(
                        arena_volume_evidence.relay_container_id
                    ),
                    arena_relay_image_digest=(
                        arena_volume_evidence.relay_image_digest
                    ),
                    arena_relay_image_observation_sha256=(
                        arena_volume_evidence
                        .relay_image_observation_sha256
                    ),
                    arena_relay_container_observation_sha256=(
                        arena_volume_evidence
                        .relay_container_observation_sha256
                    ),
                    arena_relay_readiness_receipt_path=(
                        arena_volume_evidence
                        .readiness_receipt_path
                    ),
                    arena_relay_readiness_receipt_sha256=(
                        arena_volume_evidence
                        .readiness_receipt_sha256
                    ),
                    arena_relay_attach_argv_sha256=(
                        arena_volume_evidence.attach_argv_sha256
                    ),
                    arena_relay_socket_identity_sha256=(
                        arena_volume_evidence
                        .arena_socket_identity_sha256
                    ),
                    arena_relay_preparation_receipt_path=(
                        arena_volume_evidence
                        .preparation_receipt_path
                    ),
                    arena_relay_preparation_receipt_sha256=(
                        arena_volume_evidence
                        .preparation_receipt_sha256
                    ),
                    probe_isolation_mode=arena_binding_event[
                        "probe_isolation_mode"
                    ],
                    probe_isolation_evidence_sha256=(
                        arena_binding_event[
                            "probe_isolation_evidence_sha256"
                        ]
                    ),
                    neutral_cwd_attestation_path=(
                        static_receipts["neutral_cwd"][0]
                    ),
                    neutral_cwd_attestation_sha256=(
                        static_receipts["neutral_cwd"][1]
                    ),
                    app_server_config_receipt_path=(
                        static_receipts["app_server_config"][0]
                    ),
                    app_server_config_receipt_sha256=(
                        static_receipts["app_server_config"][1]
                    ),
                    codex_binary_receipt_path=(
                        static_receipts["codex_binary"][0]
                    ),
                    codex_binary_receipt_sha256=(
                        static_receipts["codex_binary"][1]
                    ),
                    protocol_schema_receipt_path=(
                        static_receipts["protocol_schema"][0]
                    ),
                    protocol_schema_receipt_sha256=(
                        static_receipts["protocol_schema"][1]
                    ),
                    controller_image_digest=(
                        prepared_transport.controller_image_digest
                    ),
                    controller_egress_proxy_image_digest=(
                        prepared_transport
                        .controller_egress_proxy_image_digest
                    ),
                    controller_egress_policy_sha256=(
                        prepared_transport
                        .controller_egress_policy_sha256
                    ),
                    controller_canary_escrow_path=(
                        canary_anchor.escrow_path
                    ),
                    controller_canary_escrow_sha256=(
                        canary_anchor.escrow_sha256
                    ),
                    controller_canary_escrow_identity_sha256=(
                        canary_anchor.escrow_identity_sha256
                    ),
                    controller_canary_commitments_json=(
                        canary_anchor.commitments_json
                    ),
                    controller_canary_commitments_sha256=(
                        canary_anchor.commitments_sha256
                    ),
                    controller_canary_placement_descriptors_json=(
                        canary_anchor.placement_descriptors_json
                    ),
                    controller_canary_placement_descriptors_sha256=(
                        canary_anchor.placement_descriptors_sha256
                    ),
                    controller_supply_chain_unobserved_until_launch=True,
                )
                runtime = _AdapterRuntime(
                    spec_fingerprint=fingerprint,
                    low_spec=low_spec,
                    attestation=attestation,
                    preparation=preparation,
                    arena_session=session,
                    arena_server=server,
                    arena_thread=thread,
                    arena_volume_runtime=arena_volume_runtime,
                )
                runtime_holder["runtime"] = runtime
                self._attempts[attempt_id] = runtime
                return preparation
            except BaseException as original:
                cleanup_errors: list[str] = []
                if attestation is not None:
                    try:
                        self._backend.teardown(
                            attestation,
                            cause=TeardownCause.CONTAINMENT_FAULT,
                        )
                    except BaseException as exc:
                        cleanup_errors.append(
                            f"container cleanup failed: {type(exc).__name__}"
                        )
                if arena_volume_runtime is not None:
                    try:
                        self._arena_volume_lifecycle.teardown(
                            identity=low_spec.identity,
                            runtime=arena_volume_runtime,
                            receipt_root=transcript_path.parent,
                            containment_fault=True,
                        )
                    except BaseException as exc:
                        cleanup_errors.append(
                            "Arena relay cleanup failed: "
                            + type(exc).__name__
                        )
                try:
                    _finish_arena_server(
                        session=session,
                        server=server,
                        thread=thread,
                        socket_path=socket_path,
                        client_factory=self._arena_client_factory,
                    )
                except BaseException as exc:
                    cleanup_errors.append(
                        f"RPC cleanup failed: {type(exc).__name__}"
                    )
                for path, label in (
                    (socket_path, "Arena socket"),
                    (token_path, "Arena token"),
                    (bridge_socket_path, "proposer bridge socket"),
                    (bridge_token_path, "proposer bridge token"),
                    (transcript_path, "host transcript"),
                    (attestation_path, "launch attestation"),
                    (
                        Path(_runner_field(
                            spec, "bridge_policy_receipt_path"
                        )),
                        "bridge policy receipt",
                    ),
                    (
                        transcript_path.parent
                        / "arena_session_binding_receipt.json",
                        "Arena session binding receipt",
                    ),
                    (
                        transcript_path.parent
                        / "neutral_cwd_attestation.json",
                        "neutral cwd attestation",
                    ),
                    (
                        transcript_path.parent
                        / "app_server_config_receipt.json",
                        "app-server config receipt",
                    ),
                    (
                        transcript_path.parent
                        / "codex_binary_receipt.json",
                        "Codex binary receipt",
                    ),
                    (
                        transcript_path.parent
                        / "app_server_protocol_schema_receipt.json",
                        "app-server protocol schema receipt",
                    ),
                    (
                        transcript_path.parent
                        / "arena_volume_readiness.json",
                        "Arena relay readiness receipt",
                    ),
                    (
                        transcript_path.parent
                        / "arena_volume_preparation.json",
                        "Arena relay preparation receipt",
                    ),
                    (
                        transcript_path.parent
                        / "arena_volume_teardown.json",
                        "Arena relay teardown receipt",
                    ),
                ):
                    try:
                        _unlink_owned_attempt_file(path, label=label)
                    except BaseException as exc:
                        cleanup_errors.append(
                            f"{label} cleanup failed: {type(exc).__name__}"
                        )
                if cleanup_errors:
                    raise ContainerContractError(
                        "attempt preparation failed and cleanup was incomplete: "
                        + "; ".join(cleanup_errors)
                    ) from original
                raise

    def _recover_incomplete_preparation(self, spec: Any) -> None:
        """Remove a pre-attestation crash remnant, then permit a fresh prepare."""
        if (
            _expected_attestation_path(spec).exists()
            or _expected_attestation_path(spec).is_symlink()
        ):
            raise ContainerContractError(
                "incomplete-preparation recovery cannot ignore an attestation"
            )
        low_spec = validate_runner_attempt_contract(
            spec,
            recovery=True,
            containment_canary_anchor=self._ensure_canary_anchor(spec),
        )
        self._arena_volume_lifecycle.reconcile_incomplete(
            low_spec.identity
        )
        _snapshot_mount_root(
            low_spec.export_root,
            label="incomplete preparation output",
            require_empty=True,
            require_private=True,
        )
        query = self._backend._identity_query(low_spec.identity)
        identities = _parse_container_id_lines(
            query.stdout, label="incomplete preparation identity query"
        )
        if identities:
            cleanup_error = self._backend._emergency_remove_identity(
                low_spec.identity
            )
            if cleanup_error is not None:
                raise ContainerContractError(
                    "incomplete preparation container cleanup failed: "
                    + cleanup_error
                )
        for path, label in (
            (low_spec.arena_socket, "stale Arena socket"),
            (low_spec.arena_token_file, "stale Arena token"),
            (low_spec.bridge_socket, "stale proposer bridge socket"),
            (low_spec.bridge_token_file, "stale proposer bridge token"),
            (
                Path(_runner_field(spec, "host_transcript_path")),
                "stale host transcript",
            ),
            (
                Path(_runner_field(spec, "app_server_transcript_path")),
                "stale app-server transcript",
            ),
            (
                Path(_runner_field(spec, "bridge_policy_receipt_path")),
                "stale bridge policy receipt",
            ),
            (
                Path(_runner_field(spec, "host_transcript_path")).parent
                / "arena_session_binding_receipt.json",
                "stale Arena session binding receipt",
            ),
            (
                Path(_runner_field(spec, "host_transcript_path")).parent
                / "neutral_cwd_attestation.json",
                "stale neutral cwd attestation",
            ),
            (
                Path(_runner_field(spec, "host_transcript_path")).parent
                / "app_server_config_receipt.json",
                "stale app-server config receipt",
            ),
            (
                Path(_runner_field(spec, "host_transcript_path")).parent
                / "codex_binary_receipt.json",
                "stale Codex binary receipt",
            ),
            (
                Path(_runner_field(spec, "host_transcript_path")).parent
                / "app_server_protocol_schema_receipt.json",
                "stale protocol schema receipt",
            ),
            (
                Path(_runner_field(spec, "host_transcript_path")).parent
                / "arena_volume_readiness.json",
                "stale Arena relay readiness receipt",
            ),
            (
                Path(_runner_field(spec, "host_transcript_path")).parent
                / "arena_volume_preparation.json",
                "stale Arena relay preparation receipt",
            ),
            (
                Path(_runner_field(spec, "host_transcript_path")).parent
                / "arena_volume_teardown.json",
                "stale Arena relay teardown receipt",
            ),
        ):
            _unlink_owned_attempt_file(path, label=label)

    def _wait_for_bridge_socket(
        self, runtime: _AdapterRuntime, *, timeout_seconds: float = 30.0
    ) -> EndpointObservation:
        deadline = time.monotonic() + timeout_seconds
        last_error: BaseException | None = None
        while time.monotonic() < deadline:
            try:
                return _snapshot_endpoint(
                    runtime.low_spec.bridge_socket,
                    label="proposer bridge socket",
                    expected_kind="socket",
                )
            except BaseException as exc:
                last_error = exc
                time.sleep(0.02)
        raise ContainerContractError(
            "proposer bridge socket did not appear within its hard bound"
        ) from last_error

    def _ensure_launch_intent(
        self, *, spec: Any, runtime: _AdapterRuntime
    ) -> str:
        path, digest = _ensure_bound_receipt(
            _expected_backend_launch_intent_path(spec),
            spec=spec,
            kind="contiguous_backend_launch_intent",
            fields={
                "preparation_id": runtime.preparation.preparation_id,
                "container_id": runtime.attestation.container_id,
                "launch_attestation_sha256":
                    runtime.attestation.document_sha256,
            },
        )
        if path != str(_expected_backend_launch_intent_path(spec)):
            raise ContainerContractError(
                "backend launch intent path drifted"
            )
        return digest

    def _prove_attempt_container_absence(
        self, runtime: _AdapterRuntime
    ) -> None:
        identity = runtime.low_spec.identity
        identities = _parse_container_id_lines(
            self._backend._identity_query(identity).stdout,
            label="failed-launch identity query",
        )
        expected_id = runtime.attestation.container_id
        if identities not in ((), (expected_id,)):
            raise ContainerContractError(
                "failed launch has an ambiguous container identity"
            )
        if identities:
            self._backend.teardown(
                runtime.launched or runtime.attestation,
                cause=TeardownCause.CONTAINMENT_FAULT,
            )
        inspect_absent = self._backend._expect_absent(
            (
                self._backend._docker,
                "container",
                "inspect",
                expected_id,
            ),
            label="failed-launch container inspection",
        )
        top_absent = self._backend._expect_absent(
            (
                self._backend._docker,
                "container",
                "top",
                expected_id,
                "-eo",
                "pid,ppid",
            ),
            label="failed-launch process inventory",
        )
        identity_empty = not self._backend._identity_query(
            identity
        ).stdout.strip()
        if not (inspect_absent and top_absent and identity_empty):
            raise ContainerContractError(
                "failed launch container/cgroup absence was not proved"
            )

    def _load_partial_backend_launch(
        self, *, spec: Any, runtime: _AdapterRuntime
    ) -> Any | None:
        path = _expected_backend_launch_path(spec)
        if not (path.exists() or path.is_symlink()):
            return None
        value = _read_unaliased_json(
            path, label="partial durable backend launch"
        )
        expected_base = _bound_receipt_base(
            spec, kind="contiguous_backend_launch"
        )
        if (
            set(value) != {*expected_base, "launch"}
            or any(value.get(name) != field
                   for name, field in expected_base.items())
            or not isinstance(value.get("launch"), dict)
        ):
            raise ContainerContractError(
                "partial durable backend launch is malformed"
            )
        runner_contract = _runner_contract()
        try:
            launched = runner_contract.BackendLaunch(**value["launch"])
        except TypeError as exc:
            raise ContainerContractError(
                "partial durable backend launch schema drifted"
            ) from exc
        if (
            launched.container_id != runtime.attestation.container_id
            or launched.backend_id != runtime.attestation.container_id
        ):
            raise ContainerContractError(
                "partial durable backend launch changed container identity"
            )
        return launched

    def _validate_launch_failure_tombstone(
        self,
        *,
        spec: Any,
        runtime: _AdapterRuntime,
        intent_sha256: str,
    ) -> dict[str, Any] | None:
        path = _expected_backend_launch_failure_path(spec)
        if not (path.exists() or path.is_symlink()):
            return None
        value = _read_unaliased_json(
            path, label="backend launch-failure tombstone"
        )
        expected_base = _bound_receipt_base(
            spec, kind="contiguous_backend_launch_failure"
        )
        required = {
            *expected_base,
            "preparation_id",
            "container_id",
            "launch_intent_sha256",
            "failure_stage",
            "error_type",
            "container_inspect_absent",
            "container_top_absent",
            "identity_query_empty",
            "app_server_pid",
            "app_server_process_group_id",
            "app_server_process_absent",
            "app_server_process_group_absent",
            "rpc_thread_absent",
            "rpc_socket_absent",
            "rpc_token_absent",
            "bridge_socket_absent",
            "bridge_token_absent",
            "app_server_control_absent",
            "probe_reconciliation_receipt_sha256",
        }
        pid = value.get("app_server_pid")
        pgid = value.get("app_server_process_group_id")
        if (
            not isinstance(value, dict)
            or set(value) != required
            or any(value.get(name) != field
                   for name, field in expected_base.items())
            or value.get("preparation_id")
            != runtime.preparation.preparation_id
            or value.get("container_id")
            != runtime.attestation.container_id
            or value.get("launch_intent_sha256") != intent_sha256
            or _safe_probe_identifier(value.get("failure_stage"))
            != value.get("failure_stage")
            or _safe_probe_identifier(value.get("error_type"))
            != value.get("error_type")
            or (pid is None) != (pgid is None)
            or (
                pid is not None
                and (
                    isinstance(pid, bool)
                    or not isinstance(pid, int)
                    or pid <= 1
                    or isinstance(pgid, bool)
                    or not isinstance(pgid, int)
                    or pgid <= 1
                )
            )
            or not _is_hex_sha256(
                value.get("probe_reconciliation_receipt_sha256")
            )
            or any(
                value.get(name) is not True
                for name in (
                    "container_inspect_absent",
                    "container_top_absent",
                    "identity_query_empty",
                    "app_server_process_absent",
                    "app_server_process_group_absent",
                    "rpc_thread_absent",
                    "rpc_socket_absent",
                    "rpc_token_absent",
                    "bridge_socket_absent",
                    "bridge_token_absent",
                    "app_server_control_absent",
                )
            )
        ):
            raise ContainerContractError(
                "backend launch-failure tombstone is malformed"
            )
        self._prove_attempt_container_absence(runtime)
        if pid is not None and (
            not _host_process_absent(pid)
            or not _host_process_group_absent(pgid)
        ):
            raise ContainerContractError(
                "a tombstoned app-server process identity reappeared"
            )
        for endpoint in (
            runtime.low_spec.arena_socket,
            runtime.low_spec.arena_token_file,
            runtime.low_spec.bridge_socket,
            runtime.low_spec.bridge_token_file,
            Path(_runner_field(spec, "app_server_control_dir")),
        ):
            if endpoint.exists() or endpoint.is_symlink():
                raise ContainerContractError(
                    "a tombstoned launch endpoint reappeared"
                )
        probe = self._probe_executor.reconcile_attempt_probes(
            spec=spec, stage="teardown"
        )
        if (
            probe["receipt_sha256"]
            != value["probe_reconciliation_receipt_sha256"]
        ):
            raise ContainerContractError(
                "launch-failure probe reconciliation receipt changed"
            )
        return value

    def _reconcile_failed_launch(
        self,
        *,
        spec: Any,
        runtime: _AdapterRuntime,
        intent_sha256: str,
        failure_stage: str,
        original: BaseException,
    ) -> None:
        """Contain every launch-owned resource and persist a terminal tombstone."""
        if self._validate_launch_failure_tombstone(
            spec=spec,
            runtime=runtime,
            intent_sha256=intent_sha256,
        ) is not None:
            return
        cleanup_errors: list[str] = []
        teardown_evidence: Any | None = None
        process_absence_receipt_validated = False
        controller_thread = runtime.controller_thread
        if _thread_is_alive(controller_thread):
            try:
                if runtime.bridge_client is not None:
                    runtime.bridge_client.close()
            except BaseException as exc:
                cleanup_errors.append(
                    "bridge close failed: " + type(exc).__name__
                )
            controller_thread.join(timeout=15)
            if _thread_is_alive(controller_thread):
                cleanup_errors.append("controller thread remained live")
            else:
                teardown_evidence = runtime.controller_teardown_evidence
        elif runtime.controller is not None:
            try:
                teardown_evidence = runtime.controller.contain()
            except BaseException as exc:
                process = getattr(runtime.controller, "process", None)
                if process is not None:
                    cleanup_errors.append(
                        "app-server containment failed: "
                        + type(exc).__name__
                    )
        elif runtime.bridge_client is not None:
            try:
                runtime.bridge_client.close()
            except BaseException as exc:
                cleanup_errors.append(
                    "bridge close failed: " + type(exc).__name__
                )
        recovered_control_process: tuple[int, int] | None = None
        try:
            recovered_control_process = (
                _reconcile_orphan_app_server_process(spec)
            )
            if recovered_control_process is not None:
                process_absence_receipt_validated = True
        except BaseException as exc:
            cleanup_errors.append(
                "app-server process-receipt reconciliation failed: "
                + type(exc).__name__
            )
        pid: int | None = None
        pgid: int | None = None
        if teardown_evidence is not None:
            pid = getattr(teardown_evidence, "pid", None)
            pgid = getattr(teardown_evidence, "process_group_id", None)
            if (
                not isinstance(pid, int)
                or isinstance(pid, bool)
                or pid <= 1
                or not isinstance(pgid, int)
                or isinstance(pgid, bool)
                or pgid <= 1
                or getattr(teardown_evidence, "process_absent", None)
                is not True
                or getattr(
                    teardown_evidence, "process_group_absent", None
                )
                is not True
            ):
                cleanup_errors.append(
                    "app-server containment evidence was incomplete"
                )
            else:
                try:
                    _validate_controller_teardown_evidence(
                        teardown_evidence,
                        spec=spec,
                        preflight=runtime.preflight_evidence,
                    )
                    process_absence_receipt_validated = True
                except BaseException as exc:
                    cleanup_errors.append(
                        "app-server absence receipt validation failed: "
                        + type(exc).__name__
                    )
        elif recovered_control_process is not None:
            pid, pgid = recovered_control_process
        elif runtime.preflight_evidence is not None:
            pid = runtime.preflight_evidence.pid
            pgid = runtime.preflight_evidence.process_group_id
        else:
            partial = self._load_partial_backend_launch(
                spec=spec, runtime=runtime
            )
            if partial is not None:
                pid = partial.app_server_pid
                pgid = partial.app_server_process_group_id
            elif (
                runtime.controller is not None
                and getattr(runtime.controller, "process", None) is not None
            ):
                cleanup_errors.append(
                    "app-server process identity was not durably observed"
                )
        if pid is not None and (
            not _host_process_absent(pid)
            or not _host_process_group_absent(pgid)
        ):
            cleanup_errors.append(
                "app-server process or process group remained present"
            )
        try:
            self._prove_attempt_container_absence(runtime)
        except BaseException as exc:
            cleanup_errors.append(
                "container cleanup failed: " + type(exc).__name__
            )
        try:
            probe = self._probe_executor.reconcile_attempt_probes(
                spec=spec, stage="teardown"
            )
        except BaseException as exc:
            probe = None
            cleanup_errors.append(
                "probe cleanup failed: " + type(exc).__name__
            )
        try:
            _finish_arena_server(
                session=runtime.arena_session,
                server=runtime.arena_server,
                thread=runtime.arena_thread,
                socket_path=runtime.low_spec.arena_socket,
                client_factory=self._arena_client_factory,
            )
        except BaseException as exc:
            cleanup_errors.append(
                "Arena cleanup failed: " + type(exc).__name__
            )
        for endpoint, label in (
            (runtime.low_spec.arena_socket, "Arena socket"),
            (runtime.low_spec.arena_token_file, "Arena token"),
            (runtime.low_spec.bridge_socket, "proposer bridge socket"),
            (runtime.low_spec.bridge_token_file, "proposer bridge token"),
        ):
            try:
                _unlink_owned_attempt_file(endpoint, label=label)
            except BaseException as exc:
                cleanup_errors.append(
                    f"{label} cleanup failed: {type(exc).__name__}"
                )
        try:
            absence_path = (
                Path(_runner_field(spec, "app_server_control_dir"))
                / "process_absent.json"
            )
            if absence_path.exists() or absence_path.is_symlink():
                if not process_absence_receipt_validated:
                    raise ContainerContractError(
                        "unvalidated app-server absence receipt remains"
                    )
                _unlink_owned_attempt_file(
                    absence_path,
                    label="app-server process-absence receipt",
                )
            _remove_empty_owned_directory(
                Path(_runner_field(spec, "app_server_control_dir")),
                label="app-server control directory",
            )
        except BaseException as exc:
            cleanup_errors.append(
                "app-server control cleanup failed: "
                + type(exc).__name__
            )
        endpoint_absent = all(
            not path.exists() and not path.is_symlink()
            for path in (
                runtime.low_spec.arena_socket,
                runtime.low_spec.arena_token_file,
                runtime.low_spec.bridge_socket,
                runtime.low_spec.bridge_token_file,
                Path(_runner_field(spec, "app_server_control_dir")),
            )
        )
        if not endpoint_absent:
            cleanup_errors.append("launch endpoints remained present")
        if cleanup_errors or probe is None:
            raise ContainerContractError(
                "backend launch failed and exact reconciliation was "
                "incomplete: " + "; ".join(cleanup_errors)
            ) from original
        stage = (
            failure_stage
            if isinstance(failure_stage, str)
            and SAFE_PROBE_IDENTIFIER_RE.fullmatch(failure_stage)
            else "unknown-stage"
        )
        error_type = type(original).__name__
        if not SAFE_PROBE_IDENTIFIER_RE.fullmatch(error_type):
            error_type = "BackendError"
        fields = {
            "preparation_id": runtime.preparation.preparation_id,
            "container_id": runtime.attestation.container_id,
            "launch_intent_sha256": intent_sha256,
            "failure_stage": stage,
            "error_type": error_type,
            "container_inspect_absent": True,
            "container_top_absent": True,
            "identity_query_empty": True,
            "app_server_pid": pid,
            "app_server_process_group_id": pgid,
            "app_server_process_absent": True,
            "app_server_process_group_absent": True,
            "rpc_thread_absent": True,
            "rpc_socket_absent": True,
            "rpc_token_absent": True,
            "bridge_socket_absent": True,
            "bridge_token_absent": True,
            "app_server_control_absent": True,
            "probe_reconciliation_receipt_sha256":
                probe["receipt_sha256"],
        }
        _ensure_bound_receipt(
            _expected_backend_launch_failure_path(spec),
            spec=spec,
            kind="contiguous_backend_launch_failure",
            fields=fields,
        )
        self._validate_launch_failure_tombstone(
            spec=spec,
            runtime=runtime,
            intent_sha256=intent_sha256,
        )

    def _controller_turn_main(
        self, runtime: _AdapterRuntime, spec: Any
    ) -> None:
        final: Any | None = None
        teardown: Any | None = None
        error: BaseException | None = None
        try:
            final = runtime.controller.run_turn()
            _validate_turn_final_evidence(
                final,
                spec=spec,
                thread_id=runtime.backend_launch.codex_thread_id,
                turn_id=runtime.backend_launch.codex_turn_id,
            )
        except BaseException as exc:
            error = exc
        finally:
            try:
                teardown = runtime.controller.contain()
                _validate_controller_teardown_evidence(
                    teardown,
                    spec=spec,
                    preflight=runtime.preflight_evidence,
                )
            except BaseException as exc:
                if error is None:
                    error = exc
                try:
                    if runtime.bridge_client is not None:
                        runtime.bridge_client.close()
                except BaseException:
                    pass
        runtime.turn_final_evidence = final
        runtime.controller_teardown_evidence = teardown
        runtime.controller_error = error

    @staticmethod
    def _controller_binding(
        spec: Any,
        prepared: Any,
    ) -> probe_transport.ControllerBinding:
        return probe_transport.ControllerBinding(
            campaign_id=_runner_field(spec, "campaign_id"),
            generation_id=_runner_field(spec, "generation_id"),
            attempt_id=_runner_field(spec, "attempt_id"),
            generation_dir=_runner_field(spec, "generation_dir"),
            state_root=_runner_field(spec, "app_server_state_dir"),
            neutral_cwd=CONTROLLER_NEUTRAL_DESTINATION,
            neutral_host_cwd=_runner_field(
                spec, "neutral_host_cwd_path"
            ),
            model=_runner_field(spec, "proposer_transport").model,
            model_provider=(
                _runner_field(spec, "proposer_transport").model_provider
            ),
            reasoning_effort=_runner_field(spec, "effort"),
            thread_mode=_runner_field(spec, "thread_mode"),
            resume_thread_id=_runner_field(
                spec, "resume_thread_id"
            ),
            hard_safety_seconds=_runner_field(
                spec, "hard_safety_seconds"
            ),
            max_auth_refreshes=_runner_field(
                spec, "max_auth_refreshes"
            ),
            app_server_control_dir=_runner_field(
                spec, "app_server_control_dir"
            ),
            attempt_spec_sha256=(
                _runner_contract().proposer_attempt_binding_sha256(spec)
            ),
            controller_canary_escrow_path=(
                prepared.controller_canary_escrow_path
            ),
            controller_canary_escrow_sha256=(
                prepared.controller_canary_escrow_sha256
            ),
            controller_canary_escrow_identity_sha256=(
                prepared.controller_canary_escrow_identity_sha256
            ),
            controller_canary_commitments_json=(
                prepared.controller_canary_commitments_json
            ),
            controller_canary_commitments_sha256=(
                prepared.controller_canary_commitments_sha256
            ),
            controller_canary_placement_descriptors_json=(
                prepared.controller_canary_placement_descriptors_json
            ),
            controller_canary_placement_descriptors_sha256=(
                prepared
                .controller_canary_placement_descriptors_sha256
            ),
        )

    @staticmethod
    def _substrate_identity_sha256(spec: Any) -> str:
        """Hash the reusable controller substrate, not a retry UUID/path."""

        transport = _runner_field(spec, "proposer_transport")
        state_root = Path(_runner_field(spec, "app_server_state_dir"))
        metadata = state_root.stat(follow_symlinks=False)
        return _json_sha256({
            "schema": 1,
            "kind": "contiguous_controller_substrate_identity",
            "controller_image_digest":
                transport.controller_image_digest,
            "controller_egress_proxy_image_digest":
                transport.controller_egress_proxy_image_digest,
            "controller_egress_policy_sha256":
                transport.controller_egress_policy_sha256,
            "controller_user": transport.controller_user,
            "controller_entrypoint":
                list(transport.controller_entrypoint),
            "codex_launcher_sha256":
                transport.codex_launcher_sha256,
            "codex_binary_sha256": transport.codex_binary_sha256,
            "codex_binary_bytes": transport.codex_binary_bytes,
            "state_filesystem_device": metadata.st_dev,
            "state_owner_uid": metadata.st_uid,
            "state_owner_gid": metadata.st_gid,
            "state_mode": stat.S_IMODE(metadata.st_mode),
        })

    @staticmethod
    def _substrate_preflight_root(spec: Any) -> Path:
        return (
            Path(_runner_field(spec, "host_transcript_path")).parent
            / "substrate_preflight"
        )

    @classmethod
    def _substrate_preflight_spec(cls, spec: Any) -> Any:
        root = cls._substrate_preflight_root(spec)
        return replace(
            spec,
            host_transcript_path=str(root / "backend.jsonl"),
            app_server_transcript_path=str(root / "app_server.jsonl"),
            app_server_control_dir=str(root / "app_server_control"),
        )

    @classmethod
    def _substrate_preflight_artifact_paths(
        cls, spec: Any
    ) -> dict[str, Path]:
        host_root = Path(
            _runner_field(spec, "host_transcript_path")
        ).parent
        return {
            "intent": host_root / "substrate_preflight_intent.json",
            "success":
                host_root / "substrate_preflight_receipt.json",
            "failure":
                host_root
                / "substrate_preflight_failure_receipt.json",
            "partial_scan":
                host_root
                / "substrate_preflight_partial_scan_receipt.json",
            "success_scan":
                host_root
                / "substrate_preflight_scan_receipt.json",
            "purge":
                host_root
                / "substrate_preflight_purge_receipt.json",
            "runtime": cls._substrate_preflight_root(spec),
        }

    def _ensure_substrate_preflight_intent(
        self,
        *,
        spec: Any,
        substrate_identity_sha256: str,
    ) -> dict[str, Any]:
        paths = self._substrate_preflight_artifact_paths(spec)
        state_root = Path(
            _runner_field(spec, "app_server_state_dir")
        )
        wip = _runner_field(spec, "wip")
        prior_wip_tree_sha256 = (
            None
            if wip is None
            else _validated_tree_hash(
                Path(wip.wip_root_path),
                label="pre-substrate-failure clean WIP",
            )
        )
        if (
            wip is not None
            and prior_wip_tree_sha256 != wip.wip_tree_sha256
        ):
            raise ContainerContractError(
                "clean WIP changed before substrate preflight"
            )
        path = paths["intent"]
        if path.exists() or path.is_symlink():
            retained = _read_unaliased_json(
                path, label="substrate preflight intent"
            )
            expected_base = _bound_receipt_base(
                spec, kind="contiguous_substrate_preflight_intent"
            )
            required = {
                *expected_base,
                "substrate_identity_sha256",
                "preflight_root",
                "state_root",
                "initial_state_tree_sha256",
                "initial_state_inventory_sha256",
                "prior_clean_wip_tree_sha256",
                "proposer_container_started",
                "bridge_connected",
                "thread_started",
                "turn_started",
                "status",
            }
            if (
                set(retained) != required
                or any(
                    retained.get(name) != value
                    for name, value in expected_base.items()
                )
                or retained.get("substrate_identity_sha256")
                != substrate_identity_sha256
                or retained.get("preflight_root")
                != str(paths["runtime"])
                or retained.get("state_root") != str(state_root)
                or not _is_hex_sha256(
                    retained.get("initial_state_tree_sha256")
                )
                or not _is_hex_sha256(
                    retained.get(
                        "initial_state_inventory_sha256"
                    )
                )
                or retained.get("prior_clean_wip_tree_sha256")
                != prior_wip_tree_sha256
                or any(
                    retained.get(name) is not False
                    for name in (
                        "proposer_container_started",
                        "bridge_connected",
                        "thread_started",
                        "turn_started",
                    )
                )
                or retained.get("status") != "PENDING"
            ):
                raise ContainerContractError(
                    "substrate preflight intent changed"
                )
            return retained
        initial_state = (
            probe_transport.inventory_controller_state(state_root)
        )
        document = {
            **_bound_receipt_base(
                spec, kind="contiguous_substrate_preflight_intent"
            ),
            "substrate_identity_sha256":
                substrate_identity_sha256,
            "preflight_root": str(paths["runtime"]),
            "state_root": str(state_root),
            "initial_state_tree_sha256":
                initial_state.tree_sha256,
            "initial_state_inventory_sha256":
                initial_state.inventory_sha256,
            "prior_clean_wip_tree_sha256":
                prior_wip_tree_sha256,
            "proposer_container_started": False,
            "bridge_connected": False,
            "thread_started": False,
            "turn_started": False,
            "status": "PENDING",
        }
        _write_private_json_new(path, document)
        return document

    def _recover_substrate_preflight_controller(
        self,
        *,
        preflight_spec: Any,
        prepared: Any,
    ) -> tuple[str | None, str | None]:
        """Prove disposable controller roles absent after a lost mediator."""

        launcher = self._controller_container_launcher
        if not isinstance(
            launcher, DockerControllerContainerLauncher
        ):
            return None, None
        binding = self._controller_binding(
            preflight_spec, prepared
        )
        return launcher.recover_preflight_absence(
            binding=binding
        )

    def _finalize_substrate_failure_cleanup(
        self,
        *,
        spec: Any,
        prepared: Any,
        substrate_identity_sha256: str,
        failure_stage: str,
        error_type: str,
        failure_class: str,
        failure_code: str,
        live_credential_sentinels: Sequence[str] | None = None,
        controller_absence_receipt_path: str | None = None,
        controller_absence_receipt_sha256: str | None = None,
    ) -> tuple[str, str, str, str, str]:
        """Scan then purge every failed preflight-owned mutable byte.

        The scan receipt is intentionally retained outside the disposable
        runtime tree.  The state and preflight runtime roots are then purged
        descriptor-confined before a zero-cost infrastructure event can close
        the reservation.  A retained scan or purge receipt is reopened
        idempotently after a crash; no partial failed controller state can
        become WIP or candidate authority.
        """

        paths = self._substrate_preflight_artifact_paths(spec)
        intent = self._ensure_substrate_preflight_intent(
            spec=spec,
            substrate_identity_sha256=substrate_identity_sha256,
        )
        intent_sha256 = _hash_unaliased_regular_file(
            paths["intent"], label="substrate preflight intent"
        )
        preflight_root = paths["runtime"]
        state_root = Path(
            _runner_field(spec, "app_server_state_dir")
        )
        partial_scan_path = paths["partial_scan"]
        purge_path = paths["purge"]
        sentinels = tuple(sorted(set(
            live_credential_sentinels
            if live_credential_sentinels is not None
            else self._credentials.leak_sentinels
        )))
        if not sentinels or any(
            not isinstance(value, str) or not value
            for value in sentinels
        ):
            raise ContainerContractError(
                "substrate failure credential sentinel set is invalid"
            )
        if partial_scan_path.exists() or partial_scan_path.is_symlink():
            partial_scan = _read_unaliased_json(
                partial_scan_path,
                label="substrate failure partial scan receipt",
            )
            if (
                partial_scan.get("substrate_preflight_intent_sha256")
                != intent_sha256
                or partial_scan.get("substrate_identity_sha256")
                != substrate_identity_sha256
                or partial_scan.get("failure_class") != failure_class
                or partial_scan.get("failure_code") != failure_code
                or partial_scan.get("status") != "COMPLETE"
            ):
                raise ContainerContractError(
                    "retained substrate partial scan changed"
                )
        else:
            try:
                import arc_agi3_contiguous_taint as taint_contract

                canaries = self._ensure_canary_escrow(spec)
                state_inventory = (
                    probe_transport.inventory_controller_state(
                        state_root,
                        sentinels=sentinels,
                    )
                )
                state_scan = taint_contract.scan_controller_state(
                    state_root,
                    inventory=state_inventory,
                    canaries=canaries,
                )
                retained_roots = {}
                if (
                    preflight_root.exists()
                    and not preflight_root.is_symlink()
                ):
                    retained_roots["substrate_preflight_runtime"] = (
                        preflight_root
                    )
                retained_scan = (
                    taint_contract.scan_retained_canary_roots(
                        retained_roots,
                        canaries=canaries,
                    )
                    if retained_roots
                    else None
                )
                secret_roots = [state_root]
                if retained_roots:
                    secret_roots.append(preflight_root)
                secret_occurrences = _secret_occurrence_count(
                    paths=(),
                    tree_roots=tuple(secret_roots),
                    sentinels=sentinels,
                )
            except Exception as exc:
                raise ContainerContractError(
                    "failed substrate bytes could not be completely "
                    "secret/taint/canary scanned"
                ) from exc
            partial_scan = {
                **_bound_receipt_base(
                    spec,
                    kind=(
                        "contiguous_substrate_preflight_partial_scan"
                    ),
                ),
                "substrate_preflight_intent_sha256":
                    intent_sha256,
                "substrate_identity_sha256":
                    substrate_identity_sha256,
                "failure_stage": failure_stage,
                "error_type": error_type,
                "failure_class": failure_class,
                "failure_code": failure_code,
                "state_root": str(state_root),
                "preflight_root": str(preflight_root),
                "controller_state_inventory":
                    state_inventory.as_receipt(),
                "controller_state_scan":
                    state_scan.as_receipt(),
                "retained_canary_scan": (
                    None
                    if retained_scan is None
                    else retained_scan.as_receipt()
                ),
                "credential_sentinel_count": len(sentinels),
                "secret_occurrences": secret_occurrences,
                "controller_absence_receipt_path":
                    controller_absence_receipt_path,
                "controller_absence_receipt_sha256":
                    controller_absence_receipt_sha256,
                "scan_completed_before_purge": True,
                "status": "COMPLETE",
            }
            _write_private_json_new(
                partial_scan_path, partial_scan
            )
        partial_scan_sha256 = _hash_unaliased_regular_file(
            partial_scan_path,
            label="substrate failure partial scan receipt",
        )

        if purge_path.exists() or purge_path.is_symlink():
            purge = _read_unaliased_json(
                purge_path,
                label="substrate preflight purge receipt",
            )
            if (
                purge.get("partial_scan_receipt_sha256")
                != partial_scan_sha256
                or purge.get("substrate_preflight_intent_sha256")
                != intent_sha256
                or purge.get("substrate_identity_sha256")
                != substrate_identity_sha256
                or purge.get("status") != "PASS"
            ):
                raise ContainerContractError(
                    "retained substrate purge receipt changed"
                )
        else:
            _purge_owned_private_directory_contents(
                state_root,
                label="failed substrate controller state",
            )
            if (
                preflight_root.exists()
                or preflight_root.is_symlink()
            ):
                _purge_owned_private_directory_contents(
                    preflight_root,
                    label="failed substrate preflight runtime",
                )
                _remove_empty_owned_directory(
                    preflight_root,
                    label="failed substrate preflight runtime",
                )
            final_state = (
                probe_transport.inventory_controller_state(
                    state_root,
                    sentinels=sentinels,
                )
            )
            wip = _runner_field(spec, "wip")
            post_wip_tree_sha256 = (
                None
                if wip is None
                else _validated_tree_hash(
                    Path(wip.wip_root_path),
                    label="post-substrate-failure clean WIP",
                )
            )
            if (
                final_state.files
                or final_state.secret_occurrences
                or post_wip_tree_sha256
                != intent["prior_clean_wip_tree_sha256"]
            ):
                raise ContainerContractError(
                    "substrate failure purge lost WIP or retained state"
                )
            purge = {
                **_bound_receipt_base(
                    spec,
                    kind="contiguous_substrate_preflight_purge",
                ),
                "substrate_preflight_intent_sha256":
                    intent_sha256,
                "substrate_identity_sha256":
                    substrate_identity_sha256,
                "partial_scan_receipt_path":
                    str(partial_scan_path),
                "partial_scan_receipt_sha256":
                    partial_scan_sha256,
                "state_root": str(state_root),
                "post_purge_state_tree_sha256":
                    final_state.tree_sha256,
                "post_purge_state_inventory_sha256":
                    final_state.inventory_sha256,
                "state_root_empty": True,
                "preflight_root": str(preflight_root),
                "preflight_root_absent": not (
                    preflight_root.exists()
                    or preflight_root.is_symlink()
                ),
                "prior_clean_wip_tree_sha256":
                    intent["prior_clean_wip_tree_sha256"],
                "post_purge_clean_wip_tree_sha256":
                    post_wip_tree_sha256,
                "candidate_authority": False,
                "wip_authority": False,
                "promotion_authority": False,
                "status": "PASS",
            }
            _write_private_json_new(purge_path, purge)
        purge_sha256 = _hash_unaliased_regular_file(
            purge_path,
            label="substrate preflight purge receipt",
        )
        post_state = probe_transport.inventory_controller_state(
            state_root, sentinels=sentinels
        )
        if (
            post_state.files
            or post_state.secret_occurrences
            or preflight_root.exists()
            or preflight_root.is_symlink()
        ):
            raise ContainerContractError(
                "failed substrate mutable bytes reappeared after purge"
            )
        return (
            str(partial_scan_path),
            partial_scan_sha256,
            str(purge_path),
            purge_sha256,
            post_state.tree_sha256,
        )

    def _new_controller(
        self,
        *,
        spec: Any,
        prepared: Any,
        bridge: Any,
        probe_launch: Any,
    ) -> Any:
        controller = self._controller_factory(
            binary_path=(
                None
                if self._controller_factory
                is probe_transport.CodexAppServerController
                else Path(
                    _runner_field(
                        spec, "proposer_transport"
                    ).codex_binary_path
                )
            ),
            binding=self._controller_binding(spec, prepared),
            transcript_path=Path(
                _runner_field(spec, "app_server_transcript_path")
            ),
            credentials=self._credentials,
            bridge=bridge,
            probe_executor=self._probe_executor,
            probe_spec=spec,
            probe_launch=probe_launch,
            **(
                {
                    "container_launcher":
                        self._controller_container_launcher
                }
                if self._controller_factory
                is probe_transport.CodexAppServerController
                else {}
            ),
        )
        if not callable(
            getattr(controller, "start_and_preflight", None)
        ) or not callable(getattr(controller, "contain", None)):
            raise ContainerContractError(
                "controller factory lacks the substrate lifecycle"
            )
        return controller

    def _run_substrate_preflight(
        self,
        *,
        spec: Any,
        prepared: Any,
    ) -> dict[str, Any]:
        """Run and destroy the exact real controller before proposer start."""

        paths = self._substrate_preflight_artifact_paths(spec)
        receipt_path = paths["success"]
        failure_path = paths["failure"]
        preflight_root = paths["runtime"]
        substrate_identity = self._substrate_identity_sha256(spec)
        if failure_path.exists() or failure_path.is_symlink():
            value = _read_unaliased_json(
                failure_path,
                label="substrate preflight failure receipt",
            )
            if (
                value.get("substrate_identity_sha256")
                != substrate_identity
                or value.get("status") != "INFRASTRUCTURE"
            ):
                raise ContainerContractError(
                    "substrate preflight failure identity changed"
                )
            raise _runner_contract().BackendSubstratePreflightError(
                substrate_identity_sha256=substrate_identity,
                failure_receipt_path=str(failure_path),
                failure_receipt_sha256=(
                    _hash_unaliased_regular_file(
                        failure_path,
                        label="substrate preflight failure receipt",
                    )
                ),
            )
        if receipt_path.exists() or receipt_path.is_symlink():
            value = _read_unaliased_json(
                receipt_path, label="substrate preflight receipt"
            )
            current_state = (
                probe_transport.inventory_controller_state(
                    Path(_runner_field(spec, "app_server_state_dir"))
                )
            )
            if (
                value.get("substrate_identity_sha256")
                != substrate_identity
                or value.get("status") != "PASS"
                or value.get("final_state_tree_sha256")
                != current_state.tree_sha256
                or value.get("proposer_container_started") is not False
                or value.get("thread_started") is not False
                or value.get("turn_started") is not False
            ):
                raise ContainerContractError(
                    "retained substrate preflight receipt changed"
                )
            return value
        intent = self._ensure_substrate_preflight_intent(
            spec=spec,
            substrate_identity_sha256=substrate_identity,
        )
        preflight_spec = self._substrate_preflight_spec(spec)
        if (
            paths["partial_scan"].exists()
            or paths["partial_scan"].is_symlink()
            or paths["purge"].exists()
            or paths["purge"].is_symlink()
        ):
            retained_partial_scan = _read_unaliased_json(
                paths["partial_scan"],
                label="substrate preflight partial scan receipt",
            )
            retained_failure_stage = retained_partial_scan.get(
                "failure_stage"
            )
            retained_error_type = retained_partial_scan.get(
                "error_type"
            )
            retained_failure_class = retained_partial_scan.get(
                "failure_class"
            )
            retained_failure_code = retained_partial_scan.get(
                "failure_code"
            )
            if (
                _safe_probe_identifier(retained_failure_stage)
                != retained_failure_stage
                or _safe_probe_identifier(retained_error_type)
                != retained_error_type
                or retained_failure_class not in {
                    "DETERMINISTIC_CONFIGURATION",
                    "TRANSIENT_INFRASTRUCTURE",
                }
                or _safe_probe_identifier(retained_failure_code)
                != retained_failure_code
            ):
                raise ContainerContractError(
                    "retained substrate failure classification is "
                    "malformed"
                )
            (
                partial_scan_path,
                partial_scan_sha256,
                purge_path,
                purge_sha256,
                post_state_tree_sha256,
            ) = self._finalize_substrate_failure_cleanup(
                spec=spec,
                prepared=prepared,
                substrate_identity_sha256=substrate_identity,
                failure_stage=retained_failure_stage,
                error_type=retained_error_type,
                failure_class=retained_failure_class,
                failure_code=retained_failure_code,
            )
            raise _SubstratePreflightFailure(
                substrate_identity_sha256=substrate_identity,
                stage=retained_failure_stage,
                error_type=retained_error_type,
                failure_class=retained_failure_class,
                failure_code=retained_failure_code,
                preflight_root=str(preflight_root),
                state_tree_sha256=post_state_tree_sha256,
                partial_scan_receipt_path=partial_scan_path,
                partial_scan_receipt_sha256=partial_scan_sha256,
                purge_receipt_path=purge_path,
                purge_receipt_sha256=purge_sha256,
            )
        if preflight_root.exists() or preflight_root.is_symlink():
            absence_path, absence_sha256 = (
                self._recover_substrate_preflight_controller(
                    preflight_spec=preflight_spec,
                    prepared=prepared,
                )
            )
            (
                partial_scan_path,
                partial_scan_sha256,
                purge_path,
                purge_sha256,
                post_state_tree_sha256,
            ) = self._finalize_substrate_failure_cleanup(
                spec=spec,
                prepared=prepared,
                substrate_identity_sha256=substrate_identity,
                failure_stage="crash-recovery",
                error_type=(
                    "RecoveredIncompleteSubstratePreflight"
                ),
                failure_class="TRANSIENT_INFRASTRUCTURE",
                failure_code="recovered_incomplete_preflight",
                controller_absence_receipt_path=absence_path,
                controller_absence_receipt_sha256=absence_sha256,
            )
            raise _SubstratePreflightFailure(
                substrate_identity_sha256=substrate_identity,
                stage="crash-recovery",
                error_type=(
                    "RecoveredIncompleteSubstratePreflight"
                ),
                failure_class="TRANSIENT_INFRASTRUCTURE",
                failure_code="recovered_incomplete_preflight",
                preflight_root=str(preflight_root),
                state_tree_sha256=post_state_tree_sha256,
                partial_scan_receipt_path=partial_scan_path,
                partial_scan_receipt_sha256=partial_scan_sha256,
                purge_receipt_path=purge_path,
                purge_receipt_sha256=purge_sha256,
            )
        preflight_root.mkdir(mode=0o700)
        (preflight_root / "app_server_control").mkdir(mode=0o700)
        _fsync_private_parent(preflight_root)
        initial_attempt_state = (
            probe_transport.inventory_controller_state(
                Path(_runner_field(spec, "app_server_state_dir"))
            )
        )
        if (
            initial_attempt_state.tree_sha256
            != intent["initial_state_tree_sha256"]
            or initial_attempt_state.inventory_sha256
            != intent["initial_state_inventory_sha256"]
        ):
            raise ContainerContractError(
                "controller state changed after substrate intent"
            )
        controller: Any | None = None
        preflight: Any | None = None
        stage = "controller-start-and-initialize"
        try:
            controller = self._new_controller(
                spec=preflight_spec,
                prepared=prepared,
                bridge=_PreflightDeniedBridge(),
                probe_launch=object(),
            )
            preflight = controller.start_and_preflight()
            stage = "preflight-evidence-validation"
            _validate_preflight_evidence(
                preflight,
                spec=preflight_spec,
                credentials=self._credentials,
            )
            state_root_write_probe = _guardian_state_write_probe(
                spec=preflight_spec,
                evidence=preflight,
            )
            stage = "preflight-controller-containment"
            teardown = controller.contain()
            _validate_controller_teardown_evidence(
                teardown,
                spec=preflight_spec,
                preflight=preflight,
            )
            stage = "preflight-secret-taint-canary-scan"
            live_sentinels = _controller_credential_sentinels(
                controller,
                originals=self._credentials.leak_sentinels,
                maximum_refreshes=_runner_field(
                    spec, "max_auth_refreshes"
                ),
            )
            final_state = (
                probe_transport.inventory_controller_state(
                    Path(_runner_field(spec, "app_server_state_dir")),
                    sentinels=live_sentinels,
                )
            )
            try:
                import arc_agi3_contiguous_taint as taint_contract

                canaries = self._ensure_canary_escrow(spec)
                state_scan = taint_contract.scan_controller_state(
                    Path(
                        _runner_field(
                            spec, "app_server_state_dir"
                        )
                    ),
                    inventory=final_state,
                    canaries=canaries,
                )
                retained_scan = (
                    taint_contract.scan_retained_canary_roots(
                        {
                            "substrate_preflight_runtime":
                                preflight_root,
                        },
                        canaries=canaries,
                    )
                )
                secret_occurrences = _secret_occurrence_count(
                    paths=(),
                    tree_roots=(
                        Path(
                            _runner_field(
                                spec, "app_server_state_dir"
                            )
                        ),
                        preflight_root,
                    ),
                    sentinels=live_sentinels,
                )
            except Exception as exc:
                raise ContainerContractError(
                    "successful substrate preflight could not be "
                    "secret/taint/canary scanned"
                ) from exc
            if (
                final_state.secret_occurrences
                or state_scan.hits
                or state_scan.canary_occurrences
                or state_scan.status != "CLEAN"
                or retained_scan.hits
                or retained_scan.canary_occurrences
                or retained_scan.status != "CLEAN"
                or secret_occurrences
            ):
                raise ContainerContractError(
                    "substrate preflight retained secret/taint/canary "
                    "bytes"
                )
            success_scan = {
                **_bound_receipt_base(
                    spec,
                    kind="contiguous_substrate_preflight_scan",
                ),
                "substrate_identity_sha256":
                    substrate_identity,
                "controller_state_inventory":
                    final_state.as_receipt(),
                "controller_state_scan":
                    state_scan.as_receipt(),
                "retained_canary_scan":
                    retained_scan.as_receipt(),
                "credential_sentinel_count":
                    len(live_sentinels),
                "secret_occurrences": 0,
                "status": "PASS",
            }
            _write_private_json_new(
                paths["success_scan"], success_scan
            )
            success_scan_sha256 = (
                _hash_unaliased_regular_file(
                    paths["success_scan"],
                    label="substrate preflight scan receipt",
                )
            )
            document = {
                **_bound_receipt_base(
                    spec, kind="contiguous_substrate_preflight"
                ),
                "substrate_identity_sha256": substrate_identity,
                "substrate_preflight_intent_sha256":
                    _hash_unaliased_regular_file(
                        paths["intent"],
                        label="substrate preflight intent",
                    ),
                "preflight_attempt_spec_sha256":
                    _runner_contract()
                    .proposer_attempt_binding_sha256(preflight_spec),
                "preflight_root": str(preflight_root),
                "state_root":
                    _runner_field(spec, "app_server_state_dir"),
                "initial_attempt_state_tree_sha256":
                    initial_attempt_state.tree_sha256,
                "controller_initial_state_tree_sha256":
                    preflight.initial_state_tree_sha256,
                "initialized_state_tree_sha256":
                    preflight.initialized_state_tree_sha256,
                "initialized_state_inventory_sha256":
                    preflight.initialized_state_inventory_sha256,
                "state_database_path":
                    preflight.state_database_path,
                "state_database_sha256":
                    preflight.state_database_sha256,
                "state_database_bytes":
                    preflight.state_database_bytes,
                "state_database_header_sha256":
                    preflight.state_database_header_sha256,
                "state_database_initialized":
                    preflight.state_database_initialized,
                "guardian_start_receipt_path":
                    preflight.guardian_start_receipt_path,
                "guardian_start_receipt_sha256":
                    preflight.guardian_start_receipt_sha256,
                "state_root_write_probe":
                    state_root_write_probe,
                "state_root_write_probe_status":
                    state_root_write_probe["status"],
                "path_alias_setup_status":
                    preflight.path_alias_setup_status,
                "preflight_stderr_sha256":
                    preflight.stderr_sha256,
                "preflight_stderr_bytes":
                    preflight.stderr_bytes,
                "controller_container_id":
                    preflight.controller_container_id,
                "egress_proxy_container_id":
                    preflight.egress_proxy_container_id,
                "controller_launch_receipt_sha256":
                    preflight.controller_launch_receipt_sha256,
                "controller_absence_receipt_sha256":
                    teardown.controller_absence_receipt_sha256,
                "controller_inspect_absent":
                    teardown.controller_inspect_absent,
                "controller_identity_query_empty":
                    teardown.controller_identity_query_empty,
                "controller_no_descendants":
                    teardown.controller_no_descendants,
                "egress_proxy_inspect_absent":
                    teardown.egress_proxy_inspect_absent,
                "egress_proxy_identity_query_empty":
                    teardown.egress_proxy_identity_query_empty,
                "egress_proxy_no_descendants":
                    teardown.egress_proxy_no_descendants,
                "preflight_scan_receipt_path":
                    str(paths["success_scan"]),
                "preflight_scan_receipt_sha256":
                    success_scan_sha256,
                "final_state_tree_sha256":
                    final_state.tree_sha256,
                "proposer_container_started": False,
                "bridge_connected": False,
                "thread_started": False,
                "turn_started": False,
                "status": "PASS",
            }
            _write_private_json_new(receipt_path, document)
            return document
        except BaseException as original:
            if type(original).__name__ == "SimulatedCrash":
                raise
            absence_path: str | None = None
            absence_sha256: str | None = None
            if controller is not None and getattr(
                controller, "process", None
            ) is not None:
                try:
                    teardown = controller.contain()
                    _validate_controller_teardown_evidence(
                        teardown,
                        spec=preflight_spec,
                        preflight=preflight,
                    )
                except BaseException as cleanup_error:
                    raise ContainerContractError(
                        "failed substrate preflight could not prove "
                        "controller absence"
                    ) from cleanup_error
                absence_path = getattr(
                    teardown, "absence_receipt_path", None
                )
                absence_sha256 = getattr(
                    teardown,
                    "controller_absence_receipt_sha256",
                    None,
                )
            elif isinstance(
                self._controller_container_launcher,
                DockerControllerContainerLauncher,
            ):
                try:
                    (
                        absence_path,
                        absence_sha256,
                    ) = self._recover_substrate_preflight_controller(
                        preflight_spec=preflight_spec,
                        prepared=prepared,
                    )
                except BaseException as cleanup_error:
                    raise ContainerContractError(
                        "failed substrate preflight could not recover "
                        "controller absence"
                    ) from cleanup_error
            live_sentinels: Sequence[str] | None = None
            if controller is not None:
                getter = getattr(
                    controller,
                    "credential_sentinels_for_host_scan",
                    None,
                )
                if callable(getter):
                    try:
                        live_sentinels = getter()
                    except BaseException:
                        live_sentinels = None
            error_type = type(original).__name__
            if _safe_probe_identifier(error_type) != error_type:
                error_type = "SubstratePreflightError"
            failure_class, failure_code = (
                _classify_substrate_preflight_failure(
                    stage, original
                )
            )
            (
                partial_scan_path,
                partial_scan_sha256,
                purge_path,
                purge_sha256,
                post_state_tree_sha256,
            ) = self._finalize_substrate_failure_cleanup(
                spec=spec,
                prepared=prepared,
                substrate_identity_sha256=substrate_identity,
                failure_stage=stage,
                error_type=error_type,
                failure_class=failure_class,
                failure_code=failure_code,
                live_credential_sentinels=live_sentinels,
                controller_absence_receipt_path=absence_path,
                controller_absence_receipt_sha256=absence_sha256,
            )
            raise _SubstratePreflightFailure(
                substrate_identity_sha256=substrate_identity,
                stage=stage,
                error_type=error_type,
                failure_class=failure_class,
                failure_code=failure_code,
                preflight_root=str(preflight_root),
                state_tree_sha256=post_state_tree_sha256,
                partial_scan_receipt_path=partial_scan_path,
                partial_scan_receipt_sha256=partial_scan_sha256,
                purge_receipt_path=purge_path,
                purge_receipt_sha256=purge_sha256,
            ) from original

    def _materialize_substrate_failure_receipt(
        self,
        *,
        spec: Any,
        substrate_identity_sha256: str,
        failure_stage: str,
        error_type: str,
        failure_class: str,
        failure_code: str,
    ) -> tuple[str, str]:
        """Commit/reopen the typed receipt after generic launch teardown.

        All scan-and-purge evidence must already be durable.  This function is
        deliberately callable from restart recovery when the generic backend
        launch tombstone reached disk but the typed receipt did not.
        """

        paths = self._substrate_preflight_artifact_paths(spec)
        for name in ("intent", "partial_scan", "purge"):
            path = paths[name]
            if not (path.exists() and not path.is_symlink()):
                raise ContainerContractError(
                    "substrate failure lacks crash-durable "
                    f"{name} evidence"
                )
        intent = _read_unaliased_json(
            paths["intent"], label="substrate preflight intent"
        )
        partial_scan = _read_unaliased_json(
            paths["partial_scan"],
            label="substrate preflight partial scan receipt",
        )
        purge = _read_unaliased_json(
            paths["purge"],
            label="substrate preflight purge receipt",
        )
        intent_sha256 = _hash_unaliased_regular_file(
            paths["intent"], label="substrate preflight intent"
        )
        partial_scan_sha256 = _hash_unaliased_regular_file(
            paths["partial_scan"],
            label="substrate preflight partial scan receipt",
        )
        purge_sha256 = _hash_unaliased_regular_file(
            paths["purge"],
            label="substrate preflight purge receipt",
        )
        if (
            intent.get("substrate_identity_sha256")
            != substrate_identity_sha256
            or partial_scan.get("substrate_identity_sha256")
            != substrate_identity_sha256
            or purge.get("substrate_identity_sha256")
            != substrate_identity_sha256
            or partial_scan.get(
                "substrate_preflight_intent_sha256"
            )
            != intent_sha256
            or partial_scan.get("failure_stage") != failure_stage
            or partial_scan.get("error_type") != error_type
            or partial_scan.get("failure_class") != failure_class
            or partial_scan.get("failure_code") != failure_code
            or purge.get("substrate_preflight_intent_sha256")
            != intent_sha256
            or purge.get("partial_scan_receipt_sha256")
            != partial_scan_sha256
            or partial_scan.get("status") != "COMPLETE"
            or purge.get("status") != "PASS"
            or purge.get("state_root_empty") is not True
            or purge.get("preflight_root_absent") is not True
            or purge.get("prior_clean_wip_tree_sha256")
            != purge.get("post_purge_clean_wip_tree_sha256")
        ):
            raise ContainerContractError(
                "substrate scan/purge chain is not exact"
            )
        tombstone_path = _expected_backend_launch_failure_path(spec)
        tombstone_sha256 = _hash_unaliased_regular_file(
            tombstone_path,
            label="backend launch-failure tombstone",
        )
        document = {
            **_bound_receipt_base(
                spec,
                kind="contiguous_substrate_preflight_failure",
            ),
            "substrate_identity_sha256":
                substrate_identity_sha256,
            "substrate_preflight_intent_path":
                str(paths["intent"]),
            "substrate_preflight_intent_sha256":
                intent_sha256,
            "preflight_root": str(paths["runtime"]),
            "state_root":
                _runner_field(spec, "app_server_state_dir"),
            "failure_stage": failure_stage,
            "error_type": error_type,
            "failure_class": failure_class,
            "failure_code": failure_code,
            "partial_scan_receipt_path":
                str(paths["partial_scan"]),
            "partial_scan_receipt_sha256":
                partial_scan_sha256,
            "purge_receipt_path": str(paths["purge"]),
            "purge_receipt_sha256": purge_sha256,
            "post_failure_state_tree_sha256":
                purge["post_purge_state_tree_sha256"],
            "state_root_empty": True,
            "preflight_root_absent": True,
            "prior_clean_wip_tree_sha256":
                purge["prior_clean_wip_tree_sha256"],
            "post_purge_clean_wip_tree_sha256":
                purge["post_purge_clean_wip_tree_sha256"],
            "backend_launch_failure_tombstone_path":
                str(tombstone_path),
            "backend_launch_failure_tombstone_sha256":
                tombstone_sha256,
            "proposer_container_started": False,
            "bridge_connected": False,
            "thread_started": False,
            "turn_started": False,
            "candidate_authority": False,
            "wip_authority": False,
            "promotion_authority": False,
            "cost_used": 0.0,
            "status": "INFRASTRUCTURE",
        }
        failure_path = paths["failure"]
        if failure_path.exists() or failure_path.is_symlink():
            if _read_unaliased_json(
                failure_path,
                label="substrate preflight failure receipt",
            ) != document:
                raise ContainerContractError(
                    "substrate failure receipt changed"
                )
        else:
            _write_private_json_new(failure_path, document)
        return (
            str(failure_path),
            _hash_unaliased_regular_file(
                failure_path,
                label="substrate preflight failure receipt",
            ),
        )

    def probe_substrate_health(
        self,
        *,
        spec: Any,
        prepared: Any,
        authorization_id: str,
        authorization_receipt_sha256: str,
        probe_index: int,
        failed_substrate_identity_sha256: str,
        incident_failure_receipt_sha256: str,
    ) -> Any:
        """Run one fresh-state, controller-only circuit health probe.

        The authorization has no solver authority.  The remediation epoch is
        derived here from observed rematerialization and real controller
        evidence; callers cannot nominate a digest and thereby clear the
        global latch.
        """

        runner = _runner_contract()
        if (
            not isinstance(authorization_id, str)
            or re.fullmatch(
                r"[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-"
                r"[89ab][0-9a-f]{3}-[0-9a-f]{12}",
                authorization_id,
            )
            is None
            or not isinstance(probe_index, int)
            or isinstance(probe_index, bool)
            or probe_index < 1
            or not _is_hex_sha256(authorization_receipt_sha256)
            or not _is_hex_sha256(
                failed_substrate_identity_sha256
            )
            or not _is_hex_sha256(
                incident_failure_receipt_sha256
            )
        ):
            raise ContainerContractError(
                "substrate health authorization is malformed"
            )
        host_root = Path(
            _runner_field(spec, "host_transcript_path")
        ).parent
        root = (
            host_root
            / "substrate_health_reprobes"
            / authorization_id
        )
        intent_path = root / "intent.json"
        started_path = root / "probe_started.json"
        scan_path = root / "scan.json"
        purge_path = root / "purge.json"
        remediation_path = root / "rematerialization.json"
        receipt_path = root / "receipt.json"
        state_parent = root / "state"
        state_root = state_parent / "codex_home"
        runtime_root = root / "substrate_preflight"
        prior_wip = _runner_field(spec, "wip")
        prior_wip_sha256 = (
            None
            if prior_wip is None
            else _validated_tree_hash(
                Path(prior_wip.wip_root_path),
                label="pre-health-probe clean WIP",
            )
        )
        if (
            prior_wip is not None
            and prior_wip_sha256 != prior_wip.wip_tree_sha256
        ):
            raise ContainerContractError(
                "clean WIP changed before substrate health probe"
            )
        if receipt_path.exists() or receipt_path.is_symlink():
            retained = _read_unaliased_json(
                receipt_path,
                label="substrate health reprobe receipt",
            )
            if (
                retained.get("authorization_id")
                != authorization_id
                or retained.get("probe_index") != probe_index
                or retained.get("authorization_receipt_sha256")
                != authorization_receipt_sha256
                or retained.get(
                    "failed_substrate_identity_sha256"
                )
                != failed_substrate_identity_sha256
                or retained.get(
                    "incident_failure_receipt_sha256"
                )
                != incident_failure_receipt_sha256
                or retained.get("status") not in {"PASS", "FAILED"}
            ):
                raise ContainerContractError(
                    "retained substrate health receipt changed identity"
                )
            return runner.BackendSubstrateHealthProbe(
                authorization_id=authorization_id,
                probe_index=probe_index,
                remediation_epoch_sha256=retained[
                    "remediation_epoch_sha256"
                ],
                failed_substrate_identity_sha256=(
                    failed_substrate_identity_sha256
                ),
                healthy_substrate_identity_sha256=retained[
                    "healthy_substrate_identity_sha256"
                ],
                incident_failure_receipt_sha256=(
                    incident_failure_receipt_sha256
                ),
                failure_class=retained["failure_class"],
                failure_code=retained["failure_code"],
                status=retained["status"],
                receipt_path=str(receipt_path),
                receipt_sha256=_hash_unaliased_regular_file(
                    receipt_path,
                    label="substrate health reprobe receipt",
                ),
            )
        root_parent = root.parent
        if root_parent.exists() or root_parent.is_symlink():
            _private_directory_identity(
                root_parent,
                label="substrate health reprobe root",
            )
        else:
            _create_private_directory_new(
                root_parent,
                label="substrate health reprobe root",
            )
        new_intent = not (
            intent_path.exists() or intent_path.is_symlink()
        )
        if new_intent:
            root.mkdir(mode=0o700)
            _fsync_private_parent(root)
            health_intent = {
                **_bound_receipt_base(
                    spec,
                    kind="contiguous_substrate_health_reprobe_intent",
                ),
                "authorization_id": authorization_id,
                "authorization_receipt_sha256":
                    authorization_receipt_sha256,
                "probe_index": probe_index,
                "failed_substrate_identity_sha256":
                    failed_substrate_identity_sha256,
                "incident_failure_receipt_sha256":
                    incident_failure_receipt_sha256,
                "health_state_root": str(state_root),
                "health_runtime_root": str(runtime_root),
                "prior_clean_wip_tree_sha256": prior_wip_sha256,
                "proposer_container_started": False,
                "bridge_connected": False,
                "thread_started": False,
                "turn_started": False,
                "status": "PENDING",
            }
            _write_private_json_new(intent_path, health_intent)
        else:
            health_intent = _read_unaliased_json(
                intent_path,
                label="substrate health reprobe intent",
            )
            if (
                health_intent.get("authorization_id")
                != authorization_id
                or health_intent.get("probe_index") != probe_index
                or health_intent.get(
                    "authorization_receipt_sha256"
                )
                != authorization_receipt_sha256
            ):
                raise ContainerContractError(
                    "substrate health intent changed identity"
                )

        failure_class: str | None = None
        failure_code: str | None = None
        status = "FAILED"
        preflight_receipt_path: str | None = None
        preflight_receipt_sha256: str | None = None
        guardian_probe_status: str | None = None
        source_scan_path: str | None = None
        source_scan_sha256: str | None = None
        initial_state_tree_sha256: str | None = None
        initial_state_inventory_sha256: str | None = None
        health_spec: Any | None = None
        if new_intent:
            state_parent.mkdir(mode=0o700)
            state_root.mkdir(mode=0o700)
            _fsync_private_parent(state_root)
            initial_state = (
                probe_transport.inventory_controller_state(
                    state_root,
                    sentinels=self._credentials.leak_sentinels,
                )
            )
            initial_state_tree_sha256 = initial_state.tree_sha256
            initial_state_inventory_sha256 = (
                initial_state.inventory_sha256
            )
            health_spec = replace(
                spec,
                host_transcript_path=str(root / "backend.jsonl"),
                app_server_transcript_path=str(
                    root / "app_server.jsonl"
                ),
                app_server_control_dir=str(
                    root / "app_server_control"
                ),
                app_server_state_dir=str(state_root),
                initial_app_server_state_tree_sha256=(
                    initial_state_tree_sha256
                ),
            )
            started_document = {
                **_bound_receipt_base(
                    spec,
                    kind=(
                        "contiguous_substrate_health_"
                        "reprobe_started"
                    ),
                ),
                "authorization_id": authorization_id,
                "authorization_receipt_sha256":
                    authorization_receipt_sha256,
                "probe_index": probe_index,
                "failed_substrate_identity_sha256":
                    failed_substrate_identity_sha256,
                "incident_failure_receipt_sha256":
                    incident_failure_receipt_sha256,
                "health_state_root": str(state_root),
                "health_runtime_root": str(runtime_root),
                "initial_state_inventory":
                    initial_state.as_receipt(),
                "health_attempt_spec_sha256":
                    runner.proposer_attempt_binding_sha256(
                        health_spec
                    ),
                "proposer_container_started": False,
                "bridge_connected": False,
                "thread_started": False,
                "turn_started": False,
                "status": "STARTED",
            }
            _write_private_json_new(
                started_path, started_document
            )
            try:
                preflight = self._run_substrate_preflight(
                    spec=health_spec,
                    prepared=prepared,
                )
                preflight_path = (
                    root / "substrate_preflight_receipt.json"
                )
                preflight_receipt_path = str(preflight_path)
                preflight_receipt_sha256 = (
                    _hash_unaliased_regular_file(
                        preflight_path,
                        label="health substrate preflight receipt",
                    )
                )
                guardian_probe_status = preflight[
                    "state_root_write_probe_status"
                ]
                source_scan_path = preflight[
                    "preflight_scan_receipt_path"
                ]
                source_scan_sha256 = preflight[
                    "preflight_scan_receipt_sha256"
                ]
                status = "PASS"
            except _SubstratePreflightFailure as exc:
                failure_class = exc.failure_class
                failure_code = exc.failure_code
                source_scan_path = exc.partial_scan_receipt_path
                source_scan_sha256 = (
                    exc.partial_scan_receipt_sha256
                )
            except BaseException as exc:
                if type(exc).__name__ == "SimulatedCrash":
                    raise
                failure_class, failure_code = (
                    _classify_substrate_preflight_failure(
                        "health-probe", exc
                    )
                )
        else:
            # A crash after authorization consumes that authorization.  It is
            # reconciled as one failed probe without starting a second
            # controller under the same single-use identity.
            failure_class = "TRANSIENT_INFRASTRUCTURE"
            failure_code = "recovered_incomplete_health_probe"

        if started_path.exists() or started_path.is_symlink():
            started = _read_unaliased_json(
                started_path,
                label="substrate health reprobe started receipt",
            )
            initial_inventory = started.get(
                "initial_state_inventory"
            )
            if (
                started.get("authorization_id")
                != authorization_id
                or started.get("authorization_receipt_sha256")
                != authorization_receipt_sha256
                or started.get("probe_index") != probe_index
                or started.get(
                    "failed_substrate_identity_sha256"
                )
                != failed_substrate_identity_sha256
                or started.get(
                    "incident_failure_receipt_sha256"
                )
                != incident_failure_receipt_sha256
                or started.get("health_state_root")
                != str(state_root)
                or started.get("health_runtime_root")
                != str(runtime_root)
                or not isinstance(initial_inventory, dict)
                or not _is_hex_sha256(
                    initial_inventory.get("tree_sha256")
                )
                or not _is_hex_sha256(
                    initial_inventory.get("inventory_sha256")
                )
                or started.get("status") != "STARTED"
            ):
                raise ContainerContractError(
                    "substrate health start evidence changed"
                )
            initial_state_tree_sha256 = initial_inventory[
                "tree_sha256"
            ]
            initial_state_inventory_sha256 = initial_inventory[
                "inventory_sha256"
            ]
            health_spec = replace(
                spec,
                host_transcript_path=str(root / "backend.jsonl"),
                app_server_transcript_path=str(
                    root / "app_server.jsonl"
                ),
                app_server_control_dir=str(
                    root / "app_server_control"
                ),
                app_server_state_dir=str(state_root),
                initial_app_server_state_tree_sha256=(
                    initial_state_tree_sha256
                ),
            )
            if (
                started.get("health_attempt_spec_sha256")
                != runner.proposer_attempt_binding_sha256(
                    health_spec
                )
            ):
                raise ContainerContractError(
                    "substrate health attempt spec changed"
                )
        if initial_state_tree_sha256 is None:
            if not state_root.exists():
                state_parent.mkdir(mode=0o700, exist_ok=True)
                state_root.mkdir(mode=0o700)
            recovered_initial_state = (
                probe_transport.inventory_controller_state(
                    state_root,
                    sentinels=self._credentials.leak_sentinels,
                )
            )
            initial_state_tree_sha256 = (
                recovered_initial_state.tree_sha256
            )
            initial_state_inventory_sha256 = (
                recovered_initial_state.inventory_sha256
            )
        if health_spec is not None and not new_intent:
            health_spec = replace(
                health_spec,
                initial_app_server_state_tree_sha256=(
                    initial_state_tree_sha256
                )
            )
            try:
                self._recover_substrate_preflight_controller(
                    preflight_spec=(
                        self._substrate_preflight_spec(health_spec)
                    ),
                    prepared=prepared,
                )
            except Exception:
                failure_class = "TRANSIENT_INFRASTRUCTURE"
                failure_code = (
                    "health_controller_absence_recovery_failed"
                )

        if not (scan_path.exists() or scan_path.is_symlink()):
            scan_document = {
                **_bound_receipt_base(
                    spec,
                    kind="contiguous_substrate_health_reprobe_scan",
                ),
                "authorization_id": authorization_id,
                "probe_index": probe_index,
                "source_scan_receipt_path": source_scan_path,
                "source_scan_receipt_sha256": source_scan_sha256,
                "state_inventory_before_purge":
                    probe_transport.inventory_controller_state(
                        state_root,
                        sentinels=self._credentials.leak_sentinels,
                    ).as_receipt(),
                "status": "COMPLETE",
            }
            _write_private_json_new(scan_path, scan_document)
        scan_sha256 = _hash_unaliased_regular_file(
            scan_path,
            label="substrate health scan receipt",
        )

        if not (purge_path.exists() or purge_path.is_symlink()):
            _purge_owned_private_directory_contents(
                state_root,
                label="substrate health state",
            )
            _remove_empty_owned_directory(
                state_root,
                label="substrate health state",
            )
            if state_parent.exists() and not any(
                state_parent.iterdir()
            ):
                _remove_empty_owned_directory(
                    state_parent,
                    label="substrate health state parent",
                )
            if runtime_root.exists() or runtime_root.is_symlink():
                _purge_owned_private_directory_contents(
                    runtime_root,
                    label="substrate health runtime",
                )
                _remove_empty_owned_directory(
                    runtime_root,
                    label="substrate health runtime",
                )
            post_wip_sha256 = (
                None
                if prior_wip is None
                else _validated_tree_hash(
                    Path(prior_wip.wip_root_path),
                    label="post-health-probe clean WIP",
                )
            )
            if post_wip_sha256 != prior_wip_sha256:
                raise ContainerContractError(
                    "substrate health probe changed clean WIP"
                )
            purge_document = {
                **_bound_receipt_base(
                    spec,
                    kind="contiguous_substrate_health_reprobe_purge",
                ),
                "authorization_id": authorization_id,
                "probe_index": probe_index,
                "scan_receipt_sha256": scan_sha256,
                "health_state_root_absent": not state_root.exists(),
                "health_runtime_root_absent":
                    not runtime_root.exists(),
                "prior_clean_wip_tree_sha256": prior_wip_sha256,
                "post_clean_wip_tree_sha256": post_wip_sha256,
                "status": "PASS",
            }
            _write_private_json_new(purge_path, purge_document)
        purge_sha256 = _hash_unaliased_regular_file(
            purge_path,
            label="substrate health purge receipt",
        )
        purge_document = _read_unaliased_json(
            purge_path,
            label="substrate health purge receipt",
        )
        if (
            purge_document.get("health_state_root_absent")
            is not True
            or purge_document.get("health_runtime_root_absent")
            is not True
            or state_root.exists()
            or runtime_root.exists()
            or purge_document.get("prior_clean_wip_tree_sha256")
            != purge_document.get("post_clean_wip_tree_sha256")
        ):
            raise ContainerContractError(
                "substrate health cleanup is incomplete"
            )

        remediation_evidence = {
            **_bound_receipt_base(
                spec,
                kind=(
                    "contiguous_substrate_health_"
                    "rematerialization_evidence"
                ),
            ),
            "authorization_id": authorization_id,
            "probe_index": probe_index,
            "authorization_receipt_sha256":
                authorization_receipt_sha256,
            "failed_substrate_identity_sha256":
                failed_substrate_identity_sha256,
            "incident_failure_receipt_sha256":
                incident_failure_receipt_sha256,
            "fresh_state_root_created": True,
            "health_state_root": str(state_root),
            "initial_state_tree_sha256":
                initial_state_tree_sha256,
            "initial_state_inventory_sha256":
                initial_state_inventory_sha256,
            "preflight_receipt_sha256":
                preflight_receipt_sha256,
            "guardian_state_root_write_probe_status":
                guardian_probe_status,
            "scan_receipt_sha256": scan_sha256,
            "purge_receipt_sha256": purge_sha256,
            "health_state_root_absent": True,
            "health_runtime_root_absent": True,
            "status": status,
        }
        remediation_epoch_sha256 = _json_sha256(
            remediation_evidence
        )
        remediation_document = {
            **remediation_evidence,
            "remediation_epoch_sha256":
                remediation_epoch_sha256,
        }
        if remediation_path.exists() or remediation_path.is_symlink():
            if _read_unaliased_json(
                remediation_path,
                label="substrate rematerialization evidence",
            ) != remediation_document:
                raise ContainerContractError(
                    "substrate remediation evidence changed"
                )
        else:
            _write_private_json_new(
                remediation_path, remediation_document
            )
        remediation_sha256 = _hash_unaliased_regular_file(
            remediation_path,
            label="substrate rematerialization evidence",
        )
        healthy_identity = (
            _json_sha256({
                "schema": 1,
                "kind": "healthy_controller_substrate_identity",
                "failed_substrate_identity_sha256":
                    failed_substrate_identity_sha256,
                "remediation_epoch_sha256":
                    remediation_epoch_sha256,
                "preflight_receipt_sha256":
                    preflight_receipt_sha256,
                "guardian_state_root_write_probe_status":
                    guardian_probe_status,
                "status": "PASS",
            })
            if status == "PASS"
            else None
        )
        if status == "PASS":
            failure_class = None
            failure_code = None
        elif failure_class is None or failure_code is None:
            failure_class = "TRANSIENT_INFRASTRUCTURE"
            failure_code = "substrate_health_probe_failed"
        document = {
            **_bound_receipt_base(
                spec,
                kind="contiguous_substrate_health_reprobe",
            ),
            "authorization_id": authorization_id,
            "authorization_receipt_sha256":
                authorization_receipt_sha256,
            "probe_index": probe_index,
            "failed_substrate_identity_sha256":
                failed_substrate_identity_sha256,
            "healthy_substrate_identity_sha256":
                healthy_identity,
            "incident_failure_receipt_sha256":
                incident_failure_receipt_sha256,
            "remediation_epoch_sha256":
                remediation_epoch_sha256,
            "rematerialization_evidence_path":
                str(remediation_path),
            "rematerialization_evidence_sha256":
                remediation_sha256,
            "fresh_state_root_created": True,
            "health_state_root": str(state_root),
            "health_runtime_root": str(runtime_root),
            "preflight_receipt_path":
                preflight_receipt_path,
            "preflight_receipt_sha256":
                preflight_receipt_sha256,
            "guardian_state_root_write_probe_status":
                guardian_probe_status,
            "scan_receipt_path": str(scan_path),
            "scan_receipt_sha256": scan_sha256,
            "purge_receipt_path": str(purge_path),
            "purge_receipt_sha256": purge_sha256,
            "failure_class": failure_class,
            "failure_code": failure_code,
            "health_state_root_absent": True,
            "health_runtime_root_absent": True,
            "proposer_container_started": False,
            "bridge_connected": False,
            "thread_started": False,
            "turn_started": False,
            "candidate_authority": False,
            "wip_authority": False,
            "promotion_authority": False,
            "cost_used": 0.0,
            "status": status,
        }
        _write_private_json_new(receipt_path, document)
        return runner.BackendSubstrateHealthProbe(
            authorization_id=authorization_id,
            probe_index=probe_index,
            remediation_epoch_sha256=remediation_epoch_sha256,
            failed_substrate_identity_sha256=(
                failed_substrate_identity_sha256
            ),
            healthy_substrate_identity_sha256=healthy_identity,
            incident_failure_receipt_sha256=(
                incident_failure_receipt_sha256
            ),
            failure_class=failure_class,
            failure_code=failure_code,
            status=status,
            receipt_path=str(receipt_path),
            receipt_sha256=_hash_unaliased_regular_file(
                receipt_path,
                label="substrate health reprobe receipt",
            ),
        )

    def launch(self, spec: Any, prepared: Any) -> Any:
        """Launch the container and one exact host-owned app-server turn."""
        runtime = self._runtime_for(spec, prepared=prepared)
        with self._lock:
            if prepared != runtime.preparation:
                raise ContainerContractError(
                    "launch preparation does not bind this exact attempt"
                )
            intent_sha256 = self._ensure_launch_intent(
                spec=spec, runtime=runtime
            )
            if self._validate_launch_failure_tombstone(
                spec=spec,
                runtime=runtime,
                intent_sha256=intent_sha256,
            ) is not None:
                substrate_paths = (
                    self._substrate_preflight_artifact_paths(spec)
                )
                substrate_failure_path = substrate_paths["failure"]
                if not (
                    substrate_failure_path.exists()
                    or substrate_failure_path.is_symlink()
                ) and all(
                    substrate_paths[name].exists()
                    and not substrate_paths[name].is_symlink()
                    for name in ("intent", "partial_scan", "purge")
                ):
                    partial_scan = _read_unaliased_json(
                        substrate_paths["partial_scan"],
                        label=(
                            "substrate preflight partial scan receipt"
                        ),
                    )
                    self._materialize_substrate_failure_receipt(
                        spec=spec,
                        substrate_identity_sha256=(
                            partial_scan[
                                "substrate_identity_sha256"
                            ]
                        ),
                        failure_stage=partial_scan["failure_stage"],
                        error_type=partial_scan["error_type"],
                        failure_class=partial_scan["failure_class"],
                        failure_code=partial_scan["failure_code"],
                    )
                if (
                    substrate_failure_path.exists()
                    or substrate_failure_path.is_symlink()
                ):
                    failure = _read_unaliased_json(
                        substrate_failure_path,
                        label="substrate preflight failure receipt",
                    )
                    raise _runner_contract().BackendSubstratePreflightError(
                        substrate_identity_sha256=(
                            failure["substrate_identity_sha256"]
                        ),
                        failure_receipt_path=str(
                            substrate_failure_path
                        ),
                        failure_receipt_sha256=(
                            _hash_unaliased_regular_file(
                                substrate_failure_path,
                                label=(
                                    "substrate preflight failure receipt"
                                ),
                            )
                        ),
                    )
                raise ContainerContractError(
                    "backend launch is durably terminal after exact "
                    "failed-launch reconciliation"
                )
            if (
                runtime.orphaned_after_supervisor_restart
                or (
                    runtime.backend_launch is not None
                    and runtime.controller_thread is None
                )
            ):
                orphan_error = ContainerContractError(
                    "supervisor ownership was lost during backend launch"
                )
                self._reconcile_failed_launch(
                    spec=spec,
                    runtime=runtime,
                    intent_sha256=intent_sha256,
                    failure_stage="supervisor-restart",
                    original=orphan_error,
                )
                raise ContainerContractError(
                    "ownerless backend launch was reconciled and is "
                    "durably terminal"
                ) from orphan_error
            if runtime.backend_launch is not None:
                return runtime.backend_launch
            bridge_events: list[tuple[str, dict[str, Any]]] = []
            bridge_client: Any | None = None
            controller: Any | None = None
            failure_stage = "substrate-preflight"
            try:
                substrate_preflight = self._run_substrate_preflight(
                    spec=spec,
                    prepared=prepared,
                )
                substrate_preflight_path = (
                    Path(_runner_field(spec, "host_transcript_path"))
                    .parent
                    / "substrate_preflight_receipt.json"
                )
                substrate_preflight_sha256 = (
                    _hash_unaliased_regular_file(
                        substrate_preflight_path,
                        label="substrate preflight receipt",
                    )
                )
                failure_stage = "container-start"
                running = self._backend.start_attested(
                    runtime.attestation, runtime.low_spec
                )
                runtime.launched = running

                def record_bridge(
                    kind: str, payload: Mapping[str, Any]
                ) -> None:
                    event = json.loads(
                        _canonical_json_bytes(dict(payload)).decode("ascii")
                    )
                    bridge_events.append((kind, event))
                    _append_host_transcript_event(
                        Path(_runner_field(spec, "host_transcript_path")),
                        {
                            "schema": 1,
                            "kind": kind,
                            "payload_sha256": _json_sha256(event),
                        },
                    )

                def freeze_target_boundary(
                    request: Mapping[str, Any],
                    response: Mapping[str, Any],
                ) -> None:
                    if runtime.target_boundary_evidence is not None:
                        raise ContainerContractError(
                            "attempt produced more than one target boundary"
                        )
                    frozen = _freeze_target_boundary_workspace(
                        spec=spec,
                        request=request,
                        response=response,
                    )
                    runtime.target_boundary_evidence = frozen
                    _append_host_transcript_event(
                        Path(_runner_field(spec, "host_transcript_path")),
                        {
                            "schema": 1,
                            "kind": "target_boundary_frozen",
                            "boundary_sha256":
                                frozen.boundary_sha256,
                            "receipt_sha256":
                                frozen.receipt_sha256,
                            "pre_response_delivery": True,
                        },
                    )

                failure_stage = "bridge-socket-wait"
                bridge_socket = self._wait_for_bridge_socket(runtime)
                bridge_token = _snapshot_endpoint(
                    runtime.low_spec.bridge_token_file,
                    label="proposer bridge token",
                    expected_kind="token",
                )
                proxy = _ProbeLaunchProxy(
                    container_id=running.attestation.container_id,
                    running_observation_sha256=(
                        running.running_observation_sha256
                    ),
                )
                failure_stage = "bridge-connect"
                bridge_client_arguments: dict[str, Any] = {
                    "socket_path": runtime.low_spec.bridge_socket,
                    "token_file":
                        runtime.low_spec.bridge_token_file,
                    "attempt_id":
                        runtime.low_spec.identity.attempt_id,
                    "evidence_callback": record_bridge,
                }
                if (
                    self._bridge_client_factory
                    is probe_transport.BridgeClient
                ):
                    bridge_client_arguments[
                        "target_boundary_callback"
                    ] = freeze_target_boundary
                bridge_client = self._bridge_client_factory(
                    **bridge_client_arguments,
                )
                runtime.bridge_client = bridge_client
                challenge = getattr(
                    bridge_client, "challenge_nonce", None
                )
                if (
                    not isinstance(challenge, str)
                    or not re.fullmatch(r"[0-9a-f]{32}", challenge)
                ):
                    raise ContainerContractError(
                        "proposer bridge handshake nonce is malformed"
                )
                _validate_bridge_handshake(bridge_client, spec=spec)
                failure_stage = "controller-create"
                controller = self._new_controller(
                    spec=spec,
                    prepared=prepared,
                    bridge=bridge_client,
                    probe_launch=proxy,
                )
                runtime.controller = controller
                failure_stage = "app-server-preflight"
                preflight = controller.start_and_preflight()
                _validate_preflight_evidence(
                    preflight,
                    spec=spec,
                    credentials=self._credentials,
                )
                usage_window = preflight.provider_usage_window
                admitted_remaining = _runner_field(
                    spec, "cost_limit_remaining"
                )
                if not usage_window.cost_control_enabled:
                    if (
                        usage_window.authority
                        != "explicit_unlimited"
                        or usage_window.limit is not None
                        or admitted_remaining is not None
                    ):
                        raise ContainerContractError(
                            "explicit unlimited authority must disable every "
                            "local proposer cost cutoff"
                        )
                elif (
                    admitted_remaining is None
                    or usage_window.remaining is None
                    or float(admitted_remaining)
                    > float(usage_window.remaining)
                ):
                    raise ContainerContractError(
                        "finite provider authority lacks a bounded compatible "
                        "proposer admission"
                    )
                runtime.preflight_evidence = preflight
                frontier = _read_unaliased_json(
                    Path(_runner_field(spec, "frontier_brief_path")),
                    label="frontier brief",
                )
                failure_stage = "turn-start"
                turn_start = controller.start_turn(
                    frontier_brief=frontier
                )
                _validate_turn_start_evidence(
                    turn_start, spec=spec
                )
                runtime.turn_start_evidence = turn_start
                failure_stage = "launch-receipts"
                host_root = Path(
                    _runner_field(spec, "host_transcript_path")
                ).parent
                bridge_path, bridge_sha256 = _ensure_bound_receipt(
                    host_root / "bridge_runtime_attestation.json",
                    spec=spec,
                    kind="contiguous_bridge_runtime",
                    fields={
                        "container_id":
                            running.attestation.container_id,
                        "socket_path":
                            str(runtime.low_spec.bridge_socket),
                        "token_file_path":
                            str(runtime.low_spec.bridge_token_file),
                        "socket_inode": bridge_socket.inode,
                        "token_inode": bridge_token.inode,
                        "token_sha256": bridge_token.content_sha256,
                        "handshake_nonce_sha256": hashlib.sha256(
                            challenge.encode("ascii")
                        ).hexdigest(),
                        "policy_receipt_sha256":
                            prepared.bridge_policy_receipt_sha256,
                        "bridge_protocol_version":
                            _runner_field(
                                spec, "proposer_transport"
                            ).bridge_protocol_version,
                        "handshake_result": getattr(
                            bridge_client, "handshake_result", None
                        ),
                        "handshake_request_sha256": getattr(
                            bridge_client,
                            "handshake_request_sha256",
                            None,
                        ),
                        "handshake_response_sha256": getattr(
                            bridge_client,
                            "handshake_response_sha256",
                            None,
                        ),
                    },
                )
                transport = _runner_field(
                    spec, "proposer_transport"
                )
                (
                    hard_safety_seconds,
                    max_auth_refreshes,
                ) = _app_server_hard_limits()
                if (
                    hard_safety_seconds
                    != _runner_field(spec, "hard_safety_seconds")
                    or max_auth_refreshes
                    != _runner_field(spec, "max_auth_refreshes")
                ):
                    raise ContainerContractError(
                        "launch hard limits changed after admission"
                    )
                app_path, app_sha256 = _ensure_bound_receipt(
                    host_root / "app_server_runtime_receipt.json",
                    spec=spec,
                    kind="contiguous_app_server_runtime",
                    fields={
                        "pid": preflight.pid,
                        "process_start":
                            preflight.process_start_identity,
                        "process_group_id":
                            preflight.process_group_id,
                        "state_root":
                            _runner_field(spec, "app_server_state_dir"),
                        "neutral_cwd":
                            CONTROLLER_NEUTRAL_DESTINATION,
                        "neutral_host_staging_cwd":
                            _runner_field(
                                spec, "neutral_host_cwd_path"
                            ),
                        "thread_id": turn_start.thread_id,
                        "turn_id": turn_start.turn_id,
                        "thread_mode": turn_start.thread_mode,
                        "model": transport.model,
                        "model_provider": transport.model_provider,
                        "reasoning_effort":
                            _runner_field(spec, "effort"),
                        "hard_safety_seconds":
                            hard_safety_seconds,
                        "max_auth_refreshes":
                            max_auth_refreshes,
                        "allow_provider_model_fallback": False,
                        "builtin_tool_names": [],
                        "dynamic_tool_namespace":
                            transport.dynamic_tool_namespace,
                        "dynamic_tool_names": list(
                            transport.dynamic_tool_names
                        ),
                        "controller_method_policy": {
                            "preflight_requests": list(
                                transport
                                .controller_preflight_request_allowlist
                            ),
                            "preflight_notifications": list(
                                transport
                                .controller_preflight_notification_allowlist
                            ),
                            "turn_requests": list(
                                transport
                                .controller_turn_request_allowlist
                            ),
                        },
                        "startup_probe_status": "PASS",
                        "auth_probe_status": "PASS",
                        "model_probe_status": "PASS",
                        "bridge_probe_status": "PASS",
                        "substrate_identity_sha256":
                            substrate_preflight[
                                "substrate_identity_sha256"
                            ],
                        "substrate_preflight_receipt_path":
                            str(substrate_preflight_path),
                        "substrate_preflight_receipt_sha256":
                            substrate_preflight_sha256,
                        "state_root_write_probe_status":
                            substrate_preflight[
                                "state_root_write_probe_status"
                            ],
                        "state_database_initialized":
                            substrate_preflight[
                                "state_database_initialized"
                            ],
                        "path_alias_setup_status":
                            substrate_preflight[
                                "path_alias_setup_status"
                            ],
                        "ambient_state_loaded": False,
                        "preflight_evidence": asdict(preflight),
                    },
                )
                chain_path, chain_receipt_sha256 = (
                    _ensure_bound_receipt(
                        host_root
                        / "turn_start_transcript_chain_receipt.json",
                        spec=spec,
                        kind="contiguous_turn_start_transcript_chain",
                        fields={
                            "thread_id": turn_start.thread_id,
                            "turn_id": turn_start.turn_id,
                            "chain_head_sha256":
                                turn_start.transcript_chain_sha256,
                            "thread_request_sha256":
                                turn_start.thread_request_sha256,
                            "turn_request_sha256":
                                turn_start.turn_request_sha256,
                            "prompt_sha256":
                                turn_start.prompt_sha256,
                        },
                    )
                )
                binding_path, binding_sha256 = _ensure_bound_receipt(
                    host_root / "turn_start_binding.json",
                    spec=spec,
                    kind="contiguous_turn_start_binding",
                    fields={
                        "thread_id": turn_start.thread_id,
                        "turn_id": turn_start.turn_id,
                        "thread_mode": turn_start.thread_mode,
                        "bridge_runtime_attestation_sha256":
                            bridge_sha256,
                        "app_server_runtime_receipt_sha256":
                            app_sha256,
                        "reasoning_effort":
                            _runner_field(spec, "effort"),
                        "model": transport.model,
                        "transcript_chain_sha256":
                            turn_start.transcript_chain_sha256,
                    },
                )
                rebinding_path: str | None = None
                rebinding_sha256: str | None = None
                if _runner_field(spec, "thread_mode") == "resume":
                    wip = _runner_field(spec, "wip")
                    if wip is None:
                        raise ContainerContractError(
                            "resume launch has no admitted WIP binding"
                        )
                    rebinding_path, rebinding_sha256 = (
                        _ensure_bound_receipt(
                            host_root / "thread_rebinding_receipt.json",
                            spec=spec,
                            kind="contiguous_thread_rebinding",
                            fields={
                                "thread_id":
                                    _runner_field(
                                        spec, "resume_thread_id"
                                    ),
                                "prior_thread_binding_sha256":
                                    _runner_field(
                                        spec,
                                        "resume_thread_binding_sha256",
                                    ),
                                "prior_transcript_chain_sha256":
                                    wip.transcript_chain_sha256,
                                "prior_app_server_state_tree_sha256":
                                    wip.app_server_state_tree_sha256,
                                "prior_app_server_state_dir":
                                    wip.app_server_state_dir,
                                "staged_app_server_state_dir":
                                    _runner_field(
                                        spec, "app_server_state_dir"
                                    ),
                                "staged_initial_state_tree_sha256":
                                    wip.app_server_state_tree_sha256,
                                "new_container_id":
                                    running.attestation.container_id,
                                "new_bridge_runtime_attestation_sha256":
                                    bridge_sha256,
                                "old_bridge_revoked": True,
                                "no_binding_overlap": True,
                            },
                        )
                    )
                runner_contract = _runner_contract()
                launched = runner_contract.BackendLaunch(
                    backend_id=running.attestation.container_id,
                    container_id=running.attestation.container_id,
                    running_observation_sha256=(
                        running.running_observation_sha256
                    ),
                    substrate_identity_sha256=(
                        substrate_preflight[
                            "substrate_identity_sha256"
                        ]
                    ),
                    substrate_preflight_receipt_path=str(
                        substrate_preflight_path
                    ),
                    substrate_preflight_receipt_sha256=(
                        substrate_preflight_sha256
                    ),
                    bridge_runtime_attestation_path=bridge_path,
                    bridge_runtime_attestation_sha256=bridge_sha256,
                    app_server_runtime_receipt_path=app_path,
                    app_server_runtime_receipt_sha256=app_sha256,
                    app_server_pid=preflight.pid,
                    app_server_process_start=(
                        preflight.process_start_identity
                    ),
                    app_server_process_group_id=(
                        preflight.process_group_id
                    ),
                    app_server_pid_is_diagnostic=True,
                    process_identity_authority=(
                        preflight.process_identity_authority
                    ),
                    controller_container_id=(
                        preflight.controller_container_id
                    ),
                    controller_image_digest=(
                        preflight.controller_image_digest
                    ),
                    egress_proxy_container_id=(
                        preflight.egress_proxy_container_id
                    ),
                    egress_proxy_image_digest=(
                        preflight.egress_proxy_image_digest
                    ),
                    egress_policy_sha256=(
                        preflight.egress_policy_sha256
                    ),
                    controller_launch_intent_sha256=(
                        preflight.controller_launch_intent_sha256
                    ),
                    controller_launch_receipt_path=(
                        preflight.controller_launch_receipt_path
                    ),
                    controller_launch_receipt_sha256=(
                        preflight.controller_launch_receipt_sha256
                    ),
                    controller_guardian_start_receipt_path=(
                        preflight.guardian_start_receipt_path
                    ),
                    controller_guardian_start_receipt_sha256=(
                        preflight.guardian_start_receipt_sha256
                    ),
                    controller_supply_chain_manifest_sha256=(
                        preflight.supply_chain_manifest_sha256
                    ),
                    codex_thread_id=turn_start.thread_id,
                    codex_turn_id=turn_start.turn_id,
                    thread_binding_path=binding_path,
                    thread_binding_sha256=binding_sha256,
                    transcript_chain_receipt_path=chain_path,
                    transcript_chain_receipt_sha256=(
                        chain_receipt_sha256
                    ),
                    transcript_chain_sha256=(
                        turn_start.transcript_chain_sha256
                    ),
                    thread_rebinding_receipt_path=rebinding_path,
                    thread_rebinding_receipt_sha256=rebinding_sha256,
                )
                proxy.codex_thread_id = launched.codex_thread_id
                proxy.codex_turn_id = launched.codex_turn_id
                proxy.thread_binding_path = launched.thread_binding_path
                proxy.thread_binding_sha256 = (
                    launched.thread_binding_sha256
                )
                proxy.bridge_runtime_attestation_sha256 = (
                    launched.bridge_runtime_attestation_sha256
                )
                proxy.app_server_runtime_receipt_sha256 = (
                    launched.app_server_runtime_receipt_sha256
                )
                proxy.transcript_chain_sha256 = (
                    launched.transcript_chain_sha256
                )
                failure_stage = "backend-launch-commit"
                _write_private_json_new(
                    _expected_backend_launch_path(spec),
                    {
                        **_bound_receipt_base(
                            spec, kind="contiguous_backend_launch"
                        ),
                        "launch": asdict(launched),
                    },
                )
                runtime.bridge_events = bridge_events
                runtime.backend_launch = launched
                thread = threading.Thread(
                    target=self._controller_turn_main,
                    args=(runtime, spec),
                    name=(
                        "arc-agi3-controller-"
                        + runtime.low_spec.identity.attempt_id[:12]
                    ),
                    daemon=False,
                )
                runtime.controller_thread = thread
                failure_stage = "controller-thread-start"
                thread.start()
                return launched
            except BaseException as original:
                if type(original).__name__ == "SimulatedCrash":
                    raise
                self._reconcile_failed_launch(
                    spec=spec,
                    runtime=runtime,
                    intent_sha256=intent_sha256,
                    failure_stage=failure_stage,
                    original=original,
                )
                runtime.backend_launch = None
                if isinstance(original, _SubstratePreflightFailure):
                    (
                        failure_path,
                        failure_sha256,
                    ) = self._materialize_substrate_failure_receipt(
                        spec=spec,
                        substrate_identity_sha256=(
                            original.substrate_identity_sha256
                        ),
                        failure_stage=original.stage,
                        error_type=original.error_type,
                        failure_class=original.failure_class,
                        failure_code=original.failure_code,
                    )
                    raise _runner_contract().BackendSubstratePreflightError(
                        substrate_identity_sha256=(
                            original.substrate_identity_sha256
                        ),
                        failure_receipt_path=failure_path,
                        failure_receipt_sha256=failure_sha256,
                    ) from original
                raise ContainerContractError(
                    "backend launch failed, was exactly reconciled, and is "
                    "durably terminal"
                ) from original

    def poll(
        self,
        *,
        spec: Any,
        prepared: Any,
        launched: Any,
        timeout_seconds: float,
    ) -> Any:
        """Return observed state; never turn a soft allocation into a signal."""
        runtime = self._runtime_for(
            spec, prepared=prepared, launched=launched
        )
        self._require_lifecycle_bindings(runtime, prepared, launched)
        if (
            isinstance(timeout_seconds, bool)
            or not isinstance(timeout_seconds, (int, float))
            or not math.isfinite(timeout_seconds)
            or timeout_seconds <= 0
        ):
            raise ContainerContractError(
                "backend poll timeout must be a positive finite number"
            )
        if runtime.orphaned_after_supervisor_restart:
            runner_contract = _runner_contract()
            poll = runner_contract.BackendPoll(
                status=runtime.orphan_terminal_status,
                observation_sha256=runtime.orphan_observation_sha256,
                exit_code=(
                    0 if runtime.orphan_terminal_status == "exited" else None
                ),
            )
            with self._lock:
                if (
                    runtime.terminal_poll is not None
                    and runtime.terminal_poll != poll
                ):
                    raise ContainerContractError(
                        "orphan terminal observation changed"
                    )
                runtime.terminal_poll = poll
            return poll
        observed = self._backend.observe_container_state(
            runtime.attestation,
            runtime.low_spec,
            timeout_seconds=min(float(timeout_seconds), 60.0),
        )
        if runtime.arena_protocol_violation is not None:
            if (
                runtime.arena_protocol_violation_sha256 is None
                or runtime.arena_protocol_containment_sha256 is None
                or observed.running
            ):
                raise ContainerContractError(
                    "public-action protocol-invalid containment did not "
                    "quiesce the proposer"
                )
            if runtime.controller_thread is not None:
                runtime.controller_thread.join(
                    timeout=min(float(timeout_seconds), 5.0)
                )
            if (
                runtime.controller_thread is not None
                and runtime.controller_thread.is_alive()
            ):
                # The solver/export cgroup and bridge are already revoked.
                # Keep the lifecycle nonterminal only while the host-owned
                # controller drains to an exact accounting/containment barrier.
                body = {
                    "kind": "arena_public_action_protocol_invalid_drain",
                    "attempt_id": runtime.low_spec.identity.attempt_id,
                    "protocol_violation_sha256":
                        runtime.arena_protocol_violation_sha256,
                    "proposer_containment_sha256":
                        runtime.arena_protocol_containment_sha256,
                    "controller_terminal": False,
                }
                return _runner_contract().BackendPoll(
                    status="running",
                    observation_sha256=_json_sha256(body),
                    exit_code=None,
                )
            status = "containment_fault"
            exit_code = observed.exit_code
        elif observed.running:
            if observed.status != "running":
                # Paused/restarting containers are not declared safely
                # terminal while their output can still change.  The release
                # gate requires a separate immediate containment path.
                raise ContainerContractError(
                    "live container entered an abnormal lifecycle state"
                )
            status = "running"
            exit_code = None
        elif (
            observed.status == "exited"
            and not observed.oom_killed
            and not observed.error
        ):
            if runtime.controller_thread is not None:
                runtime.controller_thread.join(
                    timeout=min(float(timeout_seconds), 5.0)
                )
            status = (
                "containment_fault"
                if runtime.controller_error is not None
                or (
                    runtime.controller_thread is not None
                    and runtime.controller_thread.is_alive()
                )
                else "exited"
            )
            exit_code = observed.exit_code
        else:
            status = "containment_fault"
            exit_code = observed.exit_code
        runner_contract = _runner_contract()
        poll = runner_contract.BackendPoll(
            status=status,
            observation_sha256=observed.observation_sha256,
            exit_code=exit_code,
        )
        if status != "running":
            with self._lock:
                if (
                    runtime.terminal_poll is not None
                    and runtime.terminal_poll != poll
                ):
                    raise ContainerContractError(
                        "terminal container observation changed"
                    )
                runtime.terminal_poll = poll
        return poll

    def _collect_public_action_protocol_invalid(
        self,
        *,
        spec: Any,
        runtime: _AdapterRuntime,
    ) -> Any:
        """Retain bounded scans, then emit a typed protocol-invalid result."""

        runner_contract = _runner_contract()
        violation = runtime.arena_protocol_violation
        if (
            violation is None
            or runtime.arena_protocol_violation_sha256 is None
            or runtime.arena_protocol_containment_sha256 is None
            or runtime.controller_teardown_evidence is None
        ):
            raise ContainerContractError(
                "public-action protocol-invalid result lacks terminal "
                "containment evidence"
            )
        host_root = Path(
            _runner_field(spec, "host_transcript_path")
        ).parent
        output_root = runtime.low_spec.export_root
        state_root = Path(_runner_field(spec, "app_server_state_dir"))
        attempt_canaries = self._ensure_canary_escrow(spec)
        try:
            import arc_agi3_contiguous_taint as taint_contract

            inventory = probe_transport.inventory_controller_state(
                state_root,
                sentinels=_controller_credential_sentinels(
                    runtime.controller,
                    originals=self._credentials.leak_sentinels,
                    maximum_refreshes=_runner_field(
                        spec, "max_auth_refreshes"
                    ),
                ),
            )
            state_scan = taint_contract.scan_controller_state(
                state_root,
                inventory=inventory,
                canaries=attempt_canaries,
            )
            state_path, state_sha256 = _ensure_bound_receipt(
                host_root / "controller_state_scan_receipt.json",
                spec=spec,
                kind="contiguous_controller_state_scan",
                fields={
                    "scanner_source_sha256":
                        taint_contract.source_sha256(),
                    "controller_state_scan": state_scan.as_receipt(),
                },
            )
            if runtime.turn_start_evidence is None:
                raise ContainerContractError(
                    "protocol-invalid scan lacks turn-start binding"
                )
            live_sentinels = _controller_credential_sentinels(
                runtime.controller,
                originals=self._credentials.leak_sentinels,
                maximum_refreshes=_runner_field(
                    spec, "max_auth_refreshes"
                ),
            )
            app_server_policy = taint_contract.AppServerScanPolicy(
                state_root=CONTROLLER_STATE_DESTINATION,
                neutral_cwd=CONTROLLER_NEUTRAL_DESTINATION,
                model=_runner_field(
                    spec, "proposer_transport"
                ).model,
                model_provider=_runner_field(
                    spec, "proposer_transport"
                ).model_provider,
                reasoning_effort=_runner_field(spec, "effort"),
                thread_mode=_runner_field(spec, "thread_mode"),
                resume_thread_id=_runner_field(
                    spec, "resume_thread_id"
                ),
                prompt_sha256=(
                    runtime.turn_start_evidence.prompt_sha256
                ),
                hard_safety_seconds=_runner_field(
                    spec, "hard_safety_seconds"
                ),
                max_auth_refreshes=_runner_field(
                    spec, "max_auth_refreshes"
                ),
                secret_sentinels=live_sentinels,
            )
            partial_scan_records = [
                taint_contract.scan_evidence(
                    Path(_runner_field(
                        spec, "app_server_transcript_path"
                    )),
                    evidence_kind="app_server_jsonl",
                    app_server_policy=app_server_policy,
                ),
                taint_contract.scan_evidence(
                    Path(_runner_field(
                        spec, "host_transcript_path"
                    )),
                    evidence_kind="backend_jsonl",
                ),
                *[
                    taint_contract.scan_evidence(
                        entry,
                        evidence_kind="candidate_output",
                    )
                    for entry in sorted(
                        entry
                        for entry in output_root.rglob("*")
                        if entry.is_file()
                    )
                ],
                *state_scan.records,
            ]
            partial_taint_hits = sorted({
                hit
                for record in partial_scan_records
                for hit in record.hits
            })
            partial_taint_path, partial_taint_sha256 = (
                _ensure_bound_receipt(
                    host_root
                    / "protocol_invalid_partial_taint_scan_receipt.json",
                    spec=spec,
                    kind=(
                        "contiguous_protocol_invalid_partial_taint_scan"
                    ),
                    fields={
                        "scanner_source_sha256":
                            taint_contract.source_sha256(),
                        "records": [
                            asdict(record)
                            for record in partial_scan_records
                        ],
                        "hits": partial_taint_hits,
                        "status": (
                            "TAINT"
                            if partial_taint_hits
                            else "CLEAN"
                        ),
                        "classification_authority":
                            "source_environment_taint_only",
                    },
                )
            )
            final_evidence = runtime.turn_final_evidence
            usage_complete = False
            token_observations: list[dict[str, Any]] = []
            post_window: dict[str, Any] | None = None
            settlement: dict[str, Any] | None = None
            if (
                runtime.launched is not None
                and isinstance(
                    final_evidence,
                    probe_transport.TurnFinalEvidence,
                )
            ):
                try:
                    _validate_turn_final_evidence(
                        final_evidence,
                        spec=spec,
                        thread_id=runtime.launched.codex_thread_id,
                        turn_id=runtime.launched.codex_turn_id,
                    )
                except ContainerContractError:
                    pass
                else:
                    usage_complete = True
                    token_observations = [
                        dict(item)
                        for item in
                        final_evidence.token_usage_observations
                    ]
                    post_window = asdict(
                        final_evidence.post_provider_usage_window
                    )
                    settlement = asdict(
                        final_evidence.provider_usage_settlement
                    )
            observed_total_tokens = None
            if token_observations:
                total = token_observations[-1].get("total")
                if isinstance(total, dict):
                    candidate_total = total.get("totalTokens")
                    if (
                        isinstance(candidate_total, int)
                        and not isinstance(candidate_total, bool)
                        and candidate_total >= 0
                    ):
                        observed_total_tokens = candidate_total
            partial_usage_path, partial_usage_sha256 = (
                _ensure_bound_receipt(
                    host_root
                    / "protocol_invalid_partial_usage_receipt.json",
                    spec=spec,
                    kind=(
                        "contiguous_protocol_invalid_partial_usage"
                    ),
                    fields={
                        "thread_id": (
                            runtime.launched.codex_thread_id
                            if runtime.launched is not None
                            else None
                        ),
                        "turn_id": (
                            runtime.launched.codex_turn_id
                            if runtime.launched is not None
                            else None
                        ),
                        "pre_provider_usage_window": asdict(
                            runtime.preflight_evidence
                            .provider_usage_window
                        ),
                        "token_usage_observations":
                            token_observations,
                        "observed_total_tokens":
                            observed_total_tokens,
                        "post_provider_usage_window": post_window,
                        "provider_usage_settlement": settlement,
                        "accounting_complete": usage_complete,
                        "unknown_token_usage": not usage_complete,
                        "cost_settlement_authority": False,
                    },
                )
            )
            retained_scan = taint_contract.scan_retained_canary_roots(
                {
                    "host_evidence": host_root,
                    "proposer_output": output_root,
                },
                canaries=attempt_canaries,
            )
            retained_path, retained_sha256 = _ensure_bound_receipt(
                Path(_runner_field(spec, "generation_dir"))
                / "retained_canary_scan_receipt.json",
                spec=spec,
                kind="contiguous_retained_canary_scan",
                fields={
                    "scanner_source_sha256":
                        taint_contract.source_sha256(),
                    "retained_canary_scan":
                        retained_scan.as_receipt(),
                    "controller_state_scan_receipt_sha256":
                        state_sha256,
                },
            )
        except Exception as exc:
            raise ContainerContractError(
                "public-action protocol-invalid terminal scans failed"
            ) from exc
        # A finite reservation is charged conservatively in full because the
        # rejected RPC intentionally aborts postflight provider accounting.
        # An explicitly unlimited campaign has no finite local denomination to
        # charge; retain zero here and the protocol receipt says why.
        remaining = _runner_field(spec, "cost_limit_remaining")
        cost_used = 0.0 if remaining is None else float(remaining)
        receipt_path, receipt_sha256 = _ensure_bound_receipt(
            host_root
            / "arena_public_action_protocol_invalid_receipt.json",
            spec=spec,
            kind="contiguous_arena_public_action_protocol_invalid",
            fields={
                "protocol_violation": dict(violation),
                "protocol_violation_sha256":
                    runtime.arena_protocol_violation_sha256,
                "proposer_containment_sha256":
                    runtime.arena_protocol_containment_sha256,
                "controller_absence_receipt_sha256":
                    runtime.controller_teardown_evidence
                    .controller_absence_receipt_sha256,
                "controller_state_scan_receipt_path": state_path,
                "controller_state_scan_receipt_sha256":
                    state_sha256,
                "retained_canary_scan_receipt_path":
                    retained_path,
                "retained_canary_scan_receipt_sha256":
                    retained_sha256,
                "partial_taint_scan_receipt_path":
                    partial_taint_path,
                "partial_taint_scan_receipt_sha256":
                    partial_taint_sha256,
                "partial_taint_status": (
                    "TAINT" if partial_taint_hits else "CLEAN"
                ),
                "partial_usage_receipt_path": partial_usage_path,
                "partial_usage_receipt_sha256":
                    partial_usage_sha256,
                "usage_accounting_complete": usage_complete,
                "cost_used": cost_used,
                "cost_authority": (
                    "full_finite_reservation"
                    if remaining is not None
                    else "explicit_unlimited_no_local_charge"
                ),
                "candidate_admissible": False,
                "wip_admissible": False,
                "public_observation_admissible": False,
                "sidecar_request_admissible": False,
                "supervisory_handoff_admissible": False,
                "promotion_admissible": False,
                "restart_restoration_admissible": False,
                "status": "PROTOCOL_INVALID",
            },
        )
        runtime.collection = ProtocolInvalidCollectionEvidence(
            controller_state_scan_receipt_path=state_path,
            controller_state_scan_receipt_sha256=state_sha256,
            retained_canary_scan_receipt_path=retained_path,
            retained_canary_scan_receipt_sha256=retained_sha256,
        )
        raise runner_contract.BackendPublicActionProtocolInvalidError(
            receipt_path=receipt_path,
            receipt_sha256=receipt_sha256,
            controller_state_scan_receipt_path=state_path,
            controller_state_scan_receipt_sha256=state_sha256,
            retained_canary_scan_receipt_path=retained_path,
            retained_canary_scan_receipt_sha256=retained_sha256,
            partial_taint_scan_receipt_path=partial_taint_path,
            partial_taint_scan_receipt_sha256=partial_taint_sha256,
            partial_usage_receipt_path=partial_usage_path,
            partial_usage_receipt_sha256=partial_usage_sha256,
            cost_used=cost_used,
        )

    def collect(
        self,
        *,
        spec: Any,
        prepared: Any,
        launched: Any,
        terminal: Any,
    ) -> Any:
        """Collect only quiescent output and trusted host Arena evidence."""
        attempt_canaries = self._ensure_canary_escrow(spec)
        runtime = self._runtime_for(
            spec, prepared=prepared, launched=launched
        )
        self._require_lifecycle_bindings(runtime, prepared, launched)
        with self._lock:
            if runtime.collection is not None:
                if runtime.terminal_poll != terminal:
                    raise ContainerContractError(
                        "collection terminal observation changed"
                    )
                return runtime.collection
            if (
                runtime.orphaned_after_supervisor_restart
                and runtime.terminal_poll is None
                and getattr(terminal, "status", None) != "running"
            ):
                runtime.terminal_poll = terminal
            if (
                runtime.terminal_poll is None
                or terminal != runtime.terminal_poll
                or getattr(terminal, "status", None) == "running"
            ):
                raise ContainerContractError(
                    "collection requires the exact terminal poll"
                )
            if not runtime.orphaned_after_supervisor_restart:
                if runtime.controller_thread is None:
                    raise ContainerContractError(
                        "collection has no host controller turn"
                    )
                runtime.controller_thread.join(timeout=5)
                if runtime.controller_thread.is_alive():
                    raise ContainerContractError(
                        "host controller remained live after container terminal"
                    )
                if runtime.arena_protocol_violation is not None:
                    return self._collect_public_action_protocol_invalid(
                        spec=spec, runtime=runtime
                    )
                if runtime.controller_error is not None:
                    raise ContainerContractError(
                        "host controller turn failed before complete evidence"
                    ) from runtime.controller_error
                final_evidence = runtime.turn_final_evidence
                controller_teardown = (
                    runtime.controller_teardown_evidence
                )
                _validate_turn_final_evidence(
                    final_evidence,
                    spec=spec,
                    thread_id=launched.codex_thread_id,
                    turn_id=launched.codex_turn_id,
                )
                _validate_controller_teardown_evidence(
                    controller_teardown,
                    spec=spec,
                    preflight=runtime.preflight_evidence,
                )
                self._probe_executor.prove_attempt_probe_absence(
                    spec=spec, stage="pre_collection"
                )
            else:
                raise ContainerContractError(
                    "ownerless app-server collection has no complete "
                    "controller lineage"
                )
            _require_same_mount(
                runtime.attestation.parent_input,
                _snapshot_mount_root(
                    runtime.low_spec.parent_input,
                    label="post-run parent input",
                    require_empty=False,
                    require_private=False,
                ),
                label="parent input",
            )
            _require_same_endpoint(
                runtime.attestation.arena_token_file,
                _snapshot_endpoint(
                    runtime.low_spec.arena_token_file,
                    label="post-run Arena RPC token",
                    expected_kind="token",
                ),
                label="Arena RPC token",
            )
            rpc_clean = _finish_arena_server(
                session=runtime.arena_session,
                server=runtime.arena_server,
                thread=runtime.arena_thread,
                socket_path=runtime.low_spec.arena_socket,
                client_factory=self._arena_client_factory,
            ) and not runtime.orphaned_after_supervisor_restart
            _validate_arena_transcript_binding(spec)
            arena_host_result: Any | None = None
            if rpc_clean and runtime.arena_session is not None:
                try:
                    arena_host_result = runtime.arena_session.host_result()
                except Exception:
                    arena_host_result = None
            logs = self._backend.collect_terminal_logs(
                runtime.attestation, runtime.low_spec
            )
            host_root = Path(
                _runner_field(spec, "host_transcript_path")
            ).parent
            stdout_path = host_root / "container_stdout.log"
            stderr_path = host_root / "container_stderr.log"
            stdout_raw = logs.stdout.encode("utf-8")
            stderr_raw = logs.stderr.encode("utf-8")
            stdout_sha256 = _ensure_private_immutable_bytes(
                stdout_path,
                stdout_raw,
                label="container stdout",
                maximum_bytes=MAX_CONTAINER_STREAM_BYTES,
            )
            stderr_sha256 = _ensure_private_immutable_bytes(
                stderr_path,
                stderr_raw,
                label="container stderr",
                maximum_bytes=MAX_CONTAINER_STREAM_BYTES,
            )
            if (
                stdout_sha256 != logs.stdout_sha256
                or stderr_sha256 != logs.stderr_sha256
            ):
                raise ContainerContractError(
                    "immutable container streams differ from Docker evidence"
                )
            token_value = getattr(runtime.arena_session, "token", None)
            if token_value is None:
                token_value = _read_private_token_text(
                    runtime.low_spec.arena_token_file
                )
            _append_host_transcript_event(
                Path(_runner_field(spec, "host_transcript_path")),
                {
                    "schema": 1,
                    "kind": "container_logs",
                    "container_id": runtime.attestation.container_id,
                    "observation_sha256": logs.observation_sha256,
                    "stdout_sha256": logs.stdout_sha256,
                    "stderr_sha256": logs.stderr_sha256,
                    "stdout_path": str(stdout_path),
                    "stderr_path": str(stderr_path),
                    "stdout_bytes": logs.stdout_bytes,
                    "stderr_bytes": logs.stderr_bytes,
                    "stdout_excerpt": _sanitized_log_excerpt(
                        logs.stdout, token=token_value
                    ),
                    "stderr_excerpt": _sanitized_log_excerpt(
                        logs.stderr, token=token_value
                    ),
                    "excerpt_limit_chars": MAX_CAPTURED_LOG_CHARS,
                },
            )

            output_root = runtime.low_spec.export_root
            output_tree_sha256 = _validated_tree_hash(
                output_root, label="attempt output"
            )
            outcome_path = output_root / Path(OUTCOME_DESTINATION).name
            if not outcome_path.exists() or outcome_path.is_symlink():
                raise ContainerContractError(
                    "proposer worker outcome is missing or aliased"
                )
            worker_outcome = _read_unaliased_json(
                outcome_path, label="worker outcome"
            )
            _validate_worker_outcome(
                worker_outcome,
                role=runtime.low_spec.role,
                attempt_id=runtime.low_spec.identity.attempt_id,
                solver_path=runtime.low_spec.parent_input / "solve.py",
            )
            worker_outcome_sha256 = _hash_unaliased_regular_file(
                outcome_path, label="worker outcome"
            )

            transcript_path = Path(
                _runner_field(spec, "host_transcript_path")
            )
            host_transcript_sha256 = _hash_unaliased_regular_file(
                transcript_path, label="host transcript"
            )
            native_public_observation_receipt_sha256s = (
                _persist_public_observation_receipts(
                    session=runtime.arena_session,
                    spec=spec,
                    transcript_path=transcript_path,
                )
                if runtime.arena_session is not None
                else ()
            )
            (
                supervisory_reproduction_path,
                supervisory_reproduction_sha256,
                _supervisory_reproduction,
            ) = _derive_supervisory_native_reproduction(
                spec=spec,
                native_receipt_sha256s=(
                    native_public_observation_receipt_sha256s
                ),
                host_transcript_sha256=host_transcript_sha256,
            )
            app_transcript_path = Path(
                _runner_field(spec, "app_server_transcript_path")
            )
            app_transcript_sha256 = _hash_unaliased_regular_file(
                app_transcript_path, label="app-server transcript"
            )
            if arena_host_result is not None:
                _validate_arena_host_result(
                    arena_host_result, spec=spec
                )
            result = self._result_collector(
                spec,
                terminal,
                arena_host_result,
                worker_outcome,
                output_root,
            )
            if (
                _validated_tree_hash(
                    output_root, label="post-collector attempt output"
                )
                != output_tree_sha256
                or _hash_unaliased_regular_file(
                    transcript_path, label="post-collector host transcript"
                )
                != host_transcript_sha256
                or _hash_unaliased_regular_file(
                    app_transcript_path,
                    label="post-collector app-server transcript",
                )
                != app_transcript_sha256
            ):
                raise ContainerContractError(
                    "trusted result collector mutated admitted evidence"
                )
            runner_contract = _runner_contract()
            if not isinstance(result, runner_contract.AttemptResult):
                raise ContainerContractError(
                    "trusted result collector returned the wrong result type"
                )
            if result.candidate is not None:
                handoff_binding = _runner_field(
                    spec, "supervisory_handoff"
                )
                result = replace(
                    result,
                    candidate=replace(
                        result.candidate,
                        supervisory_handoff_sha256=(
                            handoff_binding
                            .supervisory_handoff_sha256
                            if handoff_binding is not None
                            else None
                        ),
                        supervisory_native_reproduction_receipt_sha256=(
                            supervisory_reproduction_sha256
                            if handoff_binding is not None
                            else None
                        ),
                    ),
                )
            host_blocker_code = _host_blocker_code(
                arena_host_result, spec=spec
            )
            host_blocker_evidence: Any | None = None
            if result.kind == "blocker":
                # The collector/model label is never authority.  Preserve a
                # pending blocker only when independent host Arena state
                # establishes the finite code; strip all supplied evidence.
                result = runner_contract.AttemptResult(
                    kind=(
                        "blocker"
                        if host_blocker_code is not None
                        else "infrastructure"
                    ),
                    cost_used=float(result.cost_used),
                    reason=(
                        ""
                        if host_blocker_code is not None
                        else "rejected unauthenticated blocker claim"
                    ),
                )
            candidate_evidence: AuthenticatedCandidateEvidence | None = None
            wip_evidence: AuthenticatedWipEvidence | None = None
            if result.kind == "candidate":
                if (
                    result.candidate is None
                    or arena_host_result is None
                    or runtime.target_boundary_evidence is None
                    or arena_host_result.levels_completed
                    != _runner_field(spec, "target_level")
                ):
                    raise ContainerContractError(
                        "promotion candidate lacks an exact trusted K-to-K+1 "
                        "Arena result"
                    )
                candidate_evidence = (
                    _validate_authenticated_candidate_export(
                        spec=spec,
                        candidate=result.candidate,
                        arena_host_result=arena_host_result,
                        output_root=output_root,
                        bridge_events=runtime.bridge_events or (),
                        target_boundary=(
                            runtime.target_boundary_evidence
                        ),
                    )
                )
            wip_manifest_path = output_root / WIP_MANIFEST_NAME
            if wip_manifest_path.exists() or wip_manifest_path.is_symlink():
                if (
                    result.kind != "clean_no_progress"
                    or result.candidate is not None
                    or result.wip is not None
                    or candidate_evidence is not None
                    or runtime.target_boundary_evidence is not None
                ):
                    raise ContainerContractError(
                        "retained WIP is not an exact clean no-progress outcome"
                    )
                wip_evidence = _validate_authenticated_wip_export(
                    spec=spec,
                    output_root=output_root,
                    bridge_events=runtime.bridge_events or (),
                )
            elif result.wip is not None:
                raise ContainerContractError(
                    "collector supplied WIP without an authenticated manifest"
                )
            if (
                not rpc_clean
                and not runtime.orphan_collectible_export
                and result.kind not in {
                "tainted",
                "infrastructure",
                "blocker",
                }
            ):
                raise ContainerContractError(
                    "failed Arena RPC cannot yield an admissible result"
                )
            effective_result = (
                _apply_terminal_result_precedence(
                    runner_contract,
                    terminal_status=terminal.status,
                    result=result,
                )
            )
            if effective_result != result:
                result = effective_result
                # Preserve the exported bytes for quarantine/forensics, but
                # remove every route by which a containment-fault candidate or
                # WIP could become admitted execution authority.
                candidate_evidence = None
                wip_evidence = None
                runtime.target_boundary_evidence = None
            if (
                final_evidence.provider_outcome != "completed"
                and result.kind != "infrastructure"
            ):
                raise ContainerContractError(
                    "structured provider failure must be infrastructure"
                )
            if (
                final_evidence.provider_outcome == "completed"
                and final_evidence.turn_status != "completed"
            ):
                raise ContainerContractError(
                    "completed provider outcome has a noncompleted turn"
                )
            live_credential_sentinels = (
                _controller_credential_sentinels(
                    runtime.controller,
                    originals=self._credentials.leak_sentinels,
                    maximum_refreshes=_runner_field(
                        spec, "max_auth_refreshes"
                    ),
                )
            )
            try:
                controller_state_inventory = (
                    probe_transport.inventory_controller_state(
                        Path(
                            _runner_field(
                                spec, "app_server_state_dir"
                            )
                        ),
                        sentinels=live_credential_sentinels,
                    )
                )
            except probe_transport.AppServerTransportError as exc:
                raise ContainerContractError(
                    "controller state inventory is inadmissible"
                ) from exc
            state_tree_sha256 = (
                controller_state_inventory.tree_sha256
            )
            try:
                import arc_agi3_contiguous_taint as taint_contract

                controller_state_scan = (
                    taint_contract.scan_controller_state(
                        Path(
                            _runner_field(
                                spec, "app_server_state_dir"
                            )
                        ),
                        inventory=controller_state_inventory,
                        canaries=attempt_canaries,
                    )
                )
            except Exception as exc:
                raise ContainerContractError(
                    "controller state failed its complete taint/canary scan"
                ) from exc
            try:
                initial_retained_canary_scan = (
                    taint_contract.scan_retained_canary_roots(
                        {
                            "host_evidence": host_root,
                            "proposer_output": output_root,
                        },
                        canaries=attempt_canaries,
                    )
                )
            except Exception as exc:
                raise ContainerContractError(
                    "retained evidence failed its initial canary scan"
                ) from exc
            if (
                controller_state_scan.hits
                or controller_state_scan.canary_occurrences
                or controller_state_scan.status != "CLEAN"
                or initial_retained_canary_scan.hits
                or initial_retained_canary_scan.canary_occurrences
                or initial_retained_canary_scan.status != "CLEAN"
            ):
                containment_hits = sorted(
                    {
                        *controller_state_scan.hits,
                        *initial_retained_canary_scan.hits,
                    }
                )
                result = runner_contract.AttemptResult(
                    kind="tainted",
                    cost_used=float(result.cost_used),
                    reason=(
                        "containment_taint:"
                        + ",".join(containment_hits)
                    ),
                    candidate=None,
                    wip=None,
                )
                candidate_evidence = None
                wip_evidence = None
                runtime.target_boundary_evidence = None
            if (
                controller_state_inventory.secret_occurrences
                or
                state_tree_sha256
                != controller_teardown.state_tree_sha256
                or final_evidence.transcript_chain_sha256
                != controller_teardown.transcript_chain_sha256
            ):
                raise ContainerContractError(
                    "controller teardown differs from final turn/state evidence"
                )
            state_scan_path, state_scan_sha256 = _ensure_bound_receipt(
                host_root / "controller_state_scan_receipt.json",
                spec=spec,
                kind="contiguous_controller_state_scan",
                fields={
                    "scanner_source_sha256":
                        taint_contract.source_sha256(),
                    "controller_state_scan":
                        controller_state_scan.as_receipt(),
                },
            )
            token_path, token_sha256 = _ensure_bound_receipt(
                host_root / "token_usage_receipt.json",
                spec=spec,
                kind="contiguous_token_usage",
                fields={
                    "thread_id": launched.codex_thread_id,
                    "turn_id": launched.codex_turn_id,
                    "observations": list(
                        final_evidence.token_usage_observations
                    ),
                    "hard_safety_seconds":
                        final_evidence.hard_safety_seconds,
                    "max_auth_refreshes":
                        final_evidence.max_auth_refreshes,
                    "auth_refresh_count":
                        final_evidence.auth_refresh_count,
                    "redacted_auth_refresh_response_sha256": list(
                        final_evidence
                        .redacted_auth_refresh_response_sha256
                    ),
                    "credential_sentinel_scan_passed":
                        final_evidence
                        .credential_sentinel_scan_passed,
                    "post_turn_event_count":
                        final_evidence.post_turn_event_count,
                    "stdout_bytes": final_evidence.stdout_bytes,
                    "stderr_bytes": final_evidence.stderr_bytes,
                    "pipes_drained_to_eof":
                        final_evidence.pipes_drained_to_eof,
                    "final_event_observed": True,
                    "wrong_identity_events": 0,
                    "duplicate_events": 0,
                },
            )
            try:
                if runtime.preflight_evidence is None:
                    raise ContainerContractError(
                        "provider settlement lacks preflight evidence"
                    )
                pre_usage_window = (
                    probe_transport.provider_usage_window_from_dict(
                        asdict(
                            final_evidence
                            .pre_provider_usage_window
                        )
                    )
                )
                post_usage_window = (
                    probe_transport.provider_usage_window_from_dict(
                        asdict(
                            final_evidence
                            .post_provider_usage_window
                        )
                    )
                )
                provider_usage_settlement = (
                    probe_transport
                    .provider_usage_settlement_from_dict(
                        asdict(
                            final_evidence
                            .provider_usage_settlement
                        ),
                        pre=pre_usage_window,
                        post=post_usage_window,
                        token_usage_observations=(
                            final_evidence.token_usage_observations
                        ),
                    )
                )
            except Exception as exc:
                raise ContainerContractError(
                    "provider usage evidence failed typed settlement"
                ) from exc
            if (
                pre_usage_window
                != runtime.preflight_evidence.provider_usage_window
                or provider_usage_settlement
                != final_evidence.provider_usage_settlement
            ):
                raise ContainerContractError(
                    "provider usage settlement is not bound to preflight/turn"
                )
            # The injected result collector never has authority over accounting.
            # Replace its float with the independently authenticated settlement.
            result = replace(
                result,
                cost_used=float(provider_usage_settlement.charge),
            )
            provider_usage_path, provider_usage_sha256 = (
                _ensure_bound_receipt(
                    host_root / "provider_usage_receipt.json",
                    spec=spec,
                    kind="contiguous_provider_usage",
                    fields={
                        "thread_id": launched.codex_thread_id,
                        "turn_id": launched.codex_turn_id,
                        "token_usage_observations": list(
                            final_evidence.token_usage_observations
                        ),
                        "pre_provider_usage_window":
                            asdict(pre_usage_window),
                        "post_provider_usage_window":
                            asdict(post_usage_window),
                        "provider_usage_settlement":
                            asdict(provider_usage_settlement),
                    },
                )
            )
            final_chain_path, final_chain_receipt_sha256 = (
                _ensure_bound_receipt(
                    host_root / "final_transcript_chain_receipt.json",
                    spec=spec,
                    kind="contiguous_final_transcript_chain",
                    fields={
                        "thread_id": launched.codex_thread_id,
                        "turn_id": launched.codex_turn_id,
                        "chain_head_sha256":
                            final_evidence.transcript_chain_sha256,
                        "raw_transcript_sha256":
                            app_transcript_sha256,
                        "event_count":
                            final_evidence.transcript_event_count,
                    },
                )
            )
            if (
                host_blocker_code is not None
                and result.kind in {"clean_no_progress", "blocker"}
            ):
                if arena_host_result is None:
                    raise ContainerContractError(
                        "host blocker lost its Arena result"
                    )
                host_blocker_evidence = _ensure_host_blocker_receipt(
                    spec=spec,
                    arena_host_result=arena_host_result,
                    code=host_blocker_code,
                    canaries=attempt_canaries,
                )
                result = runner_contract.AttemptResult(
                    kind="blocker",
                    cost_used=float(result.cost_used),
                    reason=(
                        runner_contract.HOST_BLOCKER_REASON_PREFIX
                        + host_blocker_code
                    ),
                    blocker=host_blocker_evidence,
                )
                candidate_evidence = None
                wip_evidence = None
                runtime.target_boundary_evidence = None
            bridge_events = runtime.bridge_events or []
            publish_requests = [
                payload
                for kind, payload in bridge_events
                if kind == "bridge_request"
                and payload.get("operation")
                in {"candidate_publish", "wip_publish"}
            ]
            export_fields: dict[str, Any] = {
                "container_id": launched.container_id,
                "bridge_runtime_attestation_sha256":
                    launched.bridge_runtime_attestation_sha256,
                "output_tree_sha256": output_tree_sha256,
                "model_final_text_eligible": False,
                "outcome": result.kind,
                "host_blocker_code": (
                    host_blocker_evidence.code
                    if host_blocker_evidence is not None
                    else None
                ),
                "host_blocker_receipt_sha256": (
                    host_blocker_evidence.receipt_sha256
                    if host_blocker_evidence is not None
                    else None
                ),
                "candidate_manifest_sha256": (
                    result.candidate.candidate_manifest_sha256
                    if result.candidate is not None
                    else None
                ),
                "authenticated_candidate_path_sha256": (
                    _arena_wire_sha256(
                        list(candidate_evidence.normalized_path)
                    )
                    if candidate_evidence is not None
                    else None
                ),
                "authenticated_candidate_source_set_sha256": (
                    _json_sha256(
                        dict(candidate_evidence.exported_files_sha256)
                    )
                    if candidate_evidence is not None
                    else None
                ),
                "candidate_publish_request_sha256": (
                    candidate_evidence.publish_request_sha256
                    if candidate_evidence is not None
                    else None
                ),
                "candidate_publish_response_sha256": (
                    candidate_evidence.publish_response_sha256
                    if candidate_evidence is not None
                    else None
                ),
                "wip_manifest_sha256": (
                    wip_evidence.manifest_sha256
                    if wip_evidence is not None
                    else None
                ),
                "wip_tree_sha256": (
                    wip_evidence.wip_tree_sha256
                    if wip_evidence is not None
                    else None
                ),
                "solver_source_tree_sha256": (
                    wip_evidence.solver_source_tree_sha256
                    if wip_evidence is not None
                    else None
                ),
                "wip_publish_request_sha256": (
                    wip_evidence.publish_request_sha256
                    if wip_evidence is not None
                    else None
                ),
                "wip_publish_response_sha256": (
                    wip_evidence.publish_response_sha256
                    if wip_evidence is not None
                    else None
                ),
                "target_boundary_receipt_sha256": (
                    runtime.target_boundary_evidence.receipt_sha256
                    if runtime.target_boundary_evidence is not None
                    else None
                ),
                "target_boundary_sha256": (
                    runtime.target_boundary_evidence.boundary_sha256
                    if runtime.target_boundary_evidence is not None
                    else None
                ),
                "target_boundary_workspace_tree_sha256": (
                    runtime.target_boundary_evidence
                    .workspace_tree_sha256
                    if runtime.target_boundary_evidence is not None
                    else None
                ),
                "publication_request_sha256": [
                    _json_sha256(item) for item in publish_requests
                ],
            }
            if result.kind == "candidate" and not any(
                item.get("operation") == "candidate_publish"
                for item in publish_requests
            ):
                raise ContainerContractError(
                    "candidate result lacks an authenticated bridge publication"
                )
            export_path, export_sha256 = _ensure_bound_receipt(
                host_root / "bridge_export_receipt.json",
                spec=spec,
                kind="contiguous_bridge_export",
                fields=export_fields,
            )
            wip_export_path: str | None = None
            wip_export_sha256: str | None = None
            if wip_evidence is not None:
                wip_export_path, wip_export_sha256 = (
                    _ensure_bound_receipt(
                        host_root / "wip_export_receipt.json",
                        spec=spec,
                        kind="contiguous_wip_export",
                        fields={
                            "outcome": "wip",
                            "manifest_path": str(
                                wip_evidence.manifest_path
                            ),
                            "manifest_sha256":
                                wip_evidence.manifest_sha256,
                            "wip_root_path": str(
                                wip_evidence.wip_root_path
                            ),
                            "wip_tree_sha256":
                                wip_evidence.wip_tree_sha256,
                            "solver_source_path": str(
                                wip_evidence.solver_source_path
                            ),
                            "solver_source_tree_sha256":
                                wip_evidence
                                .solver_source_tree_sha256,
                            "exported_files_sha256": dict(
                                wip_evidence
                                .exported_files_sha256
                            ),
                            "publish_request_sha256":
                                wip_evidence
                                .publish_request_sha256,
                            "publish_response_sha256":
                                wip_evidence
                                .publish_response_sha256,
                            "total_export_bytes":
                                wip_evidence.total_export_bytes,
                            "bridge_export_receipt_sha256":
                                export_sha256,
                        },
                    )
                )
            scanned_sha256 = {
                "app_server_transcript": app_transcript_sha256,
                "backend_transcript": host_transcript_sha256,
                "container_stderr": stderr_sha256,
                "container_stdout": stdout_sha256,
                "output_tree": output_tree_sha256,
                "app_server_state_tree": state_tree_sha256,
            }
            secret_occurrences = _secret_occurrence_count(
                paths=(),
                tree_roots=(host_root, output_root),
                sentinels=live_credential_sentinels,
            )
            if secret_occurrences:
                raise ContainerContractError(
                    "external credential bytes entered retained evidence"
                )
            secret_path, secret_sha256 = _ensure_bound_receipt(
                host_root / "secret_scan_receipt.json",
                spec=spec,
                kind="contiguous_secret_scan",
                fields={
                    "scanned_sha256": scanned_sha256,
                    "controller_state_inventory":
                        controller_state_inventory.as_receipt(),
                    "secret_occurrences": 0,
                    "credential_generations_scanned":
                        final_evidence.auth_refresh_count + 1,
                    "controller_terminal_scan_passed":
                        final_evidence
                        .credential_sentinel_scan_passed,
                    "status": "PASS",
                },
            )
            try:
                import arc_agi3_contiguous_taint as taint_contract

                if runtime.turn_start_evidence is None:
                    raise ContainerContractError(
                        "app-server taint scan lacks the retained turn binding"
                    )
                app_server_policy = taint_contract.AppServerScanPolicy(
                    state_root=CONTROLLER_STATE_DESTINATION,
                    neutral_cwd=CONTROLLER_NEUTRAL_DESTINATION,
                    model=_runner_field(
                        spec, "proposer_transport"
                    ).model,
                    model_provider=_runner_field(
                        spec, "proposer_transport"
                    ).model_provider,
                    reasoning_effort=_runner_field(spec, "effort"),
                    thread_mode=_runner_field(spec, "thread_mode"),
                    resume_thread_id=_runner_field(
                        spec, "resume_thread_id"
                    ),
                    prompt_sha256=(
                        runtime.turn_start_evidence.prompt_sha256
                    ),
                    hard_safety_seconds=_runner_field(
                        spec, "hard_safety_seconds"
                    ),
                    max_auth_refreshes=_runner_field(
                        spec, "max_auth_refreshes"
                    ),
                    # These values are deliberately live-only.  They are used
                    # by the scanner below and never copied into a receipt.
                    secret_sentinels=live_credential_sentinels,
                )
                scan_records = [
                    taint_contract.scan_evidence(
                        app_transcript_path,
                        evidence_kind="app_server_jsonl",
                        app_server_policy=app_server_policy,
                    ),
                    taint_contract.scan_evidence(
                        transcript_path,
                        evidence_kind="backend_jsonl",
                    ),
                    taint_contract.scan_evidence(
                        stdout_path,
                        evidence_kind="container_stdout",
                    ),
                    taint_contract.scan_evidence(
                        stderr_path,
                        evidence_kind="container_stderr",
                    ),
                    *[
                        taint_contract.scan_evidence(
                            entry,
                            evidence_kind="candidate_output",
                        )
                        for entry in sorted(
                            entry
                            for entry in output_root.rglob("*")
                            if entry.is_file()
                        )
                    ],
                    *[
                        taint_contract.scan_evidence(
                            entry,
                            evidence_kind="candidate_output",
                        )
                        for entry in sorted(
                            entry
                            for entry in (
                                Path(
                                    runtime.target_boundary_evidence
                                    .snapshot_root
                                ).rglob("*")
                                if runtime.target_boundary_evidence
                                is not None
                                else ()
                            )
                            if entry.is_file()
                        )
                    ],
                    *controller_state_scan.records,
                ]
            except Exception as exc:
                raise ContainerContractError(
                    "trusted taint scan could not inspect collected evidence"
                ) from exc
            actionable_taint = sorted(
                {
                    hit
                    for record in scan_records
                    for hit in record.hits
                }
            )
            if actionable_taint and result.kind != "tainted":
                raise ContainerContractError(
                    "actionable taint was not classified as tainted"
                )
            taint_path, taint_sha256 = _ensure_bound_receipt(
                host_root / "taint_scan_receipt.json",
                spec=spec,
                kind="contiguous_taint_scan",
                fields={
                    "scanner_source_sha256":
                        taint_contract.source_sha256(),
                    "records": [
                        asdict(record) for record in scan_records
                    ],
                    "hits": actionable_taint,
                    "status": (
                        "TAINT" if actionable_taint else "CLEAN"
                    ),
                },
            )
            try:
                retained_canary_scan = (
                    taint_contract.scan_retained_canary_roots(
                        {
                            "host_evidence": host_root,
                            "proposer_output": output_root,
                        },
                        canaries=attempt_canaries,
                    )
                )
            except Exception as exc:
                raise ContainerContractError(
                    "retained evidence failed its terminal canary scan"
                ) from exc
            if (
                not initial_retained_canary_scan.hits
                and not initial_retained_canary_scan.canary_occurrences
                and (
                    retained_canary_scan.hits
                    or retained_canary_scan.canary_occurrences
                )
            ):
                raise ContainerContractError(
                    "trusted receipt generation introduced a containment canary"
                )
            retained_canary_path, retained_canary_sha256 = (
                _ensure_bound_receipt(
                    Path(_runner_field(spec, "generation_dir"))
                    / "retained_canary_scan_receipt.json",
                    spec=spec,
                    kind="contiguous_retained_canary_scan",
                    fields={
                        "scanner_source_sha256":
                            taint_contract.source_sha256(),
                        "retained_canary_scan":
                            retained_canary_scan.as_receipt(),
                        "controller_state_scan_receipt_sha256":
                            state_scan_sha256,
                    },
                )
            )
            retained_canary_raw = _read_unaliased_bytes(
                Path(retained_canary_path),
                label="retained canary scan receipt",
                maximum_bytes=MAX_INSPECT_BYTES,
            )
            if any(
                item.value.encode("utf-8") in retained_canary_raw
                for item in attempt_canaries
            ):
                raise ContainerContractError(
                    "retained canary receipt serialized a live canary value"
                )
            final_binding_path, final_binding_sha256 = (
                _ensure_bound_receipt(
                    Path(_runner_field(spec, "generation_dir"))
                    / "final_thread_binding.json",
                    spec=spec,
                    kind="contiguous_final_thread_binding",
                    fields={
                        "thread_id": launched.codex_thread_id,
                        "turn_id": launched.codex_turn_id,
                        "thread_mode": _runner_field(
                            spec, "thread_mode"
                        ),
                        "turn_status":
                            final_evidence.turn_status,
                        "provider_outcome":
                            final_evidence.provider_outcome,
                        "transcript_chain_sha256":
                            final_evidence.transcript_chain_sha256,
                        "final_transcript_chain_receipt_sha256":
                            final_chain_receipt_sha256,
                        "token_usage_receipt_sha256":
                            token_sha256,
                        "provider_usage_receipt_sha256":
                            provider_usage_sha256,
                        "bridge_export_receipt_sha256":
                            export_sha256,
                        "host_blocker_code": (
                            host_blocker_evidence.code
                            if host_blocker_evidence is not None
                            else None
                        ),
                        "host_blocker_receipt_sha256": (
                            host_blocker_evidence.receipt_sha256
                            if host_blocker_evidence is not None
                            else None
                        ),
                        "secret_scan_receipt_sha256":
                            secret_sha256,
                        "app_server_state_tree_sha256":
                            state_tree_sha256,
                        "controller_state_inventory_sha256":
                            controller_state_inventory.inventory_sha256,
                        "controller_state_scan_receipt_sha256":
                            state_scan_sha256,
                        "retained_canary_scan_receipt_sha256":
                            retained_canary_sha256,
                        "taint_scan_receipt_sha256":
                            taint_sha256,
                        "wip_export_receipt_sha256":
                            (
                                wip_export_sha256
                                if result.kind
                                == "clean_no_progress"
                                else None
                            ),
                        "target_boundary_receipt_sha256": (
                            runtime.target_boundary_evidence
                            .receipt_sha256
                            if runtime.target_boundary_evidence
                            is not None
                            else None
                        ),
                        "target_boundary_sha256": (
                            runtime.target_boundary_evidence
                            .boundary_sha256
                            if runtime.target_boundary_evidence
                            is not None
                            else None
                        ),
                        "target_boundary_workspace_tree_sha256": (
                            runtime.target_boundary_evidence
                            .workspace_tree_sha256
                            if runtime.target_boundary_evidence
                            is not None
                            else None
                        ),
                        "model_final_text_sha256":
                            final_evidence.final_model_text_sha256,
                        "model_final_text_eligible": False,
                    },
                )
            )
            final_binding_canary_scan = (
                taint_contract.scan_canaries_in_file(
                    Path(final_binding_path),
                    canaries=attempt_canaries,
                    evidence_kind="final_thread_binding",
                )
            )
            if (
                final_binding_canary_scan.hits
                or final_binding_canary_scan.sha256
                != final_binding_sha256
            ):
                raise ContainerContractError(
                    "final thread binding leaks a live containment canary"
                )

            if (
                wip_evidence is not None
                and result.kind == "clean_no_progress"
            ):
                if (
                    wip_export_path is None
                    or wip_export_sha256 is None
                    or actionable_taint
                    or controller_state_scan.status != "CLEAN"
                    or retained_canary_scan.status != "CLEAN"
                    or final_evidence.provider_outcome != "completed"
                    or final_evidence.turn_status != "completed"
                ):
                    raise ContainerContractError(
                        "unclean/incomplete WIP reached publication"
                    )
                wip_publication_path = (
                    Path(_runner_field(spec, "generation_dir"))
                    / "wip_publication_receipt.json"
                )
                wip_fields = {
                    "snapshot_id":
                        f"wip-{_runner_field(spec, 'attempt_id')}",
                    "wip_root_path":
                        str(wip_evidence.wip_root_path),
                    "wip_tree_sha256":
                        wip_evidence.wip_tree_sha256,
                    "solver_source_path":
                        str(wip_evidence.solver_source_path),
                    "solver_source_tree_sha256":
                        wip_evidence.solver_source_tree_sha256,
                    "game": _runner_field(spec, "game"),
                    "target_level":
                        _runner_field(spec, "target_level"),
                    "parent_checkpoint_sha256":
                        _runner_field(
                            spec, "parent_checkpoint_sha256"
                        ),
                    "frontier_sha256":
                        _runner_field(spec, "frontier_sha256"),
                    "codex_thread_id": launched.codex_thread_id,
                    "final_thread_binding_path":
                        final_binding_path,
                    "final_thread_binding_sha256":
                        final_binding_sha256,
                    "wip_export_receipt_path": wip_export_path,
                    "wip_export_receipt_sha256":
                        wip_export_sha256,
                    "final_transcript_chain_receipt_path":
                        final_chain_path,
                    "final_transcript_chain_receipt_sha256":
                        final_chain_receipt_sha256,
                    "transcript_chain_sha256":
                        final_evidence.transcript_chain_sha256,
                    "controller_state_scan_receipt_path":
                        state_scan_path,
                    "controller_state_scan_receipt_sha256":
                        state_scan_sha256,
                    "retained_canary_scan_receipt_path":
                        retained_canary_path,
                    "retained_canary_scan_receipt_sha256":
                        retained_canary_sha256,
                    "taint_scan_receipt_path": taint_path,
                    "taint_scan_receipt_sha256": taint_sha256,
                    "token_usage_receipt_path": token_path,
                    "token_usage_receipt_sha256": token_sha256,
                    "provider_usage_receipt_path":
                        provider_usage_path,
                    "provider_usage_receipt_sha256":
                        provider_usage_sha256,
                    "app_server_state_dir":
                        _runner_field(spec, "app_server_state_dir"),
                    "app_server_state_tree_sha256":
                        state_tree_sha256,
                    "supervisory_handoff_sha256": (
                        _runner_field(
                            spec, "supervisory_handoff"
                        ).supervisory_handoff_sha256
                        if _runner_field(
                            spec, "supervisory_handoff"
                        )
                        is not None
                        else None
                    ),
                    "supervisory_native_reproduction_receipt_path":
                        supervisory_reproduction_path,
                    "supervisory_native_reproduction_receipt_sha256":
                        supervisory_reproduction_sha256,
                    "taint_verdict": "clean",
                }
                (
                    wip_publication_receipt_path,
                    wip_publication_receipt_sha256,
                ) = _ensure_bound_receipt(
                    wip_publication_path,
                    spec=spec,
                    kind="contiguous_wip_publication",
                    fields=wip_fields,
                )
                publication_canary_scan = (
                    taint_contract.scan_canaries_in_file(
                        Path(wip_publication_receipt_path),
                        canaries=attempt_canaries,
                        evidence_kind="wip_publication_receipt",
                    )
                )
                if (
                    publication_canary_scan.hits
                    or publication_canary_scan.sha256
                    != wip_publication_receipt_sha256
                ):
                    raise ContainerContractError(
                        "WIP publication leaks a live containment canary"
                    )
                result = replace(
                    result,
                    wip=runner_contract.WipSnapshot(
                        **wip_fields,
                        wip_publication_receipt_path=(
                            wip_publication_receipt_path
                        ),
                        wip_publication_receipt_sha256=(
                            wip_publication_receipt_sha256
                        ),
                    ),
                )
            collection = runner_contract.BackendCollection(
                result=result,
                worker_outcome_sha256=worker_outcome_sha256,
                output_tree_sha256=output_tree_sha256,
                host_transcript_path=str(transcript_path),
                host_transcript_sha256=host_transcript_sha256,
                native_public_observation_receipt_sha256s=(
                    native_public_observation_receipt_sha256s
                ),
                container_stdout_path=str(stdout_path),
                container_stdout_sha256=stdout_sha256,
                container_stderr_path=str(stderr_path),
                container_stderr_sha256=stderr_sha256,
                app_server_transcript_path=str(app_transcript_path),
                app_server_transcript_sha256=app_transcript_sha256,
                codex_thread_id=launched.codex_thread_id,
                codex_turn_id=launched.codex_turn_id,
                structured_turn_status=final_evidence.turn_status,
                structured_provider_outcome=(
                    final_evidence.provider_outcome
                ),
                token_usage_receipt_path=token_path,
                token_usage_receipt_sha256=token_sha256,
                provider_usage_receipt_path=provider_usage_path,
                provider_usage_receipt_sha256=(
                    provider_usage_sha256
                ),
                final_transcript_chain_receipt_path=final_chain_path,
                final_transcript_chain_receipt_sha256=(
                    final_chain_receipt_sha256
                ),
                final_transcript_chain_sha256=(
                    final_evidence.transcript_chain_sha256
                ),
                final_thread_binding_path=final_binding_path,
                final_thread_binding_sha256=final_binding_sha256,
                bridge_export_receipt_path=export_path,
                bridge_export_receipt_sha256=export_sha256,
                secret_scan_receipt_path=secret_path,
                secret_scan_receipt_sha256=secret_sha256,
                controller_state_scan_receipt_path=state_scan_path,
                controller_state_scan_receipt_sha256=state_scan_sha256,
                controller_state_inventory_sha256=(
                    controller_state_inventory.inventory_sha256
                ),
                retained_canary_scan_receipt_path=(
                    retained_canary_path
                ),
                retained_canary_scan_receipt_sha256=(
                    retained_canary_sha256
                ),
                supervisory_native_reproduction_receipt_path=(
                    supervisory_reproduction_path
                ),
                supervisory_native_reproduction_receipt_sha256=(
                    supervisory_reproduction_sha256
                ),
                target_boundary_receipt_path=(
                    runtime.target_boundary_evidence.receipt_path
                    if runtime.target_boundary_evidence is not None
                    else None
                ),
                target_boundary_receipt_sha256=(
                    runtime.target_boundary_evidence.receipt_sha256
                    if runtime.target_boundary_evidence is not None
                    else None
                ),
                target_boundary_sha256=(
                    runtime.target_boundary_evidence.boundary_sha256
                    if runtime.target_boundary_evidence is not None
                    else None
                ),
                target_boundary_workspace_tree_sha256=(
                    runtime.target_boundary_evidence
                    .workspace_tree_sha256
                    if runtime.target_boundary_evidence is not None
                    else None
                ),
                taint_scan_receipt_path=taint_path,
                taint_scan_receipt_sha256=taint_sha256,
                app_server_state_tree_sha256=state_tree_sha256,
                model_final_text_sha256=(
                    final_evidence.final_model_text_sha256
                ),
            )
            runtime.collection = collection
            return collection

    def teardown(
        self,
        *,
        spec: Any,
        prepared: Any,
        launched: Any,
        cause: str,
    ) -> Any:
        """Remove the exact cgroup, then close and remove private RPC secrets."""
        durable_proof = self._load_durable_teardown_proof(
            spec=spec,
            prepared=prepared,
            launched=launched,
            cause=cause,
        )
        if durable_proof is not None:
            return durable_proof
        recovered_proof = self._recover_completed_teardown_from_intent(
            spec=spec,
            prepared=prepared,
            launched=launched,
            cause=cause,
        )
        if recovered_proof is not None:
            return recovered_proof
        runtime = self._runtime_for(
            spec, prepared=prepared, launched=launched
        )
        self._require_lifecycle_bindings(runtime, prepared, launched)
        if cause not in {"normal_exit", "containment_fault"}:
            raise ContainerContractError(
                "runner teardown cause is not an explicit lifecycle cause"
            )
        with self._lock:
            if runtime.teardown_proof is not None:
                if runtime.teardown_proof.cause != cause:
                    raise ContainerContractError(
                        "teardown cause changed after proof"
                    )
                return runtime.teardown_proof
            if (
                runtime.collection is None
                and not runtime.orphaned_after_supervisor_restart
            ):
                raise ContainerContractError(
                    "runner teardown requires completed host collection"
                )
            low_cause = (
                TeardownCause.NORMAL_EXIT
                if cause == "normal_exit"
                else TeardownCause.CONTAINMENT_FAULT
            )
            if runtime.launched is None:
                raise ContainerContractError(
                    "runner teardown has no launched attempt"
                )
            if (
                runtime.controller_teardown_evidence is None
                or (
                    runtime.controller_error is not None
                    and runtime.arena_protocol_violation is None
                )
            ):
                raise ContainerContractError(
                    "runner teardown lacks exact app-server containment evidence"
                )
            _validate_controller_teardown_evidence(
                runtime.controller_teardown_evidence,
                spec=spec,
                preflight=runtime.preflight_evidence,
            )
            self._ensure_teardown_intent(
                spec=spec,
                prepared=prepared,
                launched=launched,
                cause=cause,
            )
            low_proof = self._backend.teardown(
                runtime.launched,
                cause=low_cause,
            )
            probe_reconciliation = (
                self._probe_executor.reconcile_attempt_probes(
                    spec=spec, stage="teardown"
                )
            )
            if runtime.arena_volume_runtime is None:
                raise ContainerContractError(
                    "runner teardown lacks its Arena relay ownership"
                )
            arena_volume_teardown = (
                self._arena_volume_lifecycle.teardown(
                    identity=runtime.low_spec.identity,
                    runtime=runtime.arena_volume_runtime,
                    receipt_root=Path(
                        _runner_field(spec, "host_transcript_path")
                    ).parent,
                    containment_fault=(
                        cause == "containment_fault"
                    ),
                )
            )
            runtime.arena_volume_teardown_evidence = (
                arena_volume_teardown
            )
            _finish_arena_server(
                session=runtime.arena_session,
                server=runtime.arena_server,
                thread=runtime.arena_thread,
                socket_path=runtime.low_spec.arena_socket,
                client_factory=self._arena_client_factory,
            )
            _unlink_owned_attempt_file(
                runtime.low_spec.arena_socket, label="Arena socket"
            )
            _unlink_owned_attempt_file(
                runtime.low_spec.arena_token_file, label="Arena token"
            )
            _unlink_owned_attempt_file(
                runtime.low_spec.bridge_socket,
                label="proposer bridge socket",
            )
            _unlink_owned_attempt_file(
                runtime.low_spec.bridge_token_file,
                label="proposer bridge token",
            )
            _unlink_owned_attempt_file(
                Path(_runner_field(spec, "app_server_control_dir"))
                / "process_absent.json",
                label="app-server process-absence receipt",
            )
            _remove_empty_owned_directory(
                Path(_runner_field(spec, "app_server_control_dir")),
                label="app-server control directory",
            )
            endpoints_absent = not (
                runtime.low_spec.arena_socket.exists()
                or runtime.low_spec.arena_socket.is_symlink()
                or runtime.low_spec.arena_token_file.exists()
                or runtime.low_spec.arena_token_file.is_symlink()
            )
            bridge_absent = not (
                runtime.low_spec.bridge_socket.exists()
                or runtime.low_spec.bridge_socket.is_symlink()
                or runtime.low_spec.bridge_token_file.exists()
                or runtime.low_spec.bridge_token_file.is_symlink()
            )
            app_control = Path(
                _runner_field(spec, "app_server_control_dir")
            )
            app_control_absent = not (
                app_control.exists() or app_control.is_symlink()
            )
            no_descendants = (
                low_proof.no_descendants
                and not _thread_is_alive(runtime.arena_thread)
                and endpoints_absent
                and bridge_absent
                and app_control_absent
                and runtime.controller_teardown_evidence
                .process_absent
                and runtime.controller_teardown_evidence
                .process_group_absent
                and runtime.controller_teardown_evidence
                .controller_no_descendants
                and runtime.controller_teardown_evidence
                .egress_proxy_no_descendants
                and probe_reconciliation["identity_query_empty"]
                and arena_volume_teardown.relay_inspect_absent
                and arena_volume_teardown.relay_top_absent
                and arena_volume_teardown
                .relay_identity_query_empty
                and arena_volume_teardown.volume_inspect_absent
                and arena_volume_teardown
                .volume_identity_query_empty
            )
            if not no_descendants:
                raise ContainerContractError(
                    "attempt teardown did not eliminate every owned runtime"
                )
            if runtime.collection is None:
                raise ContainerContractError(
                    "terminal canary reveal requires the validated durable "
                    "collection"
                )
            (
                canary_reveal_path,
                canary_reveal_sha256,
            ) = self._ensure_terminal_canary_reveal(
                spec=spec,
                prepared=prepared,
                controller_state_scan_receipt_path=(
                    runtime.collection
                    .controller_state_scan_receipt_path
                ),
                controller_state_scan_receipt_sha256=(
                    runtime.collection
                    .controller_state_scan_receipt_sha256
                ),
                retained_canary_scan_receipt_path=(
                    runtime.collection
                    .retained_canary_scan_receipt_path
                ),
                retained_canary_scan_receipt_sha256=(
                    runtime.collection
                    .retained_canary_scan_receipt_sha256
                ),
                container_id=low_proof.container_id,
                controller_container_id=(
                    runtime.controller_teardown_evidence
                    .controller_container_id
                ),
                egress_proxy_container_id=(
                    runtime.controller_teardown_evidence
                    .egress_proxy_container_id
                ),
                container_proof_sha256=low_proof.proof_sha256,
            )
            (
                canary_cleanup_receipt_path,
                canary_cleanup_receipt_sha256,
            ) = self._ensure_terminal_canary_cleanup(
                spec=spec,
                canary_reveal_path=canary_reveal_path,
                canary_reveal_sha256=canary_reveal_sha256,
            )
            proof_body = {
                "schema": 1,
                "kind": "completed-teardown",
                "campaign_id": low_proof.campaign_id,
                "generation_id": low_proof.generation_id,
                "attempt_id": low_proof.attempt_id,
                "container_proof_sha256": low_proof.proof_sha256,
                "container_id": low_proof.container_id,
                "cause": cause,
                "container_inspect_absent": (
                    low_proof.container_inspect_absent
                ),
                "container_top_absent": low_proof.container_top_absent,
                "identity_query_empty": (
                    low_proof.identity_label_query_empty
                ),
                "no_descendants": no_descendants,
                "rpc_thread_absent": True,
                "rpc_socket_absent": True,
                "rpc_token_absent": True,
                "app_server_process_absent": True,
                "app_server_process_group_absent": True,
                "bridge_socket_absent": True,
                "bridge_token_absent": True,
                "app_server_control_absent": True,
                "arena_relay_container_id":
                    arena_volume_teardown.relay_container_id,
                "arena_volume_name":
                    arena_volume_teardown.volume_name,
                "arena_relay_inspect_absent": True,
                "arena_relay_top_absent": True,
                "arena_relay_identity_query_empty": True,
                "arena_volume_inspect_absent": True,
                "arena_volume_identity_query_empty": True,
                "arena_relay_attachment_status":
                    arena_volume_teardown.attachment_status,
                "arena_relay_teardown_receipt_path":
                    arena_volume_teardown.receipt_path,
                "arena_relay_teardown_receipt_sha256":
                    arena_volume_teardown.receipt_sha256,
                "process_identity_authority":
                    "controller_container_cgroup",
                "controller_container_id":
                    runtime.controller_teardown_evidence
                    .controller_container_id,
                "egress_proxy_container_id":
                    runtime.controller_teardown_evidence
                    .egress_proxy_container_id,
                "controller_inspect_absent": True,
                "controller_identity_query_empty": True,
                "controller_top_absent": True,
                "controller_no_descendants": True,
                "egress_proxy_inspect_absent": True,
                "egress_proxy_identity_query_empty": True,
                "egress_proxy_top_absent": True,
                "egress_proxy_no_descendants": True,
                "controller_absence_receipt_sha256":
                    runtime.controller_teardown_evidence
                    .controller_absence_receipt_sha256,
                "probe_reconciliation_receipt_sha256":
                    probe_reconciliation["receipt_sha256"],
                "canary_reveal_path": canary_reveal_path,
                "canary_reveal_sha256": canary_reveal_sha256,
                "canary_cleanup_receipt_path":
                    canary_cleanup_receipt_path,
                "canary_cleanup_receipt_sha256":
                    canary_cleanup_receipt_sha256,
            }
            runner_contract = _runner_contract()
            proof = runner_contract.BackendTeardownProof(
                container_id=low_proof.container_id,
                cause=cause,
                proof_sha256=_json_sha256(proof_body),
                container_inspect_absent=(
                    low_proof.container_inspect_absent
                ),
                container_top_absent=low_proof.container_top_absent,
                identity_query_empty=(
                    low_proof.identity_label_query_empty
                ),
                no_descendants=no_descendants,
                app_server_process_absent=True,
                app_server_process_group_absent=True,
                bridge_socket_absent=True,
                bridge_token_absent=True,
                app_server_control_absent=True,
                arena_relay_container_id=(
                    arena_volume_teardown.relay_container_id
                ),
                arena_volume_name=arena_volume_teardown.volume_name,
                arena_relay_inspect_absent=True,
                arena_relay_top_absent=True,
                arena_relay_identity_query_empty=True,
                arena_volume_inspect_absent=True,
                arena_volume_identity_query_empty=True,
                arena_relay_attachment_status=(
                    arena_volume_teardown.attachment_status
                ),
                arena_relay_teardown_receipt_path=(
                    arena_volume_teardown.receipt_path
                ),
                arena_relay_teardown_receipt_sha256=(
                    arena_volume_teardown.receipt_sha256
                ),
                process_identity_authority=
                    "controller_container_cgroup",
                controller_container_id=(
                    runtime.controller_teardown_evidence
                    .controller_container_id
                ),
                egress_proxy_container_id=(
                    runtime.controller_teardown_evidence
                    .egress_proxy_container_id
                ),
                controller_inspect_absent=True,
                controller_identity_query_empty=True,
                controller_top_absent=True,
                controller_no_descendants=True,
                egress_proxy_inspect_absent=True,
                egress_proxy_identity_query_empty=True,
                egress_proxy_top_absent=True,
                egress_proxy_no_descendants=True,
                controller_absence_receipt_sha256=(
                    runtime.controller_teardown_evidence
                    .controller_absence_receipt_sha256
                ),
                canary_reveal_path=canary_reveal_path,
                canary_reveal_sha256=canary_reveal_sha256,
                canary_cleanup_receipt_path=(
                    canary_cleanup_receipt_path
                ),
                canary_cleanup_receipt_sha256=(
                    canary_cleanup_receipt_sha256
                ),
            )
            _write_private_json_new(
                _expected_teardown_proof_path(spec),
                {
                    "schema": 1,
                    "campaign_id": _runner_field(spec, "campaign_id"),
                    "attempt_id": _runner_field(spec, "attempt_id"),
                    "generation_id": _runner_field(spec, "generation_id"),
                    "preparation_id": prepared.preparation_id,
                    "backend_id": launched.backend_id,
                    "proof": asdict(proof),
                    "proof_body": proof_body,
                },
            )
            runtime.teardown_proof = proof
            return proof

    def _teardown_intent_document(
        self,
        *,
        spec: Any,
        prepared: Any,
        launched: Any,
        cause: str,
    ) -> dict[str, Any]:
        if cause not in {"normal_exit", "containment_fault"}:
            raise ContainerContractError(
                "runner teardown cause is not an explicit lifecycle cause"
            )
        runner_contract = _runner_contract()
        if (
            not isinstance(prepared, runner_contract.BackendPreparation)
            or not isinstance(launched, runner_contract.BackendLaunch)
        ):
            raise ContainerContractError(
                "teardown intent bindings have the wrong types"
            )
        return {
            "schema": 1,
            "campaign_id": _runner_field(spec, "campaign_id"),
            "attempt_id": _runner_field(spec, "attempt_id"),
            "generation_id": _runner_field(spec, "generation_id"),
            "preparation_id": prepared.preparation_id,
            "backend_id": launched.backend_id,
            "container_id": launched.container_id,
            "cause": cause,
        }

    def _ensure_teardown_intent(
        self,
        *,
        spec: Any,
        prepared: Any,
        launched: Any,
        cause: str,
    ) -> None:
        path = _expected_teardown_intent_path(spec)
        expected = self._teardown_intent_document(
            spec=spec,
            prepared=prepared,
            launched=launched,
            cause=cause,
        )
        if path.exists() or path.is_symlink():
            if _read_unaliased_json(
                path, label="durable teardown intent"
            ) != expected:
                raise ContainerContractError(
                    "durable teardown intent differs from this lifecycle"
                )
            return
        _write_private_json_new(path, expected)

    def _recover_completed_teardown_from_intent(
        self,
        *,
        spec: Any,
        prepared: Any,
        launched: Any,
        cause: str,
    ) -> Any | None:
        path = _expected_teardown_intent_path(spec)
        if not (path.exists() or path.is_symlink()):
            return None
        expected = self._teardown_intent_document(
            spec=spec,
            prepared=prepared,
            launched=launched,
            cause=cause,
        )
        if _read_unaliased_json(
            path, label="durable teardown intent"
        ) != expected:
            raise ContainerContractError(
                "durable teardown intent differs from this lifecycle"
            )
        runner_contract = _runner_contract()
        if (
            not isinstance(prepared, runner_contract.BackendPreparation)
            or not isinstance(launched, runner_contract.BackendLaunch)
        ):
            raise ContainerContractError(
                "teardown recovery bindings have the wrong types"
            )
        anchored = CanaryEscrowAnchor(
            escrow_path=prepared.controller_canary_escrow_path,
            escrow_sha256=prepared.controller_canary_escrow_sha256,
            escrow_identity_sha256=(
                prepared.controller_canary_escrow_identity_sha256
            ),
            commitments_json=(
                prepared.controller_canary_commitments_json
            ),
            commitments_sha256=(
                prepared.controller_canary_commitments_sha256
            ),
            placement_descriptors_json=(
                prepared
                .controller_canary_placement_descriptors_json
            ),
            placement_descriptors_sha256=(
                prepared
                .controller_canary_placement_descriptors_sha256
            ),
        )
        anchored.validate()
        if self._ensure_canary_anchor(spec) != anchored:
            raise ContainerContractError(
                "teardown recovery canary anchor changed"
            )
        container_id = launched.container_id
        inspect_absent = self._backend._expect_absent(
            (
                self._backend._docker,
                "container",
                "inspect",
                container_id,
            ),
            label="intent-recovery container inspection",
        )
        if not inspect_absent:
            return None
        top_absent = self._backend._expect_absent(
            (
                self._backend._docker,
                "container",
                "top",
                container_id,
                "-eo",
                "pid,ppid",
            ),
            label="intent-recovery process inventory",
        )
        identity = AttemptIdentity(
            campaign_id=_runner_field(spec, "campaign_id"),
            generation_id=_runner_field(spec, "generation_id"),
            attempt_id=_runner_field(spec, "attempt_id"),
            game=_runner_field(spec, "game"),
            target_level=_runner_field(spec, "target_level"),
        )
        identity.validate()
        identity_empty = not self._backend._identity_query(
            identity
        ).stdout.strip()
        if not (top_absent and identity_empty):
            raise ContainerContractError(
                "teardown intent cannot re-prove container/cgroup absence"
            )
        receipt_root = Path(
            _runner_field(spec, "host_transcript_path")
        ).parent
        arena_preparation = (
            self._arena_volume_lifecycle
            .reopen_preparation_after_teardown(
                identity=identity,
                transport=_runner_field(
                    spec, "proposer_transport"
                ),
                receipt_root=receipt_root,
                prepared=prepared,
            )
        )
        arena_volume_teardown = (
            self._arena_volume_lifecycle.recover_teardown(
                identity=identity,
                preparation=arena_preparation,
                transport=_runner_field(
                    spec, "proposer_transport"
                ),
                receipt_root=receipt_root,
                containment_fault=(cause == "containment_fault"),
            )
        )
        if self._controller_container_launcher is None:
            raise ContainerContractError(
                "teardown recovery lacks a controller-container authority"
            )
        binding = self._controller_binding(spec, prepared)
        controller_stop = (
            self._controller_container_launcher.recover_absence(
                binding=binding,
                controller_container_id=(
                    launched.controller_container_id
                ),
                egress_proxy_container_id=(
                    launched.egress_proxy_container_id
                ),
                controller_launch_receipt_sha256=(
                    launched.controller_launch_receipt_sha256
                ),
                guardian_start_receipt_sha256=(
                    launched
                    .controller_guardian_start_receipt_sha256
                ),
            )
        )
        if (
            controller_stop.controller_container_id
            != launched.controller_container_id
            or controller_stop.egress_proxy_container_id
            != launched.egress_proxy_container_id
            or any(
                getattr(controller_stop, name) is not True
                for name in (
                    "controller_inspect_absent",
                    "controller_identity_query_empty",
                    "controller_top_absent",
                    "controller_no_descendants",
                    "egress_proxy_inspect_absent",
                    "egress_proxy_identity_query_empty",
                    "egress_proxy_top_absent",
                    "egress_proxy_no_descendants",
                )
            )
        ):
            raise ContainerContractError(
                "teardown recovery controller absence is incomplete"
            )
        if (
            not _host_process_absent(launched.app_server_pid)
            or not _host_process_group_absent(
                launched.app_server_process_group_id
            )
        ):
            return None
        _reconcile_orphan_app_server_process(spec)
        for endpoint, label in (
            (Path(_runner_field(spec, "arena_socket_path")), "Arena socket"),
            (Path(_runner_field(spec, "arena_token_file_path")), "Arena token"),
            (
                Path(_runner_field(spec, "bridge_socket_path")),
                "proposer bridge socket",
            ),
            (
                Path(_runner_field(spec, "bridge_token_file_path")),
                "proposer bridge token",
            ),
        ):
            _unlink_owned_attempt_file(endpoint, label=label)
        _remove_empty_owned_directory(
            Path(_runner_field(spec, "app_server_control_dir")),
            label="app-server control directory",
        )
        probe_reconciliation = self._probe_executor.reconcile_attempt_probes(
            spec=spec, stage="teardown"
        )
        state_scan_path = (
            Path(_runner_field(spec, "host_transcript_path")).parent
            / "controller_state_scan_receipt.json"
        )
        retained_scan_path = (
            Path(_runner_field(spec, "generation_dir"))
            / "retained_canary_scan_receipt.json"
        )
        recovered_container_proof_sha256 = _json_sha256(
            {
                "container_id": container_id,
                "container_inspect_absent": True,
                "container_top_absent": True,
                "identity_query_empty": True,
            }
        )
        canary_reveal_path, canary_reveal_sha256 = (
            self._ensure_terminal_canary_reveal(
                spec=spec,
                prepared=prepared,
                controller_state_scan_receipt_path=str(
                    state_scan_path
                ),
                controller_state_scan_receipt_sha256=(
                    _hash_unaliased_regular_file(
                        state_scan_path,
                        label="recovered controller state scan receipt",
                    )
                ),
                retained_canary_scan_receipt_path=str(
                    retained_scan_path
                ),
                retained_canary_scan_receipt_sha256=(
                    _hash_unaliased_regular_file(
                        retained_scan_path,
                        label="recovered retained canary scan receipt",
                    )
                ),
                container_id=container_id,
                controller_container_id=(
                    launched.controller_container_id
                ),
                egress_proxy_container_id=(
                    launched.egress_proxy_container_id
                ),
                container_proof_sha256=(
                    recovered_container_proof_sha256
                ),
            )
        )
        (
            canary_cleanup_receipt_path,
            canary_cleanup_receipt_sha256,
        ) = self._ensure_terminal_canary_cleanup(
            spec=spec,
            canary_reveal_path=canary_reveal_path,
            canary_reveal_sha256=canary_reveal_sha256,
        )
        body = {
            "schema": 1,
            "kind": "recovered-unacknowledged-teardown",
            "campaign_id": _runner_field(spec, "campaign_id"),
            "generation_id": _runner_field(spec, "generation_id"),
            "attempt_id": _runner_field(spec, "attempt_id"),
            "container_proof_sha256":
                recovered_container_proof_sha256,
            "container_id": container_id,
            "cause": cause,
            "container_inspect_absent": True,
            "container_top_absent": True,
            "identity_query_empty": True,
            "no_descendants": True,
            "rpc_thread_absent": True,
            "rpc_socket_absent": True,
            "rpc_token_absent": True,
            "app_server_process_absent": True,
            "app_server_process_group_absent": True,
            "bridge_socket_absent": True,
            "bridge_token_absent": True,
            "app_server_control_absent": True,
            "arena_relay_container_id":
                arena_volume_teardown.relay_container_id,
            "arena_volume_name":
                arena_volume_teardown.volume_name,
            "arena_relay_inspect_absent": True,
            "arena_relay_top_absent": True,
            "arena_relay_identity_query_empty": True,
            "arena_volume_inspect_absent": True,
            "arena_volume_identity_query_empty": True,
            "arena_relay_attachment_status":
                arena_volume_teardown.attachment_status,
            "arena_relay_teardown_receipt_path":
                arena_volume_teardown.receipt_path,
            "arena_relay_teardown_receipt_sha256":
                arena_volume_teardown.receipt_sha256,
            "process_identity_authority":
                "controller_container_cgroup",
            "controller_container_id":
                launched.controller_container_id,
            "egress_proxy_container_id":
                launched.egress_proxy_container_id,
            "controller_inspect_absent": True,
            "controller_identity_query_empty": True,
            "controller_top_absent": True,
            "controller_no_descendants": True,
            "egress_proxy_inspect_absent": True,
            "egress_proxy_identity_query_empty": True,
            "egress_proxy_top_absent": True,
            "egress_proxy_no_descendants": True,
            "controller_absence_receipt_sha256":
                controller_stop.absence_receipt_sha256,
            "probe_reconciliation_receipt_sha256":
                probe_reconciliation["receipt_sha256"],
            "canary_reveal_path": canary_reveal_path,
            "canary_reveal_sha256": canary_reveal_sha256,
            "canary_cleanup_receipt_path":
                canary_cleanup_receipt_path,
            "canary_cleanup_receipt_sha256":
                canary_cleanup_receipt_sha256,
        }
        proof = runner_contract.BackendTeardownProof(
            container_id=container_id,
            cause=cause,
            proof_sha256=_json_sha256(body),
            container_inspect_absent=True,
            container_top_absent=True,
            identity_query_empty=True,
            no_descendants=True,
            app_server_process_absent=True,
            app_server_process_group_absent=True,
            bridge_socket_absent=True,
            bridge_token_absent=True,
            app_server_control_absent=True,
            arena_relay_container_id=(
                arena_volume_teardown.relay_container_id
            ),
            arena_volume_name=arena_volume_teardown.volume_name,
            arena_relay_inspect_absent=True,
            arena_relay_top_absent=True,
            arena_relay_identity_query_empty=True,
            arena_volume_inspect_absent=True,
            arena_volume_identity_query_empty=True,
            arena_relay_attachment_status=(
                arena_volume_teardown.attachment_status
            ),
            arena_relay_teardown_receipt_path=(
                arena_volume_teardown.receipt_path
            ),
            arena_relay_teardown_receipt_sha256=(
                arena_volume_teardown.receipt_sha256
            ),
            process_identity_authority=
                "controller_container_cgroup",
            controller_container_id=(
                launched.controller_container_id
            ),
            egress_proxy_container_id=(
                launched.egress_proxy_container_id
            ),
            controller_inspect_absent=True,
            controller_identity_query_empty=True,
            controller_top_absent=True,
            controller_no_descendants=True,
            egress_proxy_inspect_absent=True,
            egress_proxy_identity_query_empty=True,
            egress_proxy_top_absent=True,
            egress_proxy_no_descendants=True,
            controller_absence_receipt_sha256=(
                controller_stop.absence_receipt_sha256
            ),
            canary_reveal_path=canary_reveal_path,
            canary_reveal_sha256=canary_reveal_sha256,
            canary_cleanup_receipt_path=(
                canary_cleanup_receipt_path
            ),
            canary_cleanup_receipt_sha256=(
                canary_cleanup_receipt_sha256
            ),
        )
        _write_private_json_new(
            _expected_teardown_proof_path(spec),
            {
                "schema": 1,
                "campaign_id": _runner_field(spec, "campaign_id"),
                "attempt_id": _runner_field(spec, "attempt_id"),
                "generation_id": _runner_field(spec, "generation_id"),
                "preparation_id": prepared.preparation_id,
                "backend_id": launched.backend_id,
                "proof": asdict(proof),
                "proof_body": body,
            },
        )
        return proof

    def _rehydrate_orphan(
        self,
        spec: Any,
        *,
        prepared: Any | None,
        launched: Any | None,
    ) -> _AdapterRuntime:
        """Recover durable identity, then quarantine the ownerless attempt.

        The old in-process Arena session cannot honestly be reconstructed.
        Rehydration therefore proves the sole labelled container, quiesces it,
        and drives the runner through a containment-fault result and teardown.
        """
        canary_anchor = self._ensure_canary_anchor(spec)
        low_spec = validate_runner_attempt_contract(
            spec,
            recovery=True,
            containment_canary_anchor=canary_anchor,
        )
        attestation_path = _expected_attestation_path(spec)
        attestation = _load_launch_attestation(
            attestation_path,
            expected_sha256=(
                getattr(prepared, "launch_attestation_sha256", None)
            ),
        )
        self._backend._validate_attestation_object(attestation, low_spec)
        current_image = self._backend.inspect_image(
            low_spec.image_reference
        )
        _require_same_image(attestation.image, current_image)
        host_root = Path(_runner_field(spec, "host_transcript_path")).parent
        required_static_paths = (
            Path(_runner_field(spec, "bridge_policy_receipt_path")),
            host_root / "arena_session_binding_receipt.json",
            host_root / "neutral_cwd_attestation.json",
            host_root / "app_server_config_receipt.json",
            host_root / "codex_binary_receipt.json",
            host_root / "app_server_protocol_schema_receipt.json",
            host_root / "arena_volume_readiness.json",
            host_root / "arena_volume_preparation.json",
        )
        if any(
            not path.exists() or path.is_symlink()
            for path in required_static_paths
        ):
            raise ContainerContractError(
                "durable preparation lacks a pre-launch static receipt"
            )
        static_receipts = _prepare_static_receipts(spec)
        recovered_arena_receipt = _read_unaliased_json(
            Path(static_receipts["arena_binding"][0]),
            label="rehydrated Arena session binding receipt",
        )
        recovered_arena_event = recovered_arena_receipt.get(
            "binding_event"
        )
        if not isinstance(recovered_arena_event, dict):
            raise ContainerContractError(
                "rehydrated Arena session binding is malformed"
            )
        runner_contract = _runner_contract()
        recovered_transport = _runner_field(
            spec, "proposer_transport"
        )
        recovered_arena_volume = (
            self._arena_volume_lifecycle.rehydrate(
                identity=low_spec.identity,
                transport=recovered_transport,
                receipt_root=host_root,
            )
        )
        recovered_arena_evidence = (
            recovered_arena_volume.evidence
        )
        recovered_preparation = runner_contract.BackendPreparation(
            preparation_id=_preparation_id(
                attestation,
                canary_anchor,
                recovered_arena_evidence,
            ),
            launch_attestation_path=str(attestation_path),
            launch_attestation_sha256=attestation.document_sha256,
            observed_image_digest=attestation.image.manifest_digest,
            image_observation_sha256=attestation.image.observation_sha256,
            container_observation_sha256=(
                attestation.container_observation_sha256
            ),
            bridge_policy_receipt_path=(
                static_receipts["bridge_policy"][0]
            ),
            bridge_policy_receipt_sha256=(
                static_receipts["bridge_policy"][1]
            ),
            arena_session_binding_receipt_path=(
                static_receipts["arena_binding"][0]
            ),
            arena_session_binding_receipt_sha256=(
                static_receipts["arena_binding"][1]
            ),
            arena_transport=recovered_arena_evidence.transport,
            arena_volume_name=recovered_arena_evidence.volume_name,
            arena_volume_observation_sha256=(
                recovered_arena_evidence.volume_observation_sha256
            ),
            arena_relay_container_id=(
                recovered_arena_evidence.relay_container_id
            ),
            arena_relay_image_digest=(
                recovered_arena_evidence.relay_image_digest
            ),
            arena_relay_image_observation_sha256=(
                recovered_arena_evidence
                .relay_image_observation_sha256
            ),
            arena_relay_container_observation_sha256=(
                recovered_arena_evidence
                .relay_container_observation_sha256
            ),
            arena_relay_readiness_receipt_path=(
                recovered_arena_evidence.readiness_receipt_path
            ),
            arena_relay_readiness_receipt_sha256=(
                recovered_arena_evidence.readiness_receipt_sha256
            ),
            arena_relay_attach_argv_sha256=(
                recovered_arena_evidence.attach_argv_sha256
            ),
            arena_relay_socket_identity_sha256=(
                recovered_arena_evidence
                .arena_socket_identity_sha256
            ),
            arena_relay_preparation_receipt_path=(
                recovered_arena_evidence.preparation_receipt_path
            ),
            arena_relay_preparation_receipt_sha256=(
                recovered_arena_evidence.preparation_receipt_sha256
            ),
            probe_isolation_mode=recovered_arena_event[
                "probe_isolation_mode"
            ],
            probe_isolation_evidence_sha256=(
                recovered_arena_event[
                    "probe_isolation_evidence_sha256"
                ]
            ),
            neutral_cwd_attestation_path=(
                static_receipts["neutral_cwd"][0]
            ),
            neutral_cwd_attestation_sha256=(
                static_receipts["neutral_cwd"][1]
            ),
            app_server_config_receipt_path=(
                static_receipts["app_server_config"][0]
            ),
            app_server_config_receipt_sha256=(
                static_receipts["app_server_config"][1]
            ),
            codex_binary_receipt_path=(
                static_receipts["codex_binary"][0]
            ),
            codex_binary_receipt_sha256=(
                static_receipts["codex_binary"][1]
            ),
            protocol_schema_receipt_path=(
                static_receipts["protocol_schema"][0]
            ),
            protocol_schema_receipt_sha256=(
                static_receipts["protocol_schema"][1]
            ),
            controller_image_digest=(
                recovered_transport.controller_image_digest
            ),
            controller_egress_proxy_image_digest=(
                recovered_transport
                .controller_egress_proxy_image_digest
            ),
            controller_egress_policy_sha256=(
                recovered_transport.controller_egress_policy_sha256
            ),
            controller_canary_escrow_path=(
                canary_anchor.escrow_path
            ),
            controller_canary_escrow_sha256=(
                canary_anchor.escrow_sha256
            ),
            controller_canary_escrow_identity_sha256=(
                canary_anchor.escrow_identity_sha256
            ),
            controller_canary_commitments_json=(
                canary_anchor.commitments_json
            ),
            controller_canary_commitments_sha256=(
                canary_anchor.commitments_sha256
            ),
            controller_canary_placement_descriptors_json=(
                canary_anchor.placement_descriptors_json
            ),
            controller_canary_placement_descriptors_sha256=(
                canary_anchor.placement_descriptors_sha256
            ),
            controller_supply_chain_unobserved_until_launch=True,
        )
        if prepared is not None:
            if (
                not isinstance(prepared, runner_contract.BackendPreparation)
                or prepared != recovered_preparation
            ):
                raise ContainerContractError(
                    "durable backend preparation differs from the journal"
                )
        token = _snapshot_endpoint(
            low_spec.arena_token_file,
            label="rehydrated Arena RPC token",
            expected_kind="token",
        )
        _require_same_endpoint(
            attestation.arena_token_file,
            token,
            label="Arena RPC token",
        )
        bridge_token = _snapshot_endpoint(
            low_spec.bridge_token_file,
            label="rehydrated proposer bridge token",
            expected_kind="token",
        )
        if attestation.bridge_token_file is None:
            raise ContainerContractError(
                "durable proposer attestation omitted its bridge token"
            )
        _require_same_endpoint(
            attestation.bridge_token_file,
            bridge_token,
            label="proposer bridge token",
        )
        if low_spec.arena_socket.exists() or low_spec.arena_socket.is_symlink():
            socket_observation = _snapshot_endpoint(
                low_spec.arena_socket,
                label="rehydrated Arena RPC socket",
                expected_kind="socket",
            )
            _require_same_endpoint(
                attestation.arena_socket,
                socket_observation,
                label="Arena RPC socket",
            )
        _hash_unaliased_regular_file(
            Path(_runner_field(spec, "host_transcript_path")),
            label="rehydrated host transcript",
        )
        query = self._backend._identity_query(low_spec.identity)
        ids = _parse_container_id_lines(
            query.stdout, label="rehydrated attempt identity query"
        )
        if len(ids) != 1 or ids[0] != attestation.container_id:
            raise ContainerContractError(
                "durable rehydration requires exactly one attested "
                "identity-labelled container"
            )
        observed_state = self._backend.observe_container_state(
            attestation, low_spec
        )
        collectible_export = (
            observed_state.status == "exited"
            and observed_state.exit_code == 0
            and not observed_state.oom_killed
            and not observed_state.error
        )
        if collectible_export:
            # Preserve immutable completed output for the trusted collector,
            # which must independently replay before it can return a candidate.
            orphan_status = "exited"
            orphan_observation = observed_state.observation_sha256
        else:
            orphan_status = "containment_fault"
            orphan_observation = (
                self._backend.quiesce_orphan_for_containment(
                    attestation, low_spec
                )
            )
        # Host app-server identity is independent of the Docker cgroup.
        # Reconcile a completed absence receipt now; quarantine immediately if
        # a live ownerless process would require an unauthenticated signal.
        _reconcile_orphan_app_server_process(spec)
        recovered_launch: Any | None = None
        running_attempt: RunningAttempt | None = None
        if launched is not None:
            if (
                not isinstance(launched, runner_contract.BackendLaunch)
                or launched.container_id != attestation.container_id
                or launched.backend_id != attestation.container_id
                or not _is_hex_sha256(
                    launched.running_observation_sha256
                )
            ):
                raise ContainerContractError(
                    "durable backend launch differs from the journal"
                )
            recovered_launch = launched
            running_attempt = RunningAttempt(
                attestation=attestation,
                running_observation_sha256=(
                    launched.running_observation_sha256
                ),
            )
        return _AdapterRuntime(
            spec_fingerprint=_runner_spec_fingerprint(spec),
            low_spec=low_spec,
            attestation=attestation,
            preparation=recovered_preparation,
            arena_session=None,
            arena_server=None,
            arena_thread=None,
            arena_volume_runtime=recovered_arena_volume,
            orphaned_after_supervisor_restart=True,
            orphan_collectible_export=collectible_export,
            orphan_terminal_status=orphan_status,
            orphan_observation_sha256=orphan_observation,
            launched=running_attempt,
            backend_launch=recovered_launch,
        )

    def _load_durable_teardown_proof(
        self,
        *,
        spec: Any,
        prepared: Any,
        launched: Any,
        cause: str,
    ) -> Any | None:
        path = _expected_teardown_proof_path(spec)
        if not (path.exists() or path.is_symlink()):
            return None
        if cause not in {"normal_exit", "containment_fault"}:
            raise ContainerContractError(
                "runner teardown cause is not an explicit lifecycle cause"
            )
        runner_contract = _runner_contract()
        if (
            not isinstance(prepared, runner_contract.BackendPreparation)
            or not isinstance(launched, runner_contract.BackendLaunch)
        ):
            raise ContainerContractError(
                "durable teardown bindings have the wrong types"
            )
        value = _read_unaliased_json(
            path, label="durable backend teardown proof"
        )
        if set(value) != {
            "schema",
            "campaign_id",
            "attempt_id",
            "generation_id",
            "preparation_id",
            "backend_id",
            "proof",
            "proof_body",
        }:
            raise ContainerContractError(
                "durable backend teardown proof schema differs"
            )
        proof_value = value["proof"]
        proof_body = value["proof_body"]
        if not isinstance(proof_value, dict) or not isinstance(
            proof_body, dict
        ):
            raise ContainerContractError(
                "durable backend teardown proof records are malformed"
            )
        try:
            proof = runner_contract.BackendTeardownProof(**proof_value)
        except TypeError as exc:
            raise ContainerContractError(
                "durable backend teardown proof body is malformed"
            ) from exc
        if (
            value["schema"] != 1
            or value["campaign_id"] != _runner_field(spec, "campaign_id")
            or value["attempt_id"] != _runner_field(spec, "attempt_id")
            or value["generation_id"] != _runner_field(
                spec, "generation_id"
            )
            or value["preparation_id"] != prepared.preparation_id
            or value["backend_id"] != launched.backend_id
            or proof.container_id != launched.container_id
            or proof.cause != cause
            or proof.proof_sha256 != _json_sha256(proof_body)
            or not _valid_durable_teardown_body(
                proof_body,
                spec=spec,
                launched=launched,
                cause=cause,
            )
            or not (
                proof.container_inspect_absent
                and proof.container_top_absent
                and proof.identity_query_empty
                and proof.no_descendants
                and proof.app_server_process_absent
                and proof.app_server_process_group_absent
                and proof.bridge_socket_absent
                and proof.bridge_token_absent
                and proof.app_server_control_absent
                and proof.process_identity_authority
                == "controller_container_cgroup"
                and proof.controller_container_id
                == launched.controller_container_id
                and proof.egress_proxy_container_id
                == launched.egress_proxy_container_id
                and proof.controller_inspect_absent
                and proof.controller_identity_query_empty
                and proof.controller_top_absent
                and proof.controller_no_descendants
                and proof.egress_proxy_inspect_absent
                and proof.egress_proxy_identity_query_empty
                and proof.egress_proxy_top_absent
                and proof.egress_proxy_no_descendants
            )
        ):
            raise ContainerContractError(
                "durable teardown proof does not bind this exact lifecycle"
            )
        low_identity = AttemptIdentity(
            campaign_id=_runner_field(spec, "campaign_id"),
            generation_id=_runner_field(spec, "generation_id"),
            attempt_id=_runner_field(spec, "attempt_id"),
            game=_runner_field(spec, "game"),
            target_level=_runner_field(spec, "target_level"),
        )
        low_identity.validate()
        inspect_absent = self._backend._expect_absent(
            (
                self._backend._docker,
                "container",
                "inspect",
                proof.container_id,
            ),
            label="rehydrated teardown container inspection",
        )
        top_absent = self._backend._expect_absent(
            (
                self._backend._docker,
                "container",
                "top",
                proof.container_id,
                "-eo",
                "pid,ppid",
            ),
            label="rehydrated teardown process inventory",
        )
        identity_empty = not self._backend._identity_query(
            low_identity
        ).stdout.strip()
        socket_path = Path(_runner_field(spec, "arena_socket_path"))
        token_path = Path(_runner_field(spec, "arena_token_file_path"))
        bridge_socket_path = Path(
            _runner_field(spec, "bridge_socket_path")
        )
        bridge_token_path = Path(
            _runner_field(spec, "bridge_token_file_path")
        )
        app_control_path = Path(
            _runner_field(spec, "app_server_control_dir")
        )
        probe_reconciliation = (
            self._probe_executor.reconcile_attempt_probes(
                spec=spec, stage="teardown"
            )
        )
        if not (
            inspect_absent
            and top_absent
            and identity_empty
            and _host_process_absent(launched.app_server_pid)
            and _host_process_group_absent(
                launched.app_server_process_group_id
            )
            and not socket_path.exists()
            and not socket_path.is_symlink()
            and not token_path.exists()
            and not token_path.is_symlink()
            and not bridge_socket_path.exists()
            and not bridge_socket_path.is_symlink()
            and not bridge_token_path.exists()
            and not bridge_token_path.is_symlink()
            and not app_control_path.exists()
            and not app_control_path.is_symlink()
            and probe_reconciliation["receipt_sha256"]
            == proof_body["probe_reconciliation_receipt_sha256"]
        ):
            raise ContainerContractError(
                "durable teardown proof could not be re-observed"
            )
        state_scan_path = (
            Path(_runner_field(spec, "host_transcript_path")).parent
            / "controller_state_scan_receipt.json"
        )
        retained_scan_path = (
            Path(_runner_field(spec, "generation_dir"))
            / "retained_canary_scan_receipt.json"
        )
        reveal_path, reveal_sha256 = (
            self._ensure_terminal_canary_reveal(
                spec=spec,
                prepared=prepared,
                controller_state_scan_receipt_path=str(
                    state_scan_path
                ),
                controller_state_scan_receipt_sha256=(
                    _hash_unaliased_regular_file(
                        state_scan_path,
                        label="durable controller state scan receipt",
                    )
                ),
                retained_canary_scan_receipt_path=str(
                    retained_scan_path
                ),
                retained_canary_scan_receipt_sha256=(
                    _hash_unaliased_regular_file(
                        retained_scan_path,
                        label="durable retained canary scan receipt",
                    )
                ),
                container_id=proof.container_id,
                controller_container_id=(
                    proof.controller_container_id
                ),
                egress_proxy_container_id=(
                    proof.egress_proxy_container_id
                ),
                container_proof_sha256=(
                    proof_body["container_proof_sha256"]
                ),
            )
        )
        if (
            reveal_path != proof.canary_reveal_path
            or reveal_sha256 != proof.canary_reveal_sha256
            or proof_body["canary_reveal_path"] != reveal_path
            or proof_body["canary_reveal_sha256"] != reveal_sha256
        ):
            raise ContainerContractError(
                "durable teardown canary reveal changed"
            )
        cleanup_path, cleanup_sha256 = (
            self._ensure_terminal_canary_cleanup(
                spec=spec,
                canary_reveal_path=reveal_path,
                canary_reveal_sha256=reveal_sha256,
            )
        )
        if (
            cleanup_path != proof.canary_cleanup_receipt_path
            or cleanup_sha256
            != proof.canary_cleanup_receipt_sha256
            or proof_body["canary_cleanup_receipt_path"]
            != cleanup_path
            or proof_body["canary_cleanup_receipt_sha256"]
            != cleanup_sha256
        ):
            raise ContainerContractError(
                "durable teardown canary cleanup changed"
            )
        return proof

    def _runtime_for(
        self,
        spec: Any,
        *,
        prepared: Any | None = None,
        launched: Any | None = None,
    ) -> _AdapterRuntime:
        attempt_id = _canonical_uuid4(
            _runner_field(spec, "attempt_id"), label="attempt_id"
        )
        fingerprint = _runner_spec_fingerprint(spec)
        with self._lock:
            try:
                runtime = self._attempts[attempt_id]
            except KeyError:
                runtime = self._rehydrate_orphan(
                    spec,
                    prepared=prepared,
                    launched=launched,
                )
                self._attempts[attempt_id] = runtime
            self._require_same_adapter_spec(runtime, fingerprint)
            return runtime

    @staticmethod
    def _require_same_adapter_spec(
        runtime: _AdapterRuntime, fingerprint: str
    ) -> None:
        if runtime.spec_fingerprint != fingerprint:
            raise ContainerContractError(
                "runner attempt spec changed after backend admission"
            )

    @staticmethod
    def _require_lifecycle_bindings(
        runtime: _AdapterRuntime,
        prepared: Any,
        launched: Any,
    ) -> None:
        if prepared != runtime.preparation:
            raise ContainerContractError(
                "backend preparation changed across lifecycle calls"
            )
        if (
            runtime.backend_launch is None
            or launched != runtime.backend_launch
            or runtime.launched is None
        ):
            raise ContainerContractError(
                "backend launch changed across lifecycle calls"
            )


def _runner_contract() -> Any:
    try:
        import arc_agi3_contiguous_runner as runner_contract
    except ImportError as exc:
        raise ContainerContractError(
            "contiguous runner contract module is unavailable"
        ) from exc
    required = {
        "AttemptResult",
        "BackendPreparation",
        "BackendLaunch",
        "BackendSubstrateHealthProbe",
        "BackendSubstratePreflightError",
        "BackendPoll",
        "BackendCollection",
        "BackendTeardownProof",
    }
    if not all(hasattr(runner_contract, name) for name in required):
        raise ContainerContractError(
            "contiguous runner lifecycle contract is incomplete"
        )
    return runner_contract


def _app_server_hard_limits() -> tuple[int, int]:
    """Load the scanner-owned exact lifetime/refresh admission constants."""
    try:
        import arc_agi3_contiguous_taint as taint_contract

        hard_seconds = taint_contract.APP_SERVER_HARD_SAFETY_SECONDS
        max_refreshes = taint_contract.MAX_AUTH_REFRESHES
    except (ImportError, AttributeError) as exc:
        raise ContainerContractError(
            "taint scanner does not export the app-server hard limits"
        ) from exc
    if (
        isinstance(hard_seconds, bool)
        or hard_seconds != 21_600
        or isinstance(max_refreshes, bool)
        or max_refreshes != 7
    ):
        raise ContainerContractError(
            "taint scanner app-server hard limits differ from the reviewed "
            "contiguous contract"
        )
    return hard_seconds, max_refreshes


def _validate_process_start_receipt(
    *,
    spec: Any,
    evidence: probe_transport.PreflightEvidence,
) -> dict[str, Any]:
    host_root = Path(
        _runner_field(spec, "host_transcript_path")
    ).parent
    path = Path(evidence.controller_launch_receipt_path)
    guardian_path = Path(evidence.guardian_start_receipt_path)
    if (
        path != host_root / "controller_launch_receipt.json"
        or guardian_path
        != host_root / "controller_guardian_start.json"
    ):
        raise ContainerContractError(
            "controller launch receipt path is substituted"
        )
    value = _read_unaliased_json(
        path, label="controller launch receipt"
    )
    transport = _runner_field(spec, "proposer_transport")
    egress_readiness_path = (
        host_root / "controller_egress_readiness.json"
    )
    egress_probe_path = (
        host_root / "controller_egress_live_probe.json"
    )
    egress_readiness = _read_unaliased_json(
        egress_readiness_path,
        label="controller egress readiness receipt",
    )
    egress_probe = _read_unaliased_json(
        egress_probe_path,
        label="controller egress live-probe receipt",
    )
    if (
        value.get("schema") != 1
        or value.get("kind") != "arc_agi3_controller_launch"
        or value.get("campaign_id")
        != _runner_field(spec, "campaign_id")
        or value.get("generation_id")
        != _runner_field(spec, "generation_id")
        or value.get("attempt_id")
        != _runner_field(spec, "attempt_id")
        or value.get("attempt_spec_sha256")
        != _runner_contract().proposer_attempt_binding_sha256(spec)
        or value.get("controller_container_id")
        != evidence.controller_container_id
        or value.get("controller_image_digest")
        != transport.controller_image_digest
        or value.get("egress_proxy_container_id")
        != evidence.egress_proxy_container_id
        or value.get("egress_proxy_image_digest")
        != transport.controller_egress_proxy_image_digest
        or value.get("egress_policy_sha256")
        != transport.controller_egress_policy_sha256
        or value.get("egress_readiness_receipt_path")
        != str(egress_readiness_path)
        or value.get("egress_readiness_receipt_sha256")
        != _hash_unaliased_regular_file(
            egress_readiness_path,
            label="controller egress readiness receipt",
        )
        or value.get("egress_live_probe_receipt_path")
        != str(egress_probe_path)
        or value.get("egress_live_probe_receipt_sha256")
        != _hash_unaliased_regular_file(
            egress_probe_path,
            label="controller egress live-probe receipt",
        )
        or value.get("egress_live_probe_before_controller_create")
        is not True
        or egress_readiness.get("schema") != 1
        or egress_readiness.get("kind")
        != "arc_agi3_controller_egress_readiness"
        or egress_readiness.get("status") != "READY"
        or egress_readiness.get("campaign_id")
        != _runner_field(spec, "campaign_id")
        or egress_readiness.get("generation_id")
        != _runner_field(spec, "generation_id")
        or egress_readiness.get("attempt_id")
        != _runner_field(spec, "attempt_id")
        or egress_readiness.get("policy")
        != transport.controller_egress_policy
        or egress_readiness.get("policy_sha256")
        != transport.controller_egress_policy_sha256
        or egress_readiness.get("readiness_nonce")
        != value.get("egress_readiness_nonce")
        or egress_readiness.get("default_deny_installed") is not True
        or egress_readiness.get("allowed_sni")
        != list(CONTROLLER_PROXY_ALLOWED_SNI)
        or not isinstance(
            egress_readiness.get("resolver_ipv4"), list
        )
        or not 1 <= len(egress_readiness["resolver_ipv4"]) <= 4
        or any(
            not _is_canonical_ipv4(address)
            for address in egress_readiness["resolver_ipv4"]
        )
        or egress_probe.get("schema") != 1
        or egress_probe.get("kind")
        != "arc_agi3_controller_egress_live_probe"
        or egress_probe.get("policy")
        != transport.controller_egress_policy
        or egress_probe.get("policy_sha256")
        != transport.controller_egress_policy_sha256
        or egress_probe.get("nonce")
        != value.get("egress_readiness_nonce")
        or egress_probe.get("uid") != CONTROLLER_PROXY_UID
        or egress_probe.get("checks")
        != {
            "allowed_openai_tls": True,
            "denied_unallowlisted_sni": True,
            "denied_loopback": True,
            "denied_metadata": True,
        }
        or egress_probe.get("status") != "PASS"
        or value.get("launch_intent_sha256")
        != evidence.controller_launch_intent_sha256
        or value.get("authoritative_identity")
        != "controller_container_cgroup"
        or value.get("credentials_in_argv_or_env") is not False
        or value.get("bridge_or_arena_mounts") != 0
        or _hash_unaliased_regular_file(
            path, label="controller launch receipt"
        )
        != evidence.process_start_receipt_sha256
        or evidence.process_start_receipt_sha256
        != evidence.controller_launch_receipt_sha256
        or _hash_unaliased_regular_file(
            guardian_path, label="controller guardian start receipt"
        )
        != evidence.guardian_start_receipt_sha256
    ):
        raise ContainerContractError(
            "controller launch/guardian receipt differs from preflight"
        )
    return value


def _guardian_state_write_probe(
    *,
    spec: Any,
    evidence: probe_transport.PreflightEvidence,
) -> dict[str, Any]:
    """Reopen the real PID-1 write probe that preceded app-server startup."""

    path = Path(evidence.guardian_start_receipt_path)
    value = _read_unaliased_json(
        path, label="controller guardian state-write probe"
    )
    try:
        runtime_uid, runtime_gid = (
            int(component)
            for component in _runner_field(
                spec, "proposer_transport"
            ).controller_user.split(":", 1)
        )
    except (AttributeError, TypeError, ValueError) as exc:
        raise ContainerContractError(
            "controller runtime identity is malformed"
        ) from exc
    expected = {
        "schema": 1,
        "kind": "controller_state_root_write_probe",
        "relative_path": CONTROLLER_STATE_WRITE_PROBE_NAME,
        "payload_sha256": hashlib.sha256(
            CONTROLLER_STATE_WRITE_PROBE_PAYLOAD
        ).hexdigest(),
        "bytes": len(CONTROLLER_STATE_WRITE_PROBE_PAYLOAD),
        "runtime_uid": runtime_uid,
        "runtime_gid": runtime_gid,
        "fsync_file": True,
        "fsync_directory": True,
        "unlinked": True,
        "status": "PASS",
    }
    if (
        _hash_unaliased_regular_file(
            path, label="controller guardian start receipt"
        )
        != evidence.guardian_start_receipt_sha256
        or value.get("state_root_write_probe") != expected
    ):
        raise ContainerContractError(
            "guardian did not prove an exact controller-identity "
            "state-root write"
        )
    return expected


def _load_process_start_receipt(
    spec: Any,
) -> tuple[dict[str, Any], str] | None:
    """Load a process-start receipt without requiring completed preflight."""
    path = (
        Path(_runner_field(spec, "app_server_control_dir"))
        / "process_start.json"
    )
    if not (path.exists() or path.is_symlink()):
        return None
    value = _read_unaliased_json(
        path, label="orphan app-server process-start receipt"
    )
    transport = _runner_field(spec, "proposer_transport")
    required = {
        "schema",
        "kind",
        "campaign_id",
        "generation_id",
        "attempt_id",
        "attempt_spec_sha256",
        "pid",
        "process_group_id",
        "process_start_identity",
        "codex_binary_sha256",
        "codex_binary_bytes",
        "hard_safety_seconds",
        "max_auth_refreshes",
        "state_root",
    }
    pid = value.get("pid")
    pgid = value.get("process_group_id")
    if (
        set(value) != required
        or value.get("schema") != 1
        or value.get("kind")
        != "contiguous_app_server_process_start"
        or value.get("campaign_id")
        != _runner_field(spec, "campaign_id")
        or value.get("generation_id")
        != _runner_field(spec, "generation_id")
        or value.get("attempt_id")
        != _runner_field(spec, "attempt_id")
        or value.get("attempt_spec_sha256")
        != _runner_contract().proposer_attempt_binding_sha256(spec)
        or isinstance(pid, bool)
        or not isinstance(pid, int)
        or pid <= 1
        or isinstance(pgid, bool)
        or not isinstance(pgid, int)
        or pgid <= 1
        or pid != pgid
        or not _is_hex_sha256(value.get("process_start_identity"))
        or value.get("codex_binary_sha256")
        != transport.codex_binary_sha256
        or value.get("codex_binary_bytes")
        != transport.codex_binary_bytes
        or value.get("hard_safety_seconds")
        != _runner_field(spec, "hard_safety_seconds")
        or value.get("max_auth_refreshes")
        != _runner_field(spec, "max_auth_refreshes")
        or value.get("state_root")
        != _runner_field(spec, "app_server_state_dir")
    ):
        raise ContainerContractError(
            "orphan app-server process-start receipt is malformed"
        )
    return (
        value,
        _hash_unaliased_regular_file(
            path, label="orphan app-server process-start receipt"
        ),
    )


def _load_process_absence_receipt(
    spec: Any,
) -> tuple[dict[str, Any], str] | None:
    """Load a backend- or controller-written process absence receipt."""
    path = (
        Path(_runner_field(spec, "app_server_control_dir"))
        / "process_absent.json"
    )
    if not (path.exists() or path.is_symlink()):
        return None
    value = _read_unaliased_json(
        path, label="orphan app-server process-absence receipt"
    )
    required = {
        "schema",
        "kind",
        "campaign_id",
        "generation_id",
        "attempt_id",
        "attempt_spec_sha256",
        "process_start_receipt_sha256",
        "pid",
        "process_group_id",
        "process_start_identity",
        "process_absent",
        "process_group_absent",
    }
    pid = value.get("pid")
    pgid = value.get("process_group_id")
    if (
        set(value) != required
        or value.get("schema") != 1
        or value.get("kind")
        != "contiguous_app_server_process_absent"
        or value.get("campaign_id")
        != _runner_field(spec, "campaign_id")
        or value.get("generation_id")
        != _runner_field(spec, "generation_id")
        or value.get("attempt_id")
        != _runner_field(spec, "attempt_id")
        or value.get("attempt_spec_sha256")
        != _runner_contract().proposer_attempt_binding_sha256(spec)
        or not _is_hex_sha256(
            value.get("process_start_receipt_sha256")
        )
        or isinstance(pid, bool)
        or not isinstance(pid, int)
        or pid <= 1
        or isinstance(pgid, bool)
        or not isinstance(pgid, int)
        or pgid <= 1
        or pid != pgid
        or not _is_hex_sha256(value.get("process_start_identity"))
        or value.get("process_absent") is not True
        or value.get("process_group_absent") is not True
    ):
        raise ContainerContractError(
            "orphan app-server process-absence receipt is malformed"
        )
    return (
        value,
        _hash_unaliased_regular_file(
            path, label="orphan app-server process-absence receipt"
        ),
    )


def _reconcile_orphan_app_server_process(
    spec: Any,
) -> tuple[int, int] | None:
    """Contain a receipt-bound ownerless app-server and persist absence."""
    control_root = Path(
        _runner_field(spec, "app_server_control_dir")
    )
    start = _load_process_start_receipt(spec)
    absent = _load_process_absence_receipt(spec)
    if absent is not None:
        value, _digest = absent
        pid = value["pid"]
        pgid = value["process_group_id"]
        if (
            not _host_process_absent(pid)
            or not _host_process_group_absent(pgid)
        ):
            raise ContainerContractError(
                "absence receipt names a live app-server process"
            )
        if start is not None:
            start_value, start_sha256 = start
            if (
                start_sha256
                != value["process_start_receipt_sha256"]
                or start_value["pid"] != pid
                or start_value["process_group_id"] != pgid
                or start_value["process_start_identity"]
                != value["process_start_identity"]
            ):
                raise ContainerContractError(
                    "process start/absence receipts have different lineage"
                )
            _unlink_owned_attempt_file(
                control_root / "process_start.json",
                label="orphan app-server process-start receipt",
            )
        return pid, pgid
    if start is None:
        return None
    value, start_sha256 = start
    pid = value["pid"]
    pgid = value["process_group_id"]

    def require_same_live_identity() -> bool:
        if _host_process_absent(pid):
            if not _host_process_group_absent(pgid):
                raise ContainerContractError(
                    "orphan process group is live without its authenticated "
                    "leader"
                )
            return False
        try:
            observed_pgid = os.getpgid(pid)
        except (ProcessLookupError, PermissionError, OSError) as exc:
            raise ContainerContractError(
                "orphan app-server process group cannot be authenticated"
            ) from exc
        if (
            observed_pgid != pgid
            or pgid == os.getpgrp()
            or pid == os.getpid()
            or probe_transport.observe_os_process_start_identity(pid)
            != value["process_start_identity"]
        ):
            raise ContainerContractError(
                "refusing to contain a reused or supervisor process identity"
            )
        return True

    if require_same_live_identity():
        # A compare-then-killpg sequence is not atomic on Darwin: the leader
        # and numeric PGID could be reused between observation and signal.
        # Until the transport owns a launch-time guardian/cgroup identity,
        # ownerless live recovery must quarantine and refuse to signal.
        raise ContainerContractError(
            "live ownerless app-server requires an atomic launch guardian"
        )
    if (
        not _host_process_absent(pid)
        or not _host_process_group_absent(pgid)
    ):
        raise ContainerContractError(
            "orphan app-server survived receipt-bound containment"
        )
    absence_body = {
        "schema": 1,
        "kind": "contiguous_app_server_process_absent",
        "campaign_id": _runner_field(spec, "campaign_id"),
        "generation_id": _runner_field(spec, "generation_id"),
        "attempt_id": _runner_field(spec, "attempt_id"),
        "attempt_spec_sha256":
            _runner_contract().proposer_attempt_binding_sha256(spec),
        "process_start_receipt_sha256": start_sha256,
        "pid": pid,
        "process_group_id": pgid,
        "process_start_identity": value["process_start_identity"],
        "process_absent": True,
        "process_group_absent": True,
    }
    _write_private_json_new(
        control_root / "process_absent.json",
        absence_body,
    )
    _unlink_owned_attempt_file(
        control_root / "process_start.json",
        label="orphan app-server process-start receipt",
    )
    _load_process_absence_receipt(spec)
    return pid, pgid


def _validate_process_absence_receipt(
    *,
    spec: Any,
    preflight: probe_transport.PreflightEvidence | None,
    evidence: probe_transport.ControllerTeardownEvidence,
) -> dict[str, Any]:
    host_root = Path(
        _runner_field(spec, "host_transcript_path")
    ).parent
    path = host_root / "controller_absence_receipt.json"
    value = _read_unaliased_json(
        path, label="controller absence receipt"
    )
    if (
        value.get("schema") != 1
        or value.get("kind") != "arc_agi3_controller_absence"
        or value.get("campaign_id")
        != _runner_field(spec, "campaign_id")
        or value.get("generation_id")
        != _runner_field(spec, "generation_id")
        or value.get("attempt_id")
        != _runner_field(spec, "attempt_id")
        or value.get("attempt_spec_sha256")
        != _runner_contract().proposer_attempt_binding_sha256(spec)
        or value.get("controller_container_id")
        != evidence.controller_container_id
        or value.get("egress_proxy_container_id")
        != evidence.egress_proxy_container_id
        or value.get("authoritative_identity")
        != "controller_container_cgroup"
        or any(
            value.get(name) is not True
            for name in (
                "controller_inspect_absent",
                "controller_identity_query_empty",
                "controller_top_absent",
                "controller_no_descendants",
                "egress_proxy_inspect_absent",
                "egress_proxy_identity_query_empty",
                "egress_proxy_top_absent",
                "egress_proxy_no_descendants",
            )
        )
        or (
            preflight is not None
            and (
                evidence.pid != preflight.pid
                or evidence.process_group_id
                != preflight.process_group_id
                or evidence.controller_container_id
                != preflight.controller_container_id
                or evidence.egress_proxy_container_id
                != preflight.egress_proxy_container_id
                or value.get(
                    "controller_launch_receipt_sha256"
                )
                != preflight.controller_launch_receipt_sha256
                or value.get(
                    "guardian_start_receipt_sha256"
                )
                != preflight.guardian_start_receipt_sha256
            )
        )
        or _hash_unaliased_regular_file(
            path, label="controller absence receipt"
        )
        != evidence.process_absent_receipt_sha256
        or evidence.process_absent_receipt_sha256
        != evidence.controller_absence_receipt_sha256
    ):
        raise ContainerContractError(
            "controller absence receipt differs from teardown"
        )
    return value


def _validate_preflight_evidence(
    evidence: Any,
    *,
    spec: Any,
    credentials: probe_transport.ExternalChatGptCredentials,
) -> None:
    transport = _runner_field(spec, "proposer_transport")
    expected_notifications = tuple(
        sorted(probe_transport.PREFLIGHT_NOTIFICATION_CARDINALITY.items())
    )
    try:
        initialized_state = (
            probe_transport.inventory_controller_state(
                Path(_runner_field(spec, "app_server_state_dir"))
            )
        )
    except Exception as exc:
        raise ContainerContractError(
            "app-server initialized state cannot be inventoried"
        ) from exc
    database_rows = {
        path: (digest, byte_count)
        for path, digest, byte_count in initialized_state.files
        if path == probe_transport.CODEX_STATE_DATABASE_NAME
    }
    if (
        not isinstance(evidence, probe_transport.PreflightEvidence)
        or evidence.schema != 1
        or evidence.pid <= 1
        or evidence.process_group_id <= 1
        or not _is_hex_sha256(evidence.process_start_identity)
        or evidence.codex_binary_sha256
        != transport.codex_binary_sha256
        or evidence.codex_binary_bytes != transport.codex_binary_bytes
        or evidence.initialize_params_sha256
        != probe_transport.INITIALIZE_PARAMS_SHA256
        or evidence.redacted_login_request_sha256
        != credentials.redacted_request_sha256()
        or evidence.dynamic_tool_specs_sha256
        != probe_transport.DYNAMIC_TOOL_SPECS_SHA256
        or evidence.base_instructions_sha256
        != probe_transport.BASE_INSTRUCTIONS_SHA256
        or evidence.developer_instructions_sha256
        != probe_transport.DEVELOPER_INSTRUCTIONS_SHA256
        or evidence.model != transport.model
        or evidence.model_provider != transport.model_provider
        or evidence.reasoning_effort != _runner_field(spec, "effort")
        or evidence.hard_safety_seconds
        != _runner_field(spec, "hard_safety_seconds")
        or evidence.max_auth_refreshes
        != _runner_field(spec, "max_auth_refreshes")
        or not _is_hex_sha256(
            evidence.process_start_receipt_sha256
        )
        or evidence.process_identity_authority
        != "controller_container_cgroup"
        or not isinstance(evidence.controller_container_id, str)
        or not CONTAINER_ID_RE.fullmatch(
            evidence.controller_container_id
        )
        or evidence.controller_image_digest
        != transport.controller_image_digest
        or not isinstance(evidence.egress_proxy_container_id, str)
        or not CONTAINER_ID_RE.fullmatch(
            evidence.egress_proxy_container_id
        )
        or evidence.egress_proxy_image_digest
        != transport.controller_egress_proxy_image_digest
        or evidence.egress_policy_sha256
        != transport.controller_egress_policy_sha256
        or not _is_hex_sha256(
            evidence.controller_launch_intent_sha256
        )
        or not isinstance(
            evidence.controller_launch_receipt_path, str
        )
        or not Path(
            evidence.controller_launch_receipt_path
        ).is_absolute()
        or not _is_hex_sha256(
            evidence.controller_launch_receipt_sha256
        )
        or not isinstance(
            evidence.guardian_start_receipt_path, str
        )
        or not Path(
            evidence.guardian_start_receipt_path
        ).is_absolute()
        or not _is_hex_sha256(
            evidence.guardian_start_receipt_sha256
        )
        or not _is_hex_sha256(
            evidence.supply_chain_manifest_sha256
        )
        or evidence.request_methods
        != tuple(transport.controller_preflight_request_allowlist)
        or evidence.notification_counts != expected_notifications
        or tuple(name for name, _digest in evidence.response_sha256)
        != tuple(transport.controller_preflight_request_allowlist)
        or not all(
            _is_hex_sha256(digest)
            for _name, digest in evidence.response_sha256
        )
        or evidence.auth_mode != "chatgptAuthTokens"
        or any(
            getattr(evidence, name) is not True
            for name in (
                "model_effort_supported",
                "system_skills_disabled",
                "hooks_empty",
                "plugins_empty",
                "apps_empty",
                "experimental_features_disabled",
                "mcp_servers_empty",
                "stderr_empty",
            )
        )
        or evidence.stderr_sha256 != hashlib.sha256(b"").hexdigest()
        or evidence.stderr_bytes != 0
        or evidence.path_alias_setup_status != "PASS"
        or evidence.state_root
        != _runner_field(spec, "app_server_state_dir")
        or not _is_hex_sha256(
            evidence.initial_state_tree_sha256
        )
        or evidence.initialized_state_tree_sha256
        != initialized_state.tree_sha256
        or evidence.initialized_state_inventory_sha256
        != initialized_state.inventory_sha256
        or evidence.initialized_state_file_count
        != initialized_state.file_count
        or evidence.initialized_state_total_bytes
        != initialized_state.total_bytes
        or evidence.state_database_path
        != probe_transport.CODEX_STATE_DATABASE_NAME
        or set(database_rows)
        != {probe_transport.CODEX_STATE_DATABASE_NAME}
        or (
            evidence.state_database_sha256,
            evidence.state_database_bytes,
        )
        != database_rows[probe_transport.CODEX_STATE_DATABASE_NAME]
        or evidence.state_database_header_sha256
        != hashlib.sha256(
            probe_transport.SQLITE3_HEADER
        ).hexdigest()
        or evidence.state_database_initialized is not True
        or not _is_hex_sha256(evidence.transcript_chain_sha256)
    ):
        raise ContainerContractError(
            "app-server preflight evidence differs from the exact contract"
        )
    _validate_process_start_receipt(
        spec=spec,
        evidence=evidence,
    )
    _guardian_state_write_probe(
        spec=spec,
        evidence=evidence,
    )


def _validate_bridge_handshake(client: Any, *, spec: Any) -> None:
    result = getattr(client, "handshake_result", None)
    request_sha256 = getattr(client, "handshake_request_sha256", None)
    response_sha256 = getattr(client, "handshake_response_sha256", None)
    transport = _runner_field(spec, "proposer_transport")
    if (
        not isinstance(result, dict)
        or result.get("campaign_id")
        != _runner_field(spec, "campaign_id")
        or result.get("generation_id")
        != _runner_field(spec, "generation_id")
        or result.get("attempt_id") != _runner_field(spec, "attempt_id")
        or result.get("game") != _runner_field(spec, "game")
        or result.get("target_level")
        != _runner_field(spec, "target_level")
        or result.get("frontier_sha256")
        != _runner_field(spec, "frontier_sha256")
        or result.get("policy_sha256")
        != _runner_field(spec, "bridge_policy_sha256")
        or result.get("operation_allowlist")
        != list(transport.bridge_operation_allowlist)
        or result.get("exec_allowlist")
        != list(transport.bridge_exec_allowlist)
        or result.get("provider_credential_names") != []
        or not isinstance(result.get("environment_names"), list)
        or set(result["environment_names"])
        - (
            ALLOWED_IMAGE_ENV_NAMES
            | ATTEMPT_ENV_NAMES
            | {"HOME", "HOSTNAME"}
        )
        or not _is_hex_sha256(request_sha256)
        or not _is_hex_sha256(response_sha256)
    ):
        raise ContainerContractError(
            "proposer bridge handshake differs from the admitted attempt"
        )


def _validate_turn_start_evidence(evidence: Any, *, spec: Any) -> None:
    if (
        not isinstance(evidence, probe_transport.TurnStartEvidence)
        or evidence.schema != 1
        or not _is_canonical_uuid(evidence.thread_id)
        or not _is_canonical_uuid(evidence.turn_id)
        or evidence.thread_mode != _runner_field(spec, "thread_mode")
        or (
            evidence.thread_mode == "resume"
            and evidence.thread_id
            != _runner_field(spec, "resume_thread_id")
        )
        or not all(
            _is_hex_sha256(value)
            for value in (
                evidence.thread_request_sha256,
                evidence.turn_request_sha256,
                evidence.prompt_sha256,
                evidence.transcript_chain_sha256,
            )
        )
    ):
        raise ContainerContractError(
            "app-server turn-start evidence differs from the attempt"
        )


def _validate_turn_final_evidence(
    evidence: Any,
    *,
    spec: Any,
    thread_id: str,
    turn_id: str,
) -> None:
    if (
        not isinstance(evidence, probe_transport.TurnFinalEvidence)
        or evidence.schema != 1
        or evidence.thread_id != thread_id
        or evidence.turn_id != turn_id
        or evidence.turn_status
        not in {"completed", "interrupted", "failed"}
        or evidence.provider_outcome
        not in {
            "completed",
            "capacity",
            "rate_limit",
            "provider_failure",
            "containment_fault",
        }
        or not isinstance(evidence.token_usage_observations, tuple)
        or not evidence.token_usage_observations
        or not all(
            isinstance(item, dict)
            for item in evidence.token_usage_observations
        )
        or hashlib.sha256(
            evidence.final_model_text.encode("utf-8")
        ).hexdigest()
        != evidence.final_model_text_sha256
        or isinstance(evidence.tool_call_count, bool)
        or not isinstance(evidence.tool_call_count, int)
        or evidence.tool_call_count < 0
        or evidence.hard_safety_seconds
        != _runner_field(spec, "hard_safety_seconds")
        or evidence.max_auth_refreshes
        != _runner_field(spec, "max_auth_refreshes")
        or isinstance(evidence.auth_refresh_count, bool)
        or not isinstance(evidence.auth_refresh_count, int)
        or not 0 <= evidence.auth_refresh_count
        <= _runner_field(spec, "max_auth_refreshes")
        or not isinstance(
            evidence.redacted_auth_refresh_response_sha256, tuple
        )
        or len(evidence.redacted_auth_refresh_response_sha256)
        != evidence.auth_refresh_count
        or len(set(evidence.redacted_auth_refresh_response_sha256))
        != evidence.auth_refresh_count
        or not all(
            _is_hex_sha256(value)
            for value in evidence.redacted_auth_refresh_response_sha256
        )
        or evidence.credential_sentinel_scan_passed is not True
        or isinstance(evidence.post_turn_event_count, bool)
        or not isinstance(evidence.post_turn_event_count, int)
        or evidence.post_turn_event_count < 0
        or isinstance(evidence.stdout_bytes, bool)
        or not isinstance(evidence.stdout_bytes, int)
        or evidence.stdout_bytes < 0
        or isinstance(evidence.stderr_bytes, bool)
        or not isinstance(evidence.stderr_bytes, int)
        or evidence.stderr_bytes < 0
        or evidence.pipes_drained_to_eof is not True
        or not _is_hex_sha256(evidence.transcript_chain_sha256)
        or isinstance(evidence.transcript_event_count, bool)
        or not isinstance(evidence.transcript_event_count, int)
        or evidence.transcript_event_count <= 0
    ):
        raise ContainerContractError(
            "app-server final evidence differs from the launched turn"
        )


def _validate_controller_teardown_evidence(
    evidence: Any,
    *,
    spec: Any,
    preflight: probe_transport.PreflightEvidence | None,
) -> None:
    if (
        not isinstance(
            evidence, probe_transport.ControllerTeardownEvidence
        )
        or evidence.schema != 1
        or (
            preflight is not None
            and (
                evidence.pid != preflight.pid
                or evidence.process_group_id
                != preflight.process_group_id
            )
        )
        or isinstance(evidence.pid, bool)
        or not isinstance(evidence.pid, int)
        or evidence.pid <= 1
        or isinstance(evidence.process_group_id, bool)
        or not isinstance(evidence.process_group_id, int)
        or evidence.process_group_id <= 1
        or isinstance(evidence.exit_code, bool)
        or not isinstance(evidence.exit_code, int)
        or evidence.process_absent is not True
        or evidence.process_group_absent is not True
        or not _is_hex_sha256(
            evidence.process_absent_receipt_sha256
        )
        or evidence.process_start_receipt_removed is not True
        or evidence.ephemeral_tmp_purged is not True
        or not _is_hex_sha256(evidence.stderr_sha256)
        or isinstance(evidence.stderr_bytes, bool)
        or not isinstance(evidence.stderr_bytes, int)
        or evidence.stderr_bytes < 0
        or not _is_hex_sha256(evidence.state_tree_sha256)
        or not _is_hex_sha256(evidence.transcript_chain_sha256)
        or evidence.process_identity_authority
        != "controller_container_cgroup"
        or not CONTAINER_ID_RE.fullmatch(
            evidence.controller_container_id
        )
        or not CONTAINER_ID_RE.fullmatch(
            evidence.egress_proxy_container_id
        )
        or any(
            getattr(evidence, name) is not True
            for name in (
                "controller_inspect_absent",
                "controller_identity_query_empty",
                "controller_top_absent",
                "controller_no_descendants",
                "egress_proxy_inspect_absent",
                "egress_proxy_identity_query_empty",
                "egress_proxy_top_absent",
                "egress_proxy_no_descendants",
            )
        )
        or not _is_hex_sha256(
            evidence.controller_absence_receipt_sha256
        )
    ):
        raise ContainerContractError(
            "app-server teardown evidence is incomplete"
        )
    _validate_process_absence_receipt(
        spec=spec,
        preflight=preflight,
        evidence=evidence,
    )


def _bound_receipt_base(spec: Any, *, kind: str) -> dict[str, Any]:
    runner_contract = _runner_contract()
    return {
        "schema": 1,
        "kind": kind,
        "campaign_id": _runner_field(spec, "campaign_id"),
        "generation_id": _runner_field(spec, "generation_id"),
        "attempt_id": _runner_field(spec, "attempt_id"),
        "attempt_spec_sha256":
            runner_contract.proposer_attempt_binding_sha256(spec),
    }


def _controller_credential_sentinels(
    controller: Any,
    *,
    originals: Sequence[str],
    maximum_refreshes: int,
) -> tuple[str, ...]:
    """Obtain the live-only original+rotated scan set without retaining it."""
    getter = getattr(
        controller, "credential_sentinels_for_host_scan", None
    )
    if not callable(getter):
        raise ContainerContractError(
            "controller does not expose its accumulated credential scan set"
        )
    values = getter()
    original_set = {
        value for value in originals
        if isinstance(value, str) and value
    }
    if (
        not isinstance(values, tuple)
        or not values
        or any(not isinstance(value, str) or not value for value in values)
        or values != tuple(sorted(set(values)))
        or not original_set.issubset(values)
        # The pinned source schema has five possible nonempty leak sentinels
        # per generation: API key plus access/account/id/refresh tokens.
        # Account is lineage-stable, but use the schema maximum so legitimate
        # rotations of every other credential cannot become uncollectable.
        or len(values) > 5 * (maximum_refreshes + 1)
    ):
        raise ContainerContractError(
            "controller credential scan lineage is malformed"
        )
    return values


def _secret_occurrence_count(
    *,
    paths: Sequence[Path],
    tree_roots: Sequence[Path],
    sentinels: Sequence[str],
) -> int:
    needle_bytes = tuple(
        value.encode("utf-8")
        for value in sentinels
        if isinstance(value, str) and value
    )
    if not needle_bytes:
        raise ContainerContractError(
            "external credential leak-sentinel set is empty"
        )
    selected = [Path(path) for path in paths]
    for tree_root in tree_roots:
        selected.extend(
            sorted(
                entry
                for entry in Path(tree_root).rglob("*")
                if entry.is_file()
            )
        )
    occurrences = 0
    for path in selected:
        raw = _read_unaliased_bytes(
            path,
            label="credential secret-scan input",
            maximum_bytes=256 * 1024 * 1024,
        )
        for needle in needle_bytes:
            occurrences += raw.count(needle)
    return occurrences


def _ensure_bound_receipt(
    path: Path,
    *,
    spec: Any,
    kind: str,
    fields: Mapping[str, Any],
) -> tuple[str, str]:
    target = Path(path)
    body = {
        **_bound_receipt_base(spec, kind=kind),
        **dict(fields),
    }
    if target.exists() or target.is_symlink():
        if _read_unaliased_json(target, label=f"{kind} receipt") != body:
            raise ContainerContractError(
                f"existing {kind} receipt differs from current observations"
            )
    else:
        _write_private_json_new(target, body)
    return (
        str(target),
        _hash_unaliased_regular_file(target, label=f"{kind} receipt"),
    )


def _prove_neutral_cwd_write_denied(path: Path) -> None:
    """Perform a real owner-identity write probe without retaining bytes."""
    root = Path(path)
    probe = root / f".contiguous-write-probe-{uuid.uuid4().hex}"
    descriptor = -1
    try:
        descriptor = os.open(
            probe,
            os.O_WRONLY
            | os.O_CREAT
            | os.O_EXCL
            | getattr(os, "O_NOFOLLOW", 0),
            0o600,
        )
    except PermissionError:
        return
    except OSError as exc:
        raise ContainerContractError(
            "neutral cwd write probe failed ambiguously"
        ) from exc
    finally:
        if descriptor >= 0:
            os.close(descriptor)
    try:
        probe.unlink(missing_ok=True)
    finally:
        raise ContainerContractError(
            "neutral cwd admitted an owner-identity write"
        )


def _observe_codex_version(
    binary_path: Path,
    *,
    neutral_cwd: Path,
    expected: str,
) -> str:
    command = (str(binary_path), "--version")
    try:
        completed = subprocess.run(
            command,
            stdin=subprocess.DEVNULL,
            stdout=subprocess.PIPE,
            stderr=subprocess.PIPE,
            text=True,
            shell=False,
            check=False,
            timeout=10,
            cwd=neutral_cwd,
            env={
                "LANG": "C.UTF-8",
                "LC_ALL": "C.UTF-8",
                "PATH": "/usr/local/bin:/opt/homebrew/bin:/usr/bin:/bin",
            },
            close_fds=True,
            start_new_session=True,
        )
    except (OSError, subprocess.TimeoutExpired) as exc:
        raise ContainerContractError(
            "pinned Codex version probe did not complete"
        ) from exc
    observed = completed.stdout.strip()
    if (
        completed.returncode != 0
        or completed.stderr
        or observed != expected
    ):
        raise ContainerContractError(
            "pinned Codex version observation differs from configuration"
        )
    return observed


def _prepare_static_receipts(
    spec: Any,
    *,
    arena_binding_event: Mapping[str, Any] | None = None,
) -> dict[str, tuple[str, str]]:
    """Observe and bind every pre-launch runner receipt projection."""
    host_root = Path(_runner_field(spec, "host_transcript_path")).parent
    transport = _runner_field(spec, "proposer_transport")
    neutral = Path(_runner_field(spec, "neutral_host_cwd_path"))
    _reject_symlink_components(neutral, label="neutral host cwd")
    metadata = neutral.stat(follow_symlinks=False)
    if (
        not stat.S_ISDIR(metadata.st_mode)
        or any(neutral.iterdir())
        or metadata.st_uid != os.getuid()
    ):
        raise ContainerContractError(
            "neutral host cwd is not an empty owner-controlled directory"
        )
    _prove_neutral_cwd_write_denied(neutral)
    neutral_tree = _validated_tree_hash(neutral, label="neutral host cwd")

    bridge_policy = Path(_runner_field(spec, "bridge_policy_path"))
    bridge_policy_sha256 = _hash_unaliased_regular_file(
        bridge_policy, label="bridge policy"
    )
    if bridge_policy_sha256 != _runner_field(spec, "bridge_policy_sha256"):
        raise ContainerContractError("bridge policy changed before receipt")
    _checkpoint, parent_path = _load_exact_parent_checkpoint(spec)
    arena_receipt_path = host_root / "arena_session_binding_receipt.json"
    if arena_binding_event is not None:
        arena_binding_projection = _validate_arena_binding_document(
            dict(arena_binding_event),
            binding_sha256=arena_binding_event.get("binding_sha256"),
            spec=spec,
            parent_path=parent_path,
        )
        arena_path, arena_sha256 = _ensure_bound_receipt(
            arena_receipt_path,
            spec=spec,
            kind="contiguous_arena_session_binding",
            fields={"binding_event": arena_binding_projection},
        )
    else:
        retained = _read_unaliased_json(
            arena_receipt_path,
            label="retained Arena session binding receipt",
        )
        expected_base = _bound_receipt_base(
            spec, kind="contiguous_arena_session_binding"
        )
        if (
            set(retained) != {*expected_base, "binding_event"}
            or any(
                retained.get(name) != value
                for name, value in expected_base.items()
            )
            or not isinstance(retained.get("binding_event"), dict)
        ):
            raise ContainerContractError(
                "retained Arena session binding receipt is malformed"
            )
        token = _read_private_token_text(
            Path(_runner_field(spec, "arena_token_file_path"))
        )
        arena_binding_projection = _validate_arena_binding_document(
            retained["binding_event"],
            binding_sha256=retained["binding_event"].get(
                "binding_sha256"
            ),
            spec=spec,
            parent_path=parent_path,
            expected_session_id=_arena_session_id(token),
        )
        arena_path = str(arena_receipt_path)
        arena_sha256 = _hash_unaliased_regular_file(
            arena_receipt_path,
            label="retained Arena session binding receipt",
        )
    hard_safety_seconds, max_auth_refreshes = (
        _app_server_hard_limits()
    )

    config_projection = {
        "model": transport.model,
        "model_provider": transport.model_provider,
        "allow_provider_model_fallback": False,
        "reasoning_effort": _runner_field(spec, "effort"),
        "hard_safety_seconds": _runner_field(
            spec, "hard_safety_seconds"
        ),
        "max_auth_refreshes": _runner_field(
            spec, "max_auth_refreshes"
        ),
        "environments": [],
        "selected_capability_roots": [],
        "runtime_workspace_roots": [
            CONTROLLER_NEUTRAL_DESTINATION
        ],
        "native_proposer_workspace": {
            "root": CONTROLLER_NEUTRAL_DESTINATION,
            "storage": "private-tmpfs",
            "git_root_equals_workspace": True,
            "git_ceiling_directories":
                CONTROLLER_NEUTRAL_DESTINATION,
            "git_discovery_across_filesystem": False,
            "parent_repo_mounts": 0,
            "campaign_plan_mounts": 0,
            "sidecar_or_quarantine_mounts": 0,
            "manuscript_comparator_benchmark_mounts": 0,
            "symlinks_allowed": False,
            "hardlinks_allowed": False,
        },
        "dynamic_tool_namespace": transport.dynamic_tool_namespace,
        "dynamic_tool_names": list(transport.dynamic_tool_names),
        "controller_method_policy": {
            "preflight_requests": list(
                transport.controller_preflight_request_allowlist
            ),
            "preflight_notifications": list(
                transport.controller_preflight_notification_allowlist
            ),
            "turn_requests": list(
                transport.controller_turn_request_allowlist
            ),
        },
        "builtin_tool_names": [],
        "approval_policy": "never",
        "sandbox_policy": {
            "type": "readOnly",
            "networkAccess": False,
        },
        "state_root": CONTROLLER_STATE_DESTINATION,
        "state_host_staging_root":
            _runner_field(spec, "app_server_state_dir"),
        "state_mode": (
            "resume_staged_copy"
            if _runner_field(spec, "thread_mode") == "resume"
            else "new_reset"
        ),
        "prior_state_root": (
            _runner_field(spec, "wip").app_server_state_dir
            if _runner_field(spec, "wip") is not None
            else None
        ),
        "staged_state_root": _runner_field(
            spec, "app_server_state_dir"
        ),
        "prior_state_tree_sha256": (
            _runner_field(spec, "wip").app_server_state_tree_sha256
            if _runner_field(spec, "wip") is not None
            else None
        ),
        "staged_initial_state_tree_sha256":
            probe_transport.inventory_controller_state(
                Path(_runner_field(spec, "app_server_state_dir"))
            ).tree_sha256,
        "ambient_state_access_status": "DENIED",
        "state_root_write_probe_status":
            "PENDING_REAL_CONTROLLER_PREFLIGHT",
        "ambient_environment_names_stripped": [
            "CODEX_HOME",
            "HOME",
            "XDG_CONFIG_HOME",
            "XDG_DATA_HOME",
            "XDG_STATE_HOME",
        ],
        "rendered_config_sha256": hashlib.sha256(
            probe_transport.render_strict_config(
                model=transport.model,
                model_provider=transport.model_provider,
                effort=_runner_field(spec, "effort"),
            ).encode("utf-8")
        ).hexdigest(),
    }
    receipts = {
        "bridge_policy": _ensure_bound_receipt(
            Path(_runner_field(spec, "bridge_policy_receipt_path")),
            spec=spec,
            kind="contiguous_bridge_policy",
            fields={
                "policy_path": str(bridge_policy),
                "policy_sha256": bridge_policy_sha256,
                "input_bundle_receipt_sha256":
                    _runner_field(spec, "input_bundle_receipt_sha256"),
                "arena_session_binding_receipt_path": arena_path,
                "arena_session_binding_receipt_sha256":
                    arena_sha256,
                "arena_session_binding_sha256":
                    arena_binding_projection["binding_sha256"],
                "seed_snapshot_sha256":
                    arena_binding_projection["seed_snapshot_sha256"],
                "exploration_seed_snapshot_sha256":
                    arena_binding_projection[
                        "exploration_seed_snapshot_sha256"
                    ],
                "probe_isolation_mode":
                    arena_binding_projection[
                        "probe_isolation_mode"
                    ],
                "probe_isolation_evidence_sha256":
                    arena_binding_projection[
                        "probe_isolation_evidence_sha256"
                    ],
            },
        ),
        "arena_binding": (arena_path, arena_sha256),
        "neutral_cwd": _ensure_bound_receipt(
            host_root / "neutral_cwd_attestation.json",
            spec=spec,
            kind="contiguous_neutral_cwd_attestation",
            fields={
                "path": str(neutral),
                "owner_uid": metadata.st_uid,
                "owner_gid": metadata.st_gid,
                "mode": stat.S_IMODE(metadata.st_mode),
                "tree_sha256": neutral_tree,
                "write_probe_status": "DENIED",
            },
        ),
        "app_server_config": _ensure_bound_receipt(
            host_root / "app_server_config_receipt.json",
            spec=spec,
            kind="contiguous_app_server_config",
            fields=config_projection,
        ),
        "codex_binary": _ensure_bound_receipt(
            host_root / "codex_binary_receipt.json",
            spec=spec,
            kind="contiguous_codex_binary",
            fields={
                "observation_stage":
                    "pending_controller_guardian",
                "controller_image_digest":
                    transport.controller_image_digest,
                "launcher_path": transport.codex_launcher_path,
                "launcher_sha256":
                    transport.codex_launcher_sha256,
                "package_manifest_path":
                    transport.codex_package_manifest_path,
                "package_manifest_sha256":
                    transport.codex_package_manifest_sha256,
                "native_binary_path": transport.codex_binary_path,
                "native_binary_sha256":
                    transport.codex_binary_sha256,
                "native_binary_bytes":
                    transport.codex_binary_bytes,
                "version": transport.codex_cli_version,
                "version_probe_argv": [
                    transport.codex_binary_path,
                    "--version",
                ],
                "host_file_observation": False,
            },
        ),
        "protocol_schema": _ensure_bound_receipt(
            host_root / "app_server_protocol_schema_receipt.json",
            spec=spec,
            kind="contiguous_app_server_protocol_schema",
            fields={
                "observation_stage":
                    "pending_controller_guardian",
                "controller_image_digest":
                    transport.controller_image_digest,
                "path": transport.app_server_protocol_schema_path,
                "sha256":
                    transport.app_server_protocol_schema_sha256,
                "bundle_path":
                    transport.app_server_protocol_schema_bundle_path,
                "bundle_sha256":
                    transport
                    .app_server_protocol_schema_bundle_sha256,
                "host_file_observation": False,
            },
        ),
    }
    return receipts


def _attempt_probe_labels(spec: Any) -> dict[str, str]:
    """Project the immutable attempt identity into crash-query labels."""
    campaign_id = _canonical_uuid4(
        _runner_field(spec, "campaign_id"), label="probe campaign_id"
    )
    generation_id = _canonical_uuid4(
        _runner_field(spec, "generation_id"), label="probe generation_id"
    )
    attempt_id = _canonical_uuid4(
        _runner_field(spec, "attempt_id"), label="probe attempt_id"
    )
    game = _runner_field(spec, "game")
    target_level = _runner_field(spec, "target_level")
    if not isinstance(game, str) or not GAME_RE.fullmatch(game):
        raise ContainerContractError(
            "attempt-wide probe game identity is malformed"
        )
    if (
        isinstance(target_level, bool)
        or not isinstance(target_level, int)
        or target_level <= 0
    ):
        raise ContainerContractError(
            "attempt-wide probe target level is malformed"
        )
    return {
        LABEL_CAMPAIGN: campaign_id,
        LABEL_GENERATION: generation_id,
        LABEL_ATTEMPT: attempt_id,
        LABEL_GAME: game,
        LABEL_LEVEL: str(target_level),
        PROBE_ROLE_LABEL: PROBE_ROLE_VALUE,
    }


def _validate_probe_reconciliation_receipt(
    value: Mapping[str, Any],
    *,
    labels: Mapping[str, str],
    stage: str,
) -> None:
    if not isinstance(value, Mapping):
        raise ContainerContractError(
            "probe reconciliation receipt does not bind this attempt"
        )
    expected_fields = {
        "schema",
        "kind",
        "stage",
        "campaign_id",
        "generation_id",
        "attempt_id",
        "game",
        "target_level",
        "removed_container_ids",
        "identity_query_empty",
        "container_inspect_absent",
        "process_groups_absent",
    }
    removed = value.get("removed_container_ids")
    if (
        set(value) != expected_fields
        or value.get("schema") != 1
        or isinstance(value.get("schema"), bool)
        or value.get("kind")
        != "arc_agi3_contiguous_probe_reconciliation"
        or value.get("stage") != stage
        or value.get("campaign_id") != labels[LABEL_CAMPAIGN]
        or value.get("generation_id") != labels[LABEL_GENERATION]
        or value.get("attempt_id") != labels[LABEL_ATTEMPT]
        or value.get("game") != labels[LABEL_GAME]
        or value.get("target_level") != int(labels[LABEL_LEVEL])
        or not isinstance(removed, list)
        or len(removed) > MAX_PROBE_FILES
        or len(removed) != len(set(removed))
        or not all(
            isinstance(container_id, str)
            and CONTAINER_ID_RE.fullmatch(container_id)
            for container_id in removed
        )
        or any(
            value.get(name) is not True
            for name in (
                "identity_query_empty",
                "container_inspect_absent",
                "process_groups_absent",
            )
        )
    ):
        raise ContainerContractError(
            "probe reconciliation receipt does not bind this attempt"
        )


